CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_username text;
  v_email text;
  v_birthday_month smallint;
  v_birthday_day smallint;
  v_birthday_year smallint;
begin
  v_email := coalesce(new.email, '');

  v_username := nullif(trim(new.raw_user_meta_data ->> 'username'), '');

  if v_username is null then
    v_username :=
      left(
        regexp_replace(
          split_part(coalesce(v_email, 'manager'), '@', 1),
          '[^a-zA-Z0-9_]',
          '_',
          'g'
        ),
        15
      )
      || '_'
      || substring(new.id::text, 1, 8);
  end if;

  v_username := left(
    regexp_replace(
      regexp_replace(trim(v_username), '\s+', '_', 'g'),
      '[^a-zA-Z0-9_]',
      '',
      'g'
    ),
    24
  );

  if length(v_username) < 3 then
    v_username := 'user_' || substring(new.id::text, 1, 8);
  end if;

  v_birthday_month := nullif(new.raw_user_meta_data ->> 'birthday_month', '')::smallint;
  v_birthday_day := nullif(new.raw_user_meta_data ->> 'birthday_day', '')::smallint;
  v_birthday_year := nullif(new.raw_user_meta_data ->> 'birthday_year', '')::smallint;

  insert into public.profiles (
    id,
    username,
    email,
    birthday_month,
    birthday_day,
    birthday_year,
    birthday_locked,
    birthday_set_at
  )
  values (
    new.id,
    v_username,
    v_email,
    v_birthday_month,
    v_birthday_day,
    v_birthday_year,
    case
      when v_birthday_month is not null and v_birthday_day is not null then true
      else false
    end,
    case
      when v_birthday_month is not null and v_birthday_day is not null then now()
      else null
    end
  )
  on conflict (id) do update
  set
    email = excluded.email,
    username = coalesce(public.profiles.username, excluded.username),
    birthday_month = case
      when public.profiles.birthday_locked = true then public.profiles.birthday_month
      else excluded.birthday_month
    end,
    birthday_day = case
      when public.profiles.birthday_locked = true then public.profiles.birthday_day
      else excluded.birthday_day
    end,
    birthday_year = case
      when public.profiles.birthday_locked = true then public.profiles.birthday_year
      else excluded.birthday_year
    end,
    birthday_locked = case
      when public.profiles.birthday_locked = true then true
      when excluded.birthday_month is not null and excluded.birthday_day is not null then true
      else public.profiles.birthday_locked
    end,
    birthday_set_at = case
      when public.profiles.birthday_set_at is not null then public.profiles.birthday_set_at
      when excluded.birthday_month is not null and excluded.birthday_day is not null then now()
      else null
    end;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_profile_email_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.email is distinct from old.email then
    update public.profiles
    set email = new.email
    where id = new.id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_club(p_name text, p_country_code text, p_primary_color text, p_secondary_color text, p_logo_path text DEFAULT NULL::text, p_motto text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_existing_club uuid;
  v_club_id uuid;

  v_name text;
  v_country_code text;
  v_primary_color text;
  v_secondary_color text;
  v_logo_path text;
  v_motto text;

  v_final_cash_balance numeric := 0;

  v_stage text := 'start';
  v_msg text;
  v_detail text;
  v_hint text;
  v_constraint text;
  v_table text;
begin
  v_stage := 'auth.uid';
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'You must be authenticated to create a club.';
  end if;

  v_stage := 'lock profile';
  perform 1
  from public.profiles
  where id = v_user_id
  for update;

  if not found then
    raise exception 'Profile not found for authenticated user.';
  end if;

  v_stage := 'check existing club';
  select c.id
  into v_existing_club
  from public.clubs c
  where c.owner_user_id = v_user_id
  limit 1;

  if v_existing_club is not null then
    raise exception 'This account already owns a club.';
  end if;

  v_stage := 'normalize inputs';
  v_name := btrim(coalesce(p_name, ''));
  v_country_code := upper(btrim(coalesce(p_country_code, '')));
  v_primary_color := btrim(coalesce(p_primary_color, ''));
  v_secondary_color := btrim(coalesce(p_secondary_color, ''));
  v_logo_path := nullif(btrim(coalesce(p_logo_path, '')), '');
  v_motto := nullif(btrim(coalesce(p_motto, '')), '');

  if v_name = '' or char_length(v_name) < 3 or char_length(v_name) > 40 then
    raise exception 'Club name must be between 3 and 40 characters.';
  end if;

  if v_country_code = '' then
    raise exception 'Country code is required.';
  end if;

  if v_primary_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Primary color must be a hex color like #F3C623.';
  end if;

  if v_secondary_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Secondary color must be a hex color like #111216.';
  end if;

  if lower(v_primary_color) = lower(v_secondary_color) then
    raise exception 'Primary and secondary colors must be different.';
  end if;

  v_stage := 'validate country';
  if not exists (
    select 1
    from public.countries
    where code = v_country_code
      and is_selectable = true
  ) then
    raise exception 'Invalid or unavailable country code.';
  end if;

  v_stage := 'insert clubs';

  insert into public.clubs (
    owner_user_id,
    name,
    country_code,
    primary_color,
    secondary_color,
    logo_path,
    motto,
    world_tier,
    club_tier,
    tier2_division,
    reputation,
    is_ai,
    is_active,
    club_type
  )
  values (
    v_user_id,
    v_name,
    v_country_code,
    v_primary_color,
    v_secondary_color,
    v_logo_path,
    v_motto,
    3,
    'proteam'::public.club_tier,
    'PRO_EAST',
    0,
    false,
    true,
    'main'
  )
  returning id into v_club_id;

  v_stage := 'insert club_memberships';
  insert into public.club_memberships (club_id, user_id, role)
  values (v_club_id, v_user_id, 'owner')
  on conflict do nothing;

  v_stage := 'insert club_settings';
  insert into public.club_settings (club_id)
  values (v_club_id)
  on conflict (club_id) do nothing;

  v_stage := 'finance_setup_new_club';
  if to_regprocedure('public.finance_setup_new_club(uuid)') is not null then
    perform public.finance_setup_new_club(v_club_id);
  end if;

  v_stage := 'final new club balance setup';
  perform public.apply_new_club_creation_balance_v1(v_club_id, true);

  -- Extra safety: sync finance summary after finalizer.
  v_stage := 'sync club_finance_summary';
  select coalesce(c.cash_balance, 0)
  into v_final_cash_balance
  from public.clubs c
  where c.id = v_club_id;

  insert into public.club_finance_summary (club_id, current_balance)
  values (v_club_id, v_final_cash_balance)
  on conflict (club_id) do update
  set current_balance = excluded.current_balance;

  v_stage := 'update profiles';
  update public.profiles
  set has_created_club = true
  where id = v_user_id;

  return v_club_id;

exception
  when others then
    get stacked diagnostics
      v_msg = message_text,
      v_detail = pg_exception_detail,
      v_hint = pg_exception_hint,
      v_constraint = constraint_name,
      v_table = table_name;

    raise exception
      'create_club failed at stage=% | sqlstate=% | msg=% | table=% | constraint=% | detail=% | hint=%',
      v_stage,
      SQLSTATE,
      coalesce(v_msg, '?'),
      coalesce(v_table, '?'),
      coalesce(v_constraint, '?'),
      coalesce(v_detail, '?'),
      coalesce(v_hint, '?');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_daily_tick()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season int; v_month smallint; v_day smallint; v_paused boolean; v_date date;
begin
  select season_number,month_number,day_number,is_paused
    into v_season,v_month,v_day,v_paused
  from public.game_state
  where id=true;

  if coalesce(v_paused,false) then return; end if;

  v_date:=public.get_current_game_date_date();

  begin perform public.run_retirement_daily_jobs(); exception when others then raise warning 'run_retirement_daily_jobs failed: %',sqlerrm; end;
  begin perform public.process_due_rider_contract_starts_v1(v_date,null,null,null); exception when others then raise warning 'process_due_rider_contract_starts_v1 failed: %',sqlerrm; end;
  begin perform public.process_developing_team_age_limits_v1(v_date); exception when others then raise warning 'process_developing_team_age_limits_v1 failed: %',sqlerrm; end;
  begin perform public.notify_developing_team_window_open(); exception when others then raise warning 'notify_developing_team_window_open failed: %',sqlerrm; end;
  begin perform public.prepare_next_season_race_calendar_if_due_v1(); exception when others then raise warning 'prepare_next_season_race_calendar_if_due_v1 failed: %',sqlerrm; end;
  begin perform public.process_daily_training_camp_activities(); exception when others then raise warning 'process_daily_training_camp_activities failed: %',sqlerrm; end;
  begin perform public.process_daily_regular_training(); exception when others then raise warning 'process_daily_regular_training failed: %',sqlerrm; end;
  begin perform public.process_daily_training_camps(); exception when others then raise warning 'process_daily_training_camps failed: %',sqlerrm; end;
  begin perform public.process_weekly_rider_development(); exception when others then raise warning 'process_weekly_rider_development failed: %',sqlerrm; end;
  begin perform public.finance_process_weekly_rider_wages_guarded_v1(); exception when others then raise warning 'finance_process_weekly_rider_wages_guarded_v1 failed: %',sqlerrm; end;
  begin perform public.finance_process_weekly_team_policy_costs(); exception when others then raise warning 'finance_process_weekly_team_policy_costs failed: %',sqlerrm; end;
  begin perform public.finance_process_team_policy_nonrecurring_costs_v1(); exception when others then raise warning 'finance_process_team_policy_nonrecurring_costs_v1 failed: %',sqlerrm; end;
  begin perform public.process_daily_fatigue(); exception when others then raise warning 'process_daily_fatigue failed: %',sqlerrm; end;
  begin perform public.process_daily_health_cases(); exception when others then raise warning 'process_daily_health_cases failed: %',sqlerrm; end;
  begin perform public.process_daily_morale_v1(); exception when others then raise warning 'process_daily_morale_v1 failed: %',sqlerrm; end;
  begin perform public.process_staff_courses(); exception when others then raise warning 'process_staff_courses failed: %',sqlerrm; end;
  begin perform public.staff_market_run_daily_refresh(150,72); exception when others then raise warning 'staff_market_run_daily_refresh failed: %',sqlerrm; end;
  begin perform public.complete_due_rider_scout_tasks(); exception when others then raise warning 'complete_due_rider_scout_tasks failed: %',sqlerrm; end;
  begin perform public.create_staff_contract_expiry_notifications(); exception when others then raise warning 'create_staff_contract_expiry_notifications failed: %',sqlerrm; end;
  begin perform public.run_daily_market_jobs_detailed(); exception when others then raise warning 'run_daily_market_jobs_detailed failed: %',sqlerrm; end;
  begin perform public.process_daily_coach_training_plans_v1(v_date); exception when others then raise warning 'process_daily_coach_training_plans_v1 failed: %',sqlerrm; end;
  begin perform public.apply_team_policy_rider_support_v1(v_date); exception when others then raise warning 'apply_team_policy_rider_support_v1 failed: %',sqlerrm; end;

  begin
    perform public.ensure_rider_skill_weekly_snapshots_v1(v_date);
  exception when others then
    raise warning 'ensure_rider_skill_weekly_snapshots_v1 failed: %',sqlerrm;
  end;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_due_game_events()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  /* Timed facility upgrades and infrastructure asset deliveries */
  perform public.process_due_infrastructure_jobs();

  /* Timed repairs for infrastructure assets:
     Team Cars, Team Bus, Equipment Van, Mobile Workshop, Medical Van */
  perform public.process_due_infrastructure_asset_repairs();

  /* Timed maintenance for normal cycling equipment:
     frames, wheelsets, tires, groupsets, helmets, shoes */
  perform public.process_due_equipment_maintenance_jobs();

  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_my_notification_read(p_user_notification_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer := 0;
  v_user_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return false;
  end if;

  update public.user_notifications
  set
    status = 'read',
    read_at = now()
  where id = p_user_notification_id
    and user_id = v_user_id
    and status = 'unread'
    and deleted_at is null;

  get diagnostics v_updated = row_count;
  return v_updated > 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_all_my_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer := 0;
  v_user_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return 0;
  end if;

  update public.user_notifications
  set
    status = 'read',
    read_at = now()
  where user_id = v_user_id
    and status = 'unread'
    and deleted_at is null;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_welcome_notification_for_new_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type_id bigint;
  v_notification_id bigint;
begin
  -- Use the new WELCOME_MESSAGE type
  select id
  into v_type_id
  from public.notification_types
  where code = 'WELCOME_MESSAGE'
    and is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'WELCOME_MESSAGE notification type not found or inactive';
  end if;

  -- Prevent duplicate welcome notification for the same user
  if exists (
    select 1
    from public.user_notifications un
    join public.notifications n on n.id = un.notification_id
    where un.user_id = NEW.id
      and un.deleted_at is null
      and n.payload_json ->> 'system_key' = 'welcome_v1'
  ) then
    return NEW;
  end if;

  -- Create welcome notification
  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json
  )
  values (
    v_type_id,
    'Welcome to ProPeloton Manager',
    'Welcome to the game! Start by reading the game manual, joining our Discord, and checking your team dashboard.',
    'admin',
    null,
    '/dashboard/help',
    jsonb_build_object(
      'system_key', 'welcome_v1',
      'category', 'welcome',
      'manual_path', '/dashboard/help',
      'recommended_next_step', 'Open help page'
    )
  )
  returning id into v_notification_id;

  -- Assign to new user as unread
  insert into public.user_notifications (
    user_id,
    notification_id,
    status
  )
  values (
    NEW.id,
    v_notification_id,
    'unread'
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_inbox_message_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.inbox_conversations
  set last_message_at = new.created_at,
      updated_at = now()
  where id = new.conversation_id;

  if new.sender_user_id is not null then
    update public.inbox_conversation_participants
    set last_read_at = new.created_at
    where conversation_id = new.conversation_id
      and user_id = new.sender_user_id;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_start_direct_conversation(p_other_user_id uuid, p_body text, p_subject text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_conversation_id uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated';
  end if;

  if p_other_user_id is null or p_other_user_id = v_me then
    raise exception 'Invalid recipient';
  end if;

  if coalesce(length(trim(p_body)), 0) = 0 then
    raise exception 'Message body is required';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_other_user_id
  ) then
    raise exception 'Recipient not found';
  end if;

  select c.id
  into v_conversation_id
  from public.inbox_conversations c
  where c.conversation_type = 'direct'
    and exists (
      select 1
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
        and cp.user_id = v_me
    )
    and exists (
      select 1
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
        and cp.user_id = p_other_user_id
    )
    and 2 = (
      select count(*)
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
    )
  limit 1;

  if v_conversation_id is null then
    insert into public.inbox_conversations (
      conversation_type,
      subject,
      created_by_user_id
    )
    values (
      'direct',
      nullif(trim(p_subject), ''),
      v_me
    )
    returning id into v_conversation_id;

    insert into public.inbox_conversation_participants (
      conversation_id,
      user_id,
      joined_at,
      last_read_at
    )
    values
      (v_conversation_id, v_me, now(), now()),
      (v_conversation_id, p_other_user_id, now(), null);
  end if;

  insert into public.inbox_messages (
    conversation_id,
    sender_user_id,
    sender_kind,
    sender_label,
    body
  )
  values (
    v_conversation_id,
    v_me,
    'user',
    null,
    trim(p_body)
  );

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_send_message(p_conversation_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_message_id uuid;
  v_type text;
begin
  if v_me is null then
    raise exception 'Not authenticated';
  end if;

  if coalesce(length(trim(p_body)), 0) = 0 then
    raise exception 'Message body is required';
  end if;

  select conversation_type
  into v_type
  from public.inbox_conversations
  where id = p_conversation_id;

  if v_type is null then
    raise exception 'Conversation not found';
  end if;

  if v_type <> 'direct' then
    raise exception 'Replies are disabled for admin messages';
  end if;

  if not exists (
    select 1
    from public.inbox_conversation_participants cp
    where cp.conversation_id = p_conversation_id
      and cp.user_id = v_me
  ) then
    raise exception 'Forbidden';
  end if;

  insert into public.inbox_messages (
    conversation_id,
    sender_user_id,
    sender_kind,
    sender_label,
    body
  )
  values (
    p_conversation_id,
    v_me,
    'user',
    null,
    trim(p_body)
  )
  returning id into v_message_id;

  return v_message_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_mark_conversation_read(p_conversation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer;
begin
  update public.inbox_conversation_participants
  set last_read_at = now()
  where conversation_id = p_conversation_id
    and user_id = auth.uid();

  get diagnostics v_updated = row_count;
  return v_updated > 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_list_threads()
 RETURNS TABLE(conversation_id uuid, conversation_type text, subject text, display_name text, other_user_id uuid, last_message_preview text, last_message_at timestamp with time zone, unread_count integer, can_reply boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'Not authenticated';
  end if;

  return query
  select
    c.id as conversation_id,
    c.conversation_type,
    c.subject,
    case
      when c.conversation_type = 'admin_direct' then 'Admin'
      else coalesce(
        nullif(trim(concat(coalesce(p2.first_name, ''), ' ', coalesce(p2.last_name, ''))), ''),
        p2.username,
        p2.email,
        'Conversation'
      )
    end as display_name,
    op.user_id as other_user_id,
    lm.body as last_message_preview,
    coalesce(lm.created_at, c.last_message_at, c.created_at) as last_message_at,
    (
      select count(*)::integer
      from public.inbox_messages mu
      where mu.conversation_id = c.id
        and mu.created_at > coalesce(cp.last_read_at, '-infinity'::timestamptz)
        and (mu.sender_user_id is null or mu.sender_user_id <> v_me)
    ) as unread_count,
    (c.conversation_type = 'direct') as can_reply
  from public.inbox_conversation_participants cp
  join public.inbox_conversations c
    on c.id = cp.conversation_id
  left join lateral (
    select cp2.user_id
    from public.inbox_conversation_participants cp2
    where cp2.conversation_id = c.id
      and cp2.user_id <> v_me
    limit 1
  ) op on true
  left join public.profiles p2
    on p2.id = op.user_id
  left join lateral (
    select m.body, m.created_at
    from public.inbox_messages m
    where m.conversation_id = c.id
    order by m.created_at desc
    limit 1
  ) lm on true
  where cp.user_id = v_me
    and cp.archived_at is null
  order by coalesce(lm.created_at, c.last_message_at, c.created_at) desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_get_messages(p_conversation_id uuid)
 RETURNS TABLE(id uuid, conversation_id uuid, sender_user_id uuid, sender_kind text, sender_display_name text, body text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'Not authenticated';
  end if;

  if not exists (
    select 1
    from public.inbox_conversation_participants cp
    where cp.conversation_id = p_conversation_id
      and cp.user_id = v_me
  ) then
    raise exception 'Forbidden';
  end if;

  return query
  select
    m.id,
    m.conversation_id,
    m.sender_user_id,
    m.sender_kind,
    case
      when m.sender_kind = 'user' then
        coalesce(
          nullif(trim(concat(coalesce(p.first_name, ''), ' ', coalesce(p.last_name, ''))), ''),
          p.username,
          p.email,
          'User'
        )
      else
        coalesce(nullif(trim(m.sender_label), ''), 'Admin')
    end as sender_display_name,
    m.body,
    m.created_at
  from public.inbox_messages m
  left join public.profiles p
    on p.id = m.sender_user_id
  where m.conversation_id = p_conversation_id
  order by m.created_at asc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_get_or_create_admin_conversation(p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conversation_id uuid;
begin
  if p_user_id is null then
    raise exception 'User is required';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = p_user_id
  ) then
    raise exception 'User not found';
  end if;

  select c.id
  into v_conversation_id
  from public.inbox_conversations c
  where c.conversation_type = 'admin_direct'
    and exists (
      select 1
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
        and cp.user_id = p_user_id
    )
    and 1 = (
      select count(*)
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
    )
  limit 1;

  if v_conversation_id is null then
    insert into public.inbox_conversations (
      conversation_type,
      subject,
      created_by_user_id
    )
    values (
      'admin_direct',
      'Admin',
      null
    )
    returning id into v_conversation_id;

    insert into public.inbox_conversation_participants (
      conversation_id,
      user_id,
      joined_at,
      last_read_at
    )
    values (
      v_conversation_id,
      p_user_id,
      now(),
      null
    );
  end if;

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_send_admin_message_to_user(p_user_id uuid, p_subject text, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conversation_id uuid;
begin
  if coalesce(length(trim(p_subject)), 0) = 0 then
    raise exception 'Subject is required';
  end if;

  if coalesce(length(trim(p_body)), 0) = 0 then
    raise exception 'Message body is required';
  end if;

  v_conversation_id := public.inbox_get_or_create_admin_conversation(p_user_id);

  update public.inbox_conversations
  set subject = trim(p_subject)
  where id = v_conversation_id;

  insert into public.inbox_messages (
    conversation_id,
    sender_user_id,
    sender_kind,
    sender_label,
    body
  )
  values (
    v_conversation_id,
    null,
    'admin',
    'Admin',
    trim(p_body)
  );

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_send_admin_message_to_all_users(p_subject text, p_body text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_total integer := 0;
begin
  if coalesce(length(trim(p_subject)), 0) = 0 then
    raise exception 'Subject is required';
  end if;

  if coalesce(length(trim(p_body)), 0) = 0 then
    raise exception 'Message body is required';
  end if;

  for r in
    select id
    from public.profiles
  loop
    perform public.inbox_send_admin_message_to_user(
      r.id,
      p_subject,
      p_body
    );
    v_total := v_total + 1;
  end loop;

  return v_total;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.inbox_seed_direct_message(p_sender_user_id uuid, p_recipient_user_id uuid, p_body text, p_subject text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_conversation_id uuid;
begin
  if p_sender_user_id is null or p_recipient_user_id is null or p_sender_user_id = p_recipient_user_id then
    raise exception 'Invalid users';
  end if;

  if coalesce(length(trim(p_body)), 0) = 0 then
    raise exception 'Message body is required';
  end if;

  if not exists (select 1 from public.profiles where id = p_sender_user_id) then
    raise exception 'Sender not found';
  end if;

  if not exists (select 1 from public.profiles where id = p_recipient_user_id) then
    raise exception 'Recipient not found';
  end if;

  select c.id
  into v_conversation_id
  from public.inbox_conversations c
  where c.conversation_type = 'direct'
    and exists (
      select 1
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
        and cp.user_id = p_sender_user_id
    )
    and exists (
      select 1
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
        and cp.user_id = p_recipient_user_id
    )
    and 2 = (
      select count(*)
      from public.inbox_conversation_participants cp
      where cp.conversation_id = c.id
    )
  limit 1;

  if v_conversation_id is null then
    insert into public.inbox_conversations (
      conversation_type,
      subject,
      created_by_user_id
    )
    values (
      'direct',
      nullif(trim(p_subject), ''),
      p_sender_user_id
    )
    returning id into v_conversation_id;

    insert into public.inbox_conversation_participants (
      conversation_id,
      user_id,
      joined_at,
      last_read_at
    )
    values
      (v_conversation_id, p_sender_user_id, now(), now()),
      (v_conversation_id, p_recipient_user_id, now(), null);
  end if;

  insert into public.inbox_messages (
    conversation_id,
    sender_user_id,
    sender_kind,
    sender_label,
    body
  )
  values (
    v_conversation_id,
    p_sender_user_id,
    'user',
    null,
    trim(p_body)
  );

  return v_conversation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_my_game_data(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin

-- mark club deleted
update public.clubs
set deleted_at = now()
where owner_user_id = p_user_id;

-- anonymize profile safely
update public.profiles
set
  username = 'deleted_' || substring(p_user_id::text,1,8),
  email = 'deleted_' || substring(p_user_id::text,1,8) || '@deleted.local',
  first_name = 'Deleted',
  last_name = 'User',
  city = 'Deleted',
  country = 'XX'
where id = p_user_id;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_referral_code(len integer DEFAULT 10)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  chars text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  result text := '';
  i int;
begin
  for i in 1..len loop
    result := result || substr(chars, 1 + floor(random() * length(chars))::int, 1);
  end loop;
  return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_club_referral(p_referral_code text, p_referred_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_referrer_club_id uuid;
  v_referrer_owner uuid;
begin
  if v_user_id is null then raise exception 'Not authenticated'; end if;

  if not exists (
    select 1 from public.clubs c
    where c.id = p_referred_club_id
      and c.owner_user_id = v_user_id
      and c.deleted_at is null
      and c.is_ai = false
      and c.club_type = 'main'
  ) then
    raise exception 'Referred club does not belong to authenticated user';
  end if;

  select c.id, c.owner_user_id
  into v_referrer_club_id, v_referrer_owner
  from public.clubs c
  where c.referral_code = upper(btrim(p_referral_code))
    and c.deleted_at is null
    and c.is_ai = false
    and c.club_type = 'main'
    and c.owner_user_id is not null
  limit 1;

  if v_referrer_club_id is null then return; end if;
  if v_referrer_owner = v_user_id then return; end if;

  insert into public.club_referrals (
    referrer_club_id, referred_user_id, referred_club_id,
    referral_code_used, status
  ) values (
    v_referrer_club_id, v_user_id, p_referred_club_id,
    upper(btrim(p_referral_code)), 'pending'
  ) on conflict (referred_user_id) do nothing;

  perform public.referral_try_paid_conversion_from_history_v1(v_user_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_get_or_create_club_account(p_club_id uuid, p_currency text DEFAULT 'CASH'::text, p_kind text DEFAULT 'main'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account_id uuid;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required';
  end if;

  if p_currency is null or btrim(p_currency) = '' then
    raise exception 'p_currency is required';
  end if;

  if p_kind is null or btrim(p_kind) = '' then
    raise exception 'p_kind is required';
  end if;

  -- Allow SQL editor / cron / service_role runs.
  -- Only enforce membership when there is a real authenticated user.
  if auth.uid() is not null
     and coalesce(auth.role(), '') <> 'service_role'
     and not finance.is_club_member_or_owner(p_club_id, auth.uid()) then
    raise exception 'You are not allowed to access finance account for this club';
  end if;

  insert into finance.accounts (club_id, currency, kind)
  values (p_club_id, p_currency, p_kind)
  on conflict (club_id, currency, kind) do nothing;

  select a.id
  into v_account_id
  from finance.accounts a
  where a.club_id = p_club_id
    and a.currency = p_currency
    and a.kind = p_kind
  limit 1;

  if v_account_id is null then
    raise exception 'Could not get or create club account for club %, currency %, kind %',
      p_club_id, p_currency, p_kind;
  end if;

  return v_account_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_transfer_club_to_club(p_from_club_id uuid, p_to_club_id uuid, p_amount bigint, p_currency text DEFAULT 'CASH'::text, p_type text DEFAULT 'club_transfer'::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid;
  v_from_acct uuid;
  v_to_acct uuid;
  v_tx uuid;
  v_from_balance bigint;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  if not finance.can_spend_from_club(p_from_club_id, v_uid) then
    raise exception 'Not allowed to spend from this club';
  end if;

  perform public.finance_get_or_create_club_account(p_from_club_id, p_currency, 'main');
  perform public.finance_get_or_create_club_account(p_to_club_id, p_currency, 'main');

  select id
  into v_from_acct
  from finance.accounts
  where club_id = p_from_club_id
    and currency = p_currency
    and kind = 'main';

  select id
  into v_to_acct
  from finance.accounts
  where club_id = p_to_club_id
    and currency = p_currency
    and kind = 'main';

  if p_idempotency_key is not null then
    insert into finance.transactions(type, created_by, idempotency_key, metadata)
    values (p_type, v_uid, p_idempotency_key, coalesce(p_metadata, '{}'::jsonb))
    on conflict (created_by, idempotency_key) do nothing
    returning id into v_tx;

    if v_tx is null then
      select id
      into v_tx
      from finance.transactions
      where created_by = v_uid
        and idempotency_key = p_idempotency_key;

      if p_type = 'rider_transfer_fee_paid' and p_amount > 0 then
        perform public.finance_apply_income_tax(
          p_to_club_id,
          v_tx,
          p_type,
          p_amount,
          coalesce(p_metadata, '{}'::jsonb) ||
          jsonb_build_object(
            'reason', 'rider_transfer_fee_income',
            'buyer_club_id', p_from_club_id,
            'seller_club_id', p_to_club_id
          )
        );
      end if;

      return v_tx;
    end if;
  else
    insert into finance.transactions(type, created_by, metadata)
    values (p_type, v_uid, coalesce(p_metadata, '{}'::jsonb))
    returning id into v_tx;
  end if;

  insert into finance.account_balances(account_id, balance)
  values (v_from_acct, 0)
  on conflict (account_id) do nothing;

  select balance
  into v_from_balance
  from finance.account_balances
  where account_id = v_from_acct
  for update;

  if v_from_balance < p_amount then
    raise exception 'Insufficient funds: have %, need %', v_from_balance, p_amount;
  end if;

  insert into finance.entries(transaction_id, account_id, amount, memo)
  values
    (v_tx, v_from_acct, -p_amount, 'debit'),
    (v_tx, v_to_acct,    p_amount, 'credit');

  if p_type = 'rider_transfer_fee_paid' and p_amount > 0 then
    perform public.finance_apply_income_tax(
      p_to_club_id,
      v_tx,
      p_type,
      p_amount,
      coalesce(p_metadata, '{}'::jsonb) ||
      jsonb_build_object(
        'reason', 'rider_transfer_fee_income',
        'buyer_club_id', p_from_club_id,
        'seller_club_id', p_to_club_id
      )
    );
  end if;

  return v_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_recompute_weekly_summaries(p_club_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform set_config('finance.internal','1',true);

  with club_wallet as (
    select a.club_id,a.id account_id
    from finance.accounts a
    where a.club_id is not null and a.currency='CASH' and a.kind='main'
      and (p_club_id is null or a.club_id=p_club_id)
  ), sums as (
    select w.club_id,
      coalesce(sum(case when e.amount>0 then e.amount else 0 end),0) income,
      coalesce(sum(case when e.amount<0 then -e.amount else 0 end),0) expenses
    from club_wallet w
    join finance.entries e on e.account_id=w.account_id
    join finance.transactions t on t.id=e.transaction_id
    left join finance.transaction_types tt on tt.code=t.type
    where t.type<>'opening_balance'
      and coalesce(tt.is_user_visible,true)=true
      and not exists(select 1 from finance.transaction_voids tv where tv.source_transaction_id=t.id)
      and t.created_at>=now()-interval '7 days'
    group by w.club_id
  )
  update public.club_finance_summary s
  set weekly_income=coalesce(x.income,0)::numeric,
      weekly_expenses=coalesce(x.expenses,0)::numeric,
      updated_at=now()
  from sums x
  where s.club_id=x.club_id and (p_club_id is null or s.club_id=p_club_id);

  update public.club_finance_summary s
  set weekly_income=0,weekly_expenses=0,updated_at=now()
  where (p_club_id is null or s.club_id=p_club_id)
    and exists(select 1 from finance.accounts a where a.club_id=s.club_id and a.currency='CASH' and a.kind='main')
    and not exists(
      select 1
      from finance.accounts a
      join finance.entries e on e.account_id=a.id
      join finance.transactions t on t.id=e.transaction_id
      left join finance.transaction_types tt on tt.code=t.type
      where a.club_id=s.club_id and a.currency='CASH' and a.kind='main'
        and t.type<>'opening_balance'
        and coalesce(tt.is_user_visible,true)=true
        and not exists(select 1 from finance.transaction_voids tv where tv.source_transaction_id=t.id)
        and t.created_at>=now()-interval '7 days'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public._guard_clubs_cash_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE'
     and new.cash_balance is distinct from old.cash_balance then
    if coalesce(current_setting('finance.internal', true), '') <> '1' then
      raise exception 'cash_balance is managed by the finance ledger';
    end if;
  end if;

  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public._guard_club_finance_summary()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE' then
    if (new.current_balance is distinct from old.current_balance)
       or (new.weekly_income is distinct from old.weekly_income)
       or (new.weekly_expenses is distinct from old.weekly_expenses)
       or (new.wage_total is distinct from old.wage_total) then
      if coalesce(current_setting('finance.internal', true), '') <> '1' then
        raise exception 'club_finance_summary is managed by the finance ledger';
      end if;
    end if;
  end if;
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.finance_spend_from_club_non_ai_core_v1(p_club_id uuid, p_amount bigint, p_type text DEFAULT 'expense'::text, p_sink_code text DEFAULT 'SINK'::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_uid uuid;
  v_role text;
  v_internal boolean := coalesce(current_setting('finance.internal', true), '') = '1';
  v_club_acct uuid;
  v_sink uuid;
  v_tx uuid;
  v_balance bigint;
  v_game_ts timestamptz;
  v_game_metadata jsonb;
  v_metadata jsonb;
begin
  v_uid := auth.uid();
  v_role := current_setting('request.jwt.claim.role', true);

  if v_internal and v_uid is null then
    select c.owner_user_id
    into v_uid
    from public.clubs c
    where c.id = p_club_id
    limit 1;
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be > 0';
  end if;

  if v_uid is not null and coalesce(v_role, '') <> 'service_role' and not v_internal then
    if not finance.can_spend_from_club(p_club_id, v_uid) then
      raise exception 'Not allowed to spend from this club';
    end if;
  end if;

  v_game_ts := public.get_current_game_timestamp();

  v_game_metadata := jsonb_build_object(
    'game_date',
    jsonb_build_object(
      'season', public.season_from_game_timestamp(v_game_ts),
      'month', extract(month from v_game_ts at time zone 'UTC')::int,
      'day', extract(day from v_game_ts at time zone 'UTC')::int,
      'hour', extract(hour from v_game_ts at time zone 'UTC')::int,
      'minute', extract(minute from v_game_ts at time zone 'UTC')::int
    )
  );

  v_metadata := coalesce(p_metadata, '{}'::jsonb) || v_game_metadata;

  perform public.finance_get_or_create_club_account(p_club_id, 'CASH', 'main');

  select a.id
  into v_club_acct
  from finance.accounts a
  where a.club_id = p_club_id
    and a.currency = 'CASH'
    and a.kind = 'main';

  select a.id
  into v_sink
  from finance.accounts a
  where a.system_code = p_sink_code
    and a.currency = 'CASH'
    and a.kind = 'main';

  if v_sink is null then
    raise exception 'Unknown sink_code: %', p_sink_code;
  end if;

  if p_idempotency_key is not null then
    insert into finance.transactions(type, created_by, idempotency_key, metadata)
    values (p_type, v_uid, p_idempotency_key, v_metadata)
    on conflict (created_by, idempotency_key) do nothing
    returning id into v_tx;

    if v_tx is null then
      select t.id
      into v_tx
      from finance.transactions t
      where t.created_by is not distinct from v_uid
        and t.idempotency_key = p_idempotency_key
      order by t.created_at desc
      limit 1;

      if v_tx is not null then
        return v_tx;
      end if;

      select t.id
      into v_tx
      from finance.transactions t
      where t.idempotency_key = p_idempotency_key
      order by t.created_at desc
      limit 1;

      if v_tx is not null then
        return v_tx;
      end if;
    end if;
  else
    insert into finance.transactions(type, created_by, metadata)
    values (p_type, v_uid, v_metadata)
    returning id into v_tx;
  end if;

  insert into finance.account_balances(account_id, balance)
  values (v_club_acct, 0)
  on conflict (account_id) do nothing;

  select b.balance
  into v_balance
  from finance.account_balances b
  where b.account_id = v_club_acct
  for update;

  if v_balance < p_amount then
    raise exception 'Insufficient funds: have %, need %', v_balance, p_amount;
  end if;

  insert into finance.entries(transaction_id, account_id, amount, memo)
  values
    (v_tx, v_club_acct, -p_amount, 'expense debit'),
    (v_tx, v_sink,       p_amount, 'expense credit');

  return v_tx;
end;$function$
;

CREATE OR REPLACE FUNCTION public.finance_grant_new_club_bonus(p_club_id uuid, p_amount bigint DEFAULT NULL::bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_amount bigint;
  v_tx uuid;
  v_club_acct uuid;
  v_treasury uuid;
  v_derived boolean := p_amount is null;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required';
  end if;

  if v_derived then
    v_amount := public.get_club_starting_cash_v1(p_club_id);
    -- AI/developing clubs intentionally use no real starting finance.
    if coalesce(v_amount,0) <= 0 then
      return null;
    end if;
  else
    v_amount := p_amount;
    if v_amount <= 0 then
      raise exception 'Bonus amount must be > 0';
    end if;
  end if;

  insert into finance.accounts(club_id, currency, kind)
  values (p_club_id, 'CASH', 'main')
  on conflict (club_id, currency, kind) do nothing;

  select id into v_club_acct
  from finance.accounts
  where club_id=p_club_id and currency='CASH' and kind='main';

  select id into v_treasury
  from finance.accounts
  where system_code='TREASURY' and currency='CASH' and kind='main';

  if v_treasury is null then
    raise exception 'TREASURY cash account not found';
  end if;

  v_tx := extensions.gen_random_uuid();

  begin
    insert into finance.transactions(id, type, created_by, metadata)
    values (
      v_tx,
      'new_club_bonus',
      auth.uid(),
      jsonb_build_object(
        'club_id', p_club_id,
        'amount', v_amount,
        'source', case when v_derived then 'team_tier_balance_profiles' else 'explicit_amount' end
      )
    );

    insert into finance.event_locks(event_type, club_id, ref_id, transaction_id)
    values ('new_club_bonus', p_club_id, p_club_id, v_tx);
  exception when unique_violation then
    select transaction_id into v_tx
    from finance.event_locks
    where event_type='new_club_bonus' and club_id=p_club_id and ref_id=p_club_id;
    return v_tx;
  end;

  insert into finance.entries(transaction_id, account_id, amount, memo)
  values
    (v_tx, v_treasury, -v_amount, 'new club starting cash debit'),
    (v_tx, v_club_acct, v_amount, 'new club starting cash credit');

  return v_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_award_race_prize(p_club_id uuid, p_race_id uuid, p_amount bigint, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tx uuid;
  v_club_acct uuid;
  v_treasury uuid;
  v_event_ref uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception
      'Only service_role can award race prizes';
  end if;

  if p_club_id is null then
    raise exception 'p_club_id is required';
  end if;

  if p_race_id is null then
    raise exception 'p_race_id is required';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Prize amount must be > 0';
  end if;

  /*
   * Every individual prize-award row must have its own
   * finance idempotency reference.
   *
   * Fall back to the race id only for older callers.
   */
  v_event_ref :=
    coalesce(
      nullif(
        p_metadata ->> 'race_prize_award_id',
        ''
      )::uuid,
      p_race_id
    );

  insert into finance.accounts (
    club_id,
    currency,
    kind
  )
  values (
    p_club_id,
    'CASH',
    'main'
  )
  on conflict (
    club_id,
    currency,
    kind
  ) do nothing;

  select account.id
  into v_club_acct
  from finance.accounts account
  where account.club_id = p_club_id
    and account.currency = 'CASH'
    and account.kind = 'main';

  select account.id
  into v_treasury
  from finance.accounts account
  where account.system_code = 'TREASURY'
    and account.currency = 'CASH'
    and account.kind = 'main';

  if v_club_acct is null then
    raise exception
      'Club cash account not found for club %',
      p_club_id;
  end if;

  if v_treasury is null then
    raise exception
      'TREASURY cash account not found';
  end if;

  v_tx := extensions.gen_random_uuid();

  begin
    insert into finance.transactions (
      id,
      type,
      created_by,
      metadata
    )
    values (
      v_tx,
      'race_prize',
      auth.uid(),
      coalesce(p_metadata, '{}'::jsonb) ||
      jsonb_build_object(
        'club_id', p_club_id,
        'race_id', p_race_id,
        'amount', p_amount,
        'finance_event_ref', v_event_ref
      )
    );

    insert into finance.event_locks (
      event_type,
      club_id,
      ref_id,
      transaction_id
    )
    values (
      'race_prize',
      p_club_id,
      v_event_ref,
      v_tx
    );

  exception
    when unique_violation then
      /*
       * This award has already been paid.
       *
       * Return the original transaction without applying tax
       * or creating ledger entries again.
       */
      select event_lock.transaction_id
      into v_tx
      from finance.event_locks event_lock
      where event_lock.event_type = 'race_prize'
        and event_lock.club_id = p_club_id
        and event_lock.ref_id = v_event_ref;

      return v_tx;
  end;

  insert into finance.entries (
    transaction_id,
    account_id,
    amount,
    memo
  )
  values
    (
      v_tx,
      v_treasury,
      -p_amount,
      'race prize debit'
    ),
    (
      v_tx,
      v_club_acct,
      p_amount,
      'race prize credit'
    );

  perform public.finance_apply_income_tax(
    p_club_id,
    v_tx,
    'race_prize',
    p_amount,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return v_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_charge_race_cost_non_ai_core_v1(p_club_id uuid, p_race_id uuid, p_amount bigint, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tx uuid;
  v_uid uuid;
  v_club_acct uuid;
  v_sink uuid;
  v_balance bigint;
begin
  v_uid := auth.uid();

  if auth.role() <> 'service_role' then
    if v_uid is null then raise exception 'Not authenticated'; end if;
    if not finance.can_spend_from_club(p_club_id, v_uid) then
      raise exception 'Not allowed to charge race costs for this club';
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Race cost amount must be > 0';
  end if;

  -- ensure club account exists
  insert into finance.accounts(club_id, currency, kind)
  values (p_club_id, 'CASH', 'main')
  on conflict (club_id, currency, kind) do nothing;

  select id into v_club_acct
  from finance.accounts
  where club_id=p_club_id and currency='CASH' and kind='main';

  select id into v_sink
  from finance.accounts
  where system_code='SINK' and currency='CASH' and kind='main';

  v_tx := extensions.gen_random_uuid();

  begin
    insert into finance.transactions(id, type, created_by, metadata)
    values (
      v_tx,
      'race_cost',
      v_uid,
      p_metadata || jsonb_build_object('club_id', p_club_id, 'race_id', p_race_id, 'amount', p_amount)
    );

    insert into finance.event_locks(event_type, club_id, ref_id, transaction_id)
    values ('race_cost', p_club_id, p_race_id, v_tx);

  exception when unique_violation then
    select transaction_id into v_tx
    from finance.event_locks
    where event_type='race_cost' and club_id=p_club_id and ref_id=p_race_id;

    return v_tx;
  end;

  -- lock + funds check (only meaningful for non-service_role too, but safe always)
  insert into finance.account_balances(account_id, balance)
  values (v_club_acct, 0)
  on conflict (account_id) do nothing;

  select balance into v_balance
  from finance.account_balances
  where account_id = v_club_acct
  for update;

  if v_balance < p_amount then
    raise exception 'Insufficient funds: have %, need %', v_balance, p_amount;
  end if;

  insert into finance.entries(transaction_id, account_id, amount, memo)
  values
    (v_tx, v_club_acct, -p_amount, 'race cost debit'),
    (v_tx, v_sink,       p_amount, 'race cost credit');

  return v_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_get_club_cashflow_series(p_club_id uuid, p_days integer DEFAULT 90)
 RETURNS TABLE(bucket_date date, income bigint, expenses bigint, net bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_days integer;
  v_restart_at timestamptz;
  v_start_date date;
  v_end_date date := current_date;
begin
  v_user_id := auth.uid();
  v_days := greatest(1, coalesce(p_days, 90));

  if p_club_id is null then
    raise exception 'Club id is required.';
  end if;

  if v_user_id is not null and not exists (
    select 1
    from public.clubs c
    where c.id = p_club_id
      and c.owner_user_id = v_user_id
      and coalesce(c.club_type::text, 'main') = 'main'
  ) then
    raise exception 'You can only view finance cashflow for your own main club.';
  end if;

  select max(h.created_at)
    into v_restart_at
  from public.club_restart_history h
  where h.club_id = p_club_id;

  v_start_date := greatest(
    current_date - (v_days - 1),
    coalesce(v_restart_at::date, current_date - (v_days - 1))
  );

  return query
  with days as (
    select generate_series(
      v_start_date,
      v_end_date,
      interval '1 day'
    )::date as bucket_date
  ),
  club_transaction_net as (
    select
      t.created_at::date as bucket_date,
      sum(e.amount)::bigint as net_amount
    from finance.transactions t
    join finance.entries e
      on e.transaction_id = t.id
    join finance.accounts a
      on a.id = e.account_id
    left join finance.transaction_types tt
      on tt.code = t.type
    where a.club_id = p_club_id
      and a.currency = 'CASH'
      and a.kind = 'main'
      and t.created_at >= v_start_date::timestamptz
      and t.created_at < (v_end_date + 1)::timestamptz
      and t.created_at > coalesce(v_restart_at, '-infinity'::timestamptz)
      and coalesce(tt.is_user_visible, true) = true
      and not exists (
        select 1
        from finance.transaction_voids v
        where v.source_transaction_id = t.id
      )
      and not exists (
        select 1
        from finance.transaction_voids v
        where v.correction_transaction_id = t.id
      )
    group by t.id, t.created_at::date
  ),
  daily as (
    select
      ctn.bucket_date,
      sum(greatest(ctn.net_amount, 0::bigint))::bigint as income,
      sum(greatest(-ctn.net_amount, 0::bigint))::bigint as expenses,
      sum(ctn.net_amount)::bigint as net
    from club_transaction_net ctn
    group by ctn.bucket_date
  )
  select
    d.bucket_date,
    coalesce(daily.income, 0)::bigint as income,
    coalesce(daily.expenses, 0)::bigint as expenses,
    coalesce(daily.net, 0)::bigint as net
  from days d
  left join daily
    on daily.bucket_date = d.bucket_date
  order by d.bucket_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.apply_coin_delta(p_user_id uuid, p_delta integer, p_reason text, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb;
  v_system_key text;
  v_current_balance integer;
  v_new_balance integer;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required';
  END IF;

  IF p_delta IS NULL THEN
    RAISE EXCEPTION 'p_delta is required';
  END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'p_reason is required';
  END IF;

  v_payload := COALESCE(
    p_payload_json,
    '{}'::jsonb
  );

  v_system_key := NULLIF(
    btrim(
      COALESCE(
        v_payload ->> 'system_key',
        ''
      )
    ),
    ''
  );

  /*
   * Ensure the wallet exists before locking it.
   */
  INSERT INTO public.user_wallets (
    user_id,
    balance
  )
  VALUES (
    p_user_id,
    0
  )
  ON CONFLICT (user_id) DO NOTHING;

  /*
   * Serialize all wallet changes for this user.
   */
  SELECT w.balance
  INTO v_current_balance
  FROM public.user_wallets w
  WHERE w.user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'Wallet could not be loaded for user %.',
      p_user_id;
  END IF;

  /*
   * Automated transactions carrying the same system key are idempotent.
   * A repeated Stripe webhook or Premium invoice does nothing.
   */
  IF v_system_key IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.user_coin_ledger l
       WHERE l.user_id = p_user_id
         AND l.payload_json ->> 'system_key' =
           v_system_key
     )
  THEN
    RETURN;
  END IF;

  v_new_balance :=
    v_current_balance + p_delta;

  /*
   * Never silently clamp an insufficient debit to zero.
   */
  IF v_new_balance < 0 THEN
    RAISE EXCEPTION
      'Insufficient coins. Current balance: %, requested delta: %.',
      v_current_balance,
      p_delta
      USING ERRCODE = 'P0001';
  END IF;

  /*
   * Insert the exact applied delta.
   * If this insert fails, the wallet is not changed.
   */
  INSERT INTO public.user_coin_ledger (
    user_id,
    delta,
    reason,
    payload_json
  )
  VALUES (
    p_user_id,
    p_delta,
    btrim(p_reason),
    v_payload
  );

  UPDATE public.user_wallets
  SET balance = v_new_balance
  WHERE user_id = p_user_id;

  RETURN;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.grant_welcome_coins_for_new_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Prevent duplicate welcome coins (same style as welcome notification)
  if exists (
    select 1
    from public.user_coin_ledger l
    where l.user_id = NEW.id
      and (l.payload_json ->> 'system_key') = 'welcome_coins_v1'
  ) then
    return NEW;
  end if;

  -- Grant 20 coins as welcome gift
  perform public.apply_coin_delta(
    NEW.id,
    20,
    'welcome',
    jsonb_build_object(
      'system_key', 'welcome_coins_v1',
      'category', 'welcome',
      'welcome_amount', 20
    )
  );

  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_tick_if_needed()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_season int;
  v_old_month int;
  v_old_day int;
  v_old_hour int;
  v_old_minute int;
  v_old_tick bigint;
  v_state_paused boolean;
  v_last_advanced_at timestamptz;
  cfg public.game_clock_config%rowtype;
  v_base_ts timestamptz;
  v_new_ts timestamptz;
  v_old_date date;
  v_new_date date;
  v_elapsed_real_seconds numeric;
  v_elapsed_game_seconds bigint;
  v_minutes_to_advance int;
  v_consumed_real_seconds numeric;
  v_days_crossed int := 0;
  v_boundary jsonb;
  v_crossed_season boolean := false;
begin
  if not pg_try_advisory_xact_lock(hashtext('public.run_daily_tick_if_needed')::bigint) then
    return false;
  end if;

  select gs.season_number,gs.month_number::int,gs.day_number::int,
         coalesce(gs.hour_number,0)::int,coalesce(gs.minute_number,0)::int,
         gs.tick_version,gs.is_paused,gs.last_advanced_at
  into v_old_season,v_old_month,v_old_day,v_old_hour,v_old_minute,
       v_old_tick,v_state_paused,v_last_advanced_at
  from public.game_state gs where gs.id=true for update;

  if not found then raise exception 'game_state is not initialized'; end if;
  if coalesce(v_state_paused,false) then return false; end if;

  select * into cfg from public.game_clock_config where id=true;
  if not found then raise exception 'game_clock_config is not initialized'; end if;
  if coalesce(cfg.is_paused,false) then return false; end if;
  if coalesce(cfg.speed_multiplier,0)<=0 then return false; end if;

  v_base_ts:=make_timestamptz(1999+v_old_season,v_old_month,v_old_day,v_old_hour,v_old_minute,0,'UTC');
  v_old_date:=v_base_ts::date;

  if v_last_advanced_at is null then
    update public.game_state set last_advanced_at=clock_timestamp() where id=true;
    return false;
  end if;

  v_elapsed_real_seconds:=extract(epoch from (clock_timestamp()-v_last_advanced_at));
  v_elapsed_game_seconds:=floor(greatest(0,v_elapsed_real_seconds)*cfg.speed_multiplier)::bigint;
  v_minutes_to_advance:=floor(v_elapsed_game_seconds/60.0)::int;
  v_minutes_to_advance:=least(v_minutes_to_advance,60);
  if v_minutes_to_advance<1 then return false; end if;

  v_new_ts:=v_base_ts+make_interval(mins=>v_minutes_to_advance);
  v_new_date:=v_new_ts::date;
  v_days_crossed:=greatest(0,v_new_date-v_old_date);
  v_crossed_season:=public.season_from_game_date(v_new_date)>public.season_from_game_date(v_old_date);

  if v_crossed_season then
    -- v4: the season boundary is owned completely by the universal v2
    -- boundary controller. The ordinary clock never writes Jan 1 itself.
    v_boundary:=public.season_transition_boundary_controller_v2(
      v_old_date,
      v_new_date,
      true
    );

    if not coalesce((v_boundary->>'ok')::boolean,false) then
      -- Fail closed. Never allow the ordinary clock to jump past a failed
      -- transition boundary.
      update public.game_state
      set is_paused=true,last_advanced_at=clock_timestamp()
      where id=true;
      update public.game_clock_config
      set is_paused=true,base_real_at=clock_timestamp()
      where id=true;
      return false;
    end if;

    return true;
  end if;

  if v_new_date>v_old_date then
    insert into public.game_daily_tick_backlog_v1(
      current_game_date,season_number,month_number,day_number,tick_version,status,source,payload
    )
    select d::date,public.season_from_game_date(d::date),extract(month from d)::int,
           extract(day from d)::int,coalesce(v_old_tick,0)+(d::date-v_old_date),
           'pending','clock_only_tick_v4',
           jsonb_build_object('reason','daily processors deferred from clock tick',
             'old_clock_date',v_old_date,'new_clock_date',v_new_date,
             'old_clock_ts',v_base_ts,'new_clock_ts',v_new_ts,
             'created_by','run_daily_tick_if_needed_clock_only_v4',
             'season_boundary_guarded',false,'created_at',now())
    from generate_series(v_old_date+1,v_new_date,interval '1 day') g(d)
    on conflict(current_game_date) do update
    set status=case when public.game_daily_tick_backlog_v1.status='processed'
                    then public.game_daily_tick_backlog_v1.status else 'pending' end,
        updated_at=now(),
        payload=public.game_daily_tick_backlog_v1.payload||excluded.payload||
                jsonb_build_object('touched_by_clock_tick_v4_at',now());
  end if;

  v_consumed_real_seconds:=(v_minutes_to_advance*60.0)/cfg.speed_multiplier;

  update public.game_state
  set season_number=public.season_from_game_date(v_new_ts::date),
      month_number=extract(month from v_new_ts)::smallint,
      day_number=extract(day from v_new_ts)::smallint,
      hour_number=extract(hour from v_new_ts)::smallint,
      minute_number=extract(minute from v_new_ts)::smallint,
      tick_version=coalesce(v_old_tick,0)+v_days_crossed,
      last_advanced_at=v_last_advanced_at+make_interval(secs=>v_consumed_real_seconds::double precision)
  where id=true;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._generate_domestic_roster_for_club_core_v1(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_country_code text;
  v_tier_key text;
  v_profile public.team_tier_balance_profiles%rowtype;

  v_first_count int;
  v_last_count int;

  v_role_rec record;

  v_rider_id uuid;
  v_first_name text;
  v_last_name text;

  v_game_date date;
  v_age_years int;
  v_birth_date date;

  v_target int;
  v_skill_min int;
  v_skill_max int;

  v_sprint int;
  v_climbing int;
  v_time_trial int;
  v_endurance int;
  v_flat int;
  v_recovery int;
  v_resistance int;
  v_race_iq int;
  v_teamwork int;

  v_morale int;
  v_potential int;
  v_salary int;
  v_market_value bigint;
begin
  -- Do not duplicate rosters.
  if exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_club_id
  ) then
    return;
  end if;

  select c.country_code
  into v_country_code
  from public.clubs c
  where c.id = p_club_id;

  if v_country_code is null then
    raise exception 'Cannot generate roster. Club % has no country_code.', p_club_id;
  end if;

  select count(*)
  into v_first_count
  from public.first_names_master
  where country_code = v_country_code;

  select count(*)
  into v_last_count
  from public.last_names_master
  where country_code = v_country_code;

  if v_first_count = 0 or v_last_count = 0 then
    raise exception
      'Cannot generate domestic roster for club %. Missing name pool for country_code=% (first_names=% last_names=%).',
      p_club_id, v_country_code, v_first_count, v_last_count;
  end if;

  v_tier_key := public._get_club_balance_tier_key(p_club_id);

  select *
  into v_profile
  from public.team_tier_balance_profiles
  where tier_key = v_tier_key;

  if not found then
    select *
    into v_profile
    from public.team_tier_balance_profiles
    where tier_key = 'amateur';
  end if;

  v_game_date := coalesce(public.get_current_game_date_date(), current_date);

  for v_role_rec in
    select *
    from public.starting_roster_role_profiles
    order by slot_no asc
  loop
    select fn.first_name
    into v_first_name
    from public.first_names_master fn
    where fn.country_code = v_country_code
    order by random()
    limit 1;

    select ln.last_name
    into v_last_name
    from public.last_names_master ln
    where ln.country_code = v_country_code
    order by random()
    limit 1;

    if v_role_rec.is_young_talent then
      v_age_years := public.rand_int(18, 22);
    elsif v_role_rec.is_leader then
      v_age_years := public.rand_int(25, 32);
    elsif v_role_rec.role_group_key in ('sprinter', 'climber', 'leadout_support', 'rouleur') then
      v_age_years := public.rand_int(22, 30);
    else
      v_age_years := public.rand_int(23, 38);
    end if;

    v_birth_date :=
      (
        v_game_date
        - (v_age_years || ' years')::interval
        - (public.rand_int(0, 364) || ' days')::interval
      )::date;

    -- Target current strength.
    if v_role_rec.is_leader then
      v_target := public._clamp_int(
        v_profile.avg_overall_target + public.rand_int(4, 7),
        v_profile.rider_min_overall,
        v_profile.rare_cap_overall
      );
    elsif v_role_rec.is_young_talent then
      v_target := public._clamp_int(
        v_profile.avg_overall_target + public.rand_int(-5, -1),
        v_profile.rider_min_overall,
        v_profile.rider_max_overall
      );
    else
      v_target := public._clamp_int(
        v_profile.avg_overall_target + public.rand_int(-4, 4),
        v_profile.rider_min_overall,
        v_profile.rider_max_overall
      );
    end if;

    v_skill_min := v_profile.rider_min_overall;
    v_skill_max := case when v_role_rec.is_leader then v_profile.rare_cap_overall else v_profile.rider_max_overall end;

    -- Start from role baseline.
    v_sprint     := v_target + public.rand_int(-4, 4);
    v_climbing   := v_target + public.rand_int(-4, 4);
    v_time_trial := v_target + public.rand_int(-5, 3);
    v_endurance  := v_target + public.rand_int(-3, 4);
    v_flat       := v_target + public.rand_int(-3, 4);
    v_recovery   := v_target + public.rand_int(-3, 4);
    v_resistance := v_target + public.rand_int(-3, 4);
    v_race_iq    := v_target + public.rand_int(-3, 4);
    v_teamwork   := v_target + public.rand_int(-3, 4);

    -- Role shaping.
    if v_role_rec.skill_profile = 'leader' then
      v_endurance  := v_endurance + 5;
      v_recovery   := v_recovery + 4;
      v_resistance := v_resistance + 4;
      v_race_iq    := v_race_iq + 6;
      v_teamwork   := v_teamwork + 3;

    elsif v_role_rec.skill_profile = 'sprinter' then
      v_sprint := v_sprint + 8;
      v_flat := v_flat + 5;
      v_climbing := v_climbing - 5;
      v_time_trial := v_time_trial - 3;

    elsif v_role_rec.skill_profile = 'climber' then
      v_climbing := v_climbing + 8;
      v_recovery := v_recovery + 4;
      v_flat := v_flat - 3;
      v_sprint := v_sprint - 4;

    elsif v_role_rec.skill_profile = 'leadout' then
      v_sprint := v_sprint + 4;
      v_flat := v_flat + 6;
      v_teamwork := v_teamwork + 6;
      v_resistance := v_resistance + 3;
      v_climbing := v_climbing - 4;

    elsif v_role_rec.skill_profile = 'rouleur' then
      v_flat := v_flat + 8;
      v_endurance := v_endurance + 5;
      v_resistance := v_resistance + 4;
      v_climbing := v_climbing - 3;

    elsif v_role_rec.skill_profile = 'domestique' then
      v_teamwork := v_teamwork + 8;
      v_endurance := v_endurance + 4;
      v_resistance := v_resistance + 4;
      v_race_iq := v_race_iq + 3;

    elsif v_role_rec.skill_profile = 'breakaway' then
      v_endurance := v_endurance + 7;
      v_resistance := v_resistance + 6;
      v_flat := v_flat + 3;
      v_race_iq := v_race_iq + 3;

    elsif v_role_rec.skill_profile = 'young_talent' then
      v_race_iq := v_race_iq - 2;
      v_teamwork := v_teamwork + 2;
      v_recovery := v_recovery + 3;
    end if;

    v_sprint     := public._clamp_int(v_sprint,     v_skill_min, v_skill_max);
    v_climbing   := public._clamp_int(v_climbing,   v_skill_min, v_skill_max);
    v_time_trial := public._clamp_int(v_time_trial, v_skill_min, v_skill_max);
    v_endurance  := public._clamp_int(v_endurance,  v_skill_min, v_skill_max);
    v_flat       := public._clamp_int(v_flat,       v_skill_min, v_skill_max);
    v_recovery   := public._clamp_int(v_recovery,   v_skill_min, v_skill_max);
    v_resistance := public._clamp_int(v_resistance, v_skill_min, v_skill_max);
    v_race_iq    := public._clamp_int(v_race_iq,    v_skill_min, v_skill_max);
    v_teamwork   := public._clamp_int(v_teamwork,   v_skill_min, v_skill_max);

    v_morale := public.rand_int(50, 70);

    if v_role_rec.is_young_talent then
      v_potential := public._clamp_int(
        public.rand_int(greatest(v_profile.potential_min, 60), v_profile.potential_max),
        v_profile.potential_min,
        v_profile.potential_max
      );
    else
      v_potential := public._clamp_int(
        public.rand_int(v_profile.potential_min, v_profile.potential_max),
        v_profile.potential_min,
        v_profile.potential_max
      );
    end if;

    if v_role_rec.is_leader then
      v_salary := public.rand_int(v_profile.leader_salary_min, v_profile.leader_salary_max);
      v_market_value := public.rand_int(
        greatest(1, floor(v_profile.squad_market_value_min::numeric / 10 * 1.4)::int),
        greatest(1, floor(v_profile.squad_market_value_max::numeric / 10 * 1.8)::int)
      )::bigint;
    else
      v_salary := public.rand_int(v_profile.normal_salary_min, v_profile.normal_salary_max);
      v_market_value := public.rand_int(
        greatest(1, floor(v_profile.squad_market_value_min::numeric / 10 * 0.6)::int),
        greatest(1, floor(v_profile.squad_market_value_max::numeric / 10 * 1.1)::int)
      )::bigint;
    end if;

    insert into public.riders (
      country_code,
      first_name,
      last_name,
      role,
      sprint,
      climbing,
      time_trial,
      endurance,
      flat,
      recovery,
      resistance,
      race_iq,
      teamwork,
      morale,
      potential,
      birth_date,
      salary,
      contract_expires_at,
      release_requested,
      market_value,
      asking_price,
      asking_price_manual,
      asking_price_updated_at,
      fatigue,
      fatigue_updated_on,
      consecutive_heavy_days,
      availability_status
    )
    values (
      v_country_code,
      v_first_name,
      v_last_name,
      v_role_rec.rider_role,
      v_sprint::smallint,
      v_climbing::smallint,
      v_time_trial::smallint,
      v_endurance::smallint,
      v_flat::smallint,
      v_recovery::smallint,
      v_resistance::smallint,
      v_race_iq::smallint,
      v_teamwork::smallint,
      v_morale::smallint,
      v_potential::smallint,
      v_birth_date,
      v_salary,
      (v_game_date + interval '12 months')::date,
      false,
      v_market_value,
      null,
      false,
      now(),
      0,
      v_game_date,
      0,
      'fit'
    )
    returning id into v_rider_id;

    insert into public.club_riders (
      club_id,
      rider_id,
      assigned_role
    )
    values (
      p_club_id,
      v_rider_id,
      v_role_rec.rider_role
    )
    on conflict (club_id, rider_id) do nothing;

    -- Use existing market-value engine when present.
    if to_regprocedure('public.refresh_rider_value_snapshot(uuid)') is not null then
      execute 'select public.refresh_rider_value_snapshot($1)' using v_rider_id;
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.finance_setup_new_club(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
begin
  perform public.finance_get_or_create_club_account(p_club_id, 'CASH', 'main');
  perform public.finance_grant_new_club_bonus(p_club_id, null);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_first_squad_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_club_id uuid;
  v_rider_count integer;
  v_club_name text;
begin
  v_club_id := new.club_id;

  select count(*)
  into v_rider_count
  from public.club_riders
  where club_id = v_club_id;

  select c.name
  into v_club_name
  from public.clubs c
  where c.id = v_club_id;

  if v_rider_count > 18 then
    raise exception
      'First squad limit reached: % already has % riders (max 18).',
      coalesce(v_club_name, 'Your team'),
      v_rider_count
      using errcode = '23514';
  end if;

  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_club_tier_from_world_tier(p_world_tier smallint)
 RETURNS club_tier
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_world_tier is null then
    return 'proteam'::public.club_tier;
  elsif p_world_tier between 1 and 2 then
    return 'worldteam'::public.club_tier;
  elsif p_world_tier between 3 and 4 then
    return 'proteam'::public.club_tier;
  elsif p_world_tier between 5 and 7 then
    return 'continental'::public.club_tier;
  else
    return 'amateur'::public.club_tier;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_age_years_on_game_date(p_birth_date date)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
begin
  if p_birth_date is null then
    return null;
  end if;

  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    return null;
  end if;

  return greatest(
    0,
    extract(year from age(v_game_date, p_birth_date))::integer
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_initial_rider_weekly_salary(p_club_tier club_tier, p_overall smallint, p_age_years integer, p_potential smallint)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_min numeric;
  v_max numeric;
  v_skill_factor numeric;
  v_age_factor numeric := 1.0;
  v_potential_bonus numeric := 1.0;
  v_result integer;
begin
  case p_club_tier
    when 'worldteam' then
      v_min := 1200;
      v_max := 5500;
    when 'proteam' then
      v_min := 500;
      v_max := 2500;
    when 'continental' then
      v_min := 200;
      v_max := 1000;
    when 'amateur' then
      v_min := 150;
      v_max := 400;
  end case;

  v_skill_factor := greatest(
    0,
    least(1, ((coalesce(p_overall, 50) - 45)::numeric / 35::numeric))
  );

  if p_age_years <= 22 then
    v_age_factor := 0.92;
  elsif p_age_years between 23 and 30 then
    v_age_factor := 1.00;
  elsif p_age_years between 31 and 34 then
    v_age_factor := 0.92;
  else
    v_age_factor := 0.80;
  end if;

  if coalesce(p_potential, 50) >= coalesce(p_overall, 50) + 8 then
    v_potential_bonus := 1.08;
  elsif coalesce(p_potential, 50) >= coalesce(p_overall, 50) + 4 then
    v_potential_bonus := 1.04;
  end if;

  v_result :=
    round(
      (v_min + ((v_max - v_min) * v_skill_factor))
      * v_age_factor
      * v_potential_bonus
    )::integer;

  return greatest(50, v_result);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.suggest_initial_contract_seasons(p_age_years integer, p_overall smallint, p_potential smallint)
 RETURNS smallint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if p_age_years <= 27 and coalesce(p_potential, 50) >= coalesce(p_overall, 50) + 4 then
    return 2;
  end if;

  return 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.initialize_club_rider_contracts(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_date date;
  v_current_season integer;
  v_club_tier public.club_tier;
  r record;
  v_age integer;
  v_salary integer;
  v_duration smallint;
  v_end_season integer;
  v_contract_id uuid;
  v_expires_on date;
begin
  select club_tier
  into v_club_tier
  from public.clubs
  where id = p_club_id;

  if v_club_tier is null then
    raise exception 'Club not found or club_tier missing for club_id=%', p_club_id;
  end if;

  select
    public.get_current_game_date_date(),
    public.get_current_season_number()
  into
    v_game_date,
    v_current_season;

  for r in
    select
      rd.id as rider_id,
      rd.morale,
      rd.overall,
      rd.potential,
      rd.birth_date
    from public.club_riders cr
    join public.riders rd on rd.id = cr.rider_id
    where cr.club_id = p_club_id
      and not exists (
        select 1
        from public.rider_contracts rc
        where rc.rider_id = rd.id
          and rc.status = 'active'
      )
  loop
    v_age := extract(year from age(v_game_date, r.birth_date))::integer;

    v_salary := public.calculate_initial_rider_weekly_salary(
      v_club_tier,
      r.overall,
      v_age,
      r.potential
    );

    v_duration := 2;
    v_end_season := v_current_season + 1;
    v_expires_on := public.get_game_date_for_season_end(v_end_season);

    insert into public.rider_contracts (
      rider_id,
      club_id,
      salary_weekly,
      signed_at,
      starts_on,
      expires_on,
      duration_seasons,
      start_season_number,
      end_season_number,
      status,
      signed_morale,
      notes_json
    )
    values (
      r.rider_id,
      p_club_id,
      v_salary,
      now(),
      v_game_date,
      v_expires_on,
      v_duration,
      v_current_season,
      v_end_season,
      'active',
      r.morale,
      jsonb_build_object('source', 'initializer_season_v2')
    )
    returning id into v_contract_id;

    insert into public.rider_payroll_state (
      contract_id,
      rider_id,
      club_id,
      payroll_status,
      missed_payment_weeks,
      outstanding_salary_debt,
      outstanding_breach_fine,
      release_due_to_nonpayment,
      last_paid_on
    )
    values (
      v_contract_id,
      r.rider_id,
      p_club_id,
      'active',
      0,
      0,
      0,
      false,
      null
    );

    update public.riders
    set
      salary = v_salary,
      contract_expires_season = v_end_season,
      contract_expires_at = v_expires_on
    where id = r.rider_id;
  end loop;

  perform public.recompute_club_wage_total(p_club_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rebalance_active_rider_contract_salaries(p_club_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.rider_contracts rc
  set salary_weekly = x.new_salary
  from (
    select
      rc2.id as contract_id,
      public.calculate_initial_rider_weekly_salary(
        c.club_tier,
        r.overall,
        public.get_age_years_on_game_date(r.birth_date),
        r.potential
      ) as new_salary
    from public.rider_contracts rc2
    join public.riders r
      on r.id = rc2.rider_id
    join public.clubs c
      on c.id = rc2.club_id
    where rc2.status = 'active'
      and (p_club_id is null or rc2.club_id = p_club_id)
  ) x
  where rc.id = x.contract_id
    and rc.salary_weekly is distinct from x.new_salary;

  update public.riders r
  set salary = rc.salary_weekly
  from public.rider_contracts rc
  where rc.rider_id = r.id
    and rc.status = 'active'
    and (p_club_id is null or rc.club_id = p_club_id)
    and r.salary is distinct from rc.salary_weekly;

  perform set_config('finance.internal', '1', true);

  update public.club_finance_summary s
  set wage_total = coalesce(x.wage_total, 0),
      updated_at = now()
  from (
    select
      rc.club_id,
      sum(rc.salary_weekly)::numeric as wage_total
    from public.rider_contracts rc
    where rc.status = 'active'
      and (p_club_id is null or rc.club_id = p_club_id)
    group by rc.club_id
  ) x
  where s.club_id = x.club_id;

  update public.club_finance_summary s
  set wage_total = 0,
      updated_at = now()
  where (p_club_id is null or s.club_id = p_club_id)
    and not exists (
      select 1
      from public.rider_contracts rc
      where rc.club_id = s.club_id
        and rc.status = 'active'
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.recompute_club_wage_total(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rider_wages numeric := 0;
  v_staff_wages numeric := 0;
  v_total_wages numeric := 0;
begin
  perform set_config('finance.internal', '1', true);

  select coalesce(sum(rc.salary_weekly), 0)::numeric
  into v_rider_wages
  from public.rider_contracts rc
  where rc.club_id = p_club_id
    and rc.status = 'active';

  select coalesce(sum(cs.salary_weekly), 0)::numeric
  into v_staff_wages
  from public.club_staff cs
  where cs.club_id = p_club_id
    and cs.is_active = true;

  v_total_wages := coalesce(v_rider_wages, 0) + coalesce(v_staff_wages, 0);

  update public.club_finance_summary s
  set wage_total = v_total_wages,
      updated_at = now()
  where s.club_id = p_club_id;

  if not found then
    insert into public.club_finance_summary (
      club_id,
      wage_total,
      updated_at
    )
    values (
      p_club_id,
      v_total_wages,
      now()
    );
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_rider_market_value_v1(p_rider_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_overall smallint;
  v_potential smallint;
  v_morale smallint;
  v_birth_date date;
  v_age_years integer;
  v_club_tier public.club_tier;
  v_salary integer;
  v_multiplier numeric := 1.25;
  v_recent_form_score numeric := 0;
  v_recent_form_multiplier numeric := 1.0;
  v_value bigint;
begin
  select
    r.overall,
    r.potential,
    r.morale,
    r.birth_date,
    c.club_tier,
    coalesce(r.salary, 0)
  into
    v_overall,
    v_potential,
    v_morale,
    v_birth_date,
    v_club_tier,
    v_salary
  from public.riders r
  join public.club_riders cr
    on cr.rider_id = r.id
  join public.clubs c
    on c.id = cr.club_id
  where r.id = p_rider_id
  order by cr.created_at asc
  limit 1;

  if v_club_tier is null then
    raise exception 'Rider % is not assigned to a club', p_rider_id;
  end if;

  begin
    v_recent_form_score := coalesce(public.calculate_rider_recent_form_score_v1(p_rider_id), 0);
  exception when others then
    v_recent_form_score := 0;
  end;

  v_age_years := public.get_age_years_on_game_date(v_birth_date);

  if v_salary <= 0 then
    v_salary := public.calculate_initial_rider_weekly_salary(
      v_club_tier,
      v_overall,
      v_age_years,
      v_potential
    );
  end if;

  if v_age_years <= 21 then
    v_multiplier := v_multiplier + 0.35;
  elsif v_age_years between 22 and 24 then
    v_multiplier := v_multiplier + 0.45;
  elsif v_age_years between 25 and 29 then
    v_multiplier := v_multiplier + 0.55;
  elsif v_age_years between 30 and 33 then
    v_multiplier := v_multiplier + 0.20;
  elsif v_age_years between 34 and 36 then
    v_multiplier := v_multiplier - 0.05;
  else
    v_multiplier := v_multiplier - 0.25;
  end if;

  if v_potential >= v_overall + 10 then
    v_multiplier := v_multiplier + 0.40;
  elsif v_potential >= v_overall + 6 then
    v_multiplier := v_multiplier + 0.22;
  elsif v_potential >= v_overall + 3 then
    v_multiplier := v_multiplier + 0.10;
  end if;

  if v_morale >= 80 then
    v_multiplier := v_multiplier + 0.08;
  elsif v_morale <= 30 then
    v_multiplier := v_multiplier - 0.12;
  end if;

  v_recent_form_multiplier :=
    1.0 + greatest(
      -0.06,
      least(
        0.08,
        coalesce(v_recent_form_score, 0) * 0.003
      )
    );

  v_value :=
    round(
      (v_salary * 52)
      * greatest(0.60, v_multiplier)
      * v_recent_form_multiplier
    )::bigint;

  return greatest(1000, v_value);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.recompute_rider_market_value_snapshot(p_rider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.riders
  set market_value = public.calculate_rider_market_value_v1(p_rider_id)
  where id = p_rider_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.recompute_all_rider_market_values(p_club_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
begin
  for r in
    select rd.id
    from public.riders rd
    where exists (
      select 1
      from public.club_riders cr
      where cr.rider_id = rd.id
        and (p_club_id is null or cr.club_id = p_club_id)
    )
  loop
    perform public.recompute_rider_market_value_snapshot(r.id);
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_rider_contract_snapshot(p_rider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_contract record;
begin
  select
    rc.salary_weekly,
    rc.expires_on,
    rc.end_season_number
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.status = 'active'
  order by rc.updated_at desc, rc.created_at desc
  limit 1;

  if found then
    update public.riders
    set
      salary = v_contract.salary_weekly,
      contract_expires_at = v_contract.expires_on,
      contract_expires_season = v_contract.end_season_number
    where id = p_rider_id;
  else
    update public.riders
    set
      salary = null,
      contract_expires_at = null,
      contract_expires_season = null
    where id = p_rider_id;
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_sync_rider_contract_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'DELETE' then
    perform public.sync_rider_contract_snapshot(old.rider_id);
    return old;
  end if;

  perform public.sync_rider_contract_snapshot(new.rider_id);

  if tg_op = 'UPDATE' and old.rider_id is distinct from new.rider_id then
    perform public.sync_rider_contract_snapshot(old.rider_id);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.open_contract_renewal_negotiation(p_rider_id uuid)
 RETURNS TABLE(negotiation_id uuid, rider_id uuid, club_id uuid, current_salary_weekly integer, expected_salary_weekly integer, min_acceptable_salary_weekly integer, current_contract_end_season integer, current_contract_expires_at date, requested_extension_seasons smallint, proposed_new_end_season integer, attempt_count integer, max_attempts integer, cooldown_until timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_club_id uuid;
  v_current_season integer;
  v_current_game_date date;
  v_rider public.riders%rowtype;
  v_contract public.rider_contracts%rowtype;
  v_existing public.rider_contract_negotiations%rowtype;
  v_latest public.rider_contract_negotiations%rowtype;
  v_recent_form_score numeric := 0;
  v_expected integer;
  v_minimum integer;
  v_requested_extension smallint := 1;
  v_proposed_new_end_season integer;
begin
  v_club_id := public.get_current_main_club_id();

  if v_club_id is null then
    raise exception 'No main club found for current user.';
  end if;

  v_current_season := public.get_current_season_number();
  v_current_game_date := public.get_current_game_date_date();

  select *
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if not found then
    raise exception 'Rider not found.';
  end if;

  if not public.rider_belongs_to_current_club_family(p_rider_id) then
    raise exception 'Rider does not belong to your club structure.';
  end if;

  select *
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.club_id = v_club_id
    and rc.status = 'active'
  order by rc.created_at desc
  limit 1;

  if not found then
    raise exception 'Active contract not found for this rider.';
  end if;

  select *
  into v_existing
  from public.rider_contract_negotiations n
  where n.rider_id = p_rider_id
    and n.club_id = v_club_id
    and n.status = 'open'
  order by n.opened_at desc, n.created_at desc
  limit 1;

  if found then
    return query
    select
      v_existing.id,
      v_existing.rider_id,
      v_existing.club_id,
      v_existing.current_salary_weekly,
      v_existing.expected_salary_weekly,
      v_existing.min_acceptable_salary_weekly,
      v_existing.current_contract_end_season,
      public.get_game_date_for_season_end(v_existing.current_contract_end_season),
      v_existing.requested_extension_seasons,
      v_existing.proposed_new_end_season,
      coalesce(v_existing.attempt_count, 0)::integer,
      coalesce(v_existing.max_attempts, 5)::integer,
      v_existing.locked_until::timestamptz;
    return;
  end if;

  select *
  into v_latest
  from public.rider_contract_negotiations n
  where n.rider_id = p_rider_id
    and n.club_id = v_club_id
  order by n.opened_at desc, n.created_at desc
  limit 1;

  if found and v_latest.locked_until is not null and v_latest.locked_until > v_current_game_date then
    raise exception 'Negotiation cooldown active until %', v_latest.locked_until;
  end if;

  /*
    Real recent form:
    Reads last 183 game days through calculate_rider_recent_form_score_v1().
    Effect is intentionally small and capped by the helper.
  */
  begin
    v_recent_form_score := coalesce(public.calculate_rider_recent_form_score_v1(p_rider_id), 0);
  exception when others then
    v_recent_form_score := 0;
  end;

  v_expected :=
    greatest(
      v_contract.salary_weekly,
      round(
        v_contract.salary_weekly
        * (
          1.05
          + ((100 - coalesce(v_rider.morale, 50)) * 0.0015)
          + (coalesce(v_rider.overall, 60) * 0.0008)
          + least(coalesce(v_recent_form_score, 0), 30) * 0.003
        )
      )::integer
    );

  v_minimum :=
    greatest(
      v_contract.salary_weekly,
      round(
        v_expected
        * (
          0.90
          + ((100 - coalesce(v_rider.morale, 50)) * 0.0008)
          + least(coalesce(v_recent_form_score, 0), 30) * 0.0015
        )
      )::integer
    );

  v_proposed_new_end_season :=
    coalesce(v_contract.end_season_number, public.season_from_game_date(v_contract.expires_on))
    + v_requested_extension;

  insert into public.rider_contract_negotiations (
    rider_id,
    club_id,
    status,
    morale_at_open,
    current_salary_weekly,
    expected_salary_weekly,
    min_acceptable_salary_weekly,
    preferred_duration_seasons,
    market_value_at_open,
    notes_json,
    opened_in_season,
    current_contract_end_season,
    requested_extension_seasons,
    proposed_new_end_season,
    attempt_count,
    max_attempts,
    locked_until
  )
  values (
    p_rider_id,
    v_club_id,
    'open',
    coalesce(v_rider.morale, 50),
    v_contract.salary_weekly,
    v_expected,
    v_minimum,
    1,
    coalesce(v_rider.market_value, 0),
    jsonb_build_object(
      'source', 'renewal_modal_v4_recent_form',
      'recent_form_score', v_recent_form_score,
      'recent_form_window_days', 183,
      'recent_form_salary_effect', 'expected_and_minimum_salary'
    ),
    v_current_season,
    coalesce(v_contract.end_season_number, public.season_from_game_date(v_contract.expires_on)),
    v_requested_extension,
    v_proposed_new_end_season,
    0,
    5,
    null
  )
  returning * into v_existing;

  return query
  select
    v_existing.id,
    v_existing.rider_id,
    v_existing.club_id,
    v_existing.current_salary_weekly,
    v_existing.expected_salary_weekly,
    v_existing.min_acceptable_salary_weekly,
    v_existing.current_contract_end_season,
    public.get_game_date_for_season_end(v_existing.current_contract_end_season),
    v_existing.requested_extension_seasons,
    v_existing.proposed_new_end_season,
    coalesce(v_existing.attempt_count, 0)::integer,
    coalesce(v_existing.max_attempts, 5)::integer,
    v_existing.locked_until::timestamptz;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_contract_renewal_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_extension_seasons smallint)
 RETURNS TABLE(accepted boolean, message text, negotiation_closed boolean, attempt_count integer, cooldown_until timestamp with time zone, new_salary_weekly integer, new_contract_end_season integer, new_contract_expires_at date, new_morale smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_neg public.rider_contract_negotiations%rowtype;
  v_rider public.riders%rowtype;
  v_contract public.rider_contracts%rowtype;
  v_current_game_date date;
  v_attempt_count integer;
  v_max_attempts integer;
  v_recent_form_score numeric := 0;
  v_accept_score numeric := 0;
  v_threshold numeric := 0;
  v_release_request_penalty numeric := 0;
  v_release_threshold_penalty numeric := 0;
  v_new_end_season integer;
  v_new_expires_on date;
  v_new_duration smallint;
  v_locked_until date;
  v_reject_reason text := '';
  v_success_morale_bonus integer := 3;
  v_new_morale smallint;
begin
  select *
  into v_neg
  from public.rider_contract_negotiations n
  where n.id = p_negotiation_id
    and n.status = 'open'
  limit 1;

  if not found then
    raise exception 'Open negotiation not found.';
  end if;

  if not exists (
    select 1
    from public.clubs c
    where c.id = v_neg.club_id
      and c.owner_user_id = auth.uid()
      and c.club_type = 'main'
      and c.is_active = true
      and c.deleted_at is null
  ) then
    raise exception 'Negotiation does not belong to your main club.';
  end if;

  v_current_game_date := public.get_current_game_date_date();
  v_attempt_count := coalesce(v_neg.attempt_count, 0);
  v_max_attempts := coalesce(v_neg.max_attempts, 5);

  if v_neg.locked_until is not null and v_neg.locked_until > v_current_game_date then
    raise exception 'Negotiation cooldown active until %', v_neg.locked_until;
  end if;

  select *
  into v_rider
  from public.riders r
  where r.id = v_neg.rider_id;

  select *
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = v_neg.rider_id
    and rc.club_id = v_neg.club_id
    and rc.status = 'active'
  order by rc.created_at desc
  limit 1;

  if not found then
    raise exception 'Active rider contract not found.';
  end if;

  /*
    Real recent form:
    Higher recent form makes the rider more demanding.
    This affects the acceptance score and threshold, but remains capped.
  */
  begin
    v_recent_form_score := coalesce(public.calculate_rider_recent_form_score_v1(v_neg.rider_id), 0);
  exception when others then
    v_recent_form_score := 0;
  end;

  if coalesce(v_rider.release_requested, false) = true then
    v_release_request_penalty := 18;
    v_release_threshold_penalty := 8;
  end if;

  v_accept_score :=
      (p_offer_salary_weekly::numeric / greatest(v_neg.expected_salary_weekly, 1)::numeric) * 100
    + (p_offer_extension_seasons * 4)
    - ((100 - coalesce(v_rider.morale, 50)) * 0.12)
    - (least(coalesce(v_recent_form_score, 0), 30) * 0.35)
    - v_release_request_penalty;

  v_threshold :=
      92
    + ((100 - coalesce(v_rider.morale, 50)) * 0.08)
    + (least(coalesce(v_recent_form_score, 0), 30) * 0.22)
    + v_release_threshold_penalty;

  if p_offer_salary_weekly < v_neg.min_acceptable_salary_weekly then
    v_reject_reason := 'Rider refused the offer because the salary is below his current expectations.';
  elsif p_offer_extension_seasons < 1 or p_offer_extension_seasons > 2 then
    v_reject_reason := 'Rider refused the offer because he is not happy with the proposed contract length.';
  elsif v_accept_score < v_threshold then
    if coalesce(v_rider.release_requested, false) = true then
      v_reject_reason := 'Rider refused the offer because he has already requested to leave and needs a much stronger reason to stay.';
    elsif coalesce(v_rider.morale, 50) < 45 or coalesce(v_recent_form_score, 0) >= 10 then
      v_reject_reason := 'Rider refused the offer because recent form and morale increase his demands.';
    else
      v_reject_reason := 'Rider refused the offer because the salary is below his current expectations.';
    end if;
  else
    v_new_end_season :=
      coalesce(v_contract.end_season_number, public.season_from_game_date(v_contract.expires_on))
      + p_offer_extension_seasons;

    v_new_expires_on := public.get_game_date_for_season_end(v_new_end_season);

    v_new_duration := p_offer_extension_seasons;

    if p_offer_salary_weekly::numeric >= (v_neg.expected_salary_weekly::numeric * 1.15) then
      v_success_morale_bonus := 5;
    else
      v_success_morale_bonus := 3;
    end if;

    v_new_morale :=
      least(
        100,
        greatest(
          0,
          coalesce(v_rider.morale, 50)::int + v_success_morale_bonus
        )
      )::smallint;

    update public.rider_contract_negotiations
    set
      status = 'accepted',
      responded_at = now(),
      offer_salary_weekly = p_offer_salary_weekly,
      offer_extension_seasons = p_offer_extension_seasons,
      offer_duration_seasons = p_offer_extension_seasons,
      attempt_count = v_attempt_count,
      locked_until = null,
      closed_reason = 'accepted',
      notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
        'release_requested_at_offer', coalesce(v_rider.release_requested, false),
        'morale_at_offer', coalesce(v_rider.morale, 50),
        'recent_form_score_at_offer', v_recent_form_score,
        'accept_score', v_accept_score,
        'accept_threshold', v_threshold,
        'morale_after_acceptance', v_new_morale,
        'morale_bonus_from_renewal', v_success_morale_bonus
      ),
      updated_at = now()
    where id = v_neg.id;

    update public.rider_contracts
    set
      salary_weekly = p_offer_salary_weekly,
      duration_seasons = v_new_duration,
      expires_on = v_new_expires_on,
      end_season_number = v_new_end_season,
      signed_morale = v_new_morale,
      notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
        'renewal_morale_bonus', v_success_morale_bonus,
        'release_request_resolved_by_renewal', coalesce(v_rider.release_requested, false),
        'recent_form_score_at_renewal', v_recent_form_score
      ),
      updated_at = now()
    where id = v_contract.id;

    update public.riders
    set
      salary = p_offer_salary_weekly,
      contract_expires_at = v_new_expires_on,
      contract_expires_season = v_new_end_season,
      morale = v_new_morale,
      low_morale_since = null,
      asked_for_more_selection = false,
      release_requested = false
    where id = v_rider.id;

    return query
    select
      true,
      format(
        'Contract extended for %s %s until season %s. Rider morale improved by %s.',
        p_offer_extension_seasons,
        case when p_offer_extension_seasons = 1 then 'season' else 'seasons' end,
        v_new_end_season,
        v_success_morale_bonus
      ),
      true,
      v_attempt_count,
      null::timestamptz,
      p_offer_salary_weekly,
      v_new_end_season,
      v_new_expires_on,
      v_new_morale;

    return;
  end if;

  v_attempt_count := v_attempt_count + 1;

  if v_attempt_count >= v_max_attempts then
    v_locked_until := v_current_game_date + 3;

    update public.rider_contract_negotiations
    set
      status = 'rejected',
      responded_at = now(),
      offer_salary_weekly = p_offer_salary_weekly,
      offer_extension_seasons = p_offer_extension_seasons,
      offer_duration_seasons = p_offer_extension_seasons,
      attempt_count = v_attempt_count,
      locked_until = v_locked_until,
      closed_reason = 'max_attempts_reached',
      notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
        'release_requested_at_final_rejection', coalesce(v_rider.release_requested, false),
        'morale_before_final_rejection', coalesce(v_rider.morale, 50),
        'recent_form_score_at_final_rejection', v_recent_form_score,
        'morale_penalty_from_failed_negotiation', 10
      ),
      updated_at = now()
    where id = v_neg.id;

    update public.riders
    set
      morale = greatest(0, morale - 10),
      low_morale_since = case
        when greatest(0, morale - 10) < 20 and low_morale_since is null then v_current_game_date
        when greatest(0, morale - 10) >= 20 then null
        else low_morale_since
      end,
      asked_for_more_selection = case
        when greatest(0, morale - 10) < 20 then true
        else asked_for_more_selection
      end
    where id = v_rider.id
    returning morale into v_rider.morale;

    return query
    select
      false,
      'Negotiations have collapsed for 3 in-game days, and morale dropped by 10.',
      true,
      v_attempt_count,
      v_locked_until::timestamptz,
      null::integer,
      null::integer,
      null::date,
      v_rider.morale;

    return;
  end if;

  update public.rider_contract_negotiations
  set
    offer_salary_weekly = p_offer_salary_weekly,
    offer_extension_seasons = p_offer_extension_seasons,
    offer_duration_seasons = p_offer_extension_seasons,
    attempt_count = v_attempt_count,
    locked_until = null,
    notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
      'release_requested_at_rejection', coalesce(v_rider.release_requested, false),
      'morale_at_rejection', coalesce(v_rider.morale, 50),
      'recent_form_score_at_rejection', v_recent_form_score,
      'accept_score', v_accept_score,
      'accept_threshold', v_threshold
    ),
    updated_at = now()
  where id = v_neg.id;

  return query
  select
    false,
    v_reject_reason,
    false,
    v_attempt_count,
    null::timestamptz,
    null::integer,
    null::integer,
    null::date,
    v_rider.morale;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_rider_market_value(p_rider_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_game_date date;
  v_birth_date date;
  v_salary integer;
  v_contract_expires_at date;
  v_morale smallint;
  v_potential smallint;
  v_overall smallint;
  v_role public.rider_role;

  v_sprint smallint;
  v_climbing smallint;
  v_time_trial smallint;
  v_endurance smallint;
  v_flat smallint;
  v_recovery smallint;
  v_resistance smallint;
  v_race_iq smallint;
  v_teamwork smallint;

  v_age integer;
  v_days_left integer;

  v_base_value numeric;
  v_age_multiplier numeric := 1.0;
  v_potential_multiplier numeric := 1.0;
  v_contract_multiplier numeric := 1.0;
  v_morale_multiplier numeric := 1.0;
  v_role_fit_multiplier numeric := 1.0;
  v_recent_form_score numeric := 0;
  v_recent_form_multiplier numeric := 1.0;
  v_role_score numeric := 0;
  v_result numeric;
begin
  v_game_date := public.get_current_game_date_date();

  select
    r.birth_date,
    coalesce(r.salary, 0),
    r.contract_expires_at,
    coalesce(r.morale, 50),
    coalesce(r.potential, 0),
    coalesce(r.overall, 0),
    r.role,
    coalesce(r.sprint, 0),
    coalesce(r.climbing, 0),
    coalesce(r.time_trial, 0),
    coalesce(r.endurance, 0),
    coalesce(r.flat, 0),
    coalesce(r.recovery, 0),
    coalesce(r.resistance, 0),
    coalesce(r.race_iq, 0),
    coalesce(r.teamwork, 0)
  into
    v_birth_date,
    v_salary,
    v_contract_expires_at,
    v_morale,
    v_potential,
    v_overall,
    v_role,
    v_sprint,
    v_climbing,
    v_time_trial,
    v_endurance,
    v_flat,
    v_recovery,
    v_resistance,
    v_race_iq,
    v_teamwork
  from public.riders r
  where r.id = p_rider_id;

  if not found then
    raise exception 'Rider not found for id %', p_rider_id;
  end if;

  begin
    v_recent_form_score := coalesce(public.calculate_rider_recent_form_score_v1(p_rider_id), 0);
  exception when others then
    v_recent_form_score := 0;
  end;

  if v_birth_date is null or v_game_date is null then
    v_age := 25;
  else
    v_age := extract(year from age(v_game_date, v_birth_date))::integer;
  end if;

  if v_contract_expires_at is null or v_game_date is null then
    v_days_left := 180;
  else
    v_days_left := greatest(v_contract_expires_at - v_game_date, 0);
  end if;

  v_base_value :=
    greatest(
      coalesce(v_salary, 0),
      (coalesce(v_overall, 50) * 20) + greatest(coalesce(v_potential, 50) - coalesce(v_overall, 50), 0) * 12,
      150
    ) * 52 * 2.0;

  v_age_multiplier :=
    case
      when v_age <= 21 then 1.40
      when v_age between 22 and 24 then 1.25
      when v_age between 25 and 28 then 1.15
      when v_age between 29 and 31 then 1.00
      when v_age between 32 and 34 then 0.80
      else 0.60
    end;

  v_potential_multiplier :=
    1.0 + least(greatest((coalesce(v_potential, 0) - coalesce(v_overall, 0)) * 0.015, 0), 0.30);

  v_contract_multiplier :=
    case
      when v_days_left < 30 then 0.65
      when v_days_left < 90 then 0.80
      when v_days_left < 180 then 0.95
      when v_days_left < 365 then 1.05
      when v_days_left < 730 then 1.15
      else 1.25
    end;

  v_morale_multiplier :=
    case
      when v_morale >= 85 then 1.05
      when v_morale >= 70 then 1.02
      when v_morale >= 50 then 1.00
      when v_morale >= 35 then 0.97
      else 0.93
    end;

  v_role_score :=
    case v_role
      when 'Sprinter' then
        (v_sprint * 0.42 + v_flat * 0.18 + v_endurance * 0.12 + v_recovery * 0.10 + v_race_iq * 0.10 + v_resistance * 0.08)
      when 'Climber' then
        (v_climbing * 0.40 + v_recovery * 0.18 + v_endurance * 0.14 + v_resistance * 0.12 + v_race_iq * 0.10 + v_teamwork * 0.06)
      when 'TT' then
        (v_time_trial * 0.42 + v_endurance * 0.18 + v_flat * 0.14 + v_recovery * 0.10 + v_race_iq * 0.10 + v_resistance * 0.06)
      when 'Domestique' then
        (v_teamwork * 0.26 + v_endurance * 0.18 + v_recovery * 0.14 + v_resistance * 0.14 + v_race_iq * 0.14 + v_flat * 0.14)
      when 'Breakaway' then
        (v_resistance * 0.24 + v_endurance * 0.20 + v_race_iq * 0.16 + v_recovery * 0.12 + v_flat * 0.12 + v_climbing * 0.08 + v_time_trial * 0.08)
      when 'All-rounder' then
        ((v_sprint + v_climbing + v_time_trial + v_endurance + v_flat + v_recovery + v_resistance + v_race_iq + v_teamwork) / 9.0)
      when 'Leader' then
        (v_climbing * 0.22 + v_time_trial * 0.18 + v_recovery * 0.15 + v_endurance * 0.15 + v_race_iq * 0.12 + v_resistance * 0.10 + v_teamwork * 0.08)
      else
        coalesce(v_overall, 0)
    end;

  v_role_fit_multiplier :=
    case
      when v_role_score >= 85 then 1.12
      when v_role_score >= 80 then 1.08
      when v_role_score >= 75 then 1.04
      when v_role_score >= 70 then 1.00
      when v_role_score >= 65 then 0.96
      else 0.92
    end;

  /*
    Recent form effect:
    - v_recent_form_score is capped in helper between -15 and +30.
    - Market value multiplier is capped between -6% and +8%.
    - This keeps form meaningful but not dominant.
  */
  v_recent_form_multiplier :=
    1.0 + greatest(
      -0.06,
      least(
        0.08,
        coalesce(v_recent_form_score, 0) * 0.003
      )
    );

  v_result :=
    v_base_value
    * v_age_multiplier
    * v_potential_multiplier
    * v_contract_multiplier
    * v_morale_multiplier
    * v_role_fit_multiplier
    * v_recent_form_multiplier;

  return round(greatest(v_result, 10000))::bigint;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_rider_market_value(p_rider_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_value bigint;
begin
  v_value := public.calculate_rider_market_value(p_rider_id);

  update public.riders
  set market_value = v_value
  where id = p_rider_id;

  return v_value;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_all_rider_market_values()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  v_count integer;
begin
  update public.riders r
  set market_value = public.calculate_rider_market_value(r.id);

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.explain_rider_market_value(p_rider_id uuid)
 RETURNS TABLE(rider_id uuid, display_name text, role rider_role, age integer, salary integer, overall smallint, potential smallint, morale smallint, contract_expires_at date, days_left integer, role_score numeric, base_value numeric, age_multiplier numeric, potential_multiplier numeric, contract_multiplier numeric, morale_multiplier numeric, role_fit_multiplier numeric, final_market_value bigint)
 LANGUAGE plpgsql
AS $function$declare
  v_game_date date;
begin
  select public.get_current_game_date()::date into v_game_date;

  return query
  with rider_data as (
    select
      r.id as rider_id,
      r.display_name,
      r.role,
      r.birth_date,
      coalesce(r.salary, 0)::integer as salary,
      coalesce(r.overall, 0)::smallint as overall,
      coalesce(r.potential, 0)::smallint as potential,
      coalesce(r.morale, 50)::smallint as morale,
      r.contract_expires_at,
      coalesce(r.sprint, 0)::smallint as sprint,
      coalesce(r.climbing, 0)::smallint as climbing,
      coalesce(r.time_trial, 0)::smallint as time_trial,
      coalesce(r.endurance, 0)::smallint as endurance,
      coalesce(r.flat, 0)::smallint as flat,
      coalesce(r.recovery, 0)::smallint as recovery,
      coalesce(r.resistance, 0)::smallint as resistance,
      coalesce(r.race_iq, 0)::smallint as race_iq,
      coalesce(r.teamwork, 0)::smallint as teamwork
    from public.riders r
    where r.id = p_rider_id
  ),
  calc as (
    select
      rd.*,
      case
        when rd.birth_date is null or v_game_date is null then 25
        else extract(year from age(v_game_date, rd.birth_date))::integer
      end as age,
      case
        when rd.contract_expires_at is null or v_game_date is null then 180
        else greatest((rd.contract_expires_at - v_game_date), 0)
      end as days_left,
      case rd.role
        when 'Sprinter' then
          (rd.sprint * 0.42 + rd.flat * 0.18 + rd.endurance * 0.12 + rd.recovery * 0.10 + rd.race_iq * 0.10 + rd.resistance * 0.08)
        when 'Climber' then
          (rd.climbing * 0.40 + rd.recovery * 0.18 + rd.endurance * 0.14 + rd.resistance * 0.12 + rd.race_iq * 0.10 + rd.teamwork * 0.06)
        when 'TT' then
          (rd.time_trial * 0.42 + rd.endurance * 0.18 + rd.flat * 0.14 + rd.recovery * 0.10 + rd.race_iq * 0.10 + rd.resistance * 0.06)
        when 'Domestique' then
          (rd.teamwork * 0.26 + rd.endurance * 0.18 + rd.recovery * 0.14 + rd.resistance * 0.14 + rd.race_iq * 0.14 + rd.flat * 0.14)
        when 'Breakaway' then
          (rd.resistance * 0.24 + rd.endurance * 0.20 + rd.race_iq * 0.16 + rd.recovery * 0.12 + rd.flat * 0.12 + rd.climbing * 0.08 + rd.time_trial * 0.08)
        when 'All-rounder' then
          ((rd.sprint + rd.climbing + rd.time_trial + rd.endurance + rd.flat + rd.recovery + rd.resistance + rd.race_iq + rd.teamwork) / 9.0)
        when 'Leader' then
          (rd.climbing * 0.22 + rd.time_trial * 0.18 + rd.recovery * 0.15 + rd.endurance * 0.15 + rd.race_iq * 0.12 + rd.resistance * 0.10 + rd.teamwork * 0.08)
        else
          rd.overall::numeric
      end as role_score
    from rider_data rd
  ),
  mult as (
    select
      c.*,
      (
  greatest(
    c.salary,
    (c.overall * 20) + greatest(c.potential - c.overall, 0) * 12,
    150
  ) * 52 * 2.0
)::numeric as base_value,
      case
        when c.age <= 21 then 1.40
        when c.age between 22 and 24 then 1.25
        when c.age between 25 and 28 then 1.15
        when c.age between 29 and 31 then 1.00
        when c.age between 32 and 34 then 0.80
        else 0.60
      end::numeric as age_multiplier,
      (1.0 + least(greatest((c.potential - c.overall) * 0.015, 0), 0.30))::numeric as potential_multiplier,
      case
        when c.days_left < 30 then 0.65
        when c.days_left < 90 then 0.80
        when c.days_left < 180 then 0.95
        when c.days_left < 365 then 1.05
        when c.days_left < 730 then 1.15
        else 1.25
      end::numeric as contract_multiplier,
      case
        when c.morale >= 85 then 1.05
        when c.morale >= 70 then 1.02
        when c.morale >= 50 then 1.00
        when c.morale >= 35 then 0.97
        else 0.93
      end::numeric as morale_multiplier,
      case
        when c.role_score >= 85 then 1.12
        when c.role_score >= 80 then 1.08
        when c.role_score >= 75 then 1.04
        when c.role_score >= 70 then 1.00
        when c.role_score >= 65 then 0.96
        else 0.92
      end::numeric as role_fit_multiplier
    from calc c
  )
  select
    m.rider_id,
    m.display_name,
    m.role,
    m.age,
    m.salary,
    m.overall,
    m.potential,
    m.morale,
    m.contract_expires_at,
    m.days_left,
    round(m.role_score, 2) as role_score,
    round(m.base_value, 2) as base_value,
    m.age_multiplier,
    m.potential_multiplier,
    m.contract_multiplier,
    m.morale_multiplier,
    m.role_fit_multiplier,
    round(
      greatest(
        m.base_value
        * m.age_multiplier
        * m.potential_multiplier
        * m.contract_multiplier
        * m.morale_multiplier
        * m.role_fit_multiplier,
        10000
      )
    )::bigint as final_market_value
  from mult m;
end;$function$
;

CREATE OR REPLACE FUNCTION public.refresh_market_values_if_new_game_month()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_game_date date;
  v_month_key text;
  v_updated_count integer:=0;
  v_remaining integer:=0;
begin
  v_game_date:=public.get_current_game_date_date();

  if v_game_date is null then
    return jsonb_build_object('ok',false,'reason','game_date_missing');
  end if;

  v_month_key:=to_char(v_game_date,'YYYY-MM');

  if not pg_try_advisory_xact_lock(hashtext('market_value_monthly_refresh')) then
    return jsonb_build_object('ok',true,'busy',true,'game_month',v_month_key);
  end if;

  with batch as materialized (
    select r.id
    from public.riders r
    where coalesce(r.market_value_refreshed_game_month,'')<>v_month_key
    order by r.id
    for update skip locked
    limit 1500
  ),
  updated as (
    update public.riders r
    set market_value=public.calculate_rider_market_value(r.id),
        market_value_refreshed_game_month=v_month_key
    from batch b
    where r.id=b.id
    returning r.id
  )
  select count(*) into v_updated_count from updated;

  select count(*) into v_remaining
  from public.riders r
  where coalesce(r.market_value_refreshed_game_month,'')<>v_month_key;

  if v_remaining=0 then
    insert into public.game_system_state(key,value_text,updated_at)
    values('market_value_last_refresh_game_month',v_month_key,now())
    on conflict(key) do update
    set value_text=excluded.value_text,updated_at=excluded.updated_at;
  end if;

  return jsonb_build_object(
    'ok',true,
    'game_month',v_month_key,
    'updated_count',v_updated_count,
    'remaining_count',v_remaining,
    'complete',v_remaining=0
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_rider_asking_price(p_rider_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$declare
  v_game_date date;
  v_market_value bigint;
  v_contract_expires_at date;
  v_morale smallint;
  v_release_requested boolean;
  v_days_left integer;
  v_contract_multiplier numeric := 1.0;
  v_morale_multiplier numeric := 1.0;
  v_release_multiplier numeric := 1.0;
  v_seller_premium numeric := 1.05;
  v_result numeric;
begin
  v_game_date := public.get_current_game_date_date();

  select
    coalesce(market_value, public.calculate_rider_market_value(id)),
    contract_expires_at,
    coalesce(morale, 50),
    coalesce(release_requested, false)
  into
    v_market_value,
    v_contract_expires_at,
    v_morale,
    v_release_requested
  from public.riders
  where id = p_rider_id;

  if not found then
    raise exception 'Rider not found for id %', p_rider_id;
  end if;

  if v_contract_expires_at is null or v_game_date is null then
    v_days_left := 180;
  else
    v_days_left := greatest(v_contract_expires_at - v_game_date, 0);
  end if;

  v_contract_multiplier :=
    case
      when v_days_left < 30 then 0.88
      when v_days_left < 90 then 0.95
      when v_days_left < 180 then 1.00
      when v_days_left < 365 then 1.08
      else 1.15
    end;

  v_morale_multiplier :=
    case
      when v_morale >= 85 then 1.04
      when v_morale >= 70 then 1.02
      when v_morale >= 50 then 1.00
      when v_morale >= 35 then 0.97
      else 0.93
    end;

  v_release_multiplier :=
    case
      when v_release_requested then 0.90
      else 1.00
    end;

  v_result :=
    v_market_value
    * v_contract_multiplier
    * v_morale_multiplier
    * v_release_multiplier
    * v_seller_premium;

  return round(greatest(v_result, 10000))::bigint;
end;$function$
;

CREATE OR REPLACE FUNCTION public.calculate_rider_default_asking_price(p_rider_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$declare
  v_game_date date;
  v_market_value bigint;
  v_contract_expires_at date;
  v_morale smallint;
  v_release_requested boolean;
  v_days_left integer;
  v_contract_multiplier numeric := 1.0;
  v_morale_multiplier numeric := 1.0;
  v_release_multiplier numeric := 1.0;
  v_seller_premium numeric := 1.08;
  v_result numeric;
begin
  v_game_date := public.get_current_game_date_date();

  select
    coalesce(r.market_value, public.calculate_rider_market_value(r.id)),
    r.contract_expires_at,
    coalesce(r.morale, 50),
    coalesce(r.release_requested, false)
  into
    v_market_value,
    v_contract_expires_at,
    v_morale,
    v_release_requested
  from public.riders r
  where r.id = p_rider_id;

  if not found then
    raise exception 'Rider not found for id %', p_rider_id;
  end if;

  if v_contract_expires_at is null or v_game_date is null then
    v_days_left := 180;
  else
    v_days_left := greatest(v_contract_expires_at - v_game_date, 0);
  end if;

  v_contract_multiplier :=
    case
      when v_days_left < 30 then 0.88
      when v_days_left < 90 then 0.95
      when v_days_left < 180 then 1.00
      when v_days_left < 365 then 1.08
      else 1.15
    end;

  v_morale_multiplier :=
    case
      when v_morale >= 85 then 1.04
      when v_morale >= 70 then 1.02
      when v_morale >= 50 then 1.00
      when v_morale >= 35 then 0.97
      else 0.93
    end;

  v_release_multiplier :=
    case
      when v_release_requested then 0.90
      else 1.00
    end;

  v_result :=
    v_market_value
    * v_contract_multiplier
    * v_morale_multiplier
    * v_release_multiplier
    * v_seller_premium;

  return round(greatest(v_result, 10000))::bigint;
end;$function$
;

CREATE OR REPLACE FUNCTION public.refresh_rider_value_snapshot(p_rider_id uuid)
 RETURNS TABLE(rider_id uuid, market_value bigint, asking_price bigint, asking_price_manual boolean)
 LANGUAGE plpgsql
AS $function$
declare
  v_market_value bigint;
  v_default_asking_price bigint;
begin
  v_market_value := public.calculate_rider_market_value(p_rider_id);
  v_default_asking_price := public.calculate_rider_default_asking_price(p_rider_id);

  update public.riders r
  set
    market_value = v_market_value,
    asking_price = case
      when coalesce(r.asking_price_manual, false) then r.asking_price
      when exists (
        select 1
        from public.rider_transfer_listings l
        where l.rider_id = r.id
          and l.status in ('listed', 'club_accepted')
      ) then v_default_asking_price
      else r.asking_price
    end,
    asking_price_updated_at = case
      when coalesce(r.asking_price_manual, false) then r.asking_price_updated_at
      when exists (
        select 1
        from public.rider_transfer_listings l
        where l.rider_id = r.id
          and l.status in ('listed', 'club_accepted')
      ) then now()
      else r.asking_price_updated_at
    end
  where r.id = p_rider_id;

  return query
  select r.id, r.market_value, r.asking_price, r.asking_price_manual
  from public.riders r
  where r.id = p_rider_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._finance_process_weekly_rider_wages_core_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'finance', 'pg_temp'
AS $function$
declare
  v_current_game_date date;
  v_iso_dow integer;
  v_payroll_date date;
  v_week_key text;

  r record;
  v_result record;

  v_clubs_processed integer := 0;
  v_clubs_charged integer := 0;
  v_clubs_skipped_no_riders integer := 0;
  v_clubs_skipped_already_charged integer := 0;
  v_clubs_skipped_insufficient_funds integer := 0;
  v_clubs_failed integer := 0;

  v_existing_transaction_id uuid;
  v_errors jsonb := '[]'::jsonb;
begin
  v_current_game_date := public.get_current_game_date_date();

  if v_current_game_date is null then
    return jsonb_build_object(
      'ok', false,
      'reason', 'game_date_missing'
    );
  end if;

  v_iso_dow := extract(isodow from v_current_game_date)::int;

  -- Monday of the current in-game week.
  v_payroll_date := (v_current_game_date - (v_iso_dow - 1))::date;
  v_week_key := to_char(v_payroll_date, 'IYYY-IW');

  for r in
    select c.id as club_id
    from public.clubs c
    where c.club_type = 'main'
      and c.deleted_at is null
      and coalesce(c.is_active, true) = true
  loop
    v_clubs_processed := v_clubs_processed + 1;

    select t.id
    into v_existing_transaction_id
    from finance.transactions t
    where t.type = 'rider_salary_payday'
      and coalesce(t.metadata ->> 'charged_club_id', t.metadata ->> 'club_id', '') = r.club_id::text
      and coalesce(t.metadata ->> 'game_date', t.metadata ->> 'in_game_date', '') = v_payroll_date::text
      and coalesce(t.metadata ->> 'is_reversal', 'false') <> 'true'
    order by t.created_at desc
    limit 1;

    if v_existing_transaction_id is not null then
      v_clubs_skipped_already_charged := v_clubs_skipped_already_charged + 1;
      continue;
    end if;

    begin
      select *
      into v_result
      from public.finance_charge_club_rider_wages(
        r.club_id,
        'rider_salary_payday:' || r.club_id::text || ':' || v_week_key,
        v_payroll_date
      );

      if v_result.transaction_id is null
         and coalesce(v_result.total_wages, 0) > 0
         and coalesce(v_result.rider_count, 0) > 0 then

        v_clubs_skipped_insufficient_funds := v_clubs_skipped_insufficient_funds + 1;

      elsif v_result.transaction_id is null then

        v_clubs_skipped_no_riders := v_clubs_skipped_no_riders + 1;

      else

        v_clubs_charged := v_clubs_charged + 1;

      end if;

    exception when others then
      v_clubs_failed := v_clubs_failed + 1;

      v_errors := v_errors || jsonb_build_array(
        jsonb_build_object(
          'club_id', r.club_id,
          'error', sqlerrm
        )
      );

      continue;
    end;
  end loop;

  insert into finance.system_state (key, value_text, updated_at)
  values ('rider_salary_payday_last_week', v_week_key, now())
  on conflict (key)
  do update set
    value_text = excluded.value_text,
    updated_at = excluded.updated_at;

  return jsonb_build_object(
    'ok', true,
    'did_run', true,
    'week_key', v_week_key,
    'payroll_date', v_payroll_date,
    'current_game_date', v_current_game_date,
    'clubs_processed', v_clubs_processed,
    'clubs_charged', v_clubs_charged,
    'clubs_skipped_no_riders', v_clubs_skipped_no_riders,
    'clubs_skipped_already_charged', v_clubs_skipped_already_charged,
    'clubs_skipped_insufficient_funds', v_clubs_skipped_insufficient_funds,
    'clubs_failed', v_clubs_failed,
    'errors', v_errors,
    'scope', 'main_plus_developing_squads',
    'salary_source_policy', 'active_contract_else_riders_salary'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_refresh_rider_market_value()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_old_morale_band integer;
  v_new_morale_band integer;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_old_morale_band := case
      when coalesce(old.morale, 50) >= 85 then 5
      when coalesce(old.morale, 50) >= 70 then 4
      when coalesce(old.morale, 50) >= 50 then 3
      when coalesce(old.morale, 50) >= 35 then 2
      else 1
    end;

    v_new_morale_band := case
      when coalesce(new.morale, 50) >= 85 then 5
      when coalesce(new.morale, 50) >= 70 then 4
      when coalesce(new.morale, 50) >= 50 then 3
      when coalesce(new.morale, 50) >= 35 then 2
      else 1
    end;

    if old.salary is not distinct from new.salary
       and old.birth_date is not distinct from new.birth_date
       and old.contract_expires_at is not distinct from new.contract_expires_at
       and old.potential is not distinct from new.potential
       and old.overall is not distinct from new.overall
       and old.role is not distinct from new.role
       and old.sprint is not distinct from new.sprint
       and old.climbing is not distinct from new.climbing
       and old.time_trial is not distinct from new.time_trial
       and old.endurance is not distinct from new.endurance
       and old.flat is not distinct from new.flat
       and old.recovery is not distinct from new.recovery
       and old.resistance is not distinct from new.resistance
       and old.race_iq is not distinct from new.race_iq
       and old.teamwork is not distinct from new.teamwork
       and old.release_requested is not distinct from new.release_requested
       and v_old_morale_band = v_new_morale_band
    then
      return new;
    end if;
  end if;

  perform public.refresh_rider_value_snapshot(new.id);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_season_reset()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_run_id bigint;
  v_locked boolean;
  v_world_promoted_count integer := 0;
  v_world_relegated_count integer := 0;
  v_pro_promoted_count integer := 0;
  v_pro_relegated_count integer := 0;
  v_continental_promoted_count integer := 0;
  v_continental_relegated_count integer := 0;
  v_playoff_promoted_count integer := 0;
begin
  v_locked := pg_try_advisory_lock(987654321);

  if not v_locked then
    raise exception 'Season reset already running.';
  end if;

  insert into public.season_reset_runs (started_at, message)
  values (now(), 'Season reset started')
  returning id into v_run_id;

  -- Soft-delete inactive real clubs before calculating standings.
  update public.clubs
  set
    deleted_at = now(),
    updated_at = now()
  where deleted_at is null
    and is_ai = false
    and is_active = false;

  create temporary table tmp_active_clubs on commit drop as
  select
    c.id,
    c.name,
    upper(c.country_code) as country_code,
    c.club_tier,
    c.amateur_division,
    c.season_points,
    c.created_at
  from public.clubs c
  where c.deleted_at is null
    and c.is_active = true;

  create temporary table tmp_world_ranked on commit drop as
  select
    id,
    row_number() over (order by season_points desc, name asc, created_at asc) as rank_pos
  from tmp_active_clubs
  where club_tier = 'worldteam';

  create temporary table tmp_pro_ranked on commit drop as
  select
    id,
    row_number() over (order by season_points desc, name asc, created_at asc) as rank_pos
  from tmp_active_clubs
  where club_tier = 'proteam';

  create temporary table tmp_cont_ranked on commit drop as
  select
    id,
    row_number() over (order by season_points desc, name asc, created_at asc) as rank_pos
  from tmp_active_clubs
  where club_tier = 'continental';

  create temporary table tmp_amateur_ranked on commit drop as
  select
    c.id,
    c.amateur_division,
    row_number() over (
      partition by c.amateur_division
      order by c.season_points desc, c.name asc, c.created_at asc
    ) as division_rank
  from tmp_active_clubs c
  where c.club_tier = 'amateur'
    and c.amateur_division is not null;

  create temporary table tmp_relegated_from_world on commit drop as
  select w.id
  from tmp_world_ranked w
  where w.rank_pos > greatest((select count(*) from tmp_world_ranked) - 5, 0);

  create temporary table tmp_promoted_to_world on commit drop as
  select p.id
  from tmp_pro_ranked p
  where p.rank_pos <= 5;

  create temporary table tmp_relegated_from_pro on commit drop as
  select p.id
  from tmp_pro_ranked p
  where p.rank_pos > greatest((select count(*) from tmp_pro_ranked) - 10, 0);

  create temporary table tmp_promoted_to_pro on commit drop as
  select c.id
  from tmp_cont_ranked c
  where c.rank_pos <= 10;

  create temporary table tmp_relegated_from_continental on commit drop as
  select c.id
  from tmp_cont_ranked c
  where c.rank_pos > greatest((select count(*) from tmp_cont_ranked) - 25, 0);

  create temporary table tmp_amateur_division_winners on commit drop as
  select a.id
  from tmp_amateur_ranked a
  where a.division_rank = 1;

  create temporary table tmp_amateur_playoff_candidates on commit drop as
  select
    c.id,
    row_number() over (
      order by c.season_points desc, c.name asc, c.created_at asc
    ) as playoff_rank
  from tmp_active_clubs c
  join tmp_amateur_ranked a on a.id = c.id
  where c.club_tier = 'amateur'
    and a.division_rank in (2, 3, 4);

  create temporary table tmp_amateur_playoff_promoted on commit drop as
  select p.id
  from tmp_amateur_playoff_candidates p
  left join tmp_amateur_division_winners w on w.id = p.id
  where w.id is null
    and p.playoff_rank <= 13;

  -- Promote to World
  update public.clubs c
  set
    club_tier = 'worldteam',
    tier2_division = null,
    tier3_division = null,
    amateur_division = null,
    season_points = 0
  where c.id in (select id from tmp_promoted_to_world);
  get diagnostics v_world_promoted_count = row_count;

  -- Relegate from World to Pro
  update public.clubs c
  set
    club_tier = 'proteam',
    tier2_division = public.get_expected_tier2_division_for_country(c.country_code),
    tier3_division = null,
    amateur_division = null,
    season_points = 0
  where c.id in (select id from tmp_relegated_from_world);
  get diagnostics v_world_relegated_count = row_count;

  -- Promote from Continental to Pro
  update public.clubs c
  set
    club_tier = 'proteam',
    tier2_division = public.get_expected_tier2_division_for_country(c.country_code),
    tier3_division = null,
    amateur_division = null,
    season_points = 0
  where c.id in (select id from tmp_promoted_to_pro);
  get diagnostics v_pro_promoted_count = row_count;

  -- Relegate from Pro to Continental
  update public.clubs c
  set
    club_tier = 'continental',
    tier2_division = null,
    tier3_division = public.get_expected_tier3_division_for_country(c.country_code),
    amateur_division = null,
    season_points = 0
  where c.id in (select id from tmp_relegated_from_pro);
  get diagnostics v_pro_relegated_count = row_count;

  -- Promote from Amateur to Continental
  update public.clubs c
  set
    club_tier = 'continental',
    tier2_division = null,
    tier3_division = public.get_expected_tier3_division_for_country(c.country_code),
    amateur_division = null,
    season_points = 0
  where c.id in (
    select id from tmp_amateur_division_winners
    union
    select id from tmp_amateur_playoff_promoted
  );
  get diagnostics v_continental_promoted_count = row_count;

  select count(*) into v_playoff_promoted_count
  from tmp_amateur_playoff_promoted;

  -- Relegate from Continental to Amateur
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code),
    season_points = 0
  where c.id in (select id from tmp_relegated_from_continental);
  get diagnostics v_continental_relegated_count = row_count;

  -- Reset points for everyone else still active
  update public.clubs
  set season_points = 0
  where deleted_at is null
    and is_active = true
    and id not in (
      select id from tmp_promoted_to_world
      union
      select id from tmp_relegated_from_world
      union
      select id from tmp_promoted_to_pro
      union
      select id from tmp_relegated_from_pro
      union
      select id from tmp_relegated_from_continental
      union
      select id from tmp_amateur_division_winners
      union
      select id from tmp_amateur_playoff_promoted
    );

  update public.season_reset_runs
  set
    finished_at = now(),
    success = true,
    message = 'Season reset completed successfully',
    world_promoted_count = v_world_promoted_count,
    world_relegated_count = v_world_relegated_count,
    pro_promoted_count = v_pro_promoted_count,
    pro_relegated_count = v_pro_relegated_count,
    continental_promoted_count = v_continental_promoted_count,
    continental_relegated_count = v_continental_relegated_count,
    playoff_promoted_count = v_playoff_promoted_count
  where id = v_run_id;

  perform pg_advisory_unlock(987654321);

exception
  when others then
    if v_run_id is not null then
      update public.season_reset_runs
      set
        finished_at = now(),
        success = false,
        message = sqlerrm
      where id = v_run_id;
    end if;

    perform pg_advisory_unlock(987654321);
    raise;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.populate_ai_clubs()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  raise exception
    'populate_ai_clubs is disabled. Legacy placeholder AI club generation is no longer allowed. Use curated AI teams only.';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.assign_new_club_to_ai_slot(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ai_club_id uuid;
  v_ai_world_tier smallint;
  v_ai_tier public.club_tier;
  v_ai_tier2_division text;
  v_ai_tier3_division text;
  v_ai_amateur_division text;
begin
  select
    c.id,
    c.world_tier,
    c.club_tier,
    c.tier2_division,
    c.tier3_division,
    c.amateur_division
  into
    v_ai_club_id,
    v_ai_world_tier,
    v_ai_tier,
    v_ai_tier2_division,
    v_ai_tier3_division,
    v_ai_amateur_division
  from public.clubs c
  where c.deleted_at is null
    and c.is_ai = true
  order by
    case c.club_tier
      when 'worldteam' then 1
      when 'proteam' then 2
      when 'continental' then 3
      when 'amateur' then 4
      else 99
    end asc,
    c.season_points desc,
    c.name asc,
    c.created_at asc
  limit 1;

  if v_ai_club_id is null then
    raise exception 'No AI club available to replace.';
  end if;

  update public.clubs
  set
    world_tier = v_ai_world_tier,
    club_tier = v_ai_tier,
    tier2_division = case
      when v_ai_tier = 'proteam' then v_ai_tier2_division
      else null
    end,
    tier3_division = case
      when v_ai_tier = 'continental' then v_ai_tier3_division
      else null
    end,
    amateur_division = case
      when v_ai_tier = 'amateur' then v_ai_amateur_division
      else null
    end,
    season_points = 0,
    is_ai = false,
    is_active = true
  where id = p_club_id;

  /*
    Important:
    Do not hard-delete the replaced AI club.

    The old version used:
      delete from public.clubs where id = v_ai_club_id;

    That cascades into finance accounts / entries and hits the immutable
    ledger guard. Instead, retire the AI club softly.
  */
  update public.clubs
  set
    deleted_at = now(),
    is_active = false
  where id = v_ai_club_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_assign_new_real_club_to_ai_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if new.is_ai = false
     and coalesce(new.club_type, 'main') = 'main' then
    perform public.assign_new_club_to_ai_slot(new.id);
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_profiles_mark_club_inactive_on_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_season integer;
begin
  begin v_season:=public.get_current_season_number(); exception when others then v_season:=null; end;
  update public.clubs
  set owner_user_id=null,
      is_active=false,
      season_points=0,
      inactivity_status='season_end_removal_pending',
      inactive_ai_controlled=false,
      season_end_transition_pending=true,
      inactivity_season_end_action='replace_with_ai_pool_team',
      inactivity_effective_season=v_season,
      inactivity_reason='owner_profile_deleted_season_end_removal_pending',
      archived_at=coalesce(archived_at,now()),
      updated_at=now()
  where owner_user_id=old.id and deleted_at is null and is_ai=false;
  return old;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_season_reset_if_due()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_season integer; v_month_number smallint; v_day_number smallint; v_source_season integer;
  v_timeline_id uuid; v_is_armed boolean; v_armed_source integer; v_armed_target integer; v_already_completed boolean;
  v_transition_run_id uuid; v_snapshot_rows integer:=0; v_component_result jsonb; v_error text;
  v_notification_result jsonb; v_notification_error text;
begin
  select g.season_number,g.month_number,g.day_number into v_target_season,v_month_number,v_day_number from public.get_current_game_date() g;
  if v_target_season is null then raise exception 'Unable to determine current game date from game_state.'; end if;
  if v_month_number<>1 or v_day_number not in(1,2) then return; end if;
  v_source_season:=v_target_season-1; if v_source_season<=0 then return; end if;

  select c.timeline_id,c.is_armed,c.armed_source_season,c.armed_target_season
  into v_timeline_id,v_is_armed,v_armed_source,v_armed_target
  from public.season_transition_control_v1 c where c.id=true for update;
  if v_timeline_id is null then raise exception 'Season transition control is missing.'; end if;

  select exists(select 1 from public.season_transition_runs_v1 r where r.timeline_id=v_timeline_id and r.source_season=v_source_season and r.target_season=v_target_season and r.status='completed') into v_already_completed;
  if v_already_completed then return; end if;
  if not coalesce(v_is_armed,false) or v_armed_source is distinct from v_source_season or v_armed_target is distinct from v_target_season then return; end if;

  if exists(select 1 from public.season_transition_component_readiness_v1 where required=true and status<>'ready') then
    update public.game_state set is_paused=true where id=true;
    update public.game_clock_config set is_paused=true where id=true;
    update public.season_transition_control_v1 set is_armed=false,armed_source_season=null,armed_target_season=null,armed_at=null,
      armed_note='Auto-disarmed: readiness gate was not fully green',updated_at=now() where id=true;
    return;
  end if;

  if not pg_try_advisory_xact_lock(hashtext('public.run_season_reset_if_due.transition')::bigint) then return; end if;

  insert into public.season_transition_runs_v1(timeline_id,source_season,target_season,status,metadata)
  values(v_timeline_id,v_source_season,v_target_season,'running',jsonb_build_object('trigger_month',v_month_number,'trigger_day',v_day_number,
    'started_game_date',public.get_current_game_date_date(),'framework_version',1)) returning id into v_transition_run_id;

  begin
    v_snapshot_rows:=public.snapshot_team_rankings_for_season_v1(v_source_season);
    v_component_result:=public.execute_season_transition_components_v1(v_transition_run_id,v_source_season,v_target_season);
  exception when others then
    v_error:=sqlerrm;
    update public.season_transition_runs_v1 set status='failed',finished_at=now(),error_message=v_error,
      metadata=metadata||jsonb_build_object('failed_game_date',public.get_current_game_date_date(),'failure_sqlstate',sqlstate,'clock_frozen',true)
    where id=v_transition_run_id;
    update public.season_transition_control_v1 set is_armed=false,armed_source_season=null,armed_target_season=null,armed_at=null,
      armed_note=format('Auto-disarmed after failed transition %s -> %s: %s',v_source_season,v_target_season,v_error),updated_at=now() where id=true;
    update public.game_state set is_paused=true where id=true;
    update public.game_clock_config set is_paused=true where id=true;
    return;
  end;

  update public.season_transition_runs_v1
  set status='completed',finished_at=now(),snapshot_rows=v_snapshot_rows,legacy_reset_run_id=null,
      metadata=metadata||jsonb_build_object('completed_game_date',public.get_current_game_date_date(),'legacy_guard_was_ignored',true,'component_result',v_component_result)
  where id=v_transition_run_id;

  -- Post-completion communication is retryable and must never invalidate a successful sporting transition.
  begin
    v_notification_result:=public.run_post_season_transition_notifications_v1(v_transition_run_id,v_source_season,v_target_season);
    update public.season_transition_runs_v1 set metadata=metadata||jsonb_build_object('post_transition_notifications',v_notification_result) where id=v_transition_run_id;
  exception when others then
    v_notification_error:=sqlerrm;
    update public.season_transition_runs_v1 set metadata=metadata||jsonb_build_object('post_transition_notifications_error',v_notification_error) where id=v_transition_run_id;
  end;

  insert into public.season_reset_guard(season_number,reset_ran_on_month,reset_ran_on_day,created_at)
  values(v_target_season,v_month_number,v_day_number,now())
  on conflict(season_number) do update set reset_ran_on_month=excluded.reset_ran_on_month,reset_ran_on_day=excluded.reset_ran_on_day,created_at=excluded.created_at;

  update public.season_transition_control_v1
  set is_armed=false,armed_source_season=null,armed_target_season=null,armed_at=null,
      armed_note=format('Auto-disarmed after successful transition %s -> %s',v_source_season,v_target_season),updated_at=now()
  where id=true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rebalance_competition_structure()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_needed integer;
begin
  ---------------------------------------------------------------------------
  -- STEP 1: Fix structurally invalid division assignments from country mapping
  ---------------------------------------------------------------------------

  -- Amateur clubs must always match country -> amateur division
  update public.clubs c
  set
    amateur_division = public.get_amateur_division_for_country(c.country_code),
    tier2_division = null,
    tier3_division = null
  where c.deleted_at is null
    and c.club_tier = 'amateur'
    and (
      c.amateur_division is distinct from public.get_amateur_division_for_country(c.country_code)
      or c.tier2_division is not null
      or c.tier3_division is not null
    );

  -- Continental clubs must always match country -> tier3 division
  update public.clubs c
  set
    tier3_division = public.get_expected_tier3_division_for_country(c.country_code),
    tier2_division = null,
    amateur_division = null
  where c.deleted_at is null
    and c.club_tier = 'continental'
    and (
      c.tier3_division is distinct from public.get_expected_tier3_division_for_country(c.country_code)
      or c.tier2_division is not null
      or c.amateur_division is not null
    );

  -- Pro clubs must always match country -> tier2 division
  update public.clubs c
  set
    tier2_division = public.get_expected_tier2_division_for_country(c.country_code),
    tier3_division = null,
    amateur_division = null
  where c.deleted_at is null
    and c.club_tier = 'proteam'
    and (
      c.tier2_division is distinct from public.get_expected_tier2_division_for_country(c.country_code)
      or c.tier3_division is not null
      or c.amateur_division is not null
    );

  -- World clubs must have no lower-division fields
  update public.clubs c
  set
    tier2_division = null,
    tier3_division = null,
    amateur_division = null
  where c.deleted_at is null
    and c.club_tier = 'worldteam'
    and (
      c.tier2_division is not null
      or c.tier3_division is not null
      or c.amateur_division is not null
    );

  ---------------------------------------------------------------------------
  -- STEP 2: WORLD exact 25
  -- Fill shortages from best eligible AI in Pro
  -- Trim overflow by moving weakest AI to correct Pro division
  ---------------------------------------------------------------------------

  -- Fill World up to 25 from best AI Pro teams
  select greatest(
    25 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'worldteam'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'proteam'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'worldteam',
      tier2_division = null,
      tier3_division = null,
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- Trim World above 25 by relegating weakest AI to proper Pro division
  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'worldteam'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'worldteam'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'proteam',
    tier2_division = public.get_expected_tier2_division_for_country(c.country_code),
    tier3_division = null,
    amateur_division = null
  where c.id in (select id from overflow);

  ---------------------------------------------------------------------------
  -- STEP 3: PRO divisions min/max
  ---------------------------------------------------------------------------

  -- Fill PRO_WEST up to min 20 from best eligible AI Continental
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'proteam'
        and tier2_division = 'PRO_WEST'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'continental'
        and public.get_expected_tier2_division_for_country(c.country_code) = 'PRO_WEST'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'proteam',
      tier2_division = 'PRO_WEST',
      tier3_division = null,
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- Fill PRO_EAST up to min 20 from best eligible AI Continental
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'proteam'
        and tier2_division = 'PRO_EAST'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'continental'
        and public.get_expected_tier2_division_for_country(c.country_code) = 'PRO_EAST'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'proteam',
      tier2_division = 'PRO_EAST',
      tier3_division = null,
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- Trim PRO_WEST above max 25 using weakest AI clubs
  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'proteam'
      and c.tier2_division = 'PRO_WEST'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'proteam'
          and tier2_division = 'PRO_WEST'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'continental',
    tier2_division = null,
    tier3_division = public.get_expected_tier3_division_for_country(c.country_code),
    amateur_division = null
  where c.id in (select id from overflow);

  -- Trim PRO_EAST above max 25 using weakest AI clubs
  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'proteam'
      and c.tier2_division = 'PRO_EAST'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'proteam'
          and tier2_division = 'PRO_EAST'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'continental',
    tier2_division = null,
    tier3_division = public.get_expected_tier3_division_for_country(c.country_code),
    amateur_division = null
  where c.id in (select id from overflow);

  ---------------------------------------------------------------------------
  -- STEP 4: TIER3 divisions min/max
  ---------------------------------------------------------------------------

  -- CONTINENTAL_EUROPE fill to min 20 from best eligible AI Amateur
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'continental'
        and tier3_division = 'CONTINENTAL_EUROPE'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'amateur'
        and public.get_expected_tier3_division_for_country(c.country_code) = 'CONTINENTAL_EUROPE'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'continental',
      tier2_division = null,
      tier3_division = 'CONTINENTAL_EUROPE',
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- CONTINENTAL_AMERICA
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'continental'
        and tier3_division = 'CONTINENTAL_AMERICA'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'amateur'
        and public.get_expected_tier3_division_for_country(c.country_code) = 'CONTINENTAL_AMERICA'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'continental',
      tier2_division = null,
      tier3_division = 'CONTINENTAL_AMERICA',
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- CONTINENTAL_ASIA
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'continental'
        and tier3_division = 'CONTINENTAL_ASIA'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'amateur'
        and public.get_expected_tier3_division_for_country(c.country_code) = 'CONTINENTAL_ASIA'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'continental',
      tier2_division = null,
      tier3_division = 'CONTINENTAL_ASIA',
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- CONTINENTAL_AFRICA
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'continental'
        and tier3_division = 'CONTINENTAL_AFRICA'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'amateur'
        and public.get_expected_tier3_division_for_country(c.country_code) = 'CONTINENTAL_AFRICA'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'continental',
      tier2_division = null,
      tier3_division = 'CONTINENTAL_AFRICA',
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- CONTINENTAL_OCEANIA
  select greatest(
    20 - (
      select count(*)
      from public.clubs
      where deleted_at is null
        and is_active = true
        and club_tier = 'continental'
        and tier3_division = 'CONTINENTAL_OCEANIA'
    ),
    0
  )
  into v_needed;

  if v_needed > 0 then
    with candidates as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_active = true
        and c.is_ai = true
        and c.club_tier = 'amateur'
        and public.get_expected_tier3_division_for_country(c.country_code) = 'CONTINENTAL_OCEANIA'
      order by c.season_points desc, c.name asc, c.created_at asc
      limit v_needed
    )
    update public.clubs c
    set
      club_tier = 'continental',
      tier2_division = null,
      tier3_division = 'CONTINENTAL_OCEANIA',
      amateur_division = null
    where c.id in (select id from candidates);
  end if;

  -- Trim Tier3 overflows using weakest AI down to correct amateur division
  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'continental'
      and c.tier3_division = 'CONTINENTAL_EUROPE'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'continental'
          and tier3_division = 'CONTINENTAL_EUROPE'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code)
  where c.id in (select id from overflow);

  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'continental'
      and c.tier3_division = 'CONTINENTAL_AMERICA'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'continental'
          and tier3_division = 'CONTINENTAL_AMERICA'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code)
  where c.id in (select id from overflow);

  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'continental'
      and c.tier3_division = 'CONTINENTAL_ASIA'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'continental'
          and tier3_division = 'CONTINENTAL_ASIA'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code)
  where c.id in (select id from overflow);

  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'continental'
      and c.tier3_division = 'CONTINENTAL_AFRICA'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'continental'
          and tier3_division = 'CONTINENTAL_AFRICA'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code)
  where c.id in (select id from overflow);

  with overflow as (
    select c.id
    from public.clubs c
    where c.deleted_at is null
      and c.is_active = true
      and c.is_ai = true
      and c.club_tier = 'continental'
      and c.tier3_division = 'CONTINENTAL_OCEANIA'
    order by c.season_points asc, c.name desc, c.created_at desc
    limit greatest(
      (
        select count(*)
        from public.clubs
        where deleted_at is null
          and is_active = true
          and club_tier = 'continental'
          and tier3_division = 'CONTINENTAL_OCEANIA'
      ) - 25,
      0
    )
  )
  update public.clubs c
  set
    club_tier = 'amateur',
    tier2_division = null,
    tier3_division = null,
    amateur_division = public.get_amateur_division_for_country(c.country_code)
  where c.id in (select id from overflow);

end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_ai_club_in_amateur_division(p_amateur_division text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  raise exception
    'create_ai_club_in_amateur_division is disabled. Active AI teams must come from the curated AI pool with logo_path. Missing competition slots must be filled from public.ai_competition_filler_club_pool_v1, not by generating placeholder clubs.';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fill_ai_fallback_and_rebalance()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_needed integer;
  v_i integer;
  v_division text;
begin
  -- Ensure each amateur division has at least 10 active AI clubs
  foreach v_division in array array[
    'NORTH_AMERICA',
    'SOUTH_AMERICA',
    'WESTERN_EUROPE',
    'CENTRAL_EUROPE',
    'SOUTHERN_BALKAN_EUROPE',
    'NORTHERN_EASTERN_EUROPE',
    'WEST_NORTH_AFRICA',
    'CENTRAL_SOUTH_AFRICA',
    'WEST_CENTRAL_ASIA',
    'SOUTH_ASIA',
    'EAST_SOUTHEAST_ASIA',
    'OCEANIA'
  ]
  loop
    select greatest(
      10 - (
        select count(*)
        from public.clubs c
        where c.deleted_at is null
          and c.is_active = true
          and c.is_ai = true
          and c.club_tier = 'amateur'
          and c.amateur_division = v_division
      ),
      0
    )
    into v_needed;

    if v_needed > 0 then
      for v_i in 1..v_needed loop
        perform public.create_ai_club_in_amateur_division(v_division);
      end loop;
    end if;
  end loop;

  -- Rebalance after filling amateur AI shortages
  perform public.rebalance_competition_structure();

  -- Optional second pass:
  -- if higher divisions promoted many new amateur AI upward, amateur mins might dip again
  foreach v_division in array array[
    'NORTH_AMERICA',
    'SOUTH_AMERICA',
    'WESTERN_EUROPE',
    'CENTRAL_EUROPE',
    'SOUTHERN_BALKAN_EUROPE',
    'NORTHERN_EASTERN_EUROPE',
    'WEST_NORTH_AFRICA',
    'CENTRAL_SOUTH_AFRICA',
    'WEST_CENTRAL_ASIA',
    'SOUTH_ASIA',
    'EAST_SOUTHEAST_ASIA',
    'OCEANIA'
  ]
  loop
    select greatest(
      10 - (
        select count(*)
        from public.clubs c
        where c.deleted_at is null
          and c.is_active = true
          and c.is_ai = true
          and c.club_tier = 'amateur'
          and c.amateur_division = v_division
      ),
      0
    )
    into v_needed;

    if v_needed > 0 then
      for v_i in 1..v_needed loop
        perform public.create_ai_club_in_amateur_division(v_division);
      end loop;
    end if;
  end loop;

  -- Final rebalance so new fallback AI can flow upward if still needed
  perform public.rebalance_competition_structure();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.advance_game_state_one_hour()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_season integer;
  v_month smallint;
  v_day smallint;
  v_hour smallint;
  v_minute smallint;
  v_days_in_month integer;
  v_old_date date;
  v_new_date date;
  v_gate jsonb;
begin
  select
    season_number,
    month_number,
    day_number,
    coalesce(hour_number, 0),
    coalesce(minute_number, 0)
  into
    v_season,
    v_month,
    v_day,
    v_hour,
    v_minute
  from public.game_state
  where id = true
  for update;

  if not found then
    raise exception 'game_state is not initialized';
  end if;

  v_old_date := make_date(1999 + v_season, v_month, v_day);
  v_hour := v_hour + 1;

  if v_hour >= 24 then
    v_hour := 0;
    v_day := v_day + 1;
  end if;

  v_days_in_month := case v_month
    when 1 then 31 when 2 then 28 when 3 then 31 when 4 then 30
    when 5 then 31 when 6 then 30 when 7 then 31 when 8 then 31
    when 9 then 30 when 10 then 31 when 11 then 30 when 12 then 31
    else 31
  end;

  if v_day > v_days_in_month then
    v_day := 1;
    v_month := v_month + 1;
  end if;

  if v_month > 12 then
    v_month := 1;
    v_season := v_season + 1;
  end if;

  v_new_date := make_date(1999 + v_season, v_month, v_day);

  if public.season_from_game_date(v_new_date) > public.season_from_game_date(v_old_date) then
    v_gate := public.season_transition_boundary_gate_v1(v_old_date, v_new_date);
    if not coalesce((v_gate ->> 'allowed')::boolean, false) then
      return;
    end if;
  end if;

  update public.game_state
  set
    season_number = v_season,
    month_number = v_month,
    day_number = v_day,
    hour_number = v_hour,
    minute_number = v_minute,
    tick_version = tick_version + 1,
    last_advanced_at = now()
  where id = true;

  perform public.run_season_reset_if_due();
  perform public.complete_due_rider_scout_tasks();
  perform public.run_hourly_game_processors_v1(false);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_game_tick_if_unpaused()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_paused boolean;
begin
  select is_paused
  into v_paused
  from public.game_state
  where id = true;

  if v_paused then
    return;
  end if;

  perform public.advance_game_state_one_hour();
  perform public.process_due_game_events();
  perform public.run_hourly_game_processors_v1(false);
end;
$function$
;

