  end if;

  v_hour := v_hour + 1;

  if v_hour >= 24 then
    v_hour := 0;
    v_day := v_day + 1;
  end if;

  v_days_in_month := case v_month
    when 1 then 31
    when 2 then 28
    when 3 then 31
    when 4 then 30
    when 5 then 31
    when 6 then 30
    when 7 then 31
    when 8 then 31
    when 9 then 30
    when 10 then 31
