CREATE OR REPLACE FUNCTION public.build_finance_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_alerts jsonb := '[]'::jsonb;
  v_finance jsonb := coalesce(public.get_dashboard_finance(), '{}'::jsonb);

  v_balance numeric := coalesce(nullif(v_finance->>'balance', '')::numeric, 0);
  v_weekly_net numeric := coalesce(nullif(v_finance->>'weeklyNet', '')::numeric, 0);
  v_next_trip_forecast numeric := coalesce(nullif(v_finance->>'nextTripForecast', '')::numeric, 0);
begin
  if v_balance <= 0 then
    v_alerts := v_alerts || jsonb_build_array(
      jsonb_build_object(
        'id', 'cash-critical',
        'label', 'Club cash is critically low',
        'level', 'danger',
        'href', '#/dashboard/finance',
        'priority', 8,
        'groupKey', 'cash-status'
      )
    );
  elsif v_balance < 50000 then
    v_alerts := v_alerts || jsonb_build_array(
      jsonb_build_object(
        'id', 'cash-low',
        'label', 'Cash balance is running low',
        'level', 'warning',
        'href', '#/dashboard/finance',
        'priority', 24,
        'groupKey', 'cash-status'
      )
    );
  end if;

  if v_weekly_net < 0 then
    v_alerts := v_alerts || jsonb_build_array(
      jsonb_build_object(
        'id', 'weekly-net-negative',
        'label', 'Weekly net is negative',
        'level', 'warning',
        'href', '#/dashboard/finance',
        'priority', 27,
        'groupKey', 'weekly-net'
      )
    );
  end if;

  if v_next_trip_forecast > 0 and v_next_trip_forecast > v_balance then
    v_alerts := v_alerts || jsonb_build_array(
      jsonb_build_object(
        'id', 'trip-not-funded',
        'label', 'Upcoming trip cannot be funded',
        'level', 'danger',
        'href', '#/dashboard/finance',
        'priority', 12,
        'groupKey', 'trip-funding'
      )
    );
  end if;

  return v_alerts;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.build_sponsor_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_alerts jsonb := '[]'::jsonb;
  v_sponsor jsonb := coalesce(public.get_dashboard_main_sponsor(), '{}'::jsonb);
  v_feed jsonb := coalesce(public.get_dashboard_activity_feed(8), '[]'::jsonb);

  v_item jsonb;
  v_title text;
  v_level text;

  v_logo_url text := coalesce(
    nullif(v_sponsor->>'logoUrl', ''),
    nullif(v_sponsor->>'logo_url', ''),
    nullif(v_sponsor->>'logo', ''),
    nullif(v_sponsor->>'imageUrl', ''),
    nullif(v_sponsor->>'image_url', '')
  );

  v_is_active boolean := coalesce(nullif(v_sponsor->>'isActive', '')::boolean, false);
begin
  if not v_is_active and v_logo_url is null then
    v_alerts := v_alerts || jsonb_build_array(
      jsonb_build_object(
        'id', 'no-main-sponsor',
        'label', 'No main sponsor signed',
        'level', 'warning',
        'href', '#/dashboard/finance',
        'priority', 16,
        'groupKey', 'main-sponsor'
      )
    );
  end if;

  for v_item in
    select value
    from jsonb_array_elements(v_feed)
  loop
    v_level := lower(coalesce(v_item->>'level', ''));
    v_title := lower(coalesce(v_item->>'title', ''));

    if v_level = 'sponsor' and v_title like '%offer%' then
      v_alerts := v_alerts || jsonb_build_array(
        jsonb_build_object(
          'id', 'sponsor-offer-received',
          'label', 'New sponsor offer received',
          'level', 'info',
          'href', '#/dashboard/finance',
          'priority', 42,
          'groupKey', 'sponsor-offers'
        )
      );
    end if;

    if v_level = 'sponsor' and v_title like '%selection required%' then
      v_alerts := v_alerts || jsonb_build_array(
        jsonb_build_object(
          'id', 'sponsor-selection-required',
          'label', 'Sponsor selection required',
          'level', 'warning',
          'href', '#/dashboard/finance',
          'priority', 17,
          'groupKey', 'main-sponsor'
        )
      );
    end if;
  end loop;

  return v_alerts;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.build_infrastructure_alerts()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_alerts jsonb := '[]'::jsonb;
  v_operations jsonb := coalesce(public.get_dashboard_operations(), '[]'::jsonb);
  v_feed jsonb := coalesce(public.get_dashboard_activity_feed(8), '[]'::jsonb);

  v_item jsonb;
  v_title text;
  v_status text;
  v_summary text;
  v_level text;
begin
  for v_item in
    select value
    from jsonb_array_elements(v_operations)
  loop
    v_title := lower(coalesce(v_item->>'title', ''));
    v_status := lower(coalesce(v_item->>'status', ''));
    v_summary := lower(coalesce(v_item->>'summary', ''));

    if v_title like '%infrastructure%' or v_summary like '%medical center%' or v_summary like '%van%' then
      if v_status = 'in progress' then
        v_alerts := v_alerts || jsonb_build_array(
          jsonb_build_object(
            'id', 'infrastructure-in-progress',
            'label', 'Infrastructure work in progress',
            'level', 'info',
            'href', '#/dashboard/infrastructure',
            'priority', 50,
            'groupKey', 'infrastructure-status'
          )
        );
      elsif v_summary like '%completed%' then
        v_alerts := v_alerts || jsonb_build_array(
          jsonb_build_object(
            'id', 'infrastructure-completed',
            'label', 'Infrastructure work completed',
            'level', 'success',
            'href', '#/dashboard/infrastructure',
            'priority', 60,
            'groupKey', 'infrastructure-status'
          )
        );
      end if;
    end if;
  end loop;

  for v_item in
    select value
    from jsonb_array_elements(v_feed)
  loop
    v_level := lower(coalesce(v_item->>'level', ''));
    v_title := coalesce(v_item->>'title', '');
    v_summary := lower(coalesce(v_item->>'subtitle', ''));

    if v_level = 'infrastructure' then
      if lower(v_title) like '%completed%' or lower(v_title) like '%delivered%' or v_summary like '%improved%' then
        v_alerts := v_alerts || jsonb_build_array(
          jsonb_build_object(
            'id', 'infrastructure-feed-complete',
            'label', v_title,
            'level', 'success',
            'href', '#/dashboard/infrastructure',
            'priority', 58,
            'groupKey', 'infrastructure-feed'
          )
        );
      end if;
    end if;
  end loop;

  return v_alerts;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_create_rider_transfer_listing(p_seller_club_id uuid, p_rider_id uuid, p_asking_price bigint DEFAULT NULL::bigint, p_duration_days integer DEFAULT 7, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(listing_id uuid, rider_id uuid, seller_club_id uuid, asking_price bigint, min_allowed_price bigint, max_allowed_price bigint, listed_on_game_date date, expires_on_game_date date, status text, auto_price_clamped boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_market_value bigint;
  v_default_asking bigint;
  v_min_price bigint;
  v_max_price bigint;
  v_final_price bigint;
  v_auto_clamped boolean := false;
  v_listing_id uuid;
  v_expires date;
begin
  if p_seller_club_id is null or p_rider_id is null then
    raise exception 'Seller club and rider are required';
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_seller_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider does not belong to seller club';
  end if;

  if exists (
    select 1
    from public.rider_free_agents fa
    where fa.rider_id = p_rider_id
      and fa.status in ('available', 'signed')
  ) then
    raise exception 'Rider is already in free agent flow';
  end if;

  v_game_date := public.get_current_game_date_date();

  perform public.refresh_rider_value_snapshot(p_rider_id);

  select
    r.market_value,
    coalesce(r.asking_price, public.calculate_rider_default_asking_price(r.id))
  into
    v_market_value,
    v_default_asking
  from public.riders r
  where r.id = p_rider_id;

  if v_market_value is null then
    raise exception 'Could not resolve rider market value';
  end if;

  v_min_price := greatest(1000, round(v_market_value::numeric * 0.75)::bigint);
  v_max_price := greatest(v_min_price, round(v_market_value::numeric * 1.25)::bigint);
  v_final_price := coalesce(p_asking_price, v_default_asking);

  if v_final_price < v_min_price then
    v_final_price := v_min_price;
    v_auto_clamped := true;
  end if;

  if v_final_price > v_max_price then
    v_final_price := v_max_price;
    v_auto_clamped := true;
  end if;

  v_expires :=
    case
      when p_duration_days is null or p_duration_days <= 0 then null
      else v_game_date + p_duration_days
    end;

  insert into public.rider_transfer_listings (
    rider_id,
    seller_club_id,
    asking_price,
    min_allowed_price,
    max_allowed_price,
    listed_on_game_date,
    expires_on_game_date,
    status,
    auto_price_clamped
  )
  values (
    p_rider_id,
    p_seller_club_id,
    v_final_price,
    v_min_price,
    v_max_price,
    v_game_date,
    v_expires,
    'listed',
    v_auto_clamped
  )
  on conflict on constraint rider_transfer_listings_rider_id_key
  do update
  set
    seller_club_id = excluded.seller_club_id,
    asking_price = excluded.asking_price,
    min_allowed_price = excluded.min_allowed_price,
    max_allowed_price = excluded.max_allowed_price,
    listed_on_game_date = excluded.listed_on_game_date,
    expires_on_game_date = excluded.expires_on_game_date,
    status = 'listed',
    auto_price_clamped = excluded.auto_price_clamped,
    updated_at = now()
  returning public.rider_transfer_listings.id
  into v_listing_id;

  update public.riders r
  set
    asking_price = v_final_price,
    asking_price_manual = true,
    asking_price_updated_at = now(),
    release_requested = true
  where r.id = p_rider_id;

  perform public.log_rider_transfer_event(
    p_event_type      => 'listing_created',
    p_rider_id        => p_rider_id,
    p_listing_id      => v_listing_id,
    p_seller_club_id  => p_seller_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'asking_price', v_final_price,
      'min_allowed_price', v_min_price,
      'max_allowed_price', v_max_price,
      'expires_on_game_date', v_expires,
      'auto_price_clamped', v_auto_clamped,
      'source', 'admin_helper'
    )
  );

  return query
  select
    l.id,
    l.rider_id,
    l.seller_club_id,
    l.asking_price,
    l.min_allowed_price,
    l.max_allowed_price,
    l.listed_on_game_date,
    l.expires_on_game_date,
    l.status,
    l.auto_price_clamped
  from public.rider_transfer_listings l
  where l.id = v_listing_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_accept_rider_transfer_offer(p_offer_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(offer_id uuid, listing_id uuid, rider_id uuid, seller_club_id uuid, buyer_club_id uuid, negotiation_id uuid, negotiation_status text, closed_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer public.rider_transfer_offers%rowtype;
  v_start record;
  v_game_date date;
begin
  if p_offer_id is null then
    raise exception 'Offer id is required';
  end if;

  v_game_date := public.get_current_game_date_date();

  select *
  into v_offer
  from public.rider_transfer_offers o
  where o.id = p_offer_id
  for update;

  if not found then
    raise exception 'Transfer offer not found';
  end if;

  select *
  into v_start
  from public._start_rider_transfer_negotiation_internal(
    p_offer_id => v_offer.id,
    p_accepted_by => p_actor_user_id,
    p_auto_accepted => false
  );

  perform public.log_rider_transfer_event(
    p_event_type      => 'offer_accepted_by_seller',
    p_rider_id        => v_offer.rider_id,
    p_listing_id      => v_offer.listing_id,
    p_offer_id        => v_offer.id,
    p_negotiation_id  => v_start.negotiation_id,
    p_seller_club_id  => v_offer.seller_club_id,
    p_buyer_club_id   => v_offer.buyer_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'negotiation_status', v_start.negotiation_status,
      'closed_reason', v_start.closed_reason,
      'source', 'admin_helper'
    )
  );

  return query
  select
    v_offer.id,
    v_offer.listing_id,
    v_offer.rider_id,
    v_offer.seller_club_id,
    v_offer.buyer_club_id,
    v_start.negotiation_id,
    v_start.negotiation_status,
    v_start.closed_reason;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_submit_rider_transfer_contract_offer(p_negotiation_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons smallint, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(negotiation_id uuid, offer_id uuid, rider_id uuid, buyer_club_id uuid, offered_salary_weekly integer, offered_duration_seasons smallint, accepted boolean, status text, message text, transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_neg public.rider_transfer_negotiations%rowtype;
  v_now_game_date date;
  v_min_duration smallint;
  v_accepted boolean := false;
  v_hard_decline boolean := false;
  v_tx uuid := null;
begin
  if p_negotiation_id is null then
    raise exception 'Negotiation id is required';
  end if;

  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Salary offer must be > 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons < 1 or p_offer_duration_seasons > 5 then
    raise exception 'Contract duration must be between 1 and 5 seasons';
  end if;

  select *
  into v_neg
  from public.rider_transfer_negotiations n
  where n.id = p_negotiation_id
  for update;

  if not found then
    raise exception 'Transfer negotiation not found';
  end if;

  if v_neg.status <> 'open' then
    raise exception 'Only open transfer negotiations can receive rider contract offers';
  end if;

  v_now_game_date := public.get_current_game_date_date();

  if v_neg.expires_on_game_date < v_now_game_date then
    update public.rider_transfer_negotiations n
    set
      status = 'expired',
      closed_reason = 'negotiation_expired'
    where n.id = v_neg.id
      and n.status = 'open';

    update public.rider_transfer_offers o
    set
      status = 'expired',
      auto_block_reason = 'rider_negotiation_expired',
      metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
        'expired_at', now(),
        'expired_reason', 'rider_negotiation_expired'
      )
    where o.id = v_neg.offer_id
      and o.status = 'club_accepted';

    update public.rider_transfer_listings l
    set status = 'listed'
    where l.id = v_neg.listing_id
      and l.status = 'club_accepted'
      and (l.expires_on_game_date is null or l.expires_on_game_date >= v_now_game_date);

    perform public.log_rider_transfer_event(
      p_event_type      => 'negotiation_expired',
      p_rider_id        => v_neg.rider_id,
      p_listing_id      => v_neg.listing_id,
      p_offer_id        => v_neg.offer_id,
      p_negotiation_id  => v_neg.id,
      p_seller_club_id  => v_neg.seller_club_id,
      p_buyer_club_id   => v_neg.buyer_club_id,
      p_actor_user_id   => p_actor_user_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'reason', 'negotiation_expired',
        'source', 'admin_helper'
      )
    );

    raise exception 'Negotiation has expired';
  end if;

  if v_neg.locked_until is not null and v_neg.locked_until > now() then
    raise exception 'Negotiation is temporarily locked until %', v_neg.locked_until;
  end if;

  update public.rider_transfer_negotiations n
  set
    offer_salary_weekly = p_offer_salary_weekly,
    offer_duration_seasons = p_offer_duration_seasons,
    attempt_count = n.attempt_count + 1,
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'last_offer_at', now(),
      'last_offer_by', p_actor_user_id,
      'source', 'admin_helper'
    )
  where n.id = v_neg.id
  returning *
  into v_neg;

  perform public.log_rider_transfer_event(
    p_event_type      => 'contract_terms_submitted',
    p_rider_id        => v_neg.rider_id,
    p_listing_id      => v_neg.listing_id,
    p_offer_id        => v_neg.offer_id,
    p_negotiation_id  => v_neg.id,
    p_seller_club_id  => v_neg.seller_club_id,
    p_buyer_club_id   => v_neg.buyer_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offer_salary_weekly', p_offer_salary_weekly,
      'offer_duration_seasons', p_offer_duration_seasons,
      'attempt_count', v_neg.attempt_count,
      'source', 'admin_helper'
    )
  );

  v_min_duration := greatest(1, coalesce(v_neg.preferred_duration_seasons, 1) - 1);

  v_accepted :=
    p_offer_salary_weekly >= v_neg.min_acceptable_salary_weekly
    and p_offer_duration_seasons >= v_min_duration;

  v_hard_decline :=
    p_offer_salary_weekly < greatest(1, floor(v_neg.min_acceptable_salary_weekly * 0.85)::integer)
    or p_offer_duration_seasons < greatest(1, coalesce(v_neg.preferred_duration_seasons, 1) - 2)
    or v_neg.attempt_count >= v_neg.max_attempts;

  if v_accepted then
    update public.rider_transfer_negotiations n
    set
      status = 'accepted',
      locked_until = null,
      closed_reason = null,
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'rider_accepted_terms_at', now(),
        'source', 'admin_helper'
      )
    where n.id = v_neg.id;

    v_tx := public._complete_rider_transfer_after_negotiation_internal(v_neg.id);

    return query
    select
      v_neg.id,
      v_neg.offer_id,
      v_neg.rider_id,
      v_neg.buyer_club_id,
      p_offer_salary_weekly,
      p_offer_duration_seasons,
      true,
      'completed'::text,
      'Rider accepted the contract terms. Transfer completed.'::text,
      v_tx;
    return;
  end if;

  if v_hard_decline then
    update public.rider_transfer_negotiations n
    set
      status = 'declined',
      locked_until = null,
      closed_reason = 'salary_or_duration_not_competitive',
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'rider_declined_at', now(),
        'source', 'admin_helper'
      )
    where n.id = v_neg.id
    returning *
    into v_neg;

    update public.rider_transfer_offers o
    set
      status = 'rider_declined',
      auto_block_reason = 'rider_declined_terms',
      metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
        'rider_declined_at', now(),
        'rider_decline_reason', 'salary_or_duration_not_competitive'
      )
    where o.id = v_neg.offer_id
      and o.status in ('open', 'club_accepted');

    update public.rider_transfer_listings l
    set status = 'listed'
    where l.id = v_neg.listing_id
      and l.status = 'club_accepted'
      and (l.expires_on_game_date is null or l.expires_on_game_date >= v_now_game_date);

    perform public.log_rider_transfer_event(
      p_event_type      => 'rider_declined_terms',
      p_rider_id        => v_neg.rider_id,
      p_listing_id      => v_neg.listing_id,
      p_offer_id        => v_neg.offer_id,
      p_negotiation_id  => v_neg.id,
      p_seller_club_id  => v_neg.seller_club_id,
      p_buyer_club_id   => v_neg.buyer_club_id,
      p_actor_user_id   => p_actor_user_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'offer_salary_weekly', p_offer_salary_weekly,
        'offer_duration_seasons', p_offer_duration_seasons,
        'reason', 'salary_or_duration_not_competitive',
        'source', 'admin_helper'
      )
    );

    return query
    select
      v_neg.id,
      v_neg.offer_id,
      v_neg.rider_id,
      v_neg.buyer_club_id,
      p_offer_salary_weekly,
      p_offer_duration_seasons,
      false,
      'declined'::text,
      'Rider refused the contract terms.'::text,
      null::uuid;
    return;
  end if;

  update public.rider_transfer_negotiations n
  set
    locked_until = now() + interval '6 hours',
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'soft_reject_at', now(),
      'source', 'admin_helper'
    )
  where n.id = v_neg.id
  returning *
  into v_neg;

  perform public.log_rider_transfer_event(
    p_event_type      => 'negotiation_still_open',
    p_rider_id        => v_neg.rider_id,
    p_listing_id      => v_neg.listing_id,
    p_offer_id        => v_neg.offer_id,
    p_negotiation_id  => v_neg.id,
    p_seller_club_id  => v_neg.seller_club_id,
    p_buyer_club_id   => v_neg.buyer_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offer_salary_weekly', p_offer_salary_weekly,
      'offer_duration_seasons', p_offer_duration_seasons,
      'locked_until', v_neg.locked_until,
      'source', 'admin_helper'
    )
  );

  return query
  select
    v_neg.id,
    v_neg.offer_id,
    v_neg.rider_id,
    v_neg.buyer_club_id,
    p_offer_salary_weekly,
    p_offer_duration_seasons,
    false,
    'open'::text,
    'Rider has not accepted yet. Improve salary and/or contract length.'::text,
    null::uuid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_main_sponsor()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_club_id uuid;
  v_season integer;
  v_restart_at timestamptz;
  v_result jsonb;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return jsonb_build_object(
      'name', 'Main Sponsor',
      'logoUrl', '',
      'subtitle', 'No main sponsor deal signed yet.',
      'isActive', false
    );
  end if;

  select c.id
  into v_club_id
  from public.clubs c
  where c.owner_user_id = v_user_id
    and coalesce(c.club_type::text, 'main') = 'main'
    and c.deleted_at is null
  order by c.created_at asc nulls last
  limit 1;

  if v_club_id is null then
    return jsonb_build_object(
      'name', 'Main Sponsor',
      'logoUrl', '',
      'subtitle', 'No main sponsor deal signed yet.',
      'isActive', false
    );
  end if;

  v_season := public.get_current_season_number();

  select max(h.created_at)
  into v_restart_at
  from public.club_restart_history h
  where h.club_id = v_club_id;

  select jsonb_build_object(
    'name', coalesce(cs.name, sc.name, 'Main Sponsor'),
    'logoUrl', coalesce(cs.logo_url, sc.logo_url, cs.metadata ->> 'logo_url', sc.metadata ->> 'logo_url', ''),
    'subtitle',
      case
        when coalesce(cs.status, 'active') = 'active' then 'Main sponsor deal active'
        else 'No main sponsor deal signed yet.'
      end,
    'isActive', coalesce(cs.status, 'active') = 'active',
    'clubSponsorId', cs.id,
    'companyId', cs.company_id,
    'seasonNumber', cs.season_number
  )
  into v_result
  from public.club_sponsors cs
  left join public.sponsor_companies sc
    on sc.id = cs.company_id
  where cs.club_id = v_club_id
    and cs.season_number = v_season
    and cs.sponsor_kind = 'main'
    and coalesce(cs.status, 'active') not in ('expired', 'ended', 'terminated', 'inactive')
    and coalesce(cs.updated_at, cs.created_at, '-infinity'::timestamptz)
        > coalesce(v_restart_at, '-infinity'::timestamptz)
  order by coalesce(cs.updated_at, cs.created_at) desc nulls last
  limit 1;

  if v_result is null then
    return jsonb_build_object(
      'name', 'Main Sponsor',
      'logoUrl', '',
      'subtitle', 'No main sponsor deal signed yet.',
      'isActive', false
    );
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_day_races()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_game_date date;
begin
  v_game_date := public.get_current_game_date();

  /*
    ADJUST THIS SOURCE QUERY TO MATCH YOUR RACE CALENDAR TABLE.

    Assumed structure:
    - public.race_calendar rc

    Useful fields:
    - rc.id
    - rc.race_date
    - rc.name
    - rc.category
    - rc.location_name
    - rc.start_time
  */
  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'title', q.title,
        'subtitle', q.subtitle,
        'timeLabel', q.time_label,
        'href', '#/dashboard/calendar'
      )
      order by q.sort_time, q.title
    )
    from (
      select
        rc.id::text as id,
        rc.name as title,
        concat_ws(' · ',
          nullif(rc.category, ''),
          nullif(rc.location_name, '')
        ) as subtitle,
        case
          when rc.start_time is not null then to_char(rc.start_time, 'HH24:MI')
          else 'Today'
        end as time_label,
        coalesce(rc.start_time, time '23:59') as sort_time
      from public.race_calendar rc
      where rc.race_date = v_game_date
    ) q
  ), '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_news()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  /*
    ADJUST THIS SOURCE QUERY TO MATCH YOUR NEWS TABLE.

    Assumed structure:
    - public.game_news gn

    Useful fields:
    - gn.id
    - gn.title
    - gn.summary
    - gn.body
    - gn.published_at
    - gn.status
  */
  return coalesce((
    select jsonb_agg(
      jsonb_build_object(
        'id', q.id,
        'title', q.title,
        'subtitle', q.subtitle,
        'timeLabel', q.time_label,
        'href', '#/dashboard/overview'
      )
      order by q.sort_published_at desc
    )
    from (
      select
        gn.id::text as id,
        gn.title,
        coalesce(
          nullif(gn.summary, ''),
          left(regexp_replace(coalesce(gn.body, ''), '\s+', ' ', 'g'), 140)
        ) as subtitle,
        case
          when gn.published_at::date = current_date then 'Today'
          when gn.published_at::date = current_date - 1 then 'Yesterday'
          else to_char(gn.published_at::date, 'Mon DD')
        end as time_label,
        gn.published_at as sort_published_at
      from public.game_news gn
      where gn.status = 'published'
        and gn.published_at <= now()
      order by gn.published_at desc
      limit 5
    ) q
  ), '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_submit_rider_transfer_offer(p_listing_id uuid, p_buyer_club_id uuid, p_offered_price bigint, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(offer_id uuid, listing_id uuid, rider_id uuid, seller_club_id uuid, buyer_club_id uuid, offered_price bigint, status text, negotiation_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_listing public.rider_transfer_listings%rowtype;
  v_now_game_date date;
  v_offer public.rider_transfer_offers%rowtype;
  v_start record;
  v_negotiation_id uuid := null;

  v_seller_owner_user_id public.clubs.owner_user_id%type;
  v_seller_club_name text;
  v_buyer_club_name text;
  v_rider_name text;
begin
  if p_listing_id is null or p_buyer_club_id is null then
    raise exception 'Listing and buyer club are required';
  end if;

  if p_offered_price is null or p_offered_price <= 0 then
    raise exception 'Offer price must be > 0';
  end if;

  select *
  into v_listing
  from public.rider_transfer_listings l
  where l.id = p_listing_id
  for update;

  if not found then
    raise exception 'Transfer listing not found';
  end if;

  if v_listing.status <> 'listed' then
    raise exception 'Listing is not active';
  end if;

  v_now_game_date := public.get_current_game_date_date();

  if v_listing.expires_on_game_date is not null
     and v_now_game_date > v_listing.expires_on_game_date then
    update public.rider_transfer_listings l
    set status = 'expired'
    where l.id = v_listing.id
      and l.status = 'listed';

    update public.riders r
    set release_requested = false
    where r.id = v_listing.rider_id;

    perform public.log_rider_transfer_event(
      p_event_type      => 'listing_expired',
      p_rider_id        => v_listing.rider_id,
      p_listing_id      => v_listing.id,
      p_seller_club_id  => v_listing.seller_club_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'reason', 'listing_expired_before_offer',
        'source', 'admin_helper'
      )
    );

    raise exception 'Listing has expired';
  end if;

  if v_listing.seller_club_id = p_buyer_club_id then
    raise exception 'Seller club cannot bid on its own rider';
  end if;

  if exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_buyer_club_id
      and cr.rider_id = v_listing.rider_id
  ) then
    raise exception 'Buyer club already has this rider';
  end if;

  if p_offered_price < v_listing.min_allowed_price
     or p_offered_price > v_listing.max_allowed_price then
    raise exception 'Offer price must be between % and %',
      v_listing.min_allowed_price,
      v_listing.max_allowed_price;
  end if;

  if exists (
    select 1
    from public.rider_transfer_offers rto
    where rto.listing_id = v_listing.id
      and rto.buyer_club_id = p_buyer_club_id
      and rto.status = 'open'
  ) then
    raise exception
      'An open offer from this club already exists for this listing';
  end if;

  insert into public.rider_transfer_offers (
    listing_id,
    rider_id,
    seller_club_id,
    buyer_club_id,
    offered_price,
    offered_on_game_date,
    expires_on_game_date,
    status,
    metadata
  )
  values (
    v_listing.id,
    v_listing.rider_id,
    v_listing.seller_club_id,
    p_buyer_club_id,
    p_offered_price,
    v_now_game_date,
    case
      when v_listing.expires_on_game_date is null
        then v_now_game_date + 1
      else least(
        v_now_game_date + 1,
        v_listing.expires_on_game_date
      )
    end,
    'open',
    jsonb_build_object(
      'submitted_by', p_actor_user_id,
      'submitted_at', now(),
      'source', 'admin_helper'
    )
  )
  returning *
  into v_offer;

  /*
    A BEFORE INSERT trigger may intentionally return NULL after the AI daily
    offer limit is reached. In that case no row was inserted and v_offer is
    empty. Return a clean non-error result before any event or notification.
  */
  if v_offer.id is null then
    return query
    select
      null::uuid,
      v_listing.id,
      v_listing.rider_id,
      v_listing.seller_club_id,
      p_buyer_club_id,
      p_offered_price,
      'skipped_daily_ai_offer_limit'::text,
      null::uuid;
    return;
  end if;

  select
    c.owner_user_id,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_seller_owner_user_id,
    v_seller_club_name
  from public.clubs c
  where c.id = v_listing.seller_club_id;

  select
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into v_buyer_club_name
  from public.clubs c
  where c.id = v_offer.buyer_club_id;

  select
    coalesce(
      nullif(trim(concat_ws(
        ' ',
        nullif(to_jsonb(r)->>'first_name', ''),
        nullif(to_jsonb(r)->>'last_name', '')
      )), ''),
      nullif(trim(concat_ws(
        ' ',
        nullif(to_jsonb(r)->>'rider_first_name', ''),
        nullif(to_jsonb(r)->>'rider_last_name', '')
      )), ''),
      nullif(to_jsonb(r)->>'full_name', ''),
      nullif(to_jsonb(r)->>'display_name', ''),
      nullif(to_jsonb(r)->>'name', ''),
      nullif(to_jsonb(r)->>'rider_name', ''),
      r.id::text
    )
  into v_rider_name
  from public.riders r
  where r.id = v_listing.rider_id;

  v_seller_club_name :=
    coalesce(
      v_seller_club_name,
      v_listing.seller_club_id::text
    );

  v_buyer_club_name :=
    coalesce(
      v_buyer_club_name,
      v_offer.buyer_club_id::text
    );

  v_rider_name :=
    coalesce(
      v_rider_name,
      v_listing.rider_id::text
    );

  if v_seller_owner_user_id is not null then
    perform public.create_transfer_notification(
      p_user_id => v_seller_owner_user_id,
      p_type_code => 'TRANSFER_OFFER_RECEIVED',
      p_title => 'Transfer offer received',
      p_message => format(
        '%s offered %s for %s.',
        v_buyer_club_name,
        public.format_money_us(v_offer.offered_price),
        v_rider_name
      ),
      p_offer_id => v_offer.id,
      p_listing_id => v_listing.id,
      p_rider_id => v_listing.rider_id,
      p_action_url => format(
        '/dashboard/transfers?activity=outgoing&offerId=%s',
        v_offer.id
      ),
      p_payload_json => jsonb_build_object(
        'offer_id', v_offer.id,
        'listing_id', v_listing.id,
        'rider_id', v_listing.rider_id,
        'rider_name', v_rider_name,
        'buyer_club_id', v_offer.buyer_club_id,
        'buyer_club_name', v_buyer_club_name,
        'seller_club_id', v_listing.seller_club_id,
        'seller_club_name', v_seller_club_name,
        'offered_price', v_offer.offered_price,
        'asking_price', v_listing.asking_price,
        'status', v_offer.status,
        'expires_on_game_date',
          v_offer.expires_on_game_date,
        'offer_path', format(
          '/dashboard/transfers?activity=outgoing&offerId=%s',
          v_offer.id
        ),
        'rider_profile_path', format(
          '/dashboard/my-riders/%s',
          v_listing.rider_id
        )
      )
    );
  end if;

  perform public.log_rider_transfer_event(
    p_event_type      => 'offer_created',
    p_rider_id        => v_offer.rider_id,
    p_listing_id      => v_offer.listing_id,
    p_offer_id        => v_offer.id,
    p_seller_club_id  => v_offer.seller_club_id,
    p_buyer_club_id   => v_offer.buyer_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offered_price', v_offer.offered_price,
      'expires_on_game_date',
        v_offer.expires_on_game_date,
      'source', 'admin_helper'
    )
  );

  if p_offered_price >= v_listing.asking_price then
    select *
    into v_start
    from public._start_rider_transfer_negotiation_internal(
      p_offer_id => v_offer.id,
      p_accepted_by => p_actor_user_id,
      p_auto_accepted => true
    );

    v_negotiation_id := v_start.negotiation_id;

    select *
    into v_offer
    from public.rider_transfer_offers o
    where o.id = v_offer.id;

    perform public.log_rider_transfer_event(
      p_event_type      => 'offer_auto_accepted_by_price',
      p_rider_id        => v_offer.rider_id,
      p_listing_id      => v_offer.listing_id,
      p_offer_id        => v_offer.id,
      p_negotiation_id  => v_negotiation_id,
      p_seller_club_id  => v_offer.seller_club_id,
      p_buyer_club_id   => v_offer.buyer_club_id,
      p_actor_user_id   => p_actor_user_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'offered_price', v_offer.offered_price,
        'asking_price', v_listing.asking_price,
        'status', v_offer.status,
        'source', 'admin_helper'
      )
    );
  end if;

  return query
  select
    v_offer.id,
    v_offer.listing_id,
    v_offer.rider_id,
    v_offer.seller_club_id,
    v_offer.buyer_club_id,
    v_offer.offered_price,
    v_offer.status,
    v_negotiation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_reject_rider_transfer_offer(p_offer_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(offer_id uuid, listing_id uuid, rider_id uuid, seller_club_id uuid, buyer_club_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer public.rider_transfer_offers%rowtype;
begin
  select *
  into v_offer
  from public.rider_transfer_offers o
  where o.id = p_offer_id
  for update;

  if not found then
    raise exception 'Transfer offer not found';
  end if;

  if v_offer.status <> 'open' then
    raise exception 'Only open offers can be rejected';
  end if;

  update public.rider_transfer_offers o
  set
    status = 'rejected',
    metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
      'rejected_at', now(),
      'rejected_by', p_actor_user_id
    )
  where o.id = v_offer.id;

  perform public.log_rider_transfer_event(
    p_event_type      => 'offer_rejected',
    p_rider_id        => v_offer.rider_id,
    p_listing_id      => v_offer.listing_id,
    p_offer_id        => v_offer.id,
    p_seller_club_id  => v_offer.seller_club_id,
    p_buyer_club_id   => v_offer.buyer_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => public.get_current_game_date_date(),
    p_payload         => jsonb_build_object(
      'source', 'admin_helper'
    )
  );

  return query
  select
    o.id,
    o.listing_id,
    o.rider_id,
    o.seller_club_id,
    o.buyer_club_id,
    o.status
  from public.rider_transfer_offers o
  where o.id = v_offer.id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_user_notification(p_user_id uuid, p_club_id uuid, p_notification_type text, p_title text, p_body text, p_data_json jsonb DEFAULT '{}'::jsonb, p_related_listing_id uuid DEFAULT NULL::uuid, p_related_offer_id uuid DEFAULT NULL::uuid, p_related_negotiation_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
begin
  insert into public.user_notifications (
    user_id,
    club_id,
    notification_type,
    title,
    body,
    data_json,
    related_listing_id,
    related_offer_id,
    related_negotiation_id
  )
  values (
    p_user_id,
    p_club_id,
    p_notification_type,
    p_title,
    p_body,
    coalesce(p_data_json, '{}'::jsonb),
    p_related_listing_id,
    p_related_offer_id,
    p_related_negotiation_id
  )
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_rider_transfer_event_to_notifications(p_event_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.rider_transfer_events%rowtype;
  v_seller_owner_user_id uuid;
  v_buyer_owner_user_id uuid;
  v_count integer := 0;
begin
  select *
  into v_event
  from public.rider_transfer_events e
  where e.id = p_event_id;

  if not found then
    raise exception 'Transfer event not found';
  end if;

  if v_event.seller_club_id is not null then
    select c.owner_user_id
    into v_seller_owner_user_id
    from public.clubs c
    where c.id = v_event.seller_club_id;
  end if;

  if v_event.buyer_club_id is not null then
    select c.owner_user_id
    into v_buyer_owner_user_id
    from public.clubs c
    where c.id = v_event.buyer_club_id;
  end if;

  if v_event.event_type = 'offer_created' and v_seller_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_seller_owner_user_id,
      p_type_id          => 7,
      p_title            => 'New transfer offer',
      p_message          => 'A club submitted an offer for your rider.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'buyer_club_id', v_event.buyer_club_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'offer_rejected' and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Offer rejected',
      p_message          => 'Your transfer offer was rejected by the selling club.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type in ('offer_accepted_by_seller', 'offer_auto_accepted_by_price')
     and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Rider negotiation started',
      p_message          => 'The club fee was accepted. Contract talks are now open.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'negotiation_id', v_event.negotiation_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'negotiation_still_open' and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Rider wants better terms',
      p_message          => 'The rider has not accepted yet. Improve salary or contract length.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'negotiation_id', v_event.negotiation_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'rider_declined_terms' and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Rider declined terms',
      p_message          => 'The rider rejected your contract offer.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'negotiation_id', v_event.negotiation_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'rider_auto_declined_destination' and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Rider rejected destination',
      p_message          => 'The rider refused to join your club.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'negotiation_id', v_event.negotiation_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'negotiation_expired' and v_buyer_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_buyer_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Negotiation expired',
      p_message          => 'Your contract talks with the rider expired.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'offer_id', v_event.offer_id,
        'negotiation_id', v_event.negotiation_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'listing_expired' and v_seller_owner_user_id is not null then
    perform public.create_notification_for_user(
      p_user_id          => v_seller_owner_user_id,
      p_type_id          => 7,
      p_title            => 'Transfer listing expired',
      p_message          => 'Your rider was not transferred before the listing expired.',
      p_source           => 'game',
      p_action_url       => '/dashboard/transfers',
      p_payload_json     => jsonb_build_object(
        'event_type', v_event.event_type,
        'rider_id', v_event.rider_id,
        'listing_id', v_event.listing_id,
        'payload', v_event.payload
      ),
      p_source_event_id  => v_event.id
    );
    v_count := v_count + 1;
  end if;

  if v_event.event_type = 'transfer_completed' then
    if v_seller_owner_user_id is not null then
      perform public.create_notification_for_user(
        p_user_id          => v_seller_owner_user_id,
        p_type_id          => 7,
        p_title            => 'Transfer completed',
        p_message          => 'Your rider has been sold.',
        p_source           => 'game',
        p_action_url       => '/dashboard/transfers',
        p_payload_json     => jsonb_build_object(
          'side', 'seller',
          'event_type', v_event.event_type,
          'rider_id', v_event.rider_id,
          'listing_id', v_event.listing_id,
          'offer_id', v_event.offer_id,
          'negotiation_id', v_event.negotiation_id,
          'payload', v_event.payload
        ),
        p_source_event_id  => v_event.id
      );
      v_count := v_count + 1;
    end if;

    if v_buyer_owner_user_id is not null then
      perform public.create_notification_for_user(
        p_user_id          => v_buyer_owner_user_id,
        p_type_id          => 7,
        p_title            => 'Transfer completed',
        p_message          => 'The rider joined your club.',
        p_source           => 'game',
        p_action_url       => '/dashboard/transfers',
        p_payload_json     => jsonb_build_object(
          'side', 'buyer',
          'event_type', v_event.event_type,
          'rider_id', v_event.rider_id,
          'listing_id', v_event.listing_id,
          'offer_id', v_event.offer_id,
          'negotiation_id', v_event.negotiation_id,
          'payload', v_event.payload
        ),
        p_source_event_id  => v_event.id
      );
      v_count := v_count + 1;
    end if;
  end if;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  update public.user_notifications
  set is_read = true
  where id = p_notification_id
    and user_id = auth.uid();

  return found;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer := 0;
  v_user_id uuid;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    return 0;
  end if;

  update public.user_notifications
  set
    status = 'read',
    read_at = now()
  where user_id = v_user_id
    and status = 'unread'
    and deleted_at is null;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_notification_for_user(p_user_id uuid, p_type_id bigint, p_title character varying, p_message text, p_source character varying DEFAULT 'game'::character varying, p_created_by_user_id uuid DEFAULT NULL::uuid, p_action_url character varying DEFAULT NULL::character varying, p_payload_json jsonb DEFAULT NULL::jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_event_id uuid DEFAULT NULL::uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing_notification_id bigint;
  v_notification_id bigint;
begin
  if p_source_event_id is not null then
    select un.notification_id
    into v_existing_notification_id
    from public.user_notifications un
    where un.user_id = p_user_id
      and un.source_event_id = p_source_event_id
    limit 1;

    if v_existing_notification_id is not null then
      return v_existing_notification_id;
    end if;
  end if;

  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json,
    expires_at
  )
  values (
    p_type_id,
    p_title,
    p_message,
    p_source,
    p_created_by_user_id,
    p_action_url,
    p_payload_json,
    p_expires_at
  )
  returning id into v_notification_id;

  insert into public.user_notifications (
    user_id,
    notification_id,
    status,
    read_at,
    deleted_at,
    source_event_id
  )
  values (
    p_user_id,
    v_notification_id,
    'unread',
    null,
    null,
    p_source_event_id
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.log_rider_free_agent_event(p_event_type text, p_rider_id uuid, p_free_agent_id uuid DEFAULT NULL::uuid, p_negotiation_id uuid DEFAULT NULL::uuid, p_source_club_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_event_game_date date DEFAULT NULL::date, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_id uuid;
begin
  insert into public.rider_free_agent_events (
    event_type,
    free_agent_id,
    negotiation_id,
    rider_id,
    source_club_id,
    club_id,
    actor_user_id,
    event_game_date,
    payload
  )
  values (
    p_event_type,
    p_free_agent_id,
    p_negotiation_id,
    p_rider_id,
    p_source_club_id,
    p_club_id,
    p_actor_user_id,
    p_event_game_date,
    coalesce(p_payload, '{}'::jsonb)
  )
  returning id into v_event_id;

  return v_event_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.expire_rider_free_agent_market_state()
 RETURNS TABLE(expired_free_agent_count integer, expired_negotiation_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_expired_free_agent_count integer := 0;
  v_expired_negotiation_count integer := 0;
  v_row_count integer := 0;
  v_rec record;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  for v_rec in
    update public.rider_free_agent_negotiations n
    set
      status = 'withdrawn',
      closed_reason = 'free_agent_market_expired',
      locked_until = null
    where n.status = 'open'
      and exists (
        select 1
        from public.rider_free_agents fa
        where fa.id = n.free_agent_id
          and fa.expires_on_game_date < v_game_date
      )
    returning
      n.id,
      n.free_agent_id,
      n.rider_id,
      n.club_id
  loop
    perform public.log_rider_free_agent_event(
      p_event_type      => 'free_agent_negotiation_withdrawn',
      p_rider_id        => v_rec.rider_id,
      p_free_agent_id   => v_rec.free_agent_id,
      p_negotiation_id  => v_rec.id,
      p_club_id         => v_rec.club_id,
      p_event_game_date => v_game_date,
      p_payload         => jsonb_build_object(
        'reason', 'free_agent_market_expired',
        'expired_on_game_date', v_game_date
      )
    );
    v_expired_negotiation_count := v_expired_negotiation_count + 1;
  end loop;

  for v_rec in
    update public.rider_free_agent_negotiations n
    set
      status = 'withdrawn',
      closed_reason = 'negotiation_expired',
      locked_until = null
    where n.status = 'open'
      and n.expires_on_game_date < v_game_date
    returning
      n.id,
      n.free_agent_id,
      n.rider_id,
      n.club_id
  loop
    perform public.log_rider_free_agent_event(
      p_event_type      => 'free_agent_negotiation_withdrawn',
      p_rider_id        => v_rec.rider_id,
      p_free_agent_id   => v_rec.free_agent_id,
      p_negotiation_id  => v_rec.id,
      p_club_id         => v_rec.club_id,
      p_event_game_date => v_game_date,
      p_payload         => jsonb_build_object(
        'reason', 'negotiation_expired',
        'expired_on_game_date', v_game_date
      )
    );
    v_expired_negotiation_count := v_expired_negotiation_count + 1;
  end loop;

  for v_rec in
    update public.rider_free_agents fa
    set status = 'expired'
    where fa.status = 'available'
      and fa.expires_on_game_date < v_game_date
    returning
      fa.id,
      fa.rider_id,
      fa.source_club_id,
      fa.source_type
  loop
    perform public.log_rider_free_agent_event(
      p_event_type      => 'free_agent_expired',
      p_rider_id        => v_rec.rider_id,
      p_free_agent_id   => v_rec.id,
      p_source_club_id  => v_rec.source_club_id,
      p_event_game_date => v_game_date,
      p_payload         => jsonb_build_object(
        'source_type', v_rec.source_type,
        'expired_on_game_date', v_game_date
      )
    );
    v_expired_free_agent_count := v_expired_free_agent_count + 1;
  end loop;

  return query
  select v_expired_free_agent_count, v_expired_negotiation_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_open_free_agent_negotiation(p_free_agent_id uuid, p_club_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(negotiation_id uuid, free_agent_id uuid, rider_id uuid, club_id uuid, current_salary_weekly integer, expected_salary_weekly integer, min_acceptable_salary_weekly integer, preferred_duration_seasons smallint, attempt_count integer, max_attempts integer, locked_until timestamp with time zone, opened_on_game_date date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_opened_in_season integer;
  v_rider_id uuid;
  v_status text;
  v_available_from date;
  v_expires_on date;
  v_desired_tier text;
  v_expected integer;
  v_min integer;
  v_preferred smallint;
  v_current_salary integer;
  v_age integer;
  v_club_tier text;
  v_negotiation_id uuid;
  v_locked_until timestamptz;
  v_tier_gap integer;
begin
  v_game_date := public.get_current_game_date_date();
  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  v_opened_in_season := extract(year from v_game_date)::int - 2000 + 1;

  select
    fa.rider_id,
    fa.status,
    fa.available_from_game_date,
    fa.expires_on_game_date,
    fa.desired_tier,
    fa.expected_salary_weekly,
    fa.min_acceptable_salary_weekly,
    fa.preferred_duration_seasons,
    coalesce(
      (
        select rc.salary_weekly
        from public.rider_contracts rc
        where rc.rider_id = fa.rider_id
        order by
          case when rc.status = 'active' then 0 else 1 end,
          rc.created_at desc
        limit 1
      ),
      r.salary
    ),
    public.get_age_years_on_game_date(r.birth_date)
  into
    v_rider_id,
    v_status,
    v_available_from,
    v_expires_on,
    v_desired_tier,
    v_expected,
    v_min,
    v_preferred,
    v_current_salary,
    v_age
  from public.rider_free_agents fa
  join public.riders r on r.id = fa.rider_id
  where fa.id = p_free_agent_id;

  if not found then
    raise exception 'Free agent not found';
  end if;

  if v_status <> 'available' then
    raise exception 'Free agent is not available';
  end if;

  if v_available_from > v_game_date then
    raise exception 'Free agent is not available yet';
  end if;

  if v_expires_on < v_game_date then
    raise exception 'Free agent is expired';
  end if;

  select c.club_tier::text
  into v_club_tier
  from public.clubs c
  where c.id = p_club_id;

  select n.id, n.locked_until
  into v_negotiation_id, v_locked_until
  from public.rider_free_agent_negotiations n
  where n.free_agent_id = p_free_agent_id
    and n.club_id = p_club_id
    and n.status = 'open'
  order by n.created_at desc
  limit 1;

  if v_negotiation_id is not null then
    return query
    select
      n.id,
      n.free_agent_id,
      n.rider_id,
      n.club_id,
      n.current_salary_weekly,
      n.expected_salary_weekly,
      n.min_acceptable_salary_weekly,
      n.preferred_duration_seasons,
      n.attempt_count,
      n.max_attempts,
      n.locked_until,
      n.opened_on_game_date
    from public.rider_free_agent_negotiations n
    where n.id = v_negotiation_id;
    return;
  end if;

  v_tier_gap :=
    case lower(coalesce(v_desired_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end
    -
    case lower(coalesce(v_club_tier, 'amateur'))
      when 'worldteam' then 4
      when 'proteam' then 3
      when 'continental' then 2
      else 1
    end;

  if v_tier_gap > 0 and v_age <= 29 then
    perform public.log_rider_free_agent_event(
      p_event_type      => 'free_agent_auto_refused_club',
      p_rider_id        => v_rider_id,
      p_free_agent_id   => p_free_agent_id,
      p_club_id         => p_club_id,
      p_actor_user_id   => p_actor_user_id,
      p_event_game_date => v_game_date,
      p_payload         => jsonb_build_object(
        'source', 'admin_helper',
        'desired_tier', v_desired_tier,
        'club_tier', v_club_tier,
        'tier_gap', v_tier_gap,
        'age', v_age
      )
    );
    raise exception 'This rider is not interested in clubs below % tier yet', v_desired_tier;
  end if;

  if v_tier_gap > 0 then
    v_expected := round(v_expected::numeric * (1 + (0.12 * v_tier_gap)))::int;
    v_min := round(v_min::numeric * (1 + (0.15 * v_tier_gap)))::int;

    if v_age >= 34 then
      v_expected := round(v_expected::numeric * 0.96)::int;
      v_min := round(v_min::numeric * 0.95)::int;
    end if;
  end if;

  insert into public.rider_free_agent_negotiations (
    free_agent_id,
    rider_id,
    club_id,
    status,
    current_salary_weekly,
    expected_salary_weekly,
    min_acceptable_salary_weekly,
    preferred_duration_seasons,
    attempt_count,
    max_attempts,
    locked_until,
    opened_in_season,
    opened_on_game_date,
    expires_on_game_date,
    notes_json
  )
  values (
    p_free_agent_id,
    v_rider_id,
    p_club_id,
    'open',
    v_current_salary,
    v_expected,
    v_min,
    v_preferred,
    0,
    5,
    null,
    v_opened_in_season,
    v_game_date,
    v_game_date + 3,
    jsonb_build_object(
      'source', 'admin_helper',
      'desired_tier', v_desired_tier,
      'club_tier', v_club_tier,
      'tier_gap', v_tier_gap,
      'age', v_age
    )
  )
  returning id into v_negotiation_id;

  perform public.log_rider_free_agent_event(
    p_event_type      => 'free_agent_negotiation_opened',
    p_rider_id        => v_rider_id,
    p_free_agent_id   => p_free_agent_id,
    p_negotiation_id  => v_negotiation_id,
    p_club_id         => p_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'source', 'admin_helper',
      'current_salary_weekly', v_current_salary,
      'expected_salary_weekly', v_expected,
      'min_acceptable_salary_weekly', v_min,
      'preferred_duration_seasons', v_preferred
    )
  );

  return query
  select
    n.id,
    n.free_agent_id,
    n.rider_id,
    n.club_id,
    n.current_salary_weekly,
    n.expected_salary_weekly,
    n.min_acceptable_salary_weekly,
    n.preferred_duration_seasons,
    n.attempt_count,
    n.max_attempts,
    n.locked_until,
    n.opened_on_game_date
  from public.rider_free_agent_negotiations n
  where n.id = v_negotiation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_submit_free_agent_offer(p_free_agent_id uuid, p_club_id uuid, p_offer_salary_weekly integer, p_offer_duration_seasons smallint, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(negotiation_id uuid, free_agent_id uuid, rider_id uuid, club_id uuid, expected_salary_weekly integer, min_acceptable_salary_weekly integer, preferred_duration_seasons smallint, offer_salary_weekly integer, offer_duration_seasons smallint, attempt_count integer, max_attempts integer, locked_until timestamp with time zone, can_sign boolean, meets_expected_salary boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_current_season integer;
  v_rider_id uuid;
  v_fa_status text;
  v_expected_salary integer;
  v_min_acceptable_salary integer;
  v_preferred_duration smallint;
  v_available_from date;
  v_expires_on date;
  v_current_salary integer;
  v_negotiation_id uuid;
  v_locked_until timestamptz;
  v_attempt_count integer;
  v_max_attempts integer;
  v_is_new boolean := false;
  v_hard_decline boolean := false;
  v_can_sign boolean := false;
  v_meets_expected boolean := false;
begin
  if p_offer_salary_weekly is null or p_offer_salary_weekly <= 0 then
    raise exception 'Offer salary must be greater than 0';
  end if;

  if p_offer_duration_seasons is null or p_offer_duration_seasons < 1 then
    raise exception 'Offer duration must be at least 1 season';
  end if;

  v_game_date := public.get_current_game_date_date();
  v_current_season := public.get_current_season_number();

  if v_game_date is null or v_current_season is null then
    raise exception 'Game date or season is not available';
  end if;

  select
    fa.rider_id,
    fa.status,
    fa.expected_salary_weekly,
    fa.min_acceptable_salary_weekly,
    fa.preferred_duration_seasons,
    fa.available_from_game_date,
    fa.expires_on_game_date,
    coalesce(
      (
        select rc.salary_weekly
        from public.rider_contracts rc
        where rc.rider_id = fa.rider_id
        order by
          case when rc.status = 'active' then 0 else 1 end,
          rc.created_at desc
        limit 1
      ),
      r.salary
    )
  into
    v_rider_id,
    v_fa_status,
    v_expected_salary,
    v_min_acceptable_salary,
    v_preferred_duration,
    v_available_from,
    v_expires_on,
    v_current_salary
  from public.rider_free_agents fa
  join public.riders r on r.id = fa.rider_id
  where fa.id = p_free_agent_id
  for update of fa, r;

  if not found then
    raise exception 'Free agent not found';
  end if;

  if v_fa_status <> 'available' then
    raise exception 'Free agent is not available';
  end if;

  if v_game_date < v_available_from then
    raise exception 'Free agent is not available yet';
  end if;

  if v_game_date > v_expires_on then
    raise exception 'Free agent listing has expired';
  end if;

  select
    n.id,
    n.locked_until,
    n.attempt_count,
    n.max_attempts
  into
    v_negotiation_id,
    v_locked_until,
    v_attempt_count,
    v_max_attempts
  from public.rider_free_agent_negotiations n
  where n.free_agent_id = p_free_agent_id
    and n.club_id = p_club_id
    and n.status = 'open'
  for update;

  if found then
    if v_locked_until is not null and v_locked_until > now() then
      raise exception 'Negotiation is locked until %', v_locked_until;
    end if;

    update public.rider_free_agent_negotiations n
    set
      current_salary_weekly = v_current_salary,
      expected_salary_weekly = v_expected_salary,
      min_acceptable_salary_weekly = v_min_acceptable_salary,
      preferred_duration_seasons = v_preferred_duration,
      offer_salary_weekly = p_offer_salary_weekly,
      offer_duration_seasons = p_offer_duration_seasons,
      attempt_count = coalesce(n.attempt_count, 0) + 1,
      locked_until = null
    where n.id = v_negotiation_id
    returning n.attempt_count, n.max_attempts
    into v_attempt_count, v_max_attempts;
  else
    insert into public.rider_free_agent_negotiations (
      free_agent_id,
      rider_id,
      club_id,
      status,
      current_salary_weekly,
      expected_salary_weekly,
      min_acceptable_salary_weekly,
      preferred_duration_seasons,
      offer_salary_weekly,
      offer_duration_seasons,
      attempt_count,
      max_attempts,
      opened_in_season,
      opened_on_game_date,
      expires_on_game_date,
      locked_until,
      notes_json
    )
    values (
      p_free_agent_id,
      v_rider_id,
      p_club_id,
      'open',
      v_current_salary,
      v_expected_salary,
      v_min_acceptable_salary,
      v_preferred_duration,
      p_offer_salary_weekly,
      p_offer_duration_seasons,
      1,
      5,
      v_current_season,
      v_game_date,
      v_game_date + 3,
      null,
      jsonb_build_object('source', 'admin_helper')
    )
    returning id
    into v_negotiation_id;

    v_attempt_count := 1;
    v_max_attempts := 5;
    v_is_new := true;
  end if;

  v_hard_decline := (
    p_offer_salary_weekly < greatest(1, floor(coalesce(v_min_acceptable_salary, 0) * 0.75)::integer)
  );

  v_meets_expected := (
    p_offer_salary_weekly >= coalesce(v_expected_salary, 0)
  );

  v_can_sign := (
    p_offer_salary_weekly >= coalesce(v_min_acceptable_salary, 0)
    and coalesce(p_offer_duration_seasons, 0) >= 1
  );

  if v_hard_decline then
    update public.rider_free_agent_negotiations n
    set
      status = 'rejected',
      locked_until = null,
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'source', 'admin_helper',
        'hard_declined_at', now(),
        'decline_reason', 'salary_too_low'
      )
    where n.id = v_negotiation_id;

  elsif not v_can_sign then
    update public.rider_free_agent_negotiations n
    set
      locked_until = now() + interval '6 hours',
      notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
        'source', 'admin_helper',
        'soft_reject_at', now()
      )
    where n.id = v_negotiation_id;
  end if;

  perform public.log_rider_free_agent_event(
    p_event_type      => 'free_agent_offer_submitted',
    p_rider_id        => v_rider_id,
    p_free_agent_id   => p_free_agent_id,
    p_negotiation_id  => v_negotiation_id,
    p_club_id         => p_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'source', 'admin_helper',
      'current_salary_weekly', v_current_salary,
      'offer_salary_weekly', p_offer_salary_weekly,
      'offer_duration_seasons', p_offer_duration_seasons,
      'can_sign', v_can_sign,
      'meets_expected_salary', v_meets_expected,
      'hard_decline', v_hard_decline,
      'is_new', v_is_new
    )
  );

  return query
  select
    n.id,
    n.free_agent_id,
    n.rider_id,
    n.club_id,
    n.expected_salary_weekly,
    n.min_acceptable_salary_weekly,
    n.preferred_duration_seasons,
    n.offer_salary_weekly,
    n.offer_duration_seasons,
    n.attempt_count,
    n.max_attempts,
    n.locked_until,
    (
      coalesce(n.offer_salary_weekly, 0) >= coalesce(n.min_acceptable_salary_weekly, 0)
      and coalesce(n.offer_duration_seasons, 0) >= 1
      and n.status = 'open'
    ) as can_sign,
    (
      coalesce(n.offer_salary_weekly, 0) >= coalesce(n.expected_salary_weekly, 0)
    ) as meets_expected_salary
  from public.rider_free_agent_negotiations n
  where n.id = v_negotiation_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_sign_free_agent_from_negotiation(p_negotiation_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(free_agent_id uuid, rider_id uuid, club_id uuid, contract_id uuid, salary_weekly integer, duration_seasons smallint, starts_on date, expires_on date, start_season_number integer, end_season_number integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_game_date date;
  v_free_agent_id uuid;
  v_rider_id uuid;
  v_club_id uuid;
  v_status text;
  v_offer_salary_weekly integer;
  v_offer_duration_seasons smallint;
  v_min_acceptable_salary_weekly integer;
  v_offered_signing_bonus bigint;
  v_offered_agent_fee bigint;
  v_min_signing_bonus bigint := 0;
  v_min_agent_fee bigint := 0;
  v_fa_status text;
  v_available_from date;
  v_expires_market_on date;
  v_role public.rider_role;
  v_morale smallint;
  v_source_club_id uuid;
  v_start_season_number integer;
  v_end_season_number integer;
  v_contract_expires_on date;
  v_contract_id uuid;

  v_signing_market_value bigint;
  v_signing_bonus bigint := 0;
  v_agent_fee bigint := 0;
  v_transfer_lock_until_game_date date;

  v_signing_cost_tx_id uuid;
  v_club_cash_account_id uuid;
  v_sink_account_id uuid;
  v_total_signing_cost bigint := 0;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  select
    n.free_agent_id,
    n.rider_id,
    n.club_id,
    n.status,
    n.offer_salary_weekly,
    n.offer_duration_seasons,
    n.min_acceptable_salary_weekly,
    n.offer_signing_bonus,
    n.offer_agent_fee,
    fa.status,
    fa.available_from_game_date,
    fa.expires_on_game_date,
    fa.source_club_id,
    r.role,
    r.morale
  into
    v_free_agent_id,
    v_rider_id,
    v_club_id,
    v_status,
    v_offer_salary_weekly,
    v_offer_duration_seasons,
    v_min_acceptable_salary_weekly,
    v_offered_signing_bonus,
    v_offered_agent_fee,
    v_fa_status,
    v_available_from,
    v_expires_market_on,
    v_source_club_id,
    v_role,
    v_morale
  from public.rider_free_agent_negotiations n
  join public.rider_free_agents fa on fa.id = n.free_agent_id
  join public.riders r on r.id = n.rider_id
  where n.id = p_negotiation_id
  for update of n, fa, r;

  if not found then
    raise exception 'Negotiation not found';
  end if;

  if v_status <> 'open' then
    raise exception 'Negotiation is not open';
  end if;

  if v_fa_status <> 'available' then
    raise exception 'Free agent is not available';
  end if;

  if v_game_date < v_available_from then
    raise exception 'Free agent is not available yet';
  end if;

  if v_game_date > v_expires_market_on then
    raise exception 'Free agent listing has expired';
  end if;

  if v_offer_salary_weekly is null or v_offer_salary_weekly <= 0 then
    raise exception 'Negotiation has no valid salary offer';
  end if;

  if v_offer_duration_seasons is null or v_offer_duration_seasons < 1 then
    raise exception 'Negotiation has no valid duration';
  end if;

  if v_offer_salary_weekly < coalesce(v_min_acceptable_salary_weekly, 0) then
    raise exception 'Offered salary is below the minimum acceptable salary';
  end if;

  if exists (
    select 1
    from public.club_riders cr
    where cr.rider_id = v_rider_id
  ) then
    raise exception 'Rider is already assigned to a club';
  end if;

  if exists (
    select 1
    from public.rider_contracts rc
    where rc.rider_id = v_rider_id
      and rc.status = 'active'
  ) then
    raise exception 'Rider already has an active contract';
  end if;

  perform public.refresh_rider_value_snapshot(v_rider_id);

  select coalesce(r.market_value, 0)
  into v_signing_market_value
  from public.riders r
  where r.id = v_rider_id;

  if coalesce(v_signing_market_value, 0) <= 0 then
    raise exception 'Could not resolve signing market value for free agent';
  end if;

  v_min_signing_bonus := floor(v_signing_market_value::numeric * 0.10)::bigint;
  v_min_agent_fee := floor(v_signing_market_value::numeric * 0.15)::bigint;

  v_signing_bonus := greatest(coalesce(v_offered_signing_bonus, 0), v_min_signing_bonus);
  v_agent_fee := greatest(coalesce(v_offered_agent_fee, 0), v_min_agent_fee);

  v_transfer_lock_until_game_date := v_game_date + 90;

  v_start_season_number := public.season_from_game_date(v_game_date);
  v_end_season_number := v_start_season_number + v_offer_duration_seasons - 1;
  v_contract_expires_on := public.get_game_date_for_season_end(v_end_season_number);

  insert into public.club_riders (
    club_id,
    rider_id,
    assigned_role
  )
  values (
    v_club_id,
    v_rider_id,
    v_role
  );

  insert into public.rider_contracts (
    rider_id,
    club_id,
    salary_weekly,
    signed_at,
    starts_on,
    expires_on,
    duration_seasons,
    status,
    signed_morale,
    notes_json,
    start_season_number,
    end_season_number,
    acquisition_type,
    acquisition_game_date,
    acquisition_market_value,
    acquisition_source_free_agent_id,
    free_agent_signing_bonus,
    free_agent_agent_fee,
    free_agent_transfer_lock_until_game_date
  )
  values (
    v_rider_id,
    v_club_id,
    v_offer_salary_weekly,
    now(),
    v_game_date,
    v_contract_expires_on,
    v_offer_duration_seasons,
    'active',
    v_morale,
    jsonb_build_object(
      'free_agent_signing', jsonb_build_object(
        'free_agent_id', v_free_agent_id,
        'signed_from_negotiation_id', p_negotiation_id,
        'signed_by_user_id', p_actor_user_id,
        'signed_on_game_date', v_game_date,
        'acquisition_market_value', v_signing_market_value,
        'signing_bonus', v_signing_bonus,
        'agent_fee', v_agent_fee,
        'transfer_lock_until_game_date', v_transfer_lock_until_game_date,
        'source', 'admin_helper'
      )
    ),
    v_start_season_number,
    v_end_season_number,
    'free_agent',
    v_game_date,
    v_signing_market_value,
    v_free_agent_id,
    v_signing_bonus,
    v_agent_fee,
    v_transfer_lock_until_game_date
  )
  returning id into v_contract_id;

  v_total_signing_cost := coalesce(v_signing_bonus, 0) + coalesce(v_agent_fee, 0);

  if v_total_signing_cost > 0 then
    select a.id
    into v_club_cash_account_id
    from finance.accounts a
    where a.club_id = v_club_id
      and a.currency = 'CASH'
      and a.kind = 'main'
    limit 1
    for update;

    if v_club_cash_account_id is null then
      raise exception 'Club cash account not found';
    end if;

    select a.id
    into v_sink_account_id
    from finance.accounts a
    where a.system_code = 'SINK'
      and a.currency = 'CASH'
      and a.kind = 'main'
    limit 1
    for update;

    if v_sink_account_id is null then
      raise exception 'Sink cash account not found';
    end if;

    -- free-agent signing cost transaction
    select t.id
    into v_signing_cost_tx_id
    from finance.transactions t
    where t.idempotency_key = format('free-agent-signing-cost:%s', p_negotiation_id)
    limit 1;

    if v_signing_cost_tx_id is null and coalesce(v_total_signing_cost, 0) > 0 then
      insert into finance.transactions (
        id,
        type,
        created_at,
        created_by,
        idempotency_key,
        metadata
      )
      values (
        gen_random_uuid(),
        'rider_free_agent_signing_cost_paid',
        now(),
        p_actor_user_id,
        format('free-agent-signing-cost:%s', p_negotiation_id),
        jsonb_build_object(
          'source', 'admin_helper',
          'free_agent_id', v_free_agent_id,
          'rider_id', v_rider_id,
          'negotiation_id', p_negotiation_id,
          'contract_id', v_contract_id,
          'club_id', v_club_id,
          'signing_bonus', coalesce(v_signing_bonus, 0),
          'agent_fee', coalesce(v_agent_fee, 0),
          'total_signing_cost', coalesce(v_total_signing_cost, 0),
          'currency', 'CASH'
        )
      )
      returning id into v_signing_cost_tx_id;
    end if;

    insert into finance.entries (
      transaction_id,
      account_id,
      amount,
      memo,
      created_at
    )
    values
      (
        v_signing_cost_tx_id,
        v_club_cash_account_id,
        -v_total_signing_cost,
        'debit',
        now()
      ),
      (
        v_signing_cost_tx_id,
        v_sink_account_id,
        v_total_signing_cost,
        'credit',
        now()
      );

    update finance.account_balances
    set
      balance = balance - v_total_signing_cost,
      updated_at = now()
    where account_id = v_club_cash_account_id;

    update finance.account_balances
    set
      balance = balance + v_total_signing_cost,
      updated_at = now()
    where account_id = v_sink_account_id;
  end if;

  update public.rider_free_agents fa
  set status = 'signed'
  where fa.id = v_free_agent_id;

  update public.rider_free_agent_negotiations n
  set
    status = 'completed',
    closed_reason = 'signed',
    locked_until = null,
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'completed_at', now(),
      'signed_on_game_date', v_game_date,
      'contract_id', v_contract_id,
      'salary_weekly', v_offer_salary_weekly,
      'duration_seasons', v_offer_duration_seasons,
      'acquisition_market_value', v_signing_market_value,
      'signing_bonus', v_signing_bonus,
      'agent_fee', v_agent_fee,
      'transfer_lock_until_game_date', v_transfer_lock_until_game_date,
      'finance_transaction_id', v_signing_cost_tx_id,
      'total_signing_cost', v_total_signing_cost
    )
  where n.id = p_negotiation_id;

  update public.rider_free_agent_negotiations n
  set
    status = 'withdrawn',
    closed_reason = 'free_agent_signed_elsewhere',
    locked_until = null,
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'withdrawn_at', now(),
      'reason', 'free_agent_signed_elsewhere',
      'winning_negotiation_id', p_negotiation_id
    )
  where n.free_agent_id = v_free_agent_id
    and n.id <> p_negotiation_id
    and n.status = 'open';

  update public.riders r
  set
    release_requested = false,
    asking_price = null,
    asking_price_manual = false,
    asking_price_updated_at = now()
  where r.id = v_rider_id;

  perform public.log_rider_free_agent_event(
    p_event_type      => 'free_agent_signed',
    p_rider_id        => v_rider_id,
    p_free_agent_id   => v_free_agent_id,
    p_negotiation_id  => p_negotiation_id,
    p_source_club_id  => v_source_club_id,
    p_club_id         => v_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'source', 'admin_helper',
      'contract_id', v_contract_id,
      'salary_weekly', v_offer_salary_weekly,
      'duration_seasons', v_offer_duration_seasons,
      'starts_on', v_game_date,
      'expires_on', v_contract_expires_on,
      'start_season_number', v_start_season_number,
      'end_season_number', v_end_season_number,
      'acquisition_market_value', v_signing_market_value,
      'signing_bonus', v_signing_bonus,
      'agent_fee', v_agent_fee,
      'transfer_lock_until_game_date', v_transfer_lock_until_game_date,
      'finance_transaction_id', v_signing_cost_tx_id,
      'total_signing_cost', v_total_signing_cost
    )
  );

  return query
  select
    v_free_agent_id,
    v_rider_id,
    v_club_id,
    v_contract_id,
    v_offer_salary_weekly,
    v_offer_duration_seasons,
    v_game_date,
    v_contract_expires_on,
    v_start_season_number,
    v_end_season_number;
end;$function$
;

CREATE OR REPLACE FUNCTION public.admin_release_rider_to_free_agents(p_rider_id uuid, p_source_club_id uuid, p_expires_in_days integer DEFAULT 14, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(free_agent_id uuid, rider_id uuid, source_type text, source_club_id uuid, desired_tier text, expected_salary_weekly integer, min_acceptable_salary_weekly integer, preferred_duration_seasons smallint, available_from_game_date date, expires_on_game_date date, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_current_salary integer;
  v_age_years integer;
  v_overall smallint;
  v_potential smallint;
  v_role public.rider_role;
  v_current_morale smallint;
  v_club_tier_text text;
  v_desired_tier text;
  v_expected_salary integer;
  v_min_acceptable_salary integer;
  v_preferred_duration smallint;
  v_expires_on_game_date date;
  v_active_contract_id uuid;
  v_free_agent_id uuid;
begin
  v_game_date := public.get_current_game_date_date();
  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  if coalesce(p_expires_in_days, 0) < 1 then
    raise exception 'p_expires_in_days must be at least 1';
  end if;

  select
    r.salary,
    public.get_age_years_on_game_date(r.birth_date),
    r.overall,
    r.potential,
    r.role,
    r.morale,
    c.club_tier::text
  into
    v_current_salary,
    v_age_years,
    v_overall,
    v_potential,
    v_role,
    v_current_morale,
    v_club_tier_text
  from public.riders r
  join public.club_riders cr
    on cr.rider_id = r.id
  join public.clubs c
    on c.id = cr.club_id
  where r.id = p_rider_id
    and cr.club_id = p_source_club_id
  for update of r, cr, c;

  if not found then
    raise exception 'Rider is not assigned to the source club';
  end if;

  if exists (
    select 1
    from public.rider_transfer_listings l
    where l.rider_id = p_rider_id
      and l.status in ('listed', 'club_accepted')
  ) then
    raise exception 'Rider is currently in transfer flow';
  end if;

  select rc.id
  into v_active_contract_id
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.club_id = p_source_club_id
    and rc.status = 'active'
  for update;

  if v_active_contract_id is null then
    raise exception 'Active rider contract not found';
  end if;

  v_desired_tier :=
    case coalesce(v_club_tier_text, 'proteam')
      when 'amateur' then 'amateur'
      when 'continental' then 'continental'
      else 'proteam'
    end;

  v_expected_salary := greatest(coalesce(v_current_salary, 0), 250);
  v_min_acceptable_salary := greatest(floor(v_expected_salary * 0.90)::integer, 100);
  v_preferred_duration := public.suggest_initial_contract_seasons(
    coalesce(v_age_years, 25),
    coalesce(v_overall, 50)::smallint,
    coalesce(v_potential, 50)::smallint
  );
  v_expires_on_game_date := v_game_date + p_expires_in_days;

  update public.rider_contracts
  set
    status = 'released',
    notes_json = coalesce(notes_json, '{}'::jsonb) || jsonb_build_object(
      'released_to_free_agents_at', now(),
      'released_from_club_id', p_source_club_id,
      'released_on_game_date', v_game_date,
      'released_by_user_id', p_actor_user_id,
      'source', 'admin_helper'
    )
  where id = v_active_contract_id;

  delete from public.club_riders cr
  where cr.club_id = p_source_club_id
    and cr.rider_id = p_rider_id;

  insert into public.rider_free_agents (
    rider_id,
    source_type,
    source_club_id,
    desired_tier,
    expected_salary_weekly,
    min_acceptable_salary_weekly,
    preferred_duration_seasons,
    available_from_game_date,
    expires_on_game_date,
    status
  )
  values (
    p_rider_id,
    'released',
    p_source_club_id,
    v_desired_tier,
    v_expected_salary,
    v_min_acceptable_salary,
    v_preferred_duration,
    v_game_date,
    v_expires_on_game_date,
    'available'
  )
  on conflict on constraint rider_free_agents_rider_id_key
  do update set
    source_type = excluded.source_type,
    source_club_id = excluded.source_club_id,
    desired_tier = excluded.desired_tier,
    expected_salary_weekly = excluded.expected_salary_weekly,
    min_acceptable_salary_weekly = excluded.min_acceptable_salary_weekly,
    preferred_duration_seasons = excluded.preferred_duration_seasons,
    available_from_game_date = excluded.available_from_game_date,
    expires_on_game_date = excluded.expires_on_game_date,
    status = 'available'
  returning public.rider_free_agents.id into v_free_agent_id;

  delete from public.rider_free_agent_negotiations n
  where n.free_agent_id = v_free_agent_id;

  update public.riders r
  set
    release_requested = false,
    asking_price = null,
    asking_price_manual = false,
    asking_price_updated_at = now()
  where r.id = p_rider_id;

  perform public.log_rider_free_agent_event(
    p_event_type      => 'free_agent_released',
    p_rider_id        => p_rider_id,
    p_free_agent_id   => v_free_agent_id,
    p_source_club_id  => p_source_club_id,
    p_actor_user_id   => p_actor_user_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'source', 'admin_helper',
      'expected_salary_weekly', v_expected_salary,
      'min_acceptable_salary_weekly', v_min_acceptable_salary,
      'preferred_duration_seasons', v_preferred_duration,
      'expires_on_game_date', v_expires_on_game_date
    )
  );

  return query
  select
    fa.id,
    fa.rider_id,
    fa.source_type,
    fa.source_club_id,
    fa.desired_tier,
    fa.expected_salary_weekly,
    fa.min_acceptable_salary_weekly,
    fa.preferred_duration_seasons,
    fa.available_from_game_date,
    fa.expires_on_game_date,
    fa.status
  from public.rider_free_agents fa
  where fa.id = v_free_agent_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.process_rider_free_agent_event_to_notifications(p_event_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.rider_free_agent_events%rowtype;
  v_buyer_owner_user_id uuid;
  v_source_owner_user_id uuid;
  v_created_count integer := 0;
  v_notification_id bigint;
begin
  select *
  into v_event
  from public.rider_free_agent_events e
  where e.id = p_event_id;

  if not found then
    raise exception 'Free-agent event not found';
  end if;

  if v_event.club_id is not null then
    select c.owner_user_id
    into v_buyer_owner_user_id
    from public.clubs c
    where c.id = v_event.club_id;
  end if;

  if v_event.source_club_id is not null then
    select c.owner_user_id
    into v_source_owner_user_id
    from public.clubs c
    where c.id = v_event.source_club_id;
  end if;

  /*
    keep your existing branches here unchanged
  */

  if v_event.event_type = 'free_agent_signed' then
    if v_buyer_owner_user_id is not null
       and not exists (
         select 1
         from public.user_notifications un
         where un.user_id = v_buyer_owner_user_id
           and un.source_event_id = v_event.id
       ) then

      insert into public.notifications (
        type_id,
        title,
        message,
        source,
        created_by_user_id,
        action_url,
        payload_json
      )
      values (
        7,
        'Free agent signed',
        'The rider joined your club.',
        'game',
        v_event.actor_user_id,
        '/dashboard/transfers/free-agents',
        jsonb_build_object(
          'side', 'buyer',
          'event_type', v_event.event_type,
          'free_agent_id', v_event.free_agent_id,
          'negotiation_id', v_event.negotiation_id,
          'rider_id', v_event.rider_id,
          'club_id', v_event.club_id,
          'source_club_id', v_event.source_club_id,
          'payload', v_event.payload
        )
      )
      returning id into v_notification_id;

      insert into public.user_notifications (
        user_id,
        notification_id,
        status,
        created_at,
        source_event_id
      )
      values (
        v_buyer_owner_user_id,
        v_notification_id,
        'unread',
        now(),
        v_event.id
      );

      v_created_count := v_created_count + 1;
    end if;

    if v_event.source_club_id is not null
       and v_source_owner_user_id is not null
       and not exists (
         select 1
         from public.user_notifications un
         where un.user_id = v_source_owner_user_id
           and un.source_event_id = v_event.id
       ) then

      insert into public.notifications (
        type_id,
        title,
        message,
        source,
        created_by_user_id,
        action_url,
        payload_json
      )
      values (
        7,
        'Released rider signed elsewhere',
        'Your released rider signed for another club.',
        'game',
        v_event.actor_user_id,
        '/dashboard/transfers/free-agents',
        jsonb_build_object(
          'side', 'source_club',
          'event_type', v_event.event_type,
          'free_agent_id', v_event.free_agent_id,
          'negotiation_id', v_event.negotiation_id,
          'rider_id', v_event.rider_id,
          'source_club_id', v_event.source_club_id,
          'club_id', v_event.club_id,
          'payload', v_event.payload
        )
      )
      returning id into v_notification_id;

      insert into public.user_notifications (
        user_id,
        notification_id,
        status,
        created_at,
        source_event_id
      )
      values (
        v_source_owner_user_id,
        v_notification_id,
        'unread',
        now(),
        v_event.id
      );

      v_created_count := v_created_count + 1;
    end if;
  end if;

  return v_created_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.seed_generated_free_agent_pool(p_amateur_target integer DEFAULT 30, p_continental_target integer DEFAULT 18, p_proteam_target integer DEFAULT 8)
 RETURNS TABLE(created_count integer, amateur_created integer, continental_created integer, proteam_created integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_created_count integer := 0;
  v_amateur_created integer := 0;
  v_continental_created integer := 0;
  v_proteam_created integer := 0;

  v_existing_amateur integer := 0;
  v_existing_continental integer := 0;
  v_existing_proteam integer := 0;

  v_need_amateur integer := 0;
  v_need_continental integer := 0;
  v_need_proteam integer := 0;

  v_idx integer;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  select count(*) into v_existing_amateur
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'amateur';

  select count(*) into v_existing_continental
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'continental';

  select count(*) into v_existing_proteam
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'proteam';

  v_need_amateur := greatest(0, coalesce(p_amateur_target, 0) - v_existing_amateur);
  v_need_continental := greatest(0, coalesce(p_continental_target, 0) - v_existing_continental);
  v_need_proteam := greatest(0, coalesce(p_proteam_target, 0) - v_existing_proteam);

  for v_idx in 1..v_need_amateur loop
    perform public._create_generated_free_agent_internal('amateur', 14);
    v_created_count := v_created_count + 1;
    v_amateur_created := v_amateur_created + 1;
  end loop;

  for v_idx in 1..v_need_continental loop
    perform public._create_generated_free_agent_internal('continental', 14);
    v_created_count := v_created_count + 1;
    v_continental_created := v_continental_created + 1;
  end loop;

  for v_idx in 1..v_need_proteam loop
    perform public._create_generated_free_agent_internal('proteam', 14);
    v_created_count := v_created_count + 1;
    v_proteam_created := v_proteam_created + 1;
  end loop;

  return query
  select
    v_created_count,
    v_amateur_created,
    v_continental_created,
    v_proteam_created;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_create_rider_transfer_listing(p_rider_id uuid, p_seller_club_id uuid, p_duration_days integer DEFAULT 7)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_listing_id uuid;
  v_market_value bigint;
  v_asking_price bigint;
  v_today date;
begin
  select public.get_market_game_date()
  into v_today;

  select r.market_value
  into v_market_value
  from public.riders r
  where r.id = p_rider_id;

  if v_market_value is null then
    raise exception 'Rider not found or missing market value: %', p_rider_id;
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_seller_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider % is not owned by club %', p_rider_id, p_seller_club_id;
  end if;

  if exists (
    select 1
    from public.rider_transfer_listings rtl
    where rtl.rider_id = p_rider_id
      and rtl.status in ('listed', 'club_accepted')
  ) then
    raise exception 'Rider is already in transfer flow: %', p_rider_id;
  end if;

  if exists (
    select 1
    from public.rider_free_agents rfa
    where rfa.rider_id = p_rider_id
      and rfa.status = 'available'
  ) then
    raise exception 'Rider is already in free-agent flow: %', p_rider_id;
  end if;

  v_asking_price := greatest(v_market_value, 10000);

  insert into public.rider_transfer_listings (
    rider_id,
    seller_club_id,
    asking_price,
    min_allowed_price,
    max_allowed_price,
    listed_on_game_date,
    expires_on_game_date,
    status,
    auto_price_clamped
  )
  values (
    p_rider_id,
    p_seller_club_id,
    v_asking_price,
    floor(v_asking_price * 0.75)::bigint,
    ceil(v_asking_price * 1.50)::bigint,
    v_today,
    v_today + greatest(coalesce(p_duration_days, 7), 1),
    'listed',
    false
  )
  returning id into v_listing_id;

  update public.riders
  set
    asking_price = v_asking_price,
    asking_price_manual = false,
    asking_price_updated_at = now(),
    release_requested = true
  where id = p_rider_id;

  perform public.log_rider_transfer_event(
    p_event_type      => 'listing_created'::text,
    p_rider_id        => p_rider_id::uuid,
    p_listing_id      => v_listing_id::uuid,
    p_offer_id        => null::uuid,
    p_negotiation_id  => null::uuid,
    p_seller_club_id  => p_seller_club_id::uuid,
    p_buyer_club_id   => null::uuid,
    p_actor_user_id   => null::uuid,
    p_event_game_date => v_today::date,
    p_payload         => jsonb_build_object('source', 'ai_seller_job')::jsonb
  );

  return v_listing_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_club_for_transfer_sales(p_club_id uuid)
 RETURNS TABLE(action_taken text, rider_id uuid, listing_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
  v_listing_id uuid;
begin
  select
    r.id as rider_id,
    (
      coalesce(extract(year from age(current_date, r.birth_date)), 0) * 1.0
      + (100 - coalesce(r.potential, 50)) * 0.25
      + (100 - coalesce(r.morale, 50)) * 0.20
      + coalesce(r.market_value, 0) / 50000.0
    ) as sell_score
  into v_candidate
  from public.club_riders cr
  join public.riders r
    on r.id = cr.rider_id
  where cr.club_id = p_club_id
    and not exists (
      select 1
      from public.rider_transfer_listings rtl
      where rtl.rider_id = r.id
        and rtl.status in ('listed', 'club_accepted')
    )
    and not exists (
      select 1
      from public.rider_free_agents rfa
      where rfa.rider_id = r.id
        and rfa.status = 'available'
    )
  order by sell_score desc, r.market_value desc nulls last
  limit 1;

  if v_candidate.rider_id is null then
    return query
    select 'no_action'::text, null::uuid, null::uuid;
    return;
  end if;

  /*
    Lower threshold for phase 1 to ensure visible activity.
  */
  if coalesce(v_candidate.sell_score, 0) < 35 then
    return query
    select 'no_action'::text, null::uuid, null::uuid;
    return;
  end if;

  v_listing_id := public.ai_create_rider_transfer_listing(
    v_candidate.rider_id,
    p_club_id,
    7
  );

  return query
  select 'listed'::text, v_candidate.rider_id::uuid, v_listing_id::uuid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_transfer_seller_job()
 RETURNS TABLE(clubs_reviewed integer, listings_created integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
begin
  v_result :=
    public.refill_ai_transfer_market_to_target_v1();

  return query
  select
    coalesce(
      (v_result ->> 'candidates_selected')::integer,
      0
    ),
    coalesce(
      (v_result ->> 'created')::integer,
      0
    ),
    coalesce(
      (v_result ->> 'skipped')::integer,
      0
    );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_club_for_transfer_buys(p_club_id uuid)
 RETURNS TABLE(action_taken text, listing_id uuid, rider_id uuid, offer_id uuid, offered_price bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
  v_offer_price bigint;
  v_offer_result record;
  v_cfg record;
  v_cash_balance bigint;
  v_first_squad_count integer := 0;
begin
  select count(*)::integer
  into v_first_squad_count
  from public.club_riders cr
  where cr.club_id = p_club_id;

  if v_first_squad_count >= 18 then
    return query
    select
      'skipped_squad_full'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::bigint;
    return;
  end if;

  select *
  into v_cfg
  from public.get_market_ai_config();

  select c.cash_balance::bigint
  into v_cash_balance
  from public.clubs c
  where c.id = p_club_id;

  select
    rtl.id as listing_id,
    rtl.rider_id,
    rtl.asking_price,
    r.market_value,
    r.potential,
    r.morale,
    r.birth_date,
    (
      (
        case
          when coalesce(r.market_value, 0) > 0
            then (
              (
                coalesce(r.market_value, 0)
                - rtl.asking_price
              )::numeric
              / r.market_value
            ) * 100
          else 0
        end
      )
      + (coalesce(r.potential, 50) - 50) * 0.6
      + greatest(
          0,
          35 - coalesce(
            public.get_age_years_on_game_date(
              r.birth_date
            ),
            35
          )
        ) * 0.8
      + (coalesce(r.morale, 50) - 50) * 0.2
    ) as buy_score
  into v_candidate
  from public.rider_transfer_listings rtl
  join public.riders r
    on r.id = rtl.rider_id
  where rtl.status = 'listed'
    and public.market_ai_club_rider_country_eligible_v1(
      p_club_id,
      rtl.rider_id
    )
    and rtl.seller_club_id <> p_club_id
    and not exists (
      select 1
      from public.club_riders cr
      where cr.club_id = p_club_id
        and cr.rider_id = rtl.rider_id
    )
    and not exists (
      select 1
      from public.rider_transfer_offers rto
      where rto.listing_id = rtl.id
        and rto.buyer_club_id = p_club_id
        and rto.status in (
          'open',
          'club_accepted',
          'completed'
        )
    )
    and not exists (
      select 1
      from public.rider_transfer_offers rto_today
      where rto_today.listing_id = rtl.id
        and rto_today.offered_on_game_date =
          public.get_market_game_date()
    )
  order by
    buy_score desc,
    rtl.asking_price asc
  limit 1;

  if v_candidate.listing_id is null then
    return query
    select
      'skipped_no_candidate'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::bigint;
    return;
  end if;

  if coalesce(v_candidate.market_value, 0) > 0
     and v_candidate.asking_price
         <= v_candidate.market_value then
    v_offer_price := floor(
      v_candidate.asking_price
      * v_cfg.transfer_bid_pct_below_asking
    )::bigint;
  else
    v_offer_price := floor(
      v_candidate.asking_price
      * v_cfg.transfer_bid_pct_above_market
    )::bigint;
  end if;

  v_offer_price := greatest(v_offer_price, 1000);

  if not coalesce(
       v_cfg.ignore_ai_cash_constraints,
       false
     )
     and coalesce(v_cash_balance, 0) - v_offer_price
       < coalesce(v_cfg.min_club_cash_reserve, 0) then
    return query
    select
      'skipped_cash_reserve'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::bigint;
    return;
  end if;

  select *
  into v_offer_result
  from public.admin_submit_rider_transfer_offer(
    v_candidate.listing_id::uuid,
    p_club_id::uuid,
    v_offer_price::bigint,
    null::uuid
  )
  limit 1;

  if v_offer_result.offer_id is null then
    return query
    select
      'skipped_daily_offer_limit'::text,
      v_candidate.listing_id::uuid,
      v_candidate.rider_id::uuid,
      null::uuid,
      v_offer_price::bigint;
    return;
  end if;

  return query
  select
    'offered'::text,
    v_candidate.listing_id::uuid,
    v_candidate.rider_id::uuid,
    v_offer_result.offer_id::uuid,
    v_offer_price::bigint;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_transfer_buyer_job()
 RETURNS TABLE(clubs_reviewed integer, offers_created integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reviewed integer := 0;
  v_offers integer := 0;
  v_skipped integer := 0;

  v_today date;
  v_cfg record;
  v_row record;
  v_result record;

  v_daily_limit integer := 0;
  v_existing_ai_offers_today integer := 0;
  v_remaining_offer_slots integer := 0;
begin
  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  v_daily_limit := greatest(0, coalesce(v_cfg.transfer_buyer_daily_limit, 60));

  /*
    Important:
    Make the buyer job idempotent per game date.

    Without this lock + count, the job can be run twice on the same game date
    and create another full batch of AI offers from different AI buyer clubs.
  */
  perform pg_advisory_xact_lock(
    hashtext('run_ai_transfer_buyer_job:' || v_today::text)
  );

  select count(*)
  into v_existing_ai_offers_today
  from public.rider_transfer_offers rto
  join public.clubs buyer on buyer.id = rto.buyer_club_id
  where buyer.is_ai = true
    and rto.offered_on_game_date = v_today;

  v_remaining_offer_slots := greatest(
    0,
    v_daily_limit - v_existing_ai_offers_today
  );

  if v_remaining_offer_slots <= 0 then
    return query
    select 0::integer, 0::integer, 0::integer;
    return;
  end if;

  for v_row in
    with eligible_ai_buyer_clubs as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and not exists (
          select 1
          from public.rider_transfer_offers rto
          where rto.buyer_club_id = c.id
            and rto.offered_on_game_date = v_today
        )
    )
    select id
    from eligible_ai_buyer_clubs
    order by random()
    limit v_remaining_offer_slots
  loop
    v_reviewed := v_reviewed + 1;

    select *
    into v_result
    from public.ai_review_club_for_transfer_buys(v_row.id)
    limit 1;

    if v_result.action_taken = 'offered' then
      v_offers := v_offers + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return query
  select v_reviewed, v_offers, v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_club_for_free_agent_buys(p_club_id uuid)
 RETURNS TABLE(action_taken text, free_agent_id uuid, rider_id uuid, negotiation_id uuid, offered_salary integer, offered_duration smallint, can_sign boolean, meets_expected_salary boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
  v_salary_offer integer;
  v_duration smallint;
  v_offer_result record;
  v_today date;
  v_cfg record;
  v_cash_balance bigint;
  v_first_squad_count integer := 0;
begin
  select count(*)::integer
  into v_first_squad_count
  from public.club_riders cr
  where cr.club_id = p_club_id;

  if v_first_squad_count >= 18 then
    return query
    select
      'skipped_squad_full'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::integer,
      null::smallint,
      null::boolean,
      null::boolean;
    return;
  end if;

  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  select c.cash_balance::bigint
  into v_cash_balance
  from public.clubs c
  where c.id = p_club_id;

  select
    rfa.id as free_agent_id,
    rfa.rider_id,
    rfa.expected_salary_weekly,
    rfa.min_acceptable_salary_weekly,
    rfa.preferred_duration_seasons,
    rfa.desired_tier,
    r.potential,
    r.morale,
    r.birth_date,
    (
      (coalesce(r.potential, 50) - 50) * 0.7
      + greatest(
          0,
          35 - coalesce(
            extract(year from age(current_date, r.birth_date)),
            35
          )
        ) * 0.8
      + (coalesce(r.morale, 50) - 50) * 0.2
      - least(
          coalesce(rfa.expected_salary_weekly, 0) / 200,
          100
        ) * 0.4
    ) as buy_score
  into v_candidate
  from public.rider_free_agents rfa
  join public.riders r
    on r.id = rfa.rider_id
  where rfa.status = 'available'
    and public.market_ai_club_rider_country_eligible_v1(
      p_club_id,
      rfa.rider_id
    )
    and not exists (
      select 1
      from public.rider_free_agent_negotiations n
      where n.free_agent_id = rfa.id
        and n.club_id = p_club_id
        and n.status = 'open'
    )
    and not exists (
      select 1
      from public.rider_free_agent_negotiations n_today
      where n_today.free_agent_id = rfa.id
        and n_today.opened_on_game_date = v_today
    )
  order by buy_score desc, rfa.expected_salary_weekly asc
  limit 1;

  if v_candidate.free_agent_id is null then
    return query
    select
      'skipped_no_candidate'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::integer,
      null::smallint,
      null::boolean,
      null::boolean;
    return;
  end if;

  v_salary_offer := greatest(
    coalesce(v_candidate.min_acceptable_salary_weekly, 0),
    floor(
      coalesce(v_candidate.expected_salary_weekly, 0)
      * v_cfg.free_agent_expected_salary_pct
    )::integer
  );

  v_duration := coalesce(
    v_candidate.preferred_duration_seasons,
    1
  );

  if not coalesce(v_cfg.ignore_ai_cash_constraints, false)
     and coalesce(v_cash_balance, 0) - v_salary_offer
       < coalesce(v_cfg.min_club_cash_reserve, 0) then
    return query
    select
      'skipped_cash_reserve'::text,
      null::uuid,
      null::uuid,
      null::uuid,
      null::integer,
      null::smallint,
      null::boolean,
      null::boolean;
    return;
  end if;

  select *
  into v_offer_result
  from public.admin_submit_free_agent_offer(
    v_candidate.free_agent_id::uuid,
    p_club_id::uuid,
    v_salary_offer::integer,
    v_duration::smallint,
    null::uuid
  )
  limit 1;

  return query
  select
    'offered'::text,
    v_candidate.free_agent_id::uuid,
    v_candidate.rider_id::uuid,
    v_offer_result.negotiation_id::uuid,
    v_salary_offer::integer,
    v_duration::smallint,
    v_offer_result.can_sign::boolean,
    v_offer_result.meets_expected_salary::boolean;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_free_agent_buyer_job()
 RETURNS TABLE(clubs_reviewed integer, offers_created integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reviewed integer := 0;
  v_offers integer := 0;
  v_skipped integer := 0;
  v_today date;
  v_cfg record;
  v_row record;
  v_result record;
begin
  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  for v_row in
    with eligible_ai_buyer_clubs as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and not exists (
          select 1
          from public.rider_free_agent_negotiations n
          where n.club_id = c.id
            and n.opened_on_game_date = v_today
        )
    )
    select id
    from eligible_ai_buyer_clubs
    order by random()
    limit v_cfg.free_agent_buyer_daily_limit
  loop
    v_reviewed := v_reviewed + 1;

    select *
    into v_result
    from public.ai_review_club_for_free_agent_buys(v_row.id)
    limit 1;

    if v_result.action_taken = 'offered' then
      v_offers := v_offers + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return query
  select v_reviewed, v_offers, v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_club_for_free_agent_signing(p_club_id uuid)
 RETURNS TABLE(action_taken text, negotiation_id uuid, free_agent_id uuid, rider_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
begin
  select
    n.id as negotiation_id,
    n.free_agent_id,
    n.rider_id,
    n.offer_salary_weekly,
    n.offer_duration_seasons,
    n.expected_salary_weekly,
    n.min_acceptable_salary_weekly,
    n.preferred_duration_seasons,
    n.created_at
  into v_candidate
  from public.rider_free_agent_negotiations n
  join public.rider_free_agents fa
    on fa.id = n.free_agent_id
  where n.club_id = p_club_id
    and n.status = 'open'
    and fa.status = 'available'
    and coalesce(n.offer_salary_weekly, 0) >= coalesce(n.min_acceptable_salary_weekly, 0)
    and coalesce(n.offer_duration_seasons, 0) >= 1
  order by
    (coalesce(n.offer_salary_weekly, 0) - coalesce(n.min_acceptable_salary_weekly, 0)) desc,
    n.created_at asc
  limit 1;

  if v_candidate.negotiation_id is null then
    return query
    select 'skipped_no_signable_negotiation'::text, null::uuid, null::uuid, null::uuid;
    return;
  end if;

  perform public.admin_sign_free_agent_from_negotiation(
    v_candidate.negotiation_id::uuid,
    null::uuid
  );

  return query
  select
    'signed'::text,
    v_candidate.negotiation_id::uuid,
    v_candidate.free_agent_id::uuid,
    v_candidate.rider_id::uuid;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_free_agent_signing_job()
 RETURNS TABLE(clubs_reviewed integer, signings_completed integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reviewed integer := 0;
  v_signed integer := 0;
  v_skipped integer := 0;
  v_cfg record;
  v_today date;
  v_row record;
  v_result record;
begin
  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  for v_row in
    with eligible_ai_clubs as (
      select distinct c.id
      from public.clubs c
      join public.rider_free_agent_negotiations n
        on n.club_id = c.id
      join public.rider_free_agents fa
        on fa.id = n.free_agent_id
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and n.status = 'open'
        and fa.status = 'available'
        and coalesce(n.offer_salary_weekly, 0)
          >= coalesce(n.min_acceptable_salary_weekly, 0)
        and coalesce(n.offer_duration_seasons, 0) >= 1
        and (
          select count(*)
          from public.club_riders cr
          where cr.club_id = c.id
        ) < 18
        and not exists (
          select 1
          from public.rider_free_agent_events e
          where e.event_type = 'free_agent_signed'
            and e.club_id = c.id
            and e.event_game_date = v_today
        )
    )
    select id
    from eligible_ai_clubs
    order by random()
    limit v_cfg.free_agent_sign_daily_limit
  loop
    v_reviewed := v_reviewed + 1;

    begin
      select *
      into v_result
      from public.ai_review_club_for_free_agent_signing(
        v_row.id
      )
      limit 1;

    exception
      when others then
        if public.market_ai_is_skippable_roster_exception_v1(
             sqlstate,
             sqlerrm
           ) then
          v_skipped := v_skipped + 1;
          continue;
        end if;

        raise;
    end;

    if v_result.action_taken = 'signed' then
      v_signed := v_signed + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return query
  select
    v_reviewed,
    v_signed,
    v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_club_for_transfer_contract_offers(p_club_id uuid)
 RETURNS TABLE(action_taken text, negotiation_id uuid, rider_id uuid, offered_salary integer, offered_duration smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_candidate record;
  v_salary_offer integer;
  v_duration smallint;
begin
  select
    n.id as negotiation_id,
    n.rider_id,
    n.expected_salary_weekly,
    n.min_acceptable_salary_weekly,
    n.preferred_duration_seasons,
    n.offer_salary_weekly,
    n.offer_duration_seasons,
    n.attempt_count,
    n.max_attempts,
    n.locked_until,
    n.expires_on_game_date,
    n.created_at
  into v_candidate
  from public.rider_transfer_negotiations n
  where n.buyer_club_id = p_club_id
    and n.status = 'open'
    and (n.locked_until is null or n.locked_until <= now())
  order by
    coalesce(n.offer_salary_weekly, 0) desc,
    n.created_at asc
  limit 1;

  if v_candidate.negotiation_id is null then
    return query
    select 'skipped_no_open_negotiation'::text, null::uuid, null::uuid, null::integer, null::smallint;
    return;
  end if;

  v_salary_offer := greatest(
    coalesce(v_candidate.min_acceptable_salary_weekly, 0),
    coalesce(v_candidate.expected_salary_weekly, 0)
  );

  v_duration := greatest(
    1::smallint,
    coalesce(v_candidate.preferred_duration_seasons, 1)
  );

  perform public.admin_submit_rider_transfer_contract_offer(
    v_candidate.negotiation_id::uuid,
    v_salary_offer::integer,
    v_duration::smallint
  );

  return query
  select
    'submitted_terms'::text,
    v_candidate.negotiation_id::uuid,
    v_candidate.rider_id::uuid,
    v_salary_offer::integer,
    v_duration::smallint;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_transfer_contract_offer_job()
 RETURNS TABLE(clubs_reviewed integer, terms_submitted integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reviewed integer := 0;
  v_submitted integer := 0;
  v_skipped integer := 0;

  v_open_ai_buyer_clubs integer := 0;
  v_locked_blocked_ai_buyer_clubs integer := 0;
  v_already_submitted_today_ai_buyer_clubs integer := 0;
  v_full_squad_blocked_ai_buyer_clubs integer := 0;
  v_eligible_before_limit integer := 0;

  v_cfg record;
  v_today date;
  v_row record;
  v_result record;
begin
  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  if v_cfg is null then
    raise exception 'Market AI config not found.';
  end if;

  select count(*)
  into v_open_ai_buyer_clubs
  from (
    select distinct c.id
    from public.clubs c
    join public.rider_transfer_negotiations n
      on n.buyer_club_id = c.id
    where c.deleted_at is null
      and c.is_ai = true
      and c.club_type = 'main'
      and c.parent_club_id is null
      and n.status = 'open'
  ) s;

  select count(*)
  into v_locked_blocked_ai_buyer_clubs
  from (
    select distinct c.id
    from public.clubs c
    join public.rider_transfer_negotiations n
      on n.buyer_club_id = c.id
    where c.deleted_at is null
      and c.is_ai = true
      and c.club_type = 'main'
      and c.parent_club_id is null
      and n.status = 'open'
      and n.locked_until is not null
      and n.locked_until > now()
  ) s;

  select count(*)
  into v_already_submitted_today_ai_buyer_clubs
  from (
    select distinct c.id
    from public.clubs c
    join public.rider_transfer_negotiations n
      on n.buyer_club_id = c.id
    where c.deleted_at is null
      and c.is_ai = true
      and c.club_type = 'main'
      and c.parent_club_id is null
      and n.status = 'open'
      and exists (
        select 1
        from public.rider_transfer_events rte
        where rte.event_type = 'contract_terms_submitted'
          and rte.buyer_club_id = c.id
          and rte.event_game_date = v_today
      )
  ) s;

  select count(*)
  into v_full_squad_blocked_ai_buyer_clubs
  from (
    select distinct c.id
    from public.clubs c
    join public.rider_transfer_negotiations n
      on n.buyer_club_id = c.id
    where c.deleted_at is null
      and c.is_ai = true
      and c.club_type = 'main'
      and c.parent_club_id is null
      and n.status = 'open'
      and (
        select count(*)
        from public.club_riders cr
        where cr.club_id = c.id
      ) >= 18
  ) s;

  select count(*)
  into v_eligible_before_limit
  from (
    select distinct c.id
    from public.clubs c
    join public.rider_transfer_negotiations n
      on n.buyer_club_id = c.id
    where c.deleted_at is null
      and c.is_ai = true
      and c.club_type = 'main'
      and c.parent_club_id is null
      and n.status = 'open'
      and (n.locked_until is null or n.locked_until <= now())
      and (
        select count(*)
        from public.club_riders cr
        where cr.club_id = c.id
      ) < 18
      and not exists (
        select 1
        from public.rider_transfer_events rte
        where rte.event_type = 'contract_terms_submitted'
          and rte.buyer_club_id = c.id
          and rte.event_game_date = v_today
      )
  ) s;

  raise notice
    'run_ai_transfer_contract_offer_job(): today=%, open=%, locked=%, already_submitted=%, full_squad=%, eligible=%, limit=%',
    v_today,
    v_open_ai_buyer_clubs,
    v_locked_blocked_ai_buyer_clubs,
    v_already_submitted_today_ai_buyer_clubs,
    v_full_squad_blocked_ai_buyer_clubs,
    v_eligible_before_limit,
    v_cfg.transfer_contract_offer_daily_limit;

  for v_row in
    with eligible_ai_buyer_clubs as (
      select distinct c.id
      from public.clubs c
      join public.rider_transfer_negotiations n
        on n.buyer_club_id = c.id
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and n.status = 'open'
        and (n.locked_until is null or n.locked_until <= now())
        and (
          select count(*)
          from public.club_riders cr
          where cr.club_id = c.id
        ) < 18
        and not exists (
          select 1
          from public.rider_transfer_events rte
          where rte.event_type = 'contract_terms_submitted'
            and rte.buyer_club_id = c.id
            and rte.event_game_date = v_today
        )
    )
    select id
    from eligible_ai_buyer_clubs
    order by random()
    limit coalesce(
      v_cfg.transfer_contract_offer_daily_limit,
      0
    )
  loop
    v_reviewed := v_reviewed + 1;

    begin
      select *
      into v_result
      from public.ai_review_club_for_transfer_contract_offers(
        v_row.id
      )
      limit 1;

    exception
      when others then
        if public.market_ai_is_skippable_roster_exception_v1(
             sqlstate,
             sqlerrm
           ) then
          v_skipped := v_skipped + 1;
          continue;
        end if;

        raise;
    end;

    if coalesce(v_result.action_taken, '') = 'submitted_terms' then
      v_submitted := v_submitted + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return query
  select
    v_reviewed,
    v_submitted,
    v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_market_jobs()
 RETURNS TABLE(expired_transfer_listings integer, expired_transfer_offers integer, expired_transfer_negotiations integer, expired_free_agents integer, expired_free_agent_negotiations integer, refill_created_count integer, refill_amateur_created integer, refill_continental_created integer, refill_proteam_created integer, ai_seller_clubs_reviewed integer, ai_seller_listings_created integer, ai_seller_skipped_count integer, ai_buyer_clubs_reviewed integer, ai_buyer_offers_created integer, ai_buyer_skipped_count integer, ai_transfer_contract_clubs_reviewed integer, ai_transfer_contract_terms_submitted integer, ai_transfer_contract_skipped_count integer, ai_fa_buyer_clubs_reviewed integer, ai_fa_buyer_offers_created integer, ai_fa_buyer_skipped_count integer, ai_fa_sign_clubs_reviewed integer, ai_fa_signings_completed integer, ai_fa_sign_skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_transfer record;
begin
  -- daily cleanup / expiry only
  select *
  into v_transfer
  from public.expire_rider_transfer_market_state();

  return query
  select
    coalesce(v_transfer.expired_listing_count, 0),
    coalesce(v_transfer.expired_offer_count, 0),
    coalesce(v_transfer.expired_negotiation_count, 0),
    0, -- expired_free_agents
    0, -- expired_free_agent_negotiations
    0, -- refill_created_count
    0, -- refill_amateur_created
    0, -- refill_continental_created
    0, -- refill_proteam_created
    0, -- ai_seller_clubs_reviewed
    0, -- ai_seller_listings_created
    0, -- ai_seller_skipped_count
    0, -- ai_buyer_clubs_reviewed
    0, -- ai_buyer_offers_created
    0, -- ai_buyer_skipped_count
    0, -- ai_transfer_contract_clubs_reviewed
    0, -- ai_transfer_contract_terms_submitted
    0, -- ai_transfer_contract_skipped_count
    0, -- ai_fa_buyer_clubs_reviewed
    0, -- ai_fa_buyer_offers_created
    0, -- ai_fa_buyer_skipped_count
    0, -- ai_fa_sign_clubs_reviewed
    0, -- ai_fa_signings_completed
    0; -- ai_fa_sign_skipped_count
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ensure_ai_market_club_state(p_club_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.ai_market_club_state (club_id)
  values (p_club_id)
  on conflict (club_id) do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.plan_daily_generated_free_agents()
 RETURNS TABLE(total_to_create integer, amateur_to_create integer, continental_to_create integer, proteam_to_create integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_total integer;
  v_amateur integer;
  v_continental integer;
  v_proteam integer;
begin
  v_total := floor(50 + random() * 51)::integer;

  v_amateur := floor(v_total * 0.55)::integer;
  v_continental := floor(v_total * 0.30)::integer;
  v_proteam := v_total - v_amateur - v_continental;

  return query
  select
    v_total,
    v_amateur,
    v_continental,
    v_proteam;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_daily_generated_free_agents()
 RETURNS TABLE(created_count integer, amateur_created integer, continental_created integer, proteam_created integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_created_count integer := 0;
  v_amateur_created integer := 0;
  v_continental_created integer := 0;
  v_proteam_created integer := 0;

  v_total_to_create integer := 0;
  v_need_amateur integer := 0;
  v_need_continental integer := 0;
  v_need_proteam integer := 0;

  v_idx integer;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  v_total_to_create := floor(50 + random() * 51)::integer;

  v_need_amateur := floor(v_total_to_create * 0.55)::integer;
  v_need_continental := floor(v_total_to_create * 0.30)::integer;
  v_need_proteam := v_total_to_create - v_need_amateur - v_need_continental;

  for v_idx in 1..v_need_amateur loop
    perform public._create_generated_free_agent_internal('amateur', 7);
    v_created_count := v_created_count + 1;
    v_amateur_created := v_amateur_created + 1;
  end loop;

  for v_idx in 1..v_need_continental loop
    perform public._create_generated_free_agent_internal('continental', 7);
    v_created_count := v_created_count + 1;
    v_continental_created := v_continental_created + 1;
  end loop;

  for v_idx in 1..v_need_proteam loop
    perform public._create_generated_free_agent_internal('proteam', 7);
    v_created_count := v_created_count + 1;
    v_proteam_created := v_proteam_created + 1;
  end loop;

  return query
  select
    v_created_count,
    v_amateur_created,
    v_continental_created,
    v_proteam_created;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_generated_free_agents()
 RETURNS TABLE(deleted_free_agents integer, deleted_riders integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_deleted_free_agents integer := 0;
  v_deleted_riders integer := 0;
begin
  with deleted_fa as (
    delete from public.rider_free_agents fa
    where fa.source_type = 'generated'
      and fa.status = 'expired'
      and not exists (
        select 1
        from public.club_riders cr
        where cr.rider_id = fa.rider_id
      )
      and not exists (
        select 1
        from public.rider_contracts rc
        where rc.rider_id = fa.rider_id
      )
      and not exists (
        select 1
        from public.rider_free_agent_negotiations n
        where n.free_agent_id = fa.id
          and n.status = 'open'
      )
    returning fa.rider_id
  )
  select count(*)
  into v_deleted_free_agents
  from deleted_fa;

  with deleted_r as (
    delete from public.riders r
    where not exists (
      select 1
      from public.rider_free_agents fa
      where fa.rider_id = r.id
    )
      and not exists (
        select 1
        from public.club_riders cr
        where cr.rider_id = r.id
      )
      and not exists (
        select 1
        from public.rider_contracts rc
        where rc.rider_id = r.id
      )
      and not exists (
        select 1
        from public.rider_scout_reports rs
        where rs.rider_id = r.id
      )
    returning r.id
  )
  select count(*)
  into v_deleted_riders
  from deleted_r;

  return query
  select v_deleted_free_agents, v_deleted_riders;
end;$function$
;

CREATE OR REPLACE FUNCTION public.get_transfer_time_left_label(p_expires_on_game_date date)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_seconds bigint;
  v_days bigint;
  v_hours bigint;
  v_minutes bigint;
  v_remaining bigint;
begin
  if p_expires_on_game_date is null then
    return 'No expiry';
  end if;

  v_seconds := public.get_transfer_time_left_seconds(p_expires_on_game_date);

  if v_seconds is null then
    return 'No expiry';
  end if;

  if v_seconds <= 0 then
    return 'Expired';
  end if;

  v_days := v_seconds / 86400;
  v_remaining := v_seconds % 86400;

  v_hours := v_remaining / 3600;
  v_remaining := v_remaining % 3600;

  v_minutes := v_remaining / 60;
  v_remaining := v_remaining % 60;

  return v_days || 'd ' || v_hours || 'h ' || v_minutes || 'm ' || v_remaining || 's';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_transfer_market_listings(p_page integer DEFAULT 1, p_page_size integer DEFAULT 1000)
 RETURNS TABLE(listing_id uuid, rider_id uuid, seller_club_id uuid, seller_club_name text, display_name text, country_code text, role rider_role, age_years integer, overall smallint, potential smallint, market_value bigint, asking_price bigint, salary integer, contract_expires_at date, availability_status text, listed_on_game_date date, expires_on_game_date date, auto_price_clamped boolean, time_left_seconds bigint, time_left_label text, is_expired boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_page integer;
  v_page_size integer;
  v_offset integer;
  v_current_game_date date;
begin
  v_page := greatest(coalesce(p_page, 1), 1);

  select stock_policy.visible_rpc_page_size
  into v_page_size
  from public.transfer_market_stock_policy_v1 stock_policy
  where stock_policy.id = true;

  v_page_size := greatest(
    coalesce(v_page_size, 1000),
    1
  );

  v_offset := (v_page - 1) * v_page_size;
  v_current_game_date :=
    public.get_current_game_date_date();

  return query
  select
    listing_row.id as listing_id,
    listing_row.rider_id,
    listing_row.seller_club_id,
    club.name as seller_club_name,

    coalesce(
      nullif(
        trim(
          concat_ws(
            ' ',
            nullif(rider.first_name, ''),
            nullif(rider.last_name, '')
          )
        ),
        ''
      ),
      nullif(rider.display_name, ''),
      rider.id::text
    ) as display_name,

    rider.country_code,
    rider.role,
    public.get_age_years_on_game_date(
      rider.birth_date
    ) as age_years,
    rider.overall,
    rider.potential,
    rider.market_value,
    listing_row.asking_price,
    rider.salary,
    rider.contract_expires_at,
    rider.availability_status::text
      as availability_status,
    listing_row.listed_on_game_date,
    listing_row.expires_on_game_date,
    listing_row.auto_price_clamped,

    public.get_transfer_time_left_seconds(
      listing_row.expires_on_game_date
    ) as time_left_seconds,

    public.get_transfer_time_left_label(
      listing_row.expires_on_game_date
    ) as time_left_label,

    (
      public.get_transfer_time_left_seconds(
        listing_row.expires_on_game_date
      ) <= 0
    ) as is_expired

  from public.rider_transfer_listings listing_row
  join public.riders rider
    on rider.id = listing_row.rider_id
  join public.clubs club
    on club.id = listing_row.seller_club_id
  where listing_row.status = 'listed'
    and club.deleted_at is null
    and listing_row.listed_on_game_date
          <= v_current_game_date
    and (
      listing_row.expires_on_game_date is null
      or listing_row.expires_on_game_date
           >= v_current_game_date
    )
  order by
    listing_row.listed_on_game_date desc,
    listing_row.created_at desc
  offset v_offset
  limit v_page_size;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.clear_rider_asking_price(p_rider_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if not exists (
    select 1
    from public.club_roster cr
    join public.clubs c on c.id = cr.club_id
    where cr.rider_id = p_rider_id
      and c.owner_user_id = auth.uid()
      and c.is_active = true
      and c.deleted_at is null
      and c.club_type in ('main', 'developing')
  ) then
    raise exception 'You do not control this rider.';
  end if;

  update public.riders r
  set
    asking_price = null,
    asking_price_manual = false
  where r.id = p_rider_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_rider_asking_price(p_rider_id uuid, p_asking_price integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.riders
  set
    asking_price = p_asking_price,
    asking_price_manual = true
  where id = p_rider_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pick_generated_rider_first_name(p_country_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_country_code text := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  v_name text;
begin
  if v_country_code is null then
    raise exception 'Cannot generate rider first name without country_code';
  end if;

  select fn.first_name
  into v_name
  from public.first_names_master fn
  where fn.country_code = v_country_code
  order by random()
  limit 1;

  if v_name is null then
    raise exception 'Missing rider first-name master pool for country_code=%', v_country_code;
  end if;

  return v_name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.pick_generated_rider_last_name(p_country_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_country_code text := upper(nullif(btrim(coalesce(p_country_code, '')), ''));
  v_name text;
begin
  if v_country_code is null then
    raise exception 'Cannot generate rider last name without country_code';
  end if;

  select ln.last_name
  into v_name
  from public.last_names_master ln
  where ln.country_code = v_country_code
  order by random()
  limit 1;

  if v_name is null then
    raise exception 'Missing rider last-name master pool for country_code=%', v_country_code;
  end if;

  return v_name;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._create_generated_free_agent_internal(p_desired_tier text, p_expires_in_days integer DEFAULT 14)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_game_date date;
  v_tier text := lower(coalesce(p_desired_tier, ''));

  v_rider_id uuid;
  v_role public.rider_role;
  v_country_code text;
  v_first_name text;
  v_last_name text;
  v_birth_date date;
  v_age integer;
  v_overall smallint;
  v_potential smallint;
  v_salary integer;
  v_min_salary integer;
  v_preferred_duration smallint;
  v_market_value bigint;

  v_sprint smallint;
  v_climbing smallint;
  v_time_trial smallint;
  v_endurance smallint;
  v_flat smallint;
  v_recovery smallint;
  v_resistance smallint;
  v_race_iq smallint;
  v_teamwork smallint;

  v_country_codes text[] := array[
    'IT','ES','FR','DE','NL','BE','PT','PL','CZ','HR',
    'SI','AT','DK','NO','SE','CH','HU','RO','RS','SK'
  ];

  function_rand numeric;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  if v_tier not in ('amateur', 'continental', 'proteam') then
    raise exception 'Unsupported generated free-agent tier: %', p_desired_tier;
  end if;

  v_role := (
    array[
      'Domestique'::public.rider_role,
      'Climber'::public.rider_role,
      'Sprinter'::public.rider_role,
      'TT'::public.rider_role,
      'Breakaway'::public.rider_role,
      'All-rounder'::public.rider_role
    ]
  )[1 + floor(random() * 6)::int];

  v_country_code := v_country_codes[1 + floor(random() * array_length(v_country_codes, 1))::int];
  v_first_name := public.pick_generated_rider_first_name(v_country_code);
  v_last_name := public.pick_generated_rider_last_name(v_country_code);

  function_rand := random();

  if v_tier = 'amateur' then
    if function_rand < 0.20 then
      v_age := 18 + floor(random() * 5)::int;
    elsif function_rand < 0.65 then
      v_age := 23 + floor(random() * 6)::int;
    elsif function_rand < 0.90 then
      v_age := 29 + floor(random() * 5)::int;
    else
      v_age := 34 + floor(random() * 3)::int;
    end if;

    v_birth_date := (v_game_date - make_interval(years => v_age))::date - floor(random() * 365)::int;

    v_overall := (42 + floor(random() * 15))::smallint;
    v_potential := least(70, v_overall + floor(random() * 9)::int)::smallint;

    v_sprint := greatest(35, least(80, v_overall + floor(random() * 9)::int - 4))::smallint;
    v_climbing := greatest(35, least(80, v_overall + floor(random() * 9)::int - 4))::smallint;
    v_time_trial := greatest(35, least(80, v_overall + floor(random() * 9)::int - 4))::smallint;
    v_endurance := greatest(35, least(80, v_overall + floor(random() * 9)::int - 2))::smallint;
    v_flat := greatest(35, least(80, v_overall + floor(random() * 9)::int - 3))::smallint;
    v_recovery := greatest(35, least(80, v_overall + floor(random() * 9)::int - 3))::smallint;
    v_resistance := greatest(35, least(80, v_overall + floor(random() * 9)::int - 2))::smallint;
    v_race_iq := greatest(35, least(80, v_overall + floor(random() * 9)::int - 2))::smallint;
    v_teamwork := greatest(35, least(80, v_overall + floor(random() * 9)::int - 1))::smallint;

    if v_role = 'Sprinter' then
      v_sprint := least(85, v_sprint + 6)::smallint;
      v_flat := least(85, v_flat + 4)::smallint;
    elsif v_role = 'Climber' then
      v_climbing := least(85, v_climbing + 6)::smallint;
      v_recovery := least(85, v_recovery + 3)::smallint;
    elsif v_role = 'TT' then
      v_time_trial := least(85, v_time_trial + 6)::smallint;
      v_endurance := least(85, v_endurance + 3)::smallint;
    elsif v_role = 'Breakaway' then
      v_endurance := least(85, v_endurance + 4)::smallint;
      v_resistance := least(85, v_resistance + 4)::smallint;
    else
      v_teamwork := least(85, v_teamwork + 4)::smallint;
      v_race_iq := least(85, v_race_iq + 3)::smallint;
    end if;

    v_salary := greatest(250, (v_overall * 18) + floor(random() * 120)::int);
    v_min_salary := greatest(100, floor(v_salary * 0.90)::int);
    v_preferred_duration := case when v_age <= 25 and random() < 0.60 then 2 else 1 end;
    v_market_value := greatest(10000, ((v_overall::bigint * v_overall::bigint) * 55) + floor(random() * 5000)::bigint);

  elsif v_tier = 'continental' then
    if function_rand < 0.20 then
      v_age := 20 + floor(random() * 4)::int;
    elsif function_rand < 0.65 then
      v_age := 24 + floor(random() * 5)::int;
    elsif function_rand < 0.90 then
      v_age := 29 + floor(random() * 5)::int;
    else
      v_age := 34 + floor(random() * 2)::int;
    end if;

    v_birth_date := (v_game_date - make_interval(years => v_age))::date - floor(random() * 365)::int;

    v_overall := (50 + floor(random() * 15))::smallint; -- 50..64
    v_potential := least(72, v_overall + floor(random() * 6)::int)::smallint;

    v_sprint := greatest(40, least(82, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_climbing := greatest(40, least(82, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_time_trial := greatest(40, least(82, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_endurance := greatest(40, least(82, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_flat := greatest(40, least(82, v_overall + floor(random() * 8)::int - 3))::smallint;
    v_recovery := greatest(40, least(82, v_overall + floor(random() * 8)::int - 3))::smallint;
    v_resistance := greatest(40, least(82, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_race_iq := greatest(40, least(82, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_teamwork := greatest(40, least(82, v_overall + floor(random() * 8)::int - 1))::smallint;

    if v_role = 'Sprinter' then
      v_sprint := least(84, v_sprint + 6)::smallint;
      v_flat := least(84, v_flat + 4)::smallint;
    elsif v_role = 'Climber' then
      v_climbing := least(84, v_climbing + 6)::smallint;
      v_recovery := least(84, v_recovery + 3)::smallint;
    elsif v_role = 'TT' then
      v_time_trial := least(84, v_time_trial + 6)::smallint;
      v_endurance := least(84, v_endurance + 3)::smallint;
    elsif v_role = 'Breakaway' then
      v_endurance := least(84, v_endurance + 4)::smallint;
      v_resistance := least(84, v_resistance + 4)::smallint;
    else
      v_teamwork := least(84, v_teamwork + 4)::smallint;
      v_race_iq := least(84, v_race_iq + 3)::smallint;
    end if;

    v_salary := greatest(700, (v_overall * 28) + floor(random() * 180)::int);
    v_min_salary := greatest(100, floor(v_salary * 0.90)::int);
    v_preferred_duration := case when v_age <= 25 and random() < 0.60 then 2 else 1 end;
    v_market_value := greatest(40000, ((v_overall::bigint * v_overall::bigint) * 80) + floor(random() * 12000)::bigint);

  else
    if function_rand < 0.15 then
      v_age := 22 + floor(random() * 4)::int;
    elsif function_rand < 0.60 then
      v_age := 25 + floor(random() * 5)::int;
    elsif function_rand < 0.90 then
      v_age := 30 + floor(random() * 4)::int;
    else
      v_age := 34 + floor(random() * 2)::int;
    end if;

    v_birth_date := (v_game_date - make_interval(years => v_age))::date - floor(random() * 365)::int;

    v_overall := (58 + floor(random() * 13))::smallint; -- 58..70
    v_potential := least(76, v_overall + floor(random() * 6)::int)::smallint;

    v_sprint := greatest(46, least(84, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_climbing := greatest(46, least(84, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_time_trial := greatest(46, least(84, v_overall + floor(random() * 8)::int - 4))::smallint;
    v_endurance := greatest(46, least(84, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_flat := greatest(46, least(84, v_overall + floor(random() * 8)::int - 3))::smallint;
    v_recovery := greatest(46, least(84, v_overall + floor(random() * 8)::int - 3))::smallint;
    v_resistance := greatest(46, least(84, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_race_iq := greatest(46, least(84, v_overall + floor(random() * 8)::int - 2))::smallint;
    v_teamwork := greatest(46, least(84, v_overall + floor(random() * 8)::int - 1))::smallint;

    if v_role = 'Sprinter' then
      v_sprint := least(86, v_sprint + 6)::smallint;
      v_flat := least(86, v_flat + 4)::smallint;
    elsif v_role = 'Climber' then
      v_climbing := least(86, v_climbing + 6)::smallint;
      v_recovery := least(86, v_recovery + 3)::smallint;
    elsif v_role = 'TT' then
      v_time_trial := least(86, v_time_trial + 6)::smallint;
      v_endurance := least(86, v_endurance + 3)::smallint;
    elsif v_role = 'Breakaway' then
      v_endurance := least(86, v_endurance + 4)::smallint;
      v_resistance := least(86, v_resistance + 4)::smallint;
    else
      v_teamwork := least(86, v_teamwork + 4)::smallint;
      v_race_iq := least(86, v_race_iq + 3)::smallint;
    end if;

    v_salary := greatest(1400, (v_overall * 40) + floor(random() * 280)::int);
    v_min_salary := greatest(100, floor(v_salary * 0.90)::int);
    v_preferred_duration := case when v_age <= 27 and random() < 0.55 then 2 else 1 end;
    v_market_value := greatest(120000, ((v_overall::bigint * v_overall::bigint) * 120) + floor(random() * 25000)::bigint);
  end if;

  insert into public.riders (
    country_code,
    first_name,
    last_name,
    role,
    sprint,
    climbing,
    time_trial,
    endurance,
    flat,
    recovery,
    resistance,
    race_iq,
    teamwork,
    morale,
    potential,
    birth_date,
    salary,
    release_requested,
    market_value,
    asking_price,
    asking_price_manual,
    asking_price_updated_at,
    fatigue,
    fatigue_updated_on,
    consecutive_heavy_days,
    availability_status
  )
  values (
    v_country_code,
    v_first_name,
    v_last_name,
    v_role,
    v_sprint,
    v_climbing,
    v_time_trial,
    v_endurance,
    v_flat,
    v_recovery,
    v_resistance,
    v_race_iq,
    v_teamwork,
    60,
    v_potential,
    v_birth_date,
    v_salary,
    false,
    v_market_value,
    null,
    false,
    now(),
    0,
    v_game_date,
    0,
    'fit'
  )
  returning id into v_rider_id;

  insert into public.rider_free_agents (
    rider_id,
    source_type,
    source_club_id,
    desired_tier,
    expected_salary_weekly,
    min_acceptable_salary_weekly,
    preferred_duration_seasons,
    available_from_game_date,
    expires_on_game_date,
    status
  )
  values (
    v_rider_id,
    'generated',
    null,
    v_tier,
    v_salary,
    v_min_salary,
    v_preferred_duration,
    v_game_date,
    v_game_date + greatest(coalesce(p_expires_in_days, 14), 1),
    'available'
  );

  return v_rider_id;
end;$function$
;

CREATE OR REPLACE FUNCTION public.release_owned_rider(p_rider_id uuid)
 RETURNS TABLE(free_agent_id uuid, rider_id uuid, released_from_club_id uuid, release_cost bigint, remaining_weeks integer, remaining_salary bigint, expires_on_game_date date, finance_transaction_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid;
  v_main_club_id uuid;
  v_game_date date;

  v_contract public.rider_contracts%rowtype;
  v_listing_id uuid;

  v_season_end date;
  v_days_until_end_of_season integer;
  v_remaining_days integer;
  v_remaining_weeks integer;
  v_remaining_salary bigint;
  v_release_cost bigint;
  v_finance_tx uuid;
  v_idempotency_key text;

  v_market_value bigint;

  v_result_free_agent_id uuid;
  v_result_rider_id uuid;
  v_result_expires_on_game_date date;
begin
  v_uid := auth.uid();

  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_main_club_id := public._get_owned_main_club_id(v_uid);

  if v_main_club_id is null then
    raise exception 'Main club not found';
  end if;

  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = v_main_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider does not belong to your main club';
  end if;

  select rc.*
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.club_id = v_main_club_id
    and rc.status = 'active'
  order by rc.created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'Active rider contract not found';
  end if;

  select l.id
  into v_listing_id
  from public.rider_transfer_listings l
  where l.rider_id = p_rider_id
    and l.status in ('listed', 'active', 'open')
  order by l.created_at desc nulls last, l.listed_on_game_date desc nulls last
  limit 1
  for update;

  if v_listing_id is not null then
    raise exception 'Rider is currently on the transfer list. Cancel the transfer listing before releasing him';
  end if;

  begin
    select public.calculate_rider_market_value(p_rider_id)::bigint
    into v_market_value;
  exception
    when others then
      v_market_value := null;
  end;

  v_remaining_days :=
    greatest(0, coalesce(v_contract.expires_on, v_game_date) - v_game_date);

  v_remaining_weeks :=
    case
      when v_remaining_days <= 0 then 0
      else ceil(v_remaining_days / 7.0)::integer
    end;

  v_remaining_salary :=
    coalesce(v_contract.salary_weekly, 0)::bigint * v_remaining_weeks::bigint;

  v_release_cost :=
    ceil(v_remaining_salary::numeric * 0.20)::bigint;

  begin
    if v_release_cost > 0 then
      v_idempotency_key :=
        format('release-rider:%s:%s:%s', v_main_club_id, p_rider_id, v_game_date);

      v_finance_tx := public.finance_spend_from_club(
        p_club_id => v_main_club_id,
        p_amount => v_release_cost,
        p_type => 'rider_release_compensation',
        p_sink_code => 'SINK',
        p_idempotency_key => v_idempotency_key,
        p_metadata => jsonb_build_object(
          'rider_id', p_rider_id,
          'contract_id', v_contract.id,
          'salary_weekly', v_contract.salary_weekly,
          'contract_expires_on', v_contract.expires_on,
          'remaining_weeks', v_remaining_weeks,
          'remaining_salary', v_remaining_salary,
          'release_cost', v_release_cost,
          'paid_to_rider_pct', 20
        )
      );
    else
      v_finance_tx := null;
    end if;
  exception
    when others then
      raise exception 'release_owned_rider.finance_spend_from_club failed: [%] %', SQLSTATE, SQLERRM;
  end;

  v_season_end :=
    public.get_game_date_for_season_end(public.season_from_game_date(v_game_date));

  if v_season_end is null then
    raise exception 'Season end date is not available';
  end if;

  v_days_until_end_of_season :=
    greatest(1, v_season_end - v_game_date);

  begin
    select
      fa.free_agent_id,
      fa.rider_id,
      fa.expires_on_game_date
    into
      v_result_free_agent_id,
      v_result_rider_id,
      v_result_expires_on_game_date
    from public.release_rider_to_free_agents(
      p_rider_id => p_rider_id,
      p_expires_in_days => v_days_until_end_of_season
    ) fa
    limit 1;
  exception
    when others then
      raise exception 'release_owned_rider.release_rider_to_free_agents failed: [%] %', SQLSTATE, SQLERRM;
  end;

  perform public.create_rider_released_to_free_agents_notification(
    p_rider_id => p_rider_id,
    p_club_id => v_main_club_id,
    p_free_agent_id => v_result_free_agent_id,
    p_release_game_date => v_game_date,
    p_release_cost => v_release_cost,
    p_salary_weekly => v_contract.salary_weekly::bigint,
    p_market_value => v_market_value
  );

  return query
  select
    v_result_free_agent_id,
    v_result_rider_id,
    v_main_club_id,
    v_release_cost,
    v_remaining_weeks,
    v_remaining_salary,
    v_result_expires_on_game_date,
    v_finance_tx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_free_agent_maintenance(p_amateur_target integer DEFAULT 30, p_continental_target integer DEFAULT 18, p_proteam_target integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;

  v_expired_free_agent_count integer := 0;
  v_expired_negotiation_count integer := 0;

  v_deleted_free_agents integer := 0;
  v_deleted_riders integer := 0;

  v_created_count integer := 0;
  v_amateur_created integer := 0;
  v_continental_created integer := 0;
  v_proteam_created integer := 0;

  v_result jsonb;
begin
  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  -- idempotency guard: run once per game day only
  if exists (
    select 1
    from public.free_agent_daily_maintenance_log l
    where l.game_date = v_game_date
  ) then
    return jsonb_build_object(
      'ok', true,
      'did_run', false,
      'reason', 'already_processed',
      'game_date', v_game_date
    );
  end if;

  -- 1) expire outdated free-agent market state
  select
    x.expired_free_agent_count,
    x.expired_negotiation_count
  into
    v_expired_free_agent_count,
    v_expired_negotiation_count
  from public.expire_rider_free_agent_market_state() x;

  -- 2) physically clean up expired generated riders that are safe to delete
  select
    x.deleted_free_agents,
    x.deleted_riders
  into
    v_deleted_free_agents,
    v_deleted_riders
  from public.cleanup_expired_generated_free_agents() x;

  -- 3) refill pool to target counts
  select
    x.created_count,
    x.amateur_created,
    x.continental_created,
    x.proteam_created
  into
    v_created_count,
    v_amateur_created,
    v_continental_created,
    v_proteam_created
  from public.seed_generated_free_agent_pool(
    p_amateur_target,
    p_continental_target,
    p_proteam_target
  ) x;

  v_result := jsonb_build_object(
    'ok', true,
    'did_run', true,
    'game_date', v_game_date,
    'expired_free_agents', v_expired_free_agent_count,
    'expired_negotiations', v_expired_negotiation_count,
    'deleted_generated_free_agents', v_deleted_free_agents,
    'deleted_generated_riders', v_deleted_riders,
    'created_total', v_created_count,
    'created_amateur', v_amateur_created,
    'created_continental', v_continental_created,
    'created_proteam', v_proteam_created,
    'targets', jsonb_build_object(
      'amateur', p_amateur_target,
      'continental', p_continental_target,
      'proteam', p_proteam_target
    )
  );

  insert into public.free_agent_daily_maintenance_log (
    game_date,
    ran_at,
    result
  )
  values (
    v_game_date,
    now(),
    v_result
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_hourly_free_agent_maintenance_unlimited()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_date date;
  v_season integer;
  v_month smallint;
  v_day smallint;
  v_hour smallint;

  v_hour_key text;
  v_last_key text;

  -- minimum 5 per in-game hour
  -- distribution: 3 amateur, 1 continental, 1 proteam
  v_create_amateur integer := 3;
  v_create_continental integer := 1;
  v_create_proteam integer := 1;

  v_existing_amateur integer := 0;
  v_existing_continental integer := 0;
  v_existing_proteam integer := 0;

  v_expired record;
  v_cleanup record;
  v_created record;
begin
  select
    gs.season_number,
    gs.month_number,
    gs.day_number,
    gs.hour_number
  into
    v_season,
    v_month,
    v_day,
    v_hour
  from public.game_state gs
  where gs.id = true;

  if v_season is null then
    raise exception 'game_state is not initialized';
  end if;

  v_game_date := public.get_current_game_date_date();
  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  v_hour_key := format('s%sm%sd%sh%s', v_season, v_month, v_day, v_hour);

  select g.last_game_key
  into v_last_key
  from public.game_job_runtime_guard g
  where g.job_name = 'free_agent_maintenance_unlimited_hourly';

  if v_last_key = v_hour_key then
    return jsonb_build_object(
      'ok', true,
      'mode', 'unlimited_generated_hourly_trickle',
      'reason', 'already_processed',
      'did_run', false,
      'game_date', v_game_date,
      'game_hour', v_hour,
      'hourly_create', jsonb_build_object(
        'amateur', v_create_amateur,
        'continental', v_create_continental,
        'proteam', v_create_proteam
      )
    );
  end if;

  select *
  into v_expired
  from public.expire_rider_free_agent_market_state();

  select *
  into v_cleanup
  from public.cleanup_expired_generated_free_agents();

  select count(*) into v_existing_amateur
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'amateur';

  select count(*) into v_existing_continental
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'continental';

  select count(*) into v_existing_proteam
  from public.rider_free_agents fa
  where fa.source_type = 'generated'
    and fa.status = 'available'
    and fa.desired_tier = 'proteam';

  select *
  into v_created
  from public.seed_generated_free_agent_pool(
    v_existing_amateur + v_create_amateur,
    v_existing_continental + v_create_continental,
    v_existing_proteam + v_create_proteam
  );

  insert into public.game_job_runtime_guard (
    job_name,
    last_game_key,
    updated_at
  )
  values (
    'free_agent_maintenance_unlimited_hourly',
    v_hour_key,
    now()
  )
  on conflict (job_name) do update
  set
    last_game_key = excluded.last_game_key,
    updated_at = excluded.updated_at;

  return jsonb_build_object(
    'ok', true,
    'mode', 'unlimited_generated_hourly_trickle',
    'did_run', true,
    'game_date', v_game_date,
    'game_hour', v_hour,
    'hourly_create', jsonb_build_object(
      'amateur', v_create_amateur,
      'continental', v_create_continental,
      'proteam', v_create_proteam
    ),
    'created_total', coalesce(v_created.created_count, 0),
    'created_amateur', coalesce(v_created.amateur_created, 0),
    'created_continental', coalesce(v_created.continental_created, 0),
    'created_proteam', coalesce(v_created.proteam_created, 0),
    'expired_free_agents', coalesce(v_expired.expired_free_agent_count, 0),
    'expired_negotiations', coalesce(v_expired.expired_negotiation_count, 0),
    'deleted_generated_riders', coalesce(v_cleanup.deleted_riders, 0),
    'deleted_generated_free_agents', coalesce(v_cleanup.deleted_free_agents, 0)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_free_agent_maintenance_unlimited()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.run_hourly_free_agent_maintenance_unlimited();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_hourly_market_ai_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_date date;
  v_season integer;
  v_month smallint;
  v_day smallint;
  v_hour smallint;
  v_paused boolean;
  v_hour_key text;
  v_last_key text;
  v_sellers record;
  v_offer_reviews record;
  v_buyers record;
  v_transfer_contracts record;
  v_fa_buyers record;
  v_fa_signings record;
begin
  select
    gs.season_number,
    gs.month_number,
    gs.day_number,
    gs.hour_number,
    gs.is_paused
  into
    v_season,
    v_month,
    v_day,
    v_hour,
    v_paused
  from public.game_state gs
  where gs.id = true;

  if v_season is null then
    raise exception 'game_state is not initialized';
  end if;

  if coalesce(v_paused, false) then
    return jsonb_build_object(
      'ok', true,
      'did_run', false,
      'reason', 'game_paused'
    );
  end if;

  v_game_date := public.get_current_game_date_date();

  if v_game_date is null then
    raise exception 'Current game date not available';
  end if;

  v_hour_key := format('s%sm%sd%sh%s', v_season, v_month, v_day, v_hour);

  select g.last_game_key
  into v_last_key
  from public.game_job_runtime_guard g
  where g.job_name = 'market_ai_hourly';

  if v_last_key = v_hour_key then
    return jsonb_build_object(
      'ok', true,
      'did_run', false,
      'reason', 'already_processed',
      'mode', 'hourly_market_ai',
      'game_date', v_game_date,
      'game_hour', v_hour
    );
  end if;

  select * into v_sellers from public.run_ai_transfer_seller_job();
  select * into v_offer_reviews from public.run_ai_transfer_offer_review_job();
  select * into v_buyers from public.run_ai_transfer_buyer_job();
  select * into v_transfer_contracts from public.run_ai_transfer_contract_offer_job();
  select * into v_fa_buyers from public.run_ai_free_agent_buyer_job();
  select * into v_fa_signings from public.run_ai_free_agent_signing_job();

  insert into public.game_job_runtime_guard (job_name, last_game_key, updated_at)
  values ('market_ai_hourly', v_hour_key, now())
  on conflict (job_name) do update
  set last_game_key = excluded.last_game_key,
      updated_at = excluded.updated_at;

  return jsonb_build_object(
    'ok', true,
    'did_run', true,
    'mode', 'hourly_market_ai',
    'game_date', v_game_date,
    'game_hour', v_hour,
    'ai_seller', jsonb_build_object(
      'clubs_reviewed', coalesce(v_sellers.clubs_reviewed, 0),
      'listings_created', coalesce(v_sellers.listings_created, 0),
      'skipped_count', coalesce(v_sellers.skipped_count, 0)
    ),
    'ai_seller_offer_reviews', jsonb_build_object(
      'clubs_reviewed', coalesce(v_offer_reviews.clubs_reviewed, 0),
      'offers_accepted', coalesce(v_offer_reviews.offers_accepted, 0),
      'offers_rejected', coalesce(v_offer_reviews.offers_rejected, 0),
      'skipped_count', coalesce(v_offer_reviews.skipped_count, 0)
    ),
    'ai_transfer_buyer', jsonb_build_object(
      'clubs_reviewed', coalesce(v_buyers.clubs_reviewed, 0),
      'offers_created', coalesce(v_buyers.offers_created, 0),
      'skipped_count', coalesce(v_buyers.skipped_count, 0)
    ),
    'ai_transfer_contracts', jsonb_build_object(
      'clubs_reviewed', coalesce(v_transfer_contracts.clubs_reviewed, 0),
      'terms_submitted', coalesce(v_transfer_contracts.terms_submitted, 0),
      'skipped_count', coalesce(v_transfer_contracts.skipped_count, 0)
    ),
    'ai_free_agent_buyer', jsonb_build_object(
      'clubs_reviewed', coalesce(v_fa_buyers.clubs_reviewed, 0),
      'offers_created', coalesce(v_fa_buyers.offers_created, 0),
      'skipped_count', coalesce(v_fa_buyers.skipped_count, 0)
    ),
    'ai_free_agent_signings', jsonb_build_object(
      'clubs_reviewed', coalesce(v_fa_signings.clubs_reviewed, 0),
      'signings_completed', coalesce(v_fa_signings.signings_completed, 0),
      'skipped_count', coalesce(v_fa_signings.skipped_count, 0)
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rider_release_preview(p_rider_id uuid)
 RETURNS TABLE(rider_id uuid, main_club_id uuid, weekly_salary bigint, contract_expires_on date, remaining_days integer, remaining_weeks integer, remaining_salary bigint, release_cost bigint, transfer_listed boolean, transfer_listing_id uuid, blocked_reason text, season_end_game_date date, free_agent_expires_on_game_date date, current_balance bigint, balance_after_release bigint, can_afford boolean, can_release boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_uid uuid;
  v_main_club_id uuid;
  v_game_date date;
  v_contract public.rider_contracts%rowtype;
  v_listing_id uuid;
  v_season_end date;
  v_remaining_days integer;
  v_remaining_weeks integer;
  v_remaining_salary bigint;
  v_release_cost bigint;
  v_current_balance bigint;
  v_blocked_reason text;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  v_main_club_id := public._get_owned_main_club_id(v_uid);
  if v_main_club_id is null then
    raise exception 'Main club not found';
  end if;

  v_game_date := public.get_current_game_date_date();
  if v_game_date is null then
    raise exception 'Game date is not available';
  end if;

  if not exists (
    select 1
    from public.club_riders cr
    where cr.club_id = v_main_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Rider does not belong to your main club';
  end if;

  select *
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.club_id = v_main_club_id
    and rc.status = 'active'
  order by rc.created_at desc
  limit 1;

  if not found then
    raise exception 'Active rider contract not found';
  end if;

  select l.id
  into v_listing_id
  from public.rider_transfer_listings l
  where l.rider_id = p_rider_id
    and l.status in ('listed', 'active', 'open')
  order by l.created_at desc nulls last, l.listed_on_game_date desc nulls last
  limit 1;

  v_remaining_days :=
    greatest(0, coalesce(v_contract.expires_on, v_game_date) - v_game_date);

  v_remaining_weeks :=
    case
      when v_remaining_days <= 0 then 0
      else ceil(v_remaining_days / 7.0)::integer
    end;

  v_remaining_salary :=
    coalesce(v_contract.salary_weekly, 0)::bigint * v_remaining_weeks::bigint;

  v_release_cost :=
    ceil(v_remaining_salary::numeric * 0.20)::bigint;

  v_season_end :=
    public.get_game_date_for_season_end(public.season_from_game_date(v_game_date));

  if v_season_end is null then
    raise exception 'Season end date is not available';
  end if;

  select coalesce(cfs.current_balance, 0)::bigint
  into v_current_balance
  from public.club_finance_summary cfs
  where cfs.club_id = v_main_club_id;

  v_blocked_reason :=
    case
      when v_listing_id is not null then
        'This rider is currently on the transfer list. Cancel the transfer listing before releasing him.'
      when coalesce(v_current_balance, 0) < v_release_cost then
        'Your club does not have enough balance to pay the release compensation.'
      else null
    end;

  return query
  select
    p_rider_id,
    v_main_club_id,
    coalesce(v_contract.salary_weekly, 0)::bigint,
    v_contract.expires_on,
    v_remaining_days,
    v_remaining_weeks,
    v_remaining_salary,
    v_release_cost,
    (v_listing_id is not null),
    v_listing_id,
    v_blocked_reason,
    v_season_end,
    v_season_end,
    coalesce(v_current_balance, 0)::bigint,
    (coalesce(v_current_balance, 0) - v_release_cost)::bigint,
    (coalesce(v_current_balance, 0) >= v_release_cost),
    (v_blocked_reason is null);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_set_market_status_changed_at_game_ts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status_changed_at_game_ts is null then
      new.status_changed_at_game_ts := public.get_current_game_timestamp();
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    new.status_changed_at_game_ts := public.get_current_game_timestamp();
  elsif new.status_changed_at_game_ts is null then
    new.status_changed_at_game_ts := coalesce(
      old.status_changed_at_game_ts,
      public.get_current_game_timestamp()
    );
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._stamp_rider_transfer_offer_game_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.status_changed_at_game_at is null then
      new.status_changed_at_game_at := public._get_current_game_clock_ts();
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    new.status_changed_at_game_at := public._get_current_game_clock_ts();
  elsif new.status_changed_at_game_at is null then
    new.status_changed_at_game_at := public._get_current_game_clock_ts();
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.withdraw_rider_transfer_offer(p_offer_id uuid)
 RETURNS TABLE(offer_id uuid, offer_status text, listing_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_buyer_club_id uuid;
  v_offer public.rider_transfer_offers%rowtype;
  v_listing public.rider_transfer_listings%rowtype;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  v_buyer_club_id := public._get_owned_main_club_id(v_user_id);

  select *
  into v_offer
  from public.rider_transfer_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception 'Offer not found';
  end if;

  if v_offer.buyer_club_id <> v_buyer_club_id then
    raise exception 'You cannot cancel this offer';
  end if;

  if v_offer.status <> 'open' then
    raise exception 'Only open offers can be cancelled';
  end if;

  select *
  into v_listing
  from public.rider_transfer_listings
  where id = v_offer.listing_id
  for update;

  update public.rider_transfer_offers
  set
    status = 'withdrawn',
    auto_block_reason = 'withdrawn_by_buyer',
    updated_at = now()
  where id = p_offer_id;

  if v_listing.id is not null and v_listing.status = 'listed' then
    update public.rider_transfer_listings
    set
      updated_at = now()
    where id = v_listing.id;
  end if;

  return query
  select
    v_offer.id,
    'withdrawn'::text,
    coalesce(v_listing.status, 'listed')::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_sent_transfer_offers_dashboard()
 RETURNS TABLE(id uuid, listing_id uuid, rider_id uuid, seller_club_id uuid, buyer_club_id uuid, seller_club_name text, offered_price bigint, offered_on_game_date text, expires_on_game_date text, status text, auto_block_reason text, metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, status_changed_at_game_ts text, first_name text, last_name text, full_name text, display_name text, country_code text, role text, overall integer, potential integer, age_years integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_buyer_club_id uuid;
  v_current_game_ts timestamp without time zone;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  v_buyer_club_id := public._get_owned_main_club_id(v_user_id);
  v_current_game_ts := public._get_current_game_clock_ts();

  return query
  select
    o.id::uuid,
    o.listing_id::uuid,
    o.rider_id::uuid,
    o.seller_club_id::uuid,
    o.buyer_club_id::uuid,
    c.name::text as seller_club_name,
    o.offered_price::bigint,
    o.offered_on_game_date::text,
    o.expires_on_game_date::text,
    o.status::text,
    o.auto_block_reason::text,
    o.metadata::jsonb,
    o.created_at::timestamptz,
    o.updated_at::timestamptz,
    o.status_changed_at_game_at::text as status_changed_at_game_ts,
    r.first_name::text,
    r.last_name::text,
    nullif(trim(concat_ws(' ', r.first_name, r.last_name)), '')::text as full_name,
    r.display_name::text,
    r.country_code::text,
    r.role::text,
    r.overall::integer,
    r.potential::integer,
    case
      when r.birth_date is null then null
      else extract(year from age(v_current_game_ts::date, r.birth_date::date))::integer
    end::integer as age_years
  from public.rider_transfer_offers o
  join public.riders r
    on r.id = o.rider_id
  left join public.clubs c
    on c.id = o.seller_club_id
  where o.buyer_club_id = v_buyer_club_id
    and (
      o.status in ('open', 'club_accepted')
      or (
        o.status not in ('open', 'club_accepted')
        and o.status_changed_at_game_at is not null
        and o.status_changed_at_game_at >= (v_current_game_ts - interval '24 hours')
      )
    )
  order by
    case when o.status in ('open', 'club_accepted') then 0 else 1 end,
    o.status_changed_at_game_at desc nulls last,
    o.created_at desc;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_game_notification_for_user_checked(p_user_id uuid, p_type_code text, p_title text, p_message text, p_action_url text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_created_by_user_id uuid DEFAULT NULL::uuid, p_expires_at timestamp without time zone DEFAULT NULL::timestamp without time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_id text;
begin
  if p_user_id is null then raise exception 'Target user is required'; end if;
  v_code:=public.notification_canonical_type_code_v2(p_type_code);
  if v_code is null then return null; end if;
  v_id:=public.create_user_game_notification_v1(p_user_id,v_code,p_title,p_message,p_action_url,p_payload_json,null,p_expires_at at time zone 'UTC');
  return nullif(v_id,'')::bigint;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_game_notification_for_user(p_user_id uuid, p_type_code text, p_title text, p_message text, p_action_url text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb, p_created_by_user_id uuid DEFAULT NULL::uuid, p_expires_at timestamp without time zone DEFAULT NULL::timestamp without time zone)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type_id bigint;
  v_preference_group text;
  v_notification_id bigint;
  v_enabled boolean := true;
  v_report_code text;
begin
  if p_user_id is null then
    raise exception 'Target user is required';
  end if;

  select nt.id, nt.preference_group
  into v_type_id, v_preference_group
  from public.notification_types nt
  where nt.code = p_type_code
    and nt.is_active = true
  limit 1;

  if v_type_id is null then
    raise exception 'Notification type not found or inactive: %', p_type_code;
  end if;

  -- Normal Core/system preference logic remains unchanged.
  -- Staff Advisory is handled by exact report-code mute state below.
  if coalesce(v_preference_group, '') <> 'staffAdvisory'
     and v_preference_group is not null
     and to_regclass('public.user_notification_preferences') is not null then
    begin
      select coalesce(unp.is_enabled, true)
      into v_enabled
      from public.user_notification_preferences unp
      where unp.user_id = p_user_id
        and unp.preference_group = v_preference_group
      limit 1;

      v_enabled := coalesce(v_enabled, true);
    exception
      when undefined_table or undefined_column then
        v_enabled := true;
    end;
  else
    v_enabled := true;
  end if;

  if not v_enabled then
    return null;
  end if;

  if v_preference_group = 'staffAdvisory' then
    v_report_code := lower(
      btrim(coalesce(p_payload_json->>'report_code', ''))
    );

    if v_report_code <> ''
       and public.is_staff_advisory_notification_muted_v1(
         p_user_id,
         v_report_code
       )
    then
      return null;
    end if;
  end if;

  insert into public.notifications (
    type_id,
    title,
    message,
    source,
    created_by_user_id,
    action_url,
    payload_json,
    expires_at,
    created_at
  )
  values (
    v_type_id,
    p_title,
    p_message,
    'game',
    p_created_by_user_id,
    p_action_url,
    coalesce(p_payload_json, '{}'::jsonb),
    p_expires_at,
    now()
  )
  returning id into v_notification_id;

  insert into public.user_notifications (
    user_id,
    notification_id,
    status,
    read_at,
    deleted_at,
    created_at
  )
  values (
    p_user_id,
    v_notification_id,
    'unread',
    null,
    null,
    now()
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_transfer_notification(p_user_id uuid, p_type_code text, p_title text, p_message text, p_offer_id uuid DEFAULT NULL::uuid, p_listing_id uuid DEFAULT NULL::uuid, p_negotiation_id uuid DEFAULT NULL::uuid, p_rider_id uuid DEFAULT NULL::uuid, p_action_url text DEFAULT NULL::text, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_notification_id bigint;
begin
  v_notification_id := public.create_game_notification_for_user(
    p_user_id => p_user_id,
    p_type_code => p_type_code,
    p_title => p_title,
    p_message => p_message,
    p_action_url => p_action_url,
    p_payload_json => coalesce(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'offer_id', p_offer_id,
        'listing_id', p_listing_id,
        'negotiation_id', p_negotiation_id,
        'rider_id', p_rider_id
      )
  );

  return v_notification_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_rider_transfer_offer(p_listing_id uuid, p_buyer_club_id uuid, p_offered_price bigint)
 RETURNS TABLE(id uuid, listing_id uuid, rider_id uuid, seller_club_id uuid, buyer_club_id uuid, offered_price bigint, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_listing public.rider_transfer_listings%rowtype;
  v_offer public.rider_transfer_offers%rowtype;
  v_negotiation public.rider_transfer_negotiations%rowtype;
  v_start record;
  v_now_game_date date;
  v_negotiation_id uuid := null;

  v_seller_owner_user_id public.clubs.owner_user_id%type;
  v_buyer_owner_user_id public.clubs.owner_user_id%type;
  v_seller_club_name text;
  v_buyer_club_name text;
  v_rider_name text;

  v_seller_is_ai boolean := false;
  v_rider_market_value bigint := null;
  v_ai_review record;

  v_cash_balance bigint;
  v_reserved_transfer_funds bigint;
  v_available_transfer_funds bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_listing_id is null then
    raise exception 'Transfer listing id is required';
  end if;

  if p_buyer_club_id is null then
    raise exception 'Buyer club id is required';
  end if;

  if p_offered_price is null or p_offered_price <= 0 then
    raise exception 'Offer price must be > 0';
  end if;

  select *
  into v_listing
  from public.rider_transfer_listings l
  where l.id = p_listing_id
  for update;

  if not found then
    raise exception 'Transfer listing not found';
  end if;

  if v_listing.status <> 'listed' then
    raise exception 'Listing is not active';
  end if;

  v_now_game_date := public.get_current_game_date_date();

  if v_now_game_date is null then
    raise exception 'Current game date not available';
  end if;

  if v_listing.expires_on_game_date is not null
     and v_now_game_date > v_listing.expires_on_game_date then
    update public.rider_transfer_listings l
    set status = 'expired'
    where l.id = v_listing.id
      and l.status = 'listed';

    update public.riders r
    set release_requested = false
    where r.id = v_listing.rider_id;

    perform public.log_rider_transfer_event(
      p_event_type      => 'listing_expired',
      p_rider_id        => v_listing.rider_id,
      p_listing_id      => v_listing.id,
      p_seller_club_id  => v_listing.seller_club_id,
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'reason', 'listing_expired_before_offer',
        'source', 'submit_rider_transfer_offer'
      )
    );

    raise exception 'Listing has expired';
  end if;

  if v_listing.seller_club_id = p_buyer_club_id then
    raise exception 'Seller club cannot bid on its own rider';
  end if;

  if not (
    exists (
      select 1
      from public.clubs c
      where c.id = p_buyer_club_id
        and c.owner_user_id = auth.uid()
    )
    or exists (
      select 1
      from public.club_memberships cm
      where cm.club_id = p_buyer_club_id
        and cm.user_id = auth.uid()
    )
  ) then
    raise exception 'Not allowed to bid from this club';
  end if;

  if exists (
    select 1
    from public.club_riders cr
    where cr.club_id = p_buyer_club_id
      and cr.rider_id = v_listing.rider_id
  ) then
    raise exception 'Buyer club already has this rider';
  end if;

  -- price blockade removed intentionally; only > 0 check remains

  if exists (
    select 1
    from public.rider_transfer_offers rto
    where rto.listing_id = v_listing.id
      and rto.buyer_club_id = p_buyer_club_id
      and rto.status = 'open'
  ) then
    raise exception 'An open offer from this club already exists for this listing';
  end if;

  select c.cash_balance::bigint
  into v_cash_balance
  from public.clubs c
  where c.id = p_buyer_club_id;

  select coalesce(sum(o.offered_price), 0)::bigint
  into v_reserved_transfer_funds
  from public.rider_transfer_offers o
  where o.buyer_club_id = p_buyer_club_id
    and o.status in ('open', 'club_accepted');

  v_available_transfer_funds :=
    greatest(coalesce(v_cash_balance, 0) - coalesce(v_reserved_transfer_funds, 0), 0);

  if p_offered_price > v_available_transfer_funds then
    raise exception
      'Insufficient funds: available %, reserved %, need %',
      public.format_money_us(v_available_transfer_funds::numeric),
      public.format_money_us(coalesce(v_reserved_transfer_funds, 0)::numeric),
      public.format_money_us(p_offered_price::numeric);
  end if;

  insert into public.rider_transfer_offers (
    listing_id,
    rider_id,
    seller_club_id,
    buyer_club_id,
    offered_price,
    offered_on_game_date,
    expires_on_game_date,
    status,
    metadata
  )
  values (
    v_listing.id,
    v_listing.rider_id,
    v_listing.seller_club_id,
    p_buyer_club_id,
    p_offered_price,
    v_now_game_date,
    case
      when v_listing.expires_on_game_date is null then v_now_game_date + 1
      else least(v_now_game_date + 1, v_listing.expires_on_game_date)
    end,
    'open',
    jsonb_build_object(
      'submitted_by', auth.uid(),
      'submitted_at', now(),
      'source', 'submit_rider_transfer_offer'
    )
  )
  returning *
  into v_offer;

  select
    c.owner_user_id,
    c.is_ai,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_seller_owner_user_id,
    v_seller_is_ai,
    v_seller_club_name
  from public.clubs c
  where c.id = v_listing.seller_club_id;

  select
    c.owner_user_id,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_buyer_owner_user_id,
    v_buyer_club_name
  from public.clubs c
  where c.id = v_offer.buyer_club_id;

  select
    coalesce(
      nullif(trim(concat_ws(
        ' ',
        nullif(to_jsonb(r)->>'first_name', ''),
        nullif(to_jsonb(r)->>'last_name', '')
      )), ''),
      nullif(trim(concat_ws(
        ' ',
        nullif(to_jsonb(r)->>'rider_first_name', ''),
        nullif(to_jsonb(r)->>'rider_last_name', '')
      )), ''),
      nullif(to_jsonb(r)->>'full_name', ''),
      nullif(to_jsonb(r)->>'display_name', ''),
      nullif(to_jsonb(r)->>'name', ''),
      nullif(to_jsonb(r)->>'rider_name', ''),
      r.id::text
    ),
    r.market_value
  into
    v_rider_name,
    v_rider_market_value
  from public.riders r
  where r.id = v_listing.rider_id;

  v_seller_club_name := coalesce(v_seller_club_name, v_listing.seller_club_id::text);
  v_buyer_club_name := coalesce(v_buyer_club_name, v_offer.buyer_club_id::text);
  v_rider_name := coalesce(v_rider_name, v_listing.rider_id::text);

  begin
    perform public.log_transfer_value_audit(
      p_stage => 'offer_submitted',
      p_offer_id => v_offer.id,
      p_negotiation_id => null,
      p_listing_id => v_listing.id,
      p_rider_id => v_listing.rider_id,
      p_seller_club_id => v_listing.seller_club_id,
      p_buyer_club_id => v_offer.buyer_club_id,
      p_market_value => v_rider_market_value,
      p_transfer_value => v_offer.offered_price,
      p_threshold_ratio => 1.20,
      p_notes => jsonb_build_object(
        'asking_price', v_listing.asking_price,
        'min_allowed_price', v_listing.min_allowed_price,
        'max_allowed_price', v_listing.max_allowed_price,
        'source', 'submit_rider_transfer_offer'
      )
    );
  exception
    when others then
      raise exception 'log_transfer_value_audit failed [%]: %', SQLSTATE, SQLERRM;
  end;

  perform public.log_rider_transfer_event(
    p_event_type      => 'offer_created',
    p_rider_id        => v_offer.rider_id,
    p_listing_id      => v_offer.listing_id,
    p_offer_id        => v_offer.id,
    p_seller_club_id  => v_offer.seller_club_id,
    p_buyer_club_id   => v_offer.buyer_club_id,
    p_actor_user_id   => auth.uid(),
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'offered_price', v_offer.offered_price,
      'expires_on_game_date', v_offer.expires_on_game_date,
      'source', 'submit_rider_transfer_offer'
    )
  );

  if coalesce(v_seller_is_ai, false) then
    begin
      select *
      into v_ai_review
      from public.ai_review_open_transfer_offer(v_offer.id, true)
      limit 1;
    exception
      when others then
        -- do not abort whole offer submission if AI instant review fails
        null;
    end;

    select *
    into v_offer
    from public.rider_transfer_offers o
    where o.id = v_offer.id;

  elsif v_listing.asking_price is not null
     and p_offered_price >= v_listing.asking_price then
    select *
    into v_start
    from public._start_rider_transfer_negotiation_internal(
      p_offer_id => v_offer.id,
      p_accepted_by => auth.uid(),
      p_auto_accepted => true
    );

    v_negotiation_id := v_start.negotiation_id;

    select *
    into v_offer
    from public.rider_transfer_offers o
    where o.id = v_offer.id;

    select *
    into v_negotiation
    from public.rider_transfer_negotiations n
    where n.id = v_negotiation_id;

    if not found then
      raise exception 'Transfer negotiation not found after auto-accept';
    end if;

    perform public.log_rider_transfer_event(
      p_event_type      => 'offer_auto_accepted_by_price',
      p_rider_id        => v_offer.rider_id,
      p_listing_id      => v_offer.listing_id,
      p_offer_id        => v_offer.id,
      p_negotiation_id  => v_negotiation_id,
      p_seller_club_id  => v_offer.seller_club_id,
      p_buyer_club_id   => v_offer.buyer_club_id,
      p_actor_user_id   => auth.uid(),
      p_event_game_date => v_now_game_date,
      p_payload         => jsonb_build_object(
        'offered_price', v_offer.offered_price,
        'asking_price', v_listing.asking_price,
        'status', v_offer.status,
        'source', 'submit_rider_transfer_offer'
      )
    );

    if v_buyer_owner_user_id is not null then
      perform public.create_transfer_notification(
        p_user_id => v_buyer_owner_user_id,
        p_type_code => 'TRANSFER_OFFER_ACCEPTED',
        p_title => 'Transfer offer accepted',
        p_message => format(
          'Your offer of %s for %s was accepted by %s.',
          public.format_money_us(v_offer.offered_price),
          v_rider_name,
          v_seller_club_name
        ),
        p_offer_id => v_offer.id,
        p_listing_id => v_listing.id,
        p_negotiation_id => v_negotiation_id,
        p_rider_id => v_listing.rider_id,
        p_action_url => format('/dashboard/transfers/negotiations/%s', v_negotiation_id),
        p_payload_json => jsonb_build_object(
          'offer_id', v_offer.id,
          'listing_id', v_listing.id,
          'negotiation_id', v_negotiation_id,
          'rider_id', v_listing.rider_id,
          'rider_name', v_rider_name,
          'seller_club_id', v_listing.seller_club_id,
          'seller_club_name', v_seller_club_name,
          'buyer_club_id', v_offer.buyer_club_id,
          'buyer_club_name', v_buyer_club_name,
          'offered_price', v_offer.offered_price,
          'asking_price', v_listing.asking_price,
          'status', 'club_accepted'
        )
      );

      perform public.create_transfer_notification(
        p_user_id => v_buyer_owner_user_id,
        p_type_code => 'RIDER_NEGOTIATION_OPENED',
        p_title => 'Rider negotiation opened',
        p_message => format(
          'Your offer for %s was accepted. Start contract negotiation now.',
          v_rider_name
        ),
        p_offer_id => v_offer.id,
        p_listing_id => v_listing.id,
        p_negotiation_id => v_negotiation_id,
        p_rider_id => v_listing.rider_id,
        p_action_url => format('/dashboard/transfers/negotiations/%s', v_negotiation_id),
        p_payload_json => jsonb_build_object(
          'offer_id', v_offer.id,
          'listing_id', v_listing.id,
          'negotiation_id', v_negotiation_id,
          'rider_id', v_listing.rider_id,
          'rider_name', v_rider_name,
          'seller_club_name', v_seller_club_name,
          'buyer_club_name', v_buyer_club_name,
          'expected_salary_weekly', v_negotiation.expected_salary_weekly,
          'min_acceptable_salary_weekly', v_negotiation.min_acceptable_salary_weekly,
          'preferred_duration_seasons', v_negotiation.preferred_duration_seasons,
          'status', v_negotiation.status
        )
      );
    end if;
  end if;

  if v_seller_owner_user_id is not null then
    perform public.create_transfer_notification(
      p_user_id => v_seller_owner_user_id,
      p_type_code => 'TRANSFER_OFFER_RECEIVED',
      p_title => 'Transfer offer received',
      p_message => case
        when coalesce(v_offer.status, '') = 'club_accepted' then
          format(
            '%s offered %s for %s. The offer met your asking price and was auto-accepted.',
            v_buyer_club_name,
            public.format_money_us(v_offer.offered_price),
            v_rider_name
          )
        else
          format(
            '%s offered %s for %s.',
            v_buyer_club_name,
            public.format_money_us(v_offer.offered_price),
            v_rider_name
          )
      end,
      p_offer_id => v_offer.id,
      p_listing_id => v_listing.id,
      p_negotiation_id => v_negotiation_id,
      p_rider_id => v_listing.rider_id,
      p_action_url => format(
        '/dashboard/transfers?activity=outgoing&offerId=%s',
        v_offer.id
      ),
      p_payload_json => jsonb_build_object(
        'offer_id', v_offer.id,
        'listing_id', v_listing.id,
        'negotiation_id', v_negotiation_id,
        'rider_id', v_listing.rider_id,
        'rider_name', v_rider_name,
        'buyer_club_id', v_offer.buyer_club_id,
        'buyer_club_name', v_buyer_club_name,
        'seller_club_id', v_listing.seller_club_id,
        'seller_club_name', v_seller_club_name,
        'offered_price', v_offer.offered_price,
        'asking_price', v_listing.asking_price,
        'status', v_offer.status,
        'expires_on_game_date', v_offer.expires_on_game_date,
        'offer_path', format(
          '/dashboard/transfers?activity=outgoing&offerId=%s',
          v_offer.id
        ),
        'rider_profile_path', format(
          '/dashboard/my-riders/%s',
          v_listing.rider_id
        )
      )
    );
  end if;

  if v_negotiation_id is not null
     and v_seller_owner_user_id is not null then
    perform public.create_transfer_notification(
      p_user_id => v_seller_owner_user_id,
      p_type_code => 'RIDER_NEGOTIATION_OPENED',
      p_title => 'Rider negotiation started',
      p_message => format(
        '%s has entered contract negotiations with %s.',
        v_rider_name,
        v_buyer_club_name
      ),
      p_offer_id => v_offer.id,
      p_listing_id => v_listing.id,
      p_negotiation_id => v_negotiation_id,
      p_rider_id => v_listing.rider_id,
      p_action_url => format(
        '/dashboard/transfers?activity=outgoing&offerId=%s',
        v_offer.id
      ),
      p_payload_json => jsonb_build_object(
        'offer_id', v_offer.id,
        'listing_id', v_listing.id,
        'negotiation_id', v_negotiation_id,
        'rider_id', v_listing.rider_id,
        'rider_name', v_rider_name,
        'buyer_club_id', v_offer.buyer_club_id,
        'buyer_club_name', v_buyer_club_name,
        'seller_club_id', v_listing.seller_club_id,
        'seller_club_name', v_seller_club_name,
        'offered_price', v_offer.offered_price,
        'asking_price', v_listing.asking_price,
        'status', v_negotiation.status,
        'offer_path', format(
          '/dashboard/transfers?activity=outgoing&offerId=%s',
          v_offer.id
        ),
        'rider_profile_path', format(
          '/dashboard/my-riders/%s',
          v_listing.rider_id
        )
      )
    );
  end if;

  return query
  select
    v_offer.id,
    v_offer.listing_id,
    v_offer.rider_id,
    v_offer.seller_club_id,
    v_offer.buyer_club_id,
    v_offer.offered_price,
    v_offer.status;
end;$function$
;

CREATE OR REPLACE FUNCTION public.log_transfer_value_audit(p_stage text, p_offer_id uuid, p_negotiation_id uuid, p_listing_id uuid, p_rider_id uuid, p_seller_club_id uuid, p_buyer_club_id uuid, p_market_value bigint, p_transfer_value bigint, p_threshold_ratio numeric DEFAULT 1.20, p_notes jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ratio numeric(12,4);
  v_direction text;
begin
  if p_stage not in ('offer_submitted', 'transfer_completed') then
    raise exception 'Invalid transfer audit stage: %', p_stage;
  end if;

  if p_market_value is null or p_market_value <= 0 then
    return;
  end if;

  if p_transfer_value is null or p_transfer_value <= 0 then
    return;
  end if;

  v_ratio := round((p_transfer_value::numeric / p_market_value::numeric), 4);

  -- Current rule: log only when transfer price is more than 20% ABOVE market value.
  -- If you also want to log suspicious under-market deals, add the mirrored low-side branch.
  if v_ratio <= coalesce(p_threshold_ratio, 1.20) then
    return;
  end if;

  v_direction := 'above_market';

  insert into public.transfer_value_audit (
    stage,
    offer_id,
    negotiation_id,
    listing_id,
    rider_id,
    seller_club_id,
    buyer_club_id,
    market_value,
    transfer_value,
    ratio_to_market_value,
    threshold_ratio,
    direction,
    notes
  )
  values (
    p_stage,
    p_offer_id,
    p_negotiation_id,
    p_listing_id,
    p_rider_id,
    p_seller_club_id,
    p_buyer_club_id,
    p_market_value,
    p_transfer_value,
    v_ratio,
    coalesce(p_threshold_ratio, 1.20),
    v_direction,
    coalesce(p_notes, '{}'::jsonb)
  )
  on conflict (stage, offer_id) where offer_id is not null do nothing;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.scan_completed_transfer_value_audit()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer := 0;
  v_row record;
begin
  for v_row in
    select
      o.id as offer_id,
      n.id as negotiation_id,
      o.listing_id,
      o.rider_id,
      o.seller_club_id,
      o.buyer_club_id,
      o.offered_price,
      r.market_value
    from public.rider_transfer_offers o
    left join public.rider_transfer_negotiations n on n.offer_id = o.id
    join public.riders r on r.id = o.rider_id
    where o.status = 'completed'
      and not exists (
        select 1
        from public.transfer_value_audit a
        where a.stage = 'transfer_completed'
          and a.offer_id = o.id
      )
  loop
    perform public.log_transfer_value_audit(
      p_stage => 'transfer_completed',
      p_offer_id => v_row.offer_id,
      p_negotiation_id => v_row.negotiation_id,
      p_listing_id => v_row.listing_id,
      p_rider_id => v_row.rider_id,
      p_seller_club_id => v_row.seller_club_id,
      p_buyer_club_id => v_row.buyer_club_id,
      p_market_value => v_row.market_value,
      p_transfer_value => v_row.offered_price,
      p_threshold_ratio => 1.20,
      p_notes => jsonb_build_object('source', 'scan_completed_transfer_value_audit')
    );

    if found then
      v_count := v_count + 1;
    end if;
  end loop;

  return v_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_reject_rider_transfer_offer(p_offer_id uuid, p_reason text DEFAULT 'ai_seller_rejected'::text)
 RETURNS TABLE(offer_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer record;
  v_game_date date;
begin
  v_game_date := public.get_current_game_date_date();

  update public.rider_transfer_offers o
  set
    status = 'rejected',
    auto_block_reason = coalesce(p_reason, 'ai_seller_rejected'),
    metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
      'ai_rejected_at', now(),
      'ai_reject_reason', coalesce(p_reason, 'ai_seller_rejected')
    )
  where o.id = p_offer_id
    and o.status = 'open'
  returning o.*
  into v_offer;

  if not found then
    return query select p_offer_id, 'no_action'::text;
    return;
  end if;

  perform public.log_rider_transfer_event(
    p_event_type      => 'offer_rejected',
    p_rider_id        => v_offer.rider_id,
    p_listing_id      => v_offer.listing_id,
    p_offer_id        => v_offer.id,
    p_seller_club_id  => v_offer.seller_club_id,
    p_buyer_club_id   => v_offer.buyer_club_id,
    p_event_game_date => v_game_date,
    p_payload         => jsonb_build_object(
      'source', 'ai_seller_review',
      'reason', coalesce(p_reason, 'ai_seller_rejected')
    )
  );

  return query select v_offer.id, 'rejected'::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_accept_rider_transfer_offer(p_offer_id uuid)
 RETURNS TABLE(offer_id uuid, negotiation_id uuid, negotiation_status text, closed_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_start record;
begin
  select *
  into v_start
  from public._start_rider_transfer_negotiation_internal(
    p_offer_id => p_offer_id,
    p_accepted_by => null::uuid,
    p_auto_accepted => true
  )
  limit 1;

  return query
  select
    p_offer_id,
    v_start.negotiation_id,
    v_start.negotiation_status,
    v_start.closed_reason;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.ai_review_open_transfer_offer(p_offer_id uuid, p_instant boolean DEFAULT false)
 RETURNS TABLE(action_taken text, offer_id uuid, listing_id uuid, rider_id uuid, required_price bigint, rider_importance_score numeric, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg record;
  v_offer record;
  v_age integer;
  v_importance_score numeric;
  v_required_ratio numeric;
  v_required_price bigint;
  v_human_premium numeric := 0;
  v_star_premium numeric := 0;
  v_accept_result record;

  v_today date;
  v_ai_ai_daily_limit integer;
  v_ai_ai_progressed_today integer;
begin
  v_today := public.get_current_game_date_date();

  select *
  into v_cfg
  from public.market_ai_config
  where id = true;

  select
    o.id as offer_id,
    o.listing_id,
    o.rider_id,
    o.seller_club_id,
    o.buyer_club_id,
    o.offered_price,
    o.status,
    l.asking_price,
    l.status as listing_status,
    seller.is_ai as seller_is_ai,
    buyer.is_ai as buyer_is_ai,
    r.market_value,
    r.overall,
    r.potential,
    r.morale,
    public.get_age_years_on_game_date(r.birth_date) as age_years
  into v_offer
  from public.rider_transfer_offers o
  join public.rider_transfer_listings l on l.id = o.listing_id
  join public.clubs seller on seller.id = o.seller_club_id
  join public.clubs buyer on buyer.id = o.buyer_club_id
  join public.riders r on r.id = o.rider_id
  where o.id = p_offer_id
  for update;

  if not found then
    return query
    select
      'skipped_missing'::text,
      p_offer_id,
      null::uuid,
      null::uuid,
      null::bigint,
      null::numeric,
      'offer_not_found'::text;
    return;
  end if;

  if coalesce(v_offer.seller_is_ai, false) = false then
    return query
    select
      'skipped_not_ai_seller'::text,
      v_offer.offer_id,
      v_offer.listing_id,
      v_offer.rider_id,
      null::bigint,
      null::numeric,
      'seller_not_ai'::text;
    return;
  end if;

  if v_offer.status <> 'open' or v_offer.listing_status <> 'listed' then
    return query
    select
      'skipped_not_open'::text,
      v_offer.offer_id,
      v_offer.listing_id,
      v_offer.rider_id,
      null::bigint,
      null::numeric,
      'offer_or_listing_not_open'::text;
    return;
  end if;

  v_age := coalesce(v_offer.age_years, 28);

  v_importance_score :=
      coalesce(v_offer.overall, 50) * 0.45
    + coalesce(v_offer.potential, 50) * 0.35
    + coalesce(v_offer.morale, 50) * 0.20
    - greatest(0, v_age - 29) * 1.50;

  if coalesce(v_offer.buyer_is_ai, false) = false then
    v_human_premium := coalesce(v_cfg.transfer_offer_review_human_bid_premium, 0.05);
  end if;

  if v_importance_score >= coalesce(v_cfg.transfer_offer_review_star_score_threshold, 78) then
    v_star_premium := coalesce(v_cfg.transfer_offer_review_star_rider_premium, 0.06);
  elsif v_importance_score >= coalesce(v_cfg.transfer_offer_review_star_score_threshold, 78) - 8 then
    v_star_premium := coalesce(v_cfg.transfer_offer_review_star_rider_premium, 0.06) / 2.0;
  end if;

  v_required_ratio := least(
    0.99,
    greatest(
      0.80,
      coalesce(v_cfg.transfer_offer_review_accept_ratio, 0.93)
        + v_human_premium
        + v_star_premium
    )
  );

  v_required_price := ceil(v_offer.asking_price * v_required_ratio)::bigint;

  -- ============================================================
  -- Helper block used before AI accepts an AI -> AI offer.
  -- This caps AI -> AI transfer progression to max 10 per game date.
  -- It counts both club_accepted and completed because club_accepted
  -- can later become completed.
  -- ============================================================

  if p_instant then
    if v_offer.offered_price >= v_required_price then

      if coalesce(v_offer.buyer_is_ai, false) = true
         and coalesce(v_offer.seller_is_ai, false) = true
      then
        perform pg_catalog.pg_advisory_xact_lock(
          704001,
          to_char(v_today, 'YYYYMMDD')::integer
        );

        v_ai_ai_daily_limit := coalesce(
          v_cfg.transfer_ai_ai_completed_deal_daily_limit,
          10
        );

        select count(*)::integer
        into v_ai_ai_progressed_today
        from public.rider_transfer_offers o
        join public.clubs buyer on buyer.id = o.buyer_club_id
        join public.clubs seller on seller.id = o.seller_club_id
        where buyer.is_ai = true
          and seller.is_ai = true
          and o.status in ('club_accepted', 'completed')
          and coalesce(
            nullif(o.metadata ->> 'ai_ai_deal_progressed_on_game_date', '')::date,
            o.offered_on_game_date::date
          ) = v_today;

        if v_ai_ai_progressed_today >= v_ai_ai_daily_limit then
          update public.rider_transfer_offers o
          set metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
            'ai_review_skip_reason', 'ai_ai_daily_deal_limit_reached',
            'ai_review_skip_game_date', v_today,
            'ai_ai_daily_limit', v_ai_ai_daily_limit,
            'ai_ai_progressed_today', v_ai_ai_progressed_today
          )
          where o.id = v_offer.offer_id;

          return query
          select
            'held_daily_ai_ai_limit'::text,
            v_offer.offer_id,
            v_offer.listing_id,
            v_offer.rider_id,
            v_required_price,
            round(v_importance_score, 2),
            'ai_ai_daily_deal_limit_reached'::text;
          return;
        end if;
      end if;

      select *
      into v_accept_result
      from public.ai_accept_rider_transfer_offer(v_offer.offer_id)
      limit 1;

      if coalesce(v_offer.buyer_is_ai, false) = true
         and coalesce(v_offer.seller_is_ai, false) = true
      then
        update public.rider_transfer_offers o
        set metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
          'ai_ai_deal_progressed_on_game_date', v_today,
          'ai_ai_daily_cap_applied', true
        )
        where o.id = v_offer.offer_id;
      end if;

      return query
      select
        'accepted'::text,
        v_offer.offer_id,
        v_offer.listing_id,
        v_offer.rider_id,
        v_required_price,
        round(v_importance_score, 2),
        'instant_accept'::text;
      return;
    end if;

    return query
    select
      'held_for_review'::text,
      v_offer.offer_id,
      v_offer.listing_id,
      v_offer.rider_id,
      v_required_price,
      round(v_importance_score, 2),
      'await_hourly_review'::text;
    return;
  end if;

  -- Hourly AI seller review path.
  if v_offer.offered_price >= v_required_price then

    if coalesce(v_offer.buyer_is_ai, false) = true
       and coalesce(v_offer.seller_is_ai, false) = true
    then
      perform pg_catalog.pg_advisory_xact_lock(
        704001,
        to_char(v_today, 'YYYYMMDD')::integer
      );

      v_ai_ai_daily_limit := coalesce(
        v_cfg.transfer_ai_ai_completed_deal_daily_limit,
        10
      );

      select count(*)::integer
      into v_ai_ai_progressed_today
      from public.rider_transfer_offers o
      join public.clubs buyer on buyer.id = o.buyer_club_id
      join public.clubs seller on seller.id = o.seller_club_id
      where buyer.is_ai = true
        and seller.is_ai = true
        and o.status in ('club_accepted', 'completed')
        and coalesce(
          nullif(o.metadata ->> 'ai_ai_deal_progressed_on_game_date', '')::date,
          o.offered_on_game_date::date
        ) = v_today;

      if v_ai_ai_progressed_today >= v_ai_ai_daily_limit then
        update public.rider_transfer_offers o
        set metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
          'ai_review_skip_reason', 'ai_ai_daily_deal_limit_reached',
          'ai_review_skip_game_date', v_today,
          'ai_ai_daily_limit', v_ai_ai_daily_limit,
          'ai_ai_progressed_today', v_ai_ai_progressed_today
        )
        where o.id = v_offer.offer_id;

        return query
        select
          'held_daily_ai_ai_limit'::text,
          v_offer.offer_id,
          v_offer.listing_id,
          v_offer.rider_id,
          v_required_price,
          round(v_importance_score, 2),
          'ai_ai_daily_deal_limit_reached'::text;
        return;
      end if;
    end if;

    select *
    into v_accept_result
    from public.ai_accept_rider_transfer_offer(v_offer.offer_id)
    limit 1;

    if coalesce(v_offer.buyer_is_ai, false) = true
       and coalesce(v_offer.seller_is_ai, false) = true
    then
      update public.rider_transfer_offers o
      set metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
        'ai_ai_deal_progressed_on_game_date', v_today,
        'ai_ai_daily_cap_applied', true
      )
      where o.id = v_offer.offer_id;
    end if;

    return query
    select
      'accepted'::text,
      v_offer.offer_id,
      v_offer.listing_id,
      v_offer.rider_id,
      v_required_price,
      round(v_importance_score, 2),
      'meets_required_price'::text;
    return;
  end if;

  perform public.ai_reject_rider_transfer_offer(
    v_offer.offer_id,
    'ai_seller_price_too_low'
  );

  return query
  select
    'rejected'::text,
    v_offer.offer_id,
    v_offer.listing_id,
    v_offer.rider_id,
    v_required_price,
    round(v_importance_score, 2),
    'below_required_price'::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_ai_transfer_offer_review_job()
 RETURNS TABLE(clubs_reviewed integer, offers_accepted integer, offers_rejected integer, skipped_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg record;
  v_reviewed integer := 0;
  v_accepted integer := 0;
  v_rejected integer := 0;
  v_skipped integer := 0;
  v_row record;
  v_offer record;
  v_result record;
begin
  select * into v_cfg from public.market_ai_config where id = true;

  for v_row in
    with eligible_ai_seller_clubs as (
      select distinct c.id
      from public.clubs c
      join public.rider_transfer_offers o
        on o.seller_club_id = c.id
      where c.deleted_at is null
        and c.is_ai = true
        and o.status = 'open'
        and public.market_ai_club_rider_country_eligible_v1(
          o.buyer_club_id,
          o.rider_id
        )
    )
    select id
    from eligible_ai_seller_clubs
    order by random()
    limit coalesce(v_cfg.transfer_offer_review_hourly_limit, 12)
  loop
    v_reviewed := v_reviewed + 1;

    select o.id as offer_id
    into v_offer
    from public.rider_transfer_offers o
    where o.seller_club_id = v_row.id
      and o.status = 'open'
      and public.market_ai_club_rider_country_eligible_v1(
        o.buyer_club_id,
        o.rider_id
      )
    order by o.offered_price desc, o.created_at asc
    limit 1;

    if v_offer.offer_id is null then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    select *
    into v_result
    from public.ai_review_open_transfer_offer(v_offer.offer_id, false)
    limit 1;

    if v_result.action_taken = 'accepted' then
      v_accepted := v_accepted + 1;
    elsif v_result.action_taken = 'rejected' then
      v_rejected := v_rejected + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  return query
  select v_reviewed, v_accepted, v_rejected, v_skipped;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.withdraw_rider_transfer_negotiation(p_negotiation_id uuid)
 RETURNS TABLE(negotiation_id uuid, offer_id uuid, listing_id uuid, negotiation_status text, offer_status text, listing_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_negotiation public.rider_transfer_negotiations%rowtype;
  v_offer public.rider_transfer_offers%rowtype;
  v_listing public.rider_transfer_listings%rowtype;
  v_now_game_date date;

  v_seller_owner_user_id uuid;
  v_buyer_owner_user_id uuid;
  v_seller_club_name text;
  v_buyer_club_name text;
  v_rider_name text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_negotiation_id is null then
    raise exception 'Transfer negotiation id is required';
  end if;

  select *
  into v_negotiation
  from public.rider_transfer_negotiations n
  where n.id = p_negotiation_id
  for update;

  if not found then
    raise exception 'Transfer negotiation not found';
  end if;

  if v_negotiation.status <> 'open' then
    raise exception 'Only open transfer negotiations can be cancelled';
  end if;

  if not (
    exists (
      select 1
      from public.clubs c
      where c.id = v_negotiation.buyer_club_id
        and c.owner_user_id = auth.uid()
    )
    or exists (
      select 1
      from public.club_memberships cm
      where cm.club_id = v_negotiation.buyer_club_id
        and cm.user_id = auth.uid()
    )
  ) then
    raise exception 'Not allowed to cancel this negotiation';
  end if;

  v_now_game_date := public.get_current_game_date_date();

  if v_now_game_date is null then
    raise exception 'Current game date not available';
  end if;

  select *
  into v_offer
  from public.rider_transfer_offers o
  where o.id = v_negotiation.offer_id
  for update;

  if not found then
    raise exception 'Related transfer offer not found';
  end if;

  select *
  into v_listing
  from public.rider_transfer_listings l
  where l.id = v_negotiation.listing_id
  for update;

  if not found then
    raise exception 'Related transfer listing not found';
  end if;

  /*
    Use status = 'declined' so it fits your current frontend logic and any
    existing status constraints. If your DB already supports a dedicated
    'withdrawn' negotiation status, you can change this line.
  */
  update public.rider_transfer_negotiations n
  set
    status = 'declined',
    closed_reason = 'withdrawn_by_buyer',
    locked_until = null,
    notes_json = coalesce(n.notes_json, '{}'::jsonb) || jsonb_build_object(
      'withdrawn_at', now(),
      'withdrawn_by_user_id', auth.uid(),
      'withdrawn_on_game_date', v_now_game_date
    ),
    updated_at = now()
  where n.id = v_negotiation.id
  returning *
  into v_negotiation;

  update public.rider_transfer_offers o
  set
    status = 'withdrawn',
    metadata = coalesce(o.metadata, '{}'::jsonb) || jsonb_build_object(
      'withdrawn_at', now(),
      'withdrawn_by_user_id', auth.uid(),
      'withdrawn_on_game_date', v_now_game_date,
      'withdrawn_from_negotiation_id', v_negotiation.id
    ),
    updated_at = now()
  where o.id = v_offer.id
  returning *
  into v_offer;

  update public.rider_transfer_listings l
  set status = case
    when l.expires_on_game_date is not null and l.expires_on_game_date < v_now_game_date
      then 'expired'
    else 'listed'
  end
  where l.id = v_listing.id
    and l.status = 'club_accepted'
  returning *
  into v_listing;

  if not found then
    select *
    into v_listing
    from public.rider_transfer_listings l
    where l.id = v_offer.listing_id;
  end if;

  if v_listing.status = 'expired' then
    update public.riders r
    set release_requested = false
    where r.id = v_listing.rider_id
      and r.release_requested = true;
  end if;

  select
    c.owner_user_id,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_seller_owner_user_id,
    v_seller_club_name
  from public.clubs c
  where c.id = v_negotiation.seller_club_id;

  select
    c.owner_user_id,
    coalesce(
      to_jsonb(c)->>'name',
      to_jsonb(c)->>'club_name',
      to_jsonb(c)->>'display_name',
      c.id::text
    )
  into
    v_buyer_owner_user_id,
    v_buyer_club_name
  from public.clubs c
  where c.id = v_negotiation.buyer_club_id;

  select
    coalesce(
      nullif(trim(concat_ws(' ', nullif(r.first_name, ''), nullif(r.last_name, ''))), ''),
      nullif(r.display_name, ''),
      r.id::text
    )
  into v_rider_name
  from public.riders r
  where r.id = v_negotiation.rider_id;

  v_seller_club_name := coalesce(v_seller_club_name, v_negotiation.seller_club_id::text);
  v_buyer_club_name := coalesce(v_buyer_club_name, v_negotiation.buyer_club_id::text);
  v_rider_name := coalesce(v_rider_name, v_negotiation.rider_id::text);

  perform public.log_rider_transfer_event(
    p_event_type      => 'negotiation_withdrawn_by_buyer',
    p_rider_id        => v_negotiation.rider_id,
    p_listing_id      => v_negotiation.listing_id,
    p_offer_id        => v_negotiation.offer_id,
    p_negotiation_id  => v_negotiation.id,
    p_seller_club_id  => v_negotiation.seller_club_id,
    p_buyer_club_id   => v_negotiation.buyer_club_id,
    p_actor_user_id   => auth.uid(),
    p_event_game_date => v_now_game_date,
    p_payload         => jsonb_build_object(
      'closed_reason', 'withdrawn_by_buyer',
      'listing_status', v_listing.status,
      'offer_status', v_offer.status
    )
  );

  if v_seller_owner_user_id is not null then
    perform public.create_transfer_notification(
      p_user_id => v_seller_owner_user_id,
      p_type_code => 'TRANSFER_NEGOTIATION_WITHDRAWN',
      p_title => 'Transfer negotiation cancelled',
      p_message => format(
        '%s cancelled contract negotiations for %s.',
        v_buyer_club_name,
        v_rider_name
      ),
      p_offer_id => v_offer.id,
      p_listing_id => v_listing.id,
      p_negotiation_id => v_negotiation.id,
      p_rider_id => v_negotiation.rider_id,
      p_action_url => '/#/dashboard/transfers',
      p_payload_json => jsonb_build_object(
        'offer_id', v_offer.id,
        'listing_id', v_listing.id,
        'negotiation_id', v_negotiation.id,
        'rider_id', v_negotiation.rider_id,
        'rider_name', v_rider_name,
        'seller_club_id', v_negotiation.seller_club_id,
        'seller_club_name', v_seller_club_name,
        'buyer_club_id', v_negotiation.buyer_club_id,
        'buyer_club_name', v_buyer_club_name,
        'offer_status', v_offer.status,
        'negotiation_status', v_negotiation.status,
        'closed_reason', v_negotiation.closed_reason,
        'listing_status', v_listing.status
      )
    );
  end if;

  return query
  select
    v_negotiation.id,
    v_offer.id,
    v_listing.id,
    v_negotiation.status::text,
    v_offer.status::text,
    v_listing.status::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_active_scout_staff()
 RETURNS TABLE(staff_id uuid, club_id uuid, expertise integer, experience integer, efficiency integer, potential integer, leadership integer, loyalty integer, staff_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_club_id uuid;
  v_game_date date;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated.';
  end if;

  v_club_id := public.get_my_primary_club_id();
  if v_club_id is null then
    return;
  end if;

  v_game_date := public.get_current_game_date_date();

  return query
  select
    cs.id as staff_id,
    cs.club_id,
    cs.expertise::integer,
    cs.experience::integer,
    cs.efficiency::integer,
    cs.potential::integer,
    cs.leadership::integer,
    cs.loyalty::integer,
    cs.staff_name::text
  from public.club_staff cs
  where cs.club_id = v_club_id
    and cs.is_active = true
    and cs.role_type = 'scout_analyst'
    and not exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
        and sc.completes_on_game_date >= v_game_date
    )
  order by cs.expertise desc, cs.experience desc, cs.efficiency desc
  limit 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_rider_scouting_usage_today()
 RETURNS TABLE(club_id uuid, game_date date, used_count integer, daily_limit integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_club_id uuid;
  v_game_date date;
  v_used_count integer;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated.';
  end if;

  v_club_id := public.get_my_primary_club_id();
  if v_club_id is null then
    return;
  end if;

  v_game_date := public.get_current_game_date_date();

  select count(*)::integer
  into v_used_count
  from public.rider_scout_reports rsr
  where rsr.club_id = v_club_id
    and rsr.scouted_on_game_date = v_game_date;

  return query
  select
    v_club_id,
    v_game_date,
    coalesce(v_used_count, 0),
    2::integer;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.debug_get_active_scout_staff_for_club(p_club_id uuid)
 RETURNS TABLE(staff_id uuid, club_id uuid, expertise integer, experience integer, efficiency integer, potential integer, leadership integer, loyalty integer, staff_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required.';
  end if;

  v_game_date := public.get_current_game_date_date();

  return query
  select
    cs.id as staff_id,
    cs.club_id,
    cs.expertise::integer,
    cs.experience::integer,
    cs.efficiency::integer,
    cs.potential::integer,
    cs.leadership::integer,
    cs.loyalty::integer,
    cs.staff_name::text
  from public.club_staff cs
  where cs.club_id = p_club_id
    and cs.is_active = true
    and cs.role_type = 'scout_analyst'
    and not exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
        and sc.completes_on_game_date >= v_game_date
    )
  order by cs.expertise desc, cs.experience desc, cs.efficiency desc
  limit 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.debug_get_rider_scouting_usage_for_club(p_club_id uuid, p_game_date date DEFAULT NULL::date)
 RETURNS TABLE(club_id uuid, game_date date, used_count integer, daily_limit integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;
  v_used_count integer;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required.';
  end if;

  v_game_date := coalesce(p_game_date, public.get_current_game_date_date());

  select count(*)::integer
  into v_used_count
  from public.rider_scout_reports rsr
  where rsr.club_id = p_club_id
    and rsr.scouted_on_game_date = v_game_date;

  return query
  select
    p_club_id,
    v_game_date,
    coalesce(v_used_count, 0),
    2::integer;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rider_scout_precision_tier(p_precision_score integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_precision_score is null then
    return 'basic';
  elsif p_precision_score >= 85 then
    return 'elite';
  elsif p_precision_score >= 70 then
    return 'strong';
  elsif p_precision_score >= 55 then
    return 'solid';
  else
    return 'basic';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.build_scout_range_label(p_value integer, p_band_size integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_value integer;
  v_band integer;
  v_start integer;
  v_end integer;
begin
  if p_value is null then
    return '—';
  end if;

  v_value := greatest(0, least(100, p_value));
  v_band := greatest(1, p_band_size);

  v_start := floor(v_value::numeric / v_band) * v_band;
  v_end := least(100, v_start + v_band - 1);

  return v_start::text || '-' || v_end::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_scout_fatigue_label(p_fatigue integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_fatigue is null then
    return 'Unknown';
  elsif p_fatigue < 34 then
    return 'Low';
  elsif p_fatigue < 67 then
    return 'Medium';
  else
    return 'High';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.scout_external_rider(p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_club_id uuid;
  v_game_date date;

  v_scout record;
  v_usage record;
  v_rider record;
  v_owner_club_id uuid;

  v_precision_score integer;
  v_precision_tier text;

  v_band_size integer;
  v_potential_band_size integer;

  v_report jsonb;
  v_inserted_id uuid;
  v_remaining integer;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated.';
  end if;

  if p_rider_id is null then
    raise exception 'p_rider_id is required.';
  end if;

  v_club_id := public.get_my_primary_club_id();
  if v_club_id is null then
    raise exception 'Your primary club could not be resolved.';
  end if;

  v_game_date := public.get_current_game_date_date();

  select *
  into v_scout
  from public.get_my_active_scout_staff();

  if v_scout.staff_id is null then
    raise exception 'Hire an active Scout / Analyst first.';
  end if;

  select *
  into v_usage
  from public.get_my_rider_scouting_usage_today();

  if coalesce(v_usage.used_count, 0) >= coalesce(v_usage.daily_limit, 2) then
    raise exception 'Daily scouting limit reached.';
  end if;

  select
    r.id,
    r.first_name,
    r.last_name,
    r.display_name,
    r.role,
    r.sprint,
    r.climbing,
    r.time_trial,
    r.endurance,
    r.flat,
    r.recovery,
    r.resistance,
    r.race_iq,
    r.teamwork,
    r.morale,
    r.potential,
    r.fatigue,
    r.overall,
    r.availability_status,
    r.unavailable_until,
    r.unavailable_reason
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if v_rider.id is null then
    raise exception 'Rider not found.';
  end if;

  select cr.club_id
  into v_owner_club_id
  from public.club_riders cr
  where cr.rider_id = p_rider_id
  order by cr.created_at desc
  limit 1;

  if v_owner_club_id = v_club_id then
    raise exception 'You cannot scout your own rider.';
  end if;

  v_precision_score :=
    greatest(
      0,
      least(
        100,
        round(
          coalesce(v_scout.expertise, 0) * 0.50 +
          coalesce(v_scout.experience, 0) * 0.35 +
          coalesce(v_scout.efficiency, 0) * 0.15
        )
      )
    );

  v_precision_tier := public.get_rider_scout_precision_tier(v_precision_score);

  if v_precision_tier = 'elite' then
    v_band_size := 1;
    v_potential_band_size := 1;
  elsif v_precision_tier = 'strong' then
    v_band_size := 5;
    v_potential_band_size := 1;
  elsif v_precision_tier = 'solid' then
    v_band_size := 10;
    v_potential_band_size := 10;
  else
    v_band_size := 20;
    v_potential_band_size := 20;
  end if;

  v_report := jsonb_build_object(
    'precisionScore', v_precision_score,
    'precisionTier', v_precision_tier,

    'overall', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.overall::text || '%', 'exact', v_rider.overall)
      else
        jsonb_build_object('label', public.build_scout_range_label(v_rider.overall, greatest(v_band_size, 10)), 'exact', null)
    end,

    'potential', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.potential::text, 'exact', v_rider.potential)
      else
        jsonb_build_object('label', public.build_scout_range_label(v_rider.potential, v_potential_band_size), 'exact', null)
    end,

    'fatigue', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.fatigue::text, 'exact', v_rider.fatigue)
      else
        jsonb_build_object('label', public.get_scout_fatigue_label(v_rider.fatigue), 'exact', null)
    end,

    'availability', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', v_rider.unavailable_until,
          'reason', v_rider.unavailable_reason
        )
      when v_precision_tier = 'solid'
        then jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', v_rider.unavailable_until,
          'reason', null
        )
      else
        jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', null,
          'reason', null
        )
    end,

    'attributes', jsonb_build_object(
      'sprint', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.sprint, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.sprint else null end
      ),
      'climbing', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.climbing, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.climbing else null end
      ),
      'time_trial', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.time_trial, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.time_trial else null end
      ),
      'endurance', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.endurance, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.endurance else null end
      ),
      'flat', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.flat, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.flat else null end
      ),
      'recovery', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.recovery, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.recovery else null end
      ),
      'resistance', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.resistance, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.resistance else null end
      ),
      'race_iq', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.race_iq, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.race_iq else null end
      ),
      'teamwork', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.teamwork, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.teamwork else null end
      ),
      'morale', jsonb_build_object(
        'label',
        public.build_scout_range_label(v_rider.morale, v_band_size),
        'exact',
        case when v_precision_tier = 'elite' then v_rider.morale else null end
      )
    )
  );

  insert into public.rider_scout_reports (
    club_id,
    rider_id,
    scout_staff_id,
    scouted_on_game_date,
    precision_score,
    precision_tier,
    report_json
  )
  values (
    v_club_id,
    p_rider_id,
    v_scout.staff_id,
    v_game_date,
    v_precision_score,
    v_precision_tier,
    v_report
  )
  returning id into v_inserted_id;

  v_remaining := greatest(0, coalesce(v_usage.daily_limit, 2) - coalesce(v_usage.used_count, 0) - 1);

  return jsonb_build_object(
    'reportId', v_inserted_id,
    'riderId', p_rider_id,
    'clubId', v_club_id,
    'scoutedOnGameDate', v_game_date,
    'precisionScore', v_precision_score,
    'precisionTier', v_precision_tier,
    'remainingToday', v_remaining,
    'report', v_report
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.debug_scout_external_rider(p_club_id uuid, p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_game_date date;

  v_scout record;
  v_usage record;
  v_rider record;
  v_owner_club_id uuid;

  v_precision_score integer;
  v_precision_tier text;

  v_band_size integer;
  v_potential_band_size integer;

  v_report jsonb;
  v_inserted_id uuid;
  v_remaining integer;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required.';
  end if;

  if p_rider_id is null then
    raise exception 'p_rider_id is required.';
  end if;

  v_game_date := public.get_current_game_date_date();

  select *
  into v_scout
  from public.debug_get_active_scout_staff_for_club(p_club_id);

  if v_scout.staff_id is null then
    raise exception 'Hire an active Scout / Analyst first.';
  end if;

  select *
  into v_usage
  from public.debug_get_rider_scouting_usage_for_club(p_club_id, v_game_date);

  if coalesce(v_usage.used_count, 0) >= coalesce(v_usage.daily_limit, 2) then
    raise exception 'Daily scouting limit reached.';
  end if;

  select
    r.id,
    r.first_name,
    r.last_name,
    r.display_name,
    r.role,
    r.sprint,
    r.climbing,
    r.time_trial,
    r.endurance,
    r.flat,
    r.recovery,
    r.resistance,
    r.race_iq,
    r.teamwork,
    r.morale,
    r.potential,
    r.fatigue,
    r.overall,
    r.availability_status,
    r.unavailable_until,
    r.unavailable_reason
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if v_rider.id is null then
    raise exception 'Rider not found.';
  end if;

  select cr.club_id
  into v_owner_club_id
  from public.club_riders cr
  where cr.rider_id = p_rider_id
  order by cr.created_at desc nulls last
  limit 1;

  if v_owner_club_id = p_club_id then
    raise exception 'You cannot scout your own rider.';
  end if;

  v_precision_score :=
    greatest(
      0,
      least(
        100,
        round(
          coalesce(v_scout.expertise, 0) * 0.50 +
          coalesce(v_scout.experience, 0) * 0.35 +
          coalesce(v_scout.efficiency, 0) * 0.15
        )
      )
    );

  v_precision_tier := public.get_rider_scout_precision_tier(v_precision_score);

  if v_precision_tier = 'elite' then
    v_band_size := 1;
    v_potential_band_size := 1;
  elsif v_precision_tier = 'strong' then
    v_band_size := 5;
    v_potential_band_size := 1;
  elsif v_precision_tier = 'solid' then
    v_band_size := 10;
    v_potential_band_size := 10;
  else
    v_band_size := 20;
    v_potential_band_size := 20;
  end if;

  v_report := jsonb_build_object(
    'precisionScore', v_precision_score,
    'precisionTier', v_precision_tier,

    'overall', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.overall::text || '%', 'exact', v_rider.overall)
      else
        jsonb_build_object(
          'label',
          public.build_scout_range_label(v_rider.overall, greatest(v_band_size, 10)),
          'exact',
          null
        )
    end,

    'potential', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.potential::text, 'exact', v_rider.potential)
      else
        jsonb_build_object(
          'label',
          public.build_scout_range_label(v_rider.potential, v_potential_band_size),
          'exact',
          null
        )
    end,

    'fatigue', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object('label', v_rider.fatigue::text, 'exact', v_rider.fatigue)
      else
        jsonb_build_object('label', public.get_scout_fatigue_label(v_rider.fatigue), 'exact', null)
    end,

    'availability', case
      when v_precision_tier in ('strong', 'elite')
        then jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', v_rider.unavailable_until,
          'reason', v_rider.unavailable_reason
        )
      when v_precision_tier = 'solid'
        then jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', v_rider.unavailable_until,
          'reason', null
        )
      else
        jsonb_build_object(
          'status', v_rider.availability_status,
          'unavailable_until', null,
          'reason', null
        )
    end,

    'attributes', jsonb_build_object(
      'sprint', jsonb_build_object('label', public.build_scout_range_label(v_rider.sprint, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.sprint else null end),
      'climbing', jsonb_build_object('label', public.build_scout_range_label(v_rider.climbing, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.climbing else null end),
      'time_trial', jsonb_build_object('label', public.build_scout_range_label(v_rider.time_trial, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.time_trial else null end),
      'endurance', jsonb_build_object('label', public.build_scout_range_label(v_rider.endurance, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.endurance else null end),
      'flat', jsonb_build_object('label', public.build_scout_range_label(v_rider.flat, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.flat else null end),
      'recovery', jsonb_build_object('label', public.build_scout_range_label(v_rider.recovery, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.recovery else null end),
      'resistance', jsonb_build_object('label', public.build_scout_range_label(v_rider.resistance, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.resistance else null end),
      'race_iq', jsonb_build_object('label', public.build_scout_range_label(v_rider.race_iq, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.race_iq else null end),
      'teamwork', jsonb_build_object('label', public.build_scout_range_label(v_rider.teamwork, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.teamwork else null end),
      'morale', jsonb_build_object('label', public.build_scout_range_label(v_rider.morale, v_band_size), 'exact', case when v_precision_tier = 'elite' then v_rider.morale else null end)
    )
  );

  insert into public.rider_scout_reports (
    club_id,
    rider_id,
    scout_staff_id,
    scouted_on_game_date,
    precision_score,
    precision_tier,
    report_json
  )
  values (
    p_club_id,
    p_rider_id,
    v_scout.staff_id,
    v_game_date,
    v_precision_score,
    v_precision_tier,
    v_report
  )
  returning id into v_inserted_id;

  v_remaining := greatest(
    0,
    coalesce(v_usage.daily_limit, 2) - coalesce(v_usage.used_count, 0) - 1
  );

  return jsonb_build_object(
    'reportId', v_inserted_id,
    'riderId', p_rider_id,
    'clubId', p_club_id,
    'scoutedOnGameDate', v_game_date,
    'precisionScore', v_precision_score,
    'precisionTier', v_precision_tier,
    'remainingToday', v_remaining,
    'report', v_report
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_external_rider_profile(p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_club_id uuid;
  v_game_date date;
  v_is_own_rider boolean := false;
  v_rider record;
  v_latest_scout_report record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_rider_id is null then
    raise exception 'Rider id is required';
  end if;

  v_club_id := public.get_my_primary_club_id();
  v_game_date := coalesce(public.get_current_game_date_date(), current_date);

  select
    r.id,
    r.first_name,
    r.last_name,
    r.display_name,
    r.country_code,
    r.role,
    r.birth_date,
    r.image_url,
    r.contract_expires_at,
    r.contract_expires_season,
    r.market_value,
    r.salary,
    r.overall,
    r.potential,
    r.fatigue,
    r.sprint,
    r.climbing,
    r.time_trial,
    r.endurance,
    r.flat,
    r.recovery,
    r.resistance,
    r.race_iq,
    r.teamwork,
    r.morale,
    r.availability_status,
    r.unavailable_until,
    r.unavailable_reason
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if not found then
    raise exception 'Rider not found: %', p_rider_id;
  end if;

  if v_club_id is not null then
    select exists (
      select 1
      from public.club_riders cr
      where cr.club_id = v_club_id
        and cr.rider_id = p_rider_id
    )
    into v_is_own_rider;

    select
      rsr.id,
      rsr.precision_score,
      rsr.precision_tier,
      rsr.scouted_on_game_date,
      rsr.created_at,
      rsr.report_json
    into v_latest_scout_report
    from public.rider_scout_reports rsr
    where rsr.club_id = v_club_id
      and rsr.rider_id = p_rider_id
    order by
      coalesce(rsr.created_at_game_ts, rsr.created_at::timestamp without time zone) desc,
      rsr.created_at desc
    limit 1;

    if not found then
      select
        null::uuid as id,
        null::integer as precision_score,
        null::text as precision_tier,
        null::date as scouted_on_game_date,
        null::timestamp with time zone as created_at,
        null::jsonb as report_json
      into v_latest_scout_report;
    end if;
  else
    select
      null::uuid as id,
      null::integer as precision_score,
      null::text as precision_tier,
      null::date as scouted_on_game_date,
      null::timestamp with time zone as created_at,
      null::jsonb as report_json
    into v_latest_scout_report;
  end if;

  return jsonb_build_object(
    'riderId', v_rider.id,
    'clubId', v_club_id,
    'gameDate', v_game_date,
    'isOwnRider', v_is_own_rider,
    'hasScout', v_latest_scout_report.id is not null,
    'canScout', not v_is_own_rider,
    'usedToday', 0,
    'dailyLimit', 0,
    'remainingToday', 0,
    'statusMessage', case
      when v_is_own_rider then 'Own rider profile loaded'
      else 'External rider profile loaded'
    end,

    'profile', jsonb_build_object(
      'id', v_rider.id,
      'firstName', v_rider.first_name,
      'lastName', v_rider.last_name,
      'displayName', v_rider.display_name,
      'countryCode', v_rider.country_code,
      'role', v_rider.role,
      'birthDate', v_rider.birth_date,
      'ageYears', public.get_age_years_on_game_date(v_rider.birth_date),
      'imageUrl', v_rider.image_url,
      'contractExpiresAt', v_rider.contract_expires_at,
      'contractExpiresSeason', v_rider.contract_expires_season,
      'marketValue', v_rider.market_value,
      'salary', v_rider.salary
    ),

    'publicView', jsonb_build_object(
      'overall', jsonb_build_object(
        'label', coalesce(v_rider.overall::text, '—'),
        'exact', v_rider.overall
      ),
      'potential', jsonb_build_object(
        'label', coalesce(v_rider.potential::text, '—'),
        'exact', v_rider.potential
      ),
      'fatigue', jsonb_build_object(
        'label', coalesce(v_rider.fatigue::text, '—'),
        'exact', v_rider.fatigue
      ),
      'availability', jsonb_build_object(
        'status', v_rider.availability_status,
        'unavailable_until', v_rider.unavailable_until,
        'reason', v_rider.unavailable_reason
      ),
      'attributes', jsonb_build_object(
        'sprint', jsonb_build_object('label', coalesce(v_rider.sprint::text, '—'), 'exact', v_rider.sprint),
        'climbing', jsonb_build_object('label', coalesce(v_rider.climbing::text, '—'), 'exact', v_rider.climbing),
        'time_trial', jsonb_build_object('label', coalesce(v_rider.time_trial::text, '—'), 'exact', v_rider.time_trial),
        'endurance', jsonb_build_object('label', coalesce(v_rider.endurance::text, '—'), 'exact', v_rider.endurance),
        'flat', jsonb_build_object('label', coalesce(v_rider.flat::text, '—'), 'exact', v_rider.flat),
        'recovery', jsonb_build_object('label', coalesce(v_rider.recovery::text, '—'), 'exact', v_rider.recovery),
        'resistance', jsonb_build_object('label', coalesce(v_rider.resistance::text, '—'), 'exact', v_rider.resistance),
        'race_iq', jsonb_build_object('label', coalesce(v_rider.race_iq::text, '—'), 'exact', v_rider.race_iq),
        'teamwork', jsonb_build_object('label', coalesce(v_rider.teamwork::text, '—'), 'exact', v_rider.teamwork),
        'morale', jsonb_build_object('label', coalesce(v_rider.morale::text, '—'), 'exact', v_rider.morale)
      )
    ),

    'scoutReport',
    case
      when v_latest_scout_report.id is null then null
      else jsonb_build_object(
        'reportId', v_latest_scout_report.id,
        'precisionScore', v_latest_scout_report.precision_score,
        'precisionTier', v_latest_scout_report.precision_tier,
        'scoutedOnGameDate', v_latest_scout_report.scouted_on_game_date,
        'createdAt', v_latest_scout_report.created_at,
        'report', v_latest_scout_report.report_json
      )
    end
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.debug_get_external_rider_profile(p_club_id uuid, p_rider_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare
  v_game_date date;

  v_scout record;
  v_usage record;
  v_latest_report record;
  v_rider record;

  v_owner_club_id uuid;
  v_has_scout boolean;
  v_is_own_rider boolean;
  v_can_scout boolean;
  v_used_today integer;
  v_daily_limit integer;
  v_remaining_today integer;
  v_status_message text;
begin
  if p_club_id is null then
    raise exception 'p_club_id is required.';
  end if;

  if p_rider_id is null then
    raise exception 'p_rider_id is required.';
  end if;

  v_game_date := public.get_current_game_date_date();

  select
    r.id,
    r.first_name,
    r.last_name,
    r.display_name,
    r.country_code,
    r.role,
    r.birth_date,
    r.image_url,
    r.contract_expires_at,
    r.contract_expires_season,
    r.market_value,
    r.salary,
    r.overall,
    r.sprint,
    r.climbing,
    r.time_trial,
    r.endurance,
    r.flat,
    r.recovery,
    r.resistance,
    r.race_iq,
    r.teamwork,
    r.morale,
    r.potential,
    r.fatigue,
    r.availability_status,
    r.unavailable_until,
    r.unavailable_reason
  into v_rider
  from public.riders r
  where r.id = p_rider_id;

  if v_rider.id is null then
    raise exception 'Rider not found.';
  end if;

  select cr.club_id
  into v_owner_club_id
  from public.club_riders cr
  where cr.rider_id = p_rider_id
  order by cr.created_at desc nulls last
  limit 1;

  v_is_own_rider := coalesce(v_owner_club_id = p_club_id, false);

  select *
  into v_scout
  from public.debug_get_active_scout_staff_for_club(p_club_id);

  v_has_scout := coalesce(v_scout.staff_id is not null, false);

  select *
  into v_usage
  from public.debug_get_rider_scouting_usage_for_club(p_club_id, v_game_date);

  v_used_today := coalesce(v_usage.used_count, 0);
  v_daily_limit := coalesce(v_usage.daily_limit, 2);
  v_remaining_today := greatest(0, v_daily_limit - v_used_today);

  select
    lsr.id,
    lsr.precision_score,
    lsr.precision_tier,
    lsr.report_json,
    lsr.scouted_on_game_date,
    lsr.created_at
  into v_latest_report
  from public.v_latest_rider_scout_reports lsr
  where lsr.club_id = p_club_id
    and lsr.rider_id = p_rider_id;

  v_can_scout :=
    (not v_is_own_rider)
    and v_has_scout
    and v_remaining_today > 0;

  if v_is_own_rider then
    v_status_message := 'Your club already has full information on this rider.';
  elsif not v_has_scout then
    v_status_message := 'Hire an active Scout / Analyst first.';
  elsif v_remaining_today <= 0 then
    v_status_message := 'Daily scouting limit reached.';
  elsif v_latest_report.id is not null then
    v_status_message := 'Scouting report available.';
  else
    v_status_message := 'Rider can be scouted.';
  end if;

  return jsonb_build_object(
    'riderId', v_rider.id,
    'clubId', p_club_id,
    'gameDate', v_game_date,

    'isOwnRider', v_is_own_rider,
    'hasScout', v_has_scout,
    'canScout', v_can_scout,
    'usedToday', v_used_today,
    'dailyLimit', v_daily_limit,
    'remainingToday', v_remaining_today,
    'statusMessage', v_status_message,

    'profile', jsonb_build_object(
      'id', v_rider.id,
      'firstName', v_rider.first_name,
      'lastName', v_rider.last_name,
      'displayName', v_rider.display_name,
      'countryCode', v_rider.country_code,
      'role', v_rider.role,
      'birthDate', v_rider.birth_date,
      'imageUrl', v_rider.image_url,
      'contractExpiresAt', v_rider.contract_expires_at,
      'contractExpiresSeason', v_rider.contract_expires_season,
      'marketValue', v_rider.market_value,
      'salary', v_rider.salary
    ),

    'publicView', jsonb_build_object(
      'overall', jsonb_build_object(
        'label', public.build_scout_range_label(v_rider.overall, 20),
        'exact', null
      ),
      'attributes', jsonb_build_object(
        'sprint', jsonb_build_object('label', public.build_scout_range_label(v_rider.sprint, 20), 'exact', null),
        'climbing', jsonb_build_object('label', public.build_scout_range_label(v_rider.climbing, 20), 'exact', null),
        'time_trial', jsonb_build_object('label', public.build_scout_range_label(v_rider.time_trial, 20), 'exact', null),
        'endurance', jsonb_build_object('label', public.build_scout_range_label(v_rider.endurance, 20), 'exact', null),
        'flat', jsonb_build_object('label', public.build_scout_range_label(v_rider.flat, 20), 'exact', null),
        'recovery', jsonb_build_object('label', public.build_scout_range_label(v_rider.recovery, 20), 'exact', null),
        'resistance', jsonb_build_object('label', public.build_scout_range_label(v_rider.resistance, 20), 'exact', null),
        'race_iq', jsonb_build_object('label', public.build_scout_range_label(v_rider.race_iq, 20), 'exact', null),
        'teamwork', jsonb_build_object('label', public.build_scout_range_label(v_rider.teamwork, 20), 'exact', null),
        'morale', jsonb_build_object('label', public.build_scout_range_label(v_rider.morale, 20), 'exact', null)
      ),
      'potential', jsonb_build_object(
        'label', 'Hidden',
        'exact', null
      ),
      'fatigue', jsonb_build_object(
        'label', 'Hidden',
        'exact', null
      ),
      'availability', jsonb_build_object(
        'status', null,
        'unavailable_until', null,
        'reason', null
      )
    ),

    'scoutReport', case
      when v_latest_report.id is not null then
        jsonb_build_object(
          'reportId', v_latest_report.id,
          'precisionScore', v_latest_report.precision_score,
          'precisionTier', v_latest_report.precision_tier,
          'scoutedOnGameDate', v_latest_report.scouted_on_game_date,
          'createdAt', v_latest_report.created_at,
          'report', v_latest_report.report_json
        )
      else
        null
    end
  );
end;$function$
;

CREATE OR REPLACE FUNCTION public.start_rider_free_agent_negotiation_v2(p_free_agent_id uuid, p_club_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_effective_club_id uuid;
  v_rider_id uuid;
  v_free_agent_status text;
  v_expected_salary integer;
  v_expires_on_game_date date;
  v_opened_in_season integer;
  v_opened_on_game_date date;
  v_existing_negotiation_id uuid;
  v_new_negotiation_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if p_free_agent_id is null then
    raise exception 'Free agent id is required';
  end if;

  v_effective_club_id := coalesce(
    p_club_id,
    (
      select c.id
      from public.clubs c
      where c.owner_user_id = auth.uid()
        and c.deleted_at is null
      order by
        case
          when c.club_type = 'main' then 0
          when c.parent_club_id is null and coalesce(c.club_type, '') <> 'developing' then 1
          else 2
        end,
        c.created_at asc
      limit 1
    )
  );

  if v_effective_club_id is null then
    raise exception 'No main club found for current user';
  end if;

  if not exists (
    select 1
    from public.clubs c
    where c.id = v_effective_club_id
      and c.owner_user_id = auth.uid()
      and c.deleted_at is null
      and coalesce(c.club_type, '') <> 'developing'
  ) then
    raise exception 'Selected club is not allowed for this action';
  end if;

  select n.id
  into v_existing_negotiation_id
  from public.rider_free_agent_negotiations n
  where n.free_agent_id = p_free_agent_id
    and n.club_id = v_effective_club_id
    and n.status = 'open'
  order by n.created_at desc
  limit 1;

  if v_existing_negotiation_id is not null then
    return jsonb_build_object(
      'negotiation_id', v_existing_negotiation_id,
      'status', 'open',
      'reused', true
    );
  end if;

  select
    fa.rider_id,
    fa.status,
    famv.expected_salary_weekly,
    famv.expires_on_game_date
  into
    v_rider_id,
    v_free_agent_status,
    v_expected_salary,
    v_expires_on_game_date
  from public.rider_free_agents fa
  left join public.free_agent_market_view famv
    on famv.free_agent_id = fa.id
  where fa.id = p_free_agent_id
  for update of fa;

  if v_rider_id is null then
    raise exception 'Free agent not found';
  end if;

  if coalesce(v_free_agent_status, '') not in ('open', 'available') then
    raise exception 'Free agent is not available';
  end if;

  if v_expected_salary is null or v_expected_salary <= 0 then
    raise exception 'Expected salary missing for free agent %', p_free_agent_id;
  end if;

  select gs.season_number
  into v_opened_in_season
  from public.game_state gs
  limit 1;

  if v_opened_in_season is null then
    raise exception 'game_state.season_number is null';
  end if;

  v_opened_on_game_date := public.get_current_game_date_date();

  if v_opened_on_game_date is null then
    raise exception 'Current game date is null';
  end if;

  insert into public.rider_free_agent_negotiations (
    free_agent_id,
    rider_id,
    club_id,
    status,
    current_salary_weekly,
    expected_salary_weekly,
    min_acceptable_salary_weekly,
    preferred_duration_seasons,
    offer_salary_weekly,
    offer_duration_seasons,
    attempt_count,
    max_attempts,
    locked_until,
    opened_in_season,
    opened_on_game_date,
    closed_reason,
    notes_json,
    expires_on_game_date
  )
  values (
    p_free_agent_id,
    v_rider_id,
    v_effective_club_id,
    'open',
    null,
    v_expected_salary,
    v_expected_salary,
    1,
    v_expected_salary,
    1,
    0,
    5,
    null,
    v_opened_in_season,
    v_opened_on_game_date,
    null,
    '{}'::jsonb,
    coalesce(v_expires_on_game_date, v_opened_on_game_date + 3)
  )
  returning id
  into v_new_negotiation_id;

  return jsonb_build_object(
    'negotiation_id', v_new_negotiation_id,
    'status', 'open',
    'reused', false,
    'club_id', v_effective_club_id
  );

exception
  when not_null_violation then
    raise exception
      'NOT NULL failure. free_agent_id=%, club_id=%, rider_id=%, expected_salary=%, opened_in_season=%, opened_on_game_date=%, expires_on_game_date=%',
      p_free_agent_id,
      v_effective_club_id,
      v_rider_id,
      v_expected_salary,
      v_opened_in_season,
      v_opened_on_game_date,
      v_expires_on_game_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.withdraw_rider_free_agent_negotiation(p_negotiation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_negotiation record;
begin
  if v_user_id is null then
    raise exception 'Not authenticated'
      using errcode = 'P0001';
  end if;

  select
    n.id,
    n.free_agent_id,
    n.club_id,
    n.status
  into v_negotiation
  from public.rider_free_agent_negotiations n
  join public.clubs c
    on c.id = n.club_id
  where n.id = p_negotiation_id
    and c.owner_user_id = v_user_id
    and c.deleted_at is null
  limit 1;

  if not found then
    raise exception 'Free-agent negotiation not found or access denied.'
      using errcode = 'P0001';
  end if;

  if lower(coalesce(v_negotiation.status, '')) = 'withdrawn' then
    return jsonb_build_object(
      'negotiation_id', v_negotiation.id,
      'status', 'withdrawn',
      'message', 'Negotiation already withdrawn.'
    );
  end if;

  if lower(coalesce(v_negotiation.status, '')) <> 'open' then
    raise exception 'Only open free-agent negotiations can be withdrawn.'
      using errcode = 'P0001';
  end if;

  update public.rider_free_agent_negotiations
  set
    status = 'withdrawn',
    closed_reason = coalesce(closed_reason, 'withdrawn_by_club'),
    locked_until = null,
    updated_at = now()
  where id = p_negotiation_id;

  return jsonb_build_object(
    'negotiation_id', p_negotiation_id,
    'status', 'withdrawn',
    'message', 'Free-agent negotiation withdrawn successfully.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_guard_training_activity_rows()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Regular training must not be written for riders who are inside a camp window
  if new.source = 'regular_training' then
    if public.is_rider_assigned_to_training_camp_on_date(new.rider_id, new.activity_date) then
      return null;
    end if;
  end if;

  -- Normalize/force training-camp rows
  if new.source = 'training_camp' then
    new.activity_type := 'training_camp';
    new.intensity := coalesce(new.intensity, 'normal');
    new.recovery_bonus := 0;

    if coalesce(new.participated, false) then
      new.fatigue_load := 16;
    else
      new.fatigue_load := 0;
    end if;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_training_camp_activity_from_report(p_booking_id uuid, p_report_date date)
 RETURNS TABLE(inserted_rows integer, updated_rows integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_camp_id uuid;
  v_camp_type text;
  v_weather_state text;
  v_training_modifier numeric;
  v_inserted_rows integer := 0;
  v_updated_rows integer := 0;
begin
  select
    b.camp_id,
    coalesce(cat.camp_type, 'general'),
    coalesce(r.weather_state, r.payload->>'weather_state', 'good')
  into
    v_camp_id,
    v_camp_type,
    v_weather_state
  from public.training_camp_bookings b
  left join public.training_camp_catalog cat
    on cat.id = b.camp_id
  left join public.training_camp_daily_reports r
    on r.booking_id = b.id
   and r.report_date = p_report_date
  where b.id = p_booking_id;

  if not found then
    return query select 0, 0;
    return;
  end if;

  v_training_modifier :=
    case lower(coalesce(v_weather_state, 'good'))
      when 'ideal' then 1.00
      when 'good'  then 0.95
      when 'mixed' then 0.90
      when 'poor'  then 0.80
      else 0.95
    end;

  -- 1) Convert/update any existing same-day row (regular_training OR training_camp OR anything else)
  --    into the correct training_camp row for that rider/date.
  with candidates as (
    select
      tcp.rider_id,
      r.availability_status,
      case
        when coalesce(r.availability_status, 'fit') in ('injured', 'sick') then false
        else true
      end as participated
    from public.training_camp_participants tcp
    join public.riders r
      on r.id = tcp.rider_id
    where tcp.booking_id = p_booking_id
  ),
  upd as (
    update public.rider_daily_activity rda
       set source        = 'training_camp',
           activity_type = 'training_camp',
           intensity     = 'normal',
           participated  = c.participated,
           fatigue_load  = case when c.participated then 16 else 0 end,
           recovery_bonus = 0,
           source_id     = p_booking_id,
           metadata      = jsonb_strip_nulls(
                             coalesce(rda.metadata, '{}'::jsonb) ||
                             jsonb_build_object(
                               'training_system', 'training_camp',
                               'booking_id', p_booking_id,
                               'camp_id', v_camp_id,
                               'camp_type', v_camp_type,
                               'focus_code', v_camp_type,
                               'weather_state', v_weather_state,
                               'training_modifier', v_training_modifier,
                               'availability_status', c.availability_status,
                               'development_eligible', c.participated,
                               'availability_modifier', 1,
                               'development_value_base', case when c.participated then 0.04 else 0 end,
                               'missed_day', not c.participated,
                               'missed_day_reason', case when c.participated then null else 'injured_or_sick' end
                             )
                           )
      from candidates c
     where rda.rider_id = c.rider_id
       and rda.activity_date = p_report_date
    returning 1
  )
  select count(*) into v_updated_rows
  from upd;

  -- 2) Insert only for riders/dates that still have no activity row at all
  with candidates as (
    select
      tcp.rider_id,
      r.availability_status,
      case
        when coalesce(r.availability_status, 'fit') in ('injured', 'sick') then false
        else true
      end as participated
    from public.training_camp_participants tcp
    join public.riders r
      on r.id = tcp.rider_id
    where tcp.booking_id = p_booking_id
  ),
  ins as (
    insert into public.rider_daily_activity (
      rider_id,
      activity_date,
      participated,
      source,
      activity_type,
      intensity,
      fatigue_load,
      recovery_bonus,
      source_id,
      metadata
    )
    select
      c.rider_id,
      p_report_date,
      c.participated,
      'training_camp',
      'training_camp',
      'normal',
      case when c.participated then 16 else 0 end,
      0,
      p_booking_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'training_system', 'training_camp',
          'booking_id', p_booking_id,
          'camp_id', v_camp_id,
          'camp_type', v_camp_type,
          'focus_code', v_camp_type,
          'weather_state', v_weather_state,
          'training_modifier', v_training_modifier,
          'availability_status', c.availability_status,
          'development_eligible', c.participated,
          'availability_modifier', 1,
          'development_value_base', case when c.participated then 0.04 else 0 end,
          'missed_day', not c.participated,
          'missed_day_reason', case when c.participated then null else 'injured_or_sick' end
        )
      )
    from candidates c
    where not exists (
      select 1
      from public.rider_daily_activity x
      where x.rider_id = c.rider_id
        and x.activity_date = p_report_date
    )
    returning 1
  )
  select count(*) into v_inserted_rows
  from ins;

  return query
  select v_inserted_rows, v_updated_rows;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.refresh_training_camp_daily_report_metrics(p_booking_id uuid, p_report_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  v_participants_count integer := 0;
  v_completed_count integer := 0;
  v_missed_count integer := 0;
  v_avg_fatigue_before numeric := null;
  v_avg_session_input numeric := 0;
begin
  select count(*)
    into v_participants_count
  from public.training_camp_participants
  where booking_id = p_booking_id;

  select
    count(*) filter (where coalesce(rda.participated, false)),
    count(*) filter (where not coalesce(rda.participated, false)),
    coalesce(avg(coalesce(rda.fatigue_load, 0)::numeric), 0)
  into
    v_completed_count,
    v_missed_count,
    v_avg_session_input
  from public.rider_daily_activity rda
  join public.training_camp_participants tcp
    on tcp.rider_id = rda.rider_id
   and tcp.booking_id = p_booking_id
  where rda.activity_date = p_report_date
    and rda.source = 'training_camp';

  select avg_fatigue_before
    into v_avg_fatigue_before
  from public.training_camp_daily_reports
  where booking_id = p_booking_id
    and report_date = p_report_date;

  update public.training_camp_daily_reports
     set participants_count = v_participants_count,
         completed_count    = v_completed_count,
         missed_count       = v_missed_count,
         avg_fatigue_after  = coalesce(v_avg_fatigue_before, 0) + coalesce(v_avg_session_input, 0)
   where booking_id = p_booking_id
     and report_date = p_report_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_sync_training_camp_activity_from_report()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  perform public.sync_training_camp_activity_from_report(new.booking_id, new.report_date);
  perform public.refresh_training_camp_daily_report_metrics(new.booking_id, new.report_date);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_repair_training_camp_activity(p_booking_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(booking_id uuid, repaired_report_dates integer, inserted_rows integer, updated_rows integer, deleted_regular_training_rows integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_booking_id uuid;
  v_repaired_report_dates integer;
  v_inserted_rows integer;
  v_updated_rows integer;
  v_deleted_regular_rows integer;
  v_i integer;
  v_u integer;
begin
  for v_booking_id in
    select distinct r.booking_id
    from public.training_camp_daily_reports r
    join public.training_camp_bookings b on b.id = r.booking_id
    where p_booking_id is null or r.booking_id = p_booking_id
  loop
    v_repaired_report_dates := 0;
    v_inserted_rows := 0;
    v_updated_rows := 0;
    v_deleted_regular_rows := 0;

    for v_i, v_u in
      select s.inserted_rows, s.updated_rows
      from public.training_camp_daily_reports r
      cross join lateral public.sync_training_camp_activity_from_report(r.booking_id, r.report_date) s
      where r.booking_id = v_booking_id
    loop
      v_repaired_report_dates := v_repaired_report_dates + 1;
      v_inserted_rows := v_inserted_rows + coalesce(v_i, 0);
      v_updated_rows := v_updated_rows + coalesce(v_u, 0);
    end loop;

    -- refresh all report rows for this booking
    perform public.refresh_training_camp_daily_report_metrics(r.booking_id, r.report_date)
    from public.training_camp_daily_reports r
    where r.booking_id = v_booking_id;

    -- remove regular training rows on dates where a camp row exists for the same rider/date
    with del as (
      delete from public.rider_daily_activity rt
      using public.training_camp_participants tcp,
            public.rider_daily_activity camp
      where tcp.booking_id = v_booking_id
        and camp.rider_id = tcp.rider_id
        and camp.source = 'training_camp'
        and rt.rider_id = camp.rider_id
        and rt.activity_date = camp.activity_date
        and rt.source = 'regular_training'
      returning 1
    )
    select count(*) into v_deleted_regular_rows
    from del;

    booking_id := v_booking_id;
    repaired_report_dates := v_repaired_report_dates;
    inserted_rows := v_inserted_rows;
    updated_rows := v_updated_rows;
    deleted_regular_training_rows := v_deleted_regular_rows;
    return next;
  end loop;

  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_training_camp_activity_for_date(p_booking_id uuid, p_game_date date)
 RETURNS TABLE(inserted_rows integer, updated_rows integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_camp_id uuid;
  v_camp_type text;
  v_weather_state text;
  v_training_modifier numeric;
  v_inserted_rows integer := 0;
  v_updated_rows integer := 0;
begin
  select
    b.camp_id,
    coalesce(cat.camp_type, 'general')
  into
    v_camp_id,
    v_camp_type
  from public.training_camp_bookings b
  left join public.training_camp_catalog cat
    on cat.id = b.camp_id
  where b.id = p_booking_id
    and p_game_date between b.start_date and b.end_date;

  if not found then
    return query select 0, 0;
    return;
  end if;

  -- Prefer exact report weather if available; otherwise fall back to good
  select coalesce(r.weather_state, r.payload->>'weather_state', 'good')
    into v_weather_state
  from public.training_camp_daily_reports r
  where r.booking_id = p_booking_id
    and r.report_date = p_game_date;

  v_weather_state := coalesce(v_weather_state, 'good');

  v_training_modifier :=
    case lower(coalesce(v_weather_state, 'good'))
      when 'ideal' then 1.00
      when 'good'  then 0.95
      when 'mixed' then 0.90
      when 'poor'  then 0.80
      else 0.95
    end;

  -- Convert/update any same-day row into the correct training_camp row
  with candidates as (
    select
      tcp.rider_id,
      r.availability_status,
      case
        when coalesce(r.availability_status, 'fit') in ('injured', 'sick') then false
        else true
      end as participated
    from public.training_camp_participants tcp
    join public.riders r on r.id = tcp.rider_id
    where tcp.booking_id = p_booking_id
  ),
  upd as (
    update public.rider_daily_activity rda
       set source         = 'training_camp',
           activity_type  = 'training_camp',
           intensity      = 'normal',
           participated   = c.participated,
           fatigue_load   = case when c.participated then 16 else 0 end,
           recovery_bonus = 0,
           source_id      = p_booking_id,
           metadata       = jsonb_strip_nulls(
                              coalesce(rda.metadata, '{}'::jsonb) ||
                              jsonb_build_object(
                                'training_system', 'training_camp',
                                'booking_id', p_booking_id,
                                'camp_id', v_camp_id,
                                'camp_type', v_camp_type,
                                'focus_code', v_camp_type,
                                'weather_state', v_weather_state,
                                'training_modifier', v_training_modifier,
                                'availability_status', c.availability_status,
                                'development_eligible', c.participated,
                                'availability_modifier', 1,
                                'development_value_base', case when c.participated then 0.04 else 0 end,
                                'missed_day', not c.participated,
                                'missed_day_reason', case when c.participated then null else 'injured_or_sick' end
                              )
                            )
      from candidates c
     where rda.rider_id = c.rider_id
       and rda.activity_date = p_game_date
    returning 1
  )
  select count(*) into v_updated_rows
  from upd;

  -- Insert only where no row exists at all for that rider/date
  with candidates as (
    select
      tcp.rider_id,
      r.availability_status,
      case
        when coalesce(r.availability_status, 'fit') in ('injured', 'sick') then false
        else true
      end as participated
    from public.training_camp_participants tcp
    join public.riders r on r.id = tcp.rider_id
    where tcp.booking_id = p_booking_id
  ),
  ins as (
    insert into public.rider_daily_activity (
      rider_id,
      activity_date,
      participated,
      source,
      activity_type,
      intensity,
      fatigue_load,
      recovery_bonus,
      source_id,
      metadata
    )
    select
      c.rider_id,
      p_game_date,
      c.participated,
      'training_camp',
      'training_camp',
      'normal',
      case when c.participated then 16 else 0 end,
      0,
      p_booking_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'training_system', 'training_camp',
          'booking_id', p_booking_id,
          'camp_id', v_camp_id,
          'camp_type', v_camp_type,
          'focus_code', v_camp_type,
          'weather_state', v_weather_state,
          'training_modifier', v_training_modifier,
          'availability_status', c.availability_status,
          'development_eligible', c.participated,
          'availability_modifier', 1,
          'development_value_base', case when c.participated then 0.04 else 0 end,
          'missed_day', not c.participated,
          'missed_day_reason', case when c.participated then null else 'injured_or_sick' end
        )
      )
    from candidates c
    where not exists (
      select 1
      from public.rider_daily_activity x
      where x.rider_id = c.rider_id
        and x.activity_date = p_game_date
    )
    returning 1
  )
  select count(*) into v_inserted_rows
  from ins;

  return query
  select v_inserted_rows, v_updated_rows;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_repair_training_camp_activity_full_window(p_booking_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(booking_id uuid, repaired_dates integer, inserted_rows integer, updated_rows integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_booking_id uuid;
  v_start_date date;
  v_end_date date;
  v_date date;
  v_repaired_dates integer;
  v_inserted_rows integer;
  v_updated_rows integer;
  v_i integer;
  v_u integer;
begin
  for v_booking_id, v_start_date, v_end_date in
    select b.id, b.start_date, b.end_date
    from public.training_camp_bookings b
    where p_booking_id is null or b.id = p_booking_id
  loop
    v_repaired_dates := 0;
    v_inserted_rows := 0;
    v_updated_rows := 0;

    for v_date in
      select generate_series(v_start_date, v_end_date, interval '1 day')::date
    loop
      select s.inserted_rows, s.updated_rows
        into v_i, v_u
      from public.sync_training_camp_activity_for_date(v_booking_id, v_date) s;

      v_repaired_dates := v_repaired_dates + 1;
      v_inserted_rows := v_inserted_rows + coalesce(v_i, 0);
      v_updated_rows := v_updated_rows + coalesce(v_u, 0);
    end loop;

    booking_id := v_booking_id;
    repaired_dates := v_repaired_dates;
    inserted_rows := v_inserted_rows;
    updated_rows := v_updated_rows;
    return next;
  end loop;

  return;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.run_daily_market_jobs_detailed_core()
 RETURNS TABLE(expired_transfer_listings integer, expired_transfer_offers integer, expired_transfer_negotiations integer, expired_free_agents integer, expired_free_agent_negotiations integer, refill_created_count integer, refill_amateur_created integer, refill_continental_created integer, refill_proteam_created integer, ai_seller_clubs_reviewed integer, ai_seller_listings_created integer, ai_seller_skipped_count integer, ai_transfer_buyer_clubs_reviewed integer, ai_transfer_buyer_offers_created integer, ai_transfer_buyer_skipped_no_candidate integer, ai_transfer_buyer_skipped_cash_reserve integer, ai_transfer_offer_review_clubs_reviewed integer, ai_transfer_offer_review_offers_accepted integer, ai_transfer_offer_review_offers_rejected integer, ai_transfer_offer_review_skipped_count integer, ai_transfer_contract_review_clubs_reviewed integer, ai_transfer_contract_review_terms_submitted integer, ai_transfer_contract_review_skipped_count integer, ai_free_agent_buyer_clubs_reviewed integer, ai_free_agent_buyer_offers_created integer, ai_free_agent_buyer_skipped_no_candidate integer, ai_free_agent_buyer_skipped_cash_reserve integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_transfer record;
  v_free_agents record;
  v_refill record;
  v_sellers record;
  v_offer_review record;
  v_contract_review record;
  v_cfg record;
  v_row record;
  v_result record;

  v_tb_reviewed integer := 0;
  v_tb_offered integer := 0;
  v_tb_skip_no_candidate integer := 0;
  v_tb_skip_cash integer := 0;

  v_fab_reviewed integer := 0;
  v_fab_offered integer := 0;
  v_fab_skip_no_candidate integer := 0;
  v_fab_skip_cash integer := 0;

  v_today date;
begin
  v_today := public.get_market_game_date();

  select *
  into v_cfg
  from public.get_market_ai_config();

  select *
  into v_transfer
  from public.expire_rider_transfer_market_state();

  select *
  into v_free_agents
  from public.expire_rider_free_agent_market_state();

  select *
  into v_refill
  from public.refill_generated_free_agent_pool();

  select *
  into v_sellers
  from public.run_ai_transfer_seller_job();

  for v_row in
    with eligible_ai_buyer_clubs as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and (
          select count(*)
          from public.club_riders cr
          where cr.club_id = c.id
        ) < 18
        and not exists (
          select 1
          from public.rider_transfer_offers rto
          where rto.buyer_club_id = c.id
            and rto.offered_on_game_date = v_today
        )
    )
    select id
    from eligible_ai_buyer_clubs
    order by random()
    limit v_cfg.transfer_buyer_daily_limit
  loop
    v_tb_reviewed := v_tb_reviewed + 1;

    begin
      select *
      into v_result
      from public.ai_review_club_for_transfer_buys(v_row.id)
      limit 1;

    exception
      when others then
        if public.market_ai_is_skippable_roster_exception_v1(
             sqlstate,
             sqlerrm
           ) then
          v_tb_skip_no_candidate := v_tb_skip_no_candidate + 1;
          continue;
        end if;

        raise;
    end;

    if v_result.action_taken = 'offered' then
      v_tb_offered := v_tb_offered + 1;
    elsif v_result.action_taken = 'skipped_cash_reserve' then
      v_tb_skip_cash := v_tb_skip_cash + 1;
    else
      v_tb_skip_no_candidate := v_tb_skip_no_candidate + 1;
    end if;
  end loop;

  select *
  into v_offer_review
  from public.run_ai_transfer_offer_review_job();

  select *
  into v_contract_review
  from public.run_ai_transfer_contract_offer_job();

  for v_row in
    with eligible_ai_buyer_clubs as (
      select c.id
      from public.clubs c
      where c.deleted_at is null
        and c.is_ai = true
        and c.club_type = 'main'
        and c.parent_club_id is null
        and (
          select count(*)
          from public.club_riders cr
          where cr.club_id = c.id
        ) < 18
        and not exists (
          select 1
          from public.rider_free_agent_negotiations n
          where n.club_id = c.id
            and n.opened_on_game_date = v_today
        )
    )
    select id
    from eligible_ai_buyer_clubs
    order by random()
    limit v_cfg.free_agent_buyer_daily_limit
  loop
    v_fab_reviewed := v_fab_reviewed + 1;

    begin
      select *
      into v_result
      from public.ai_review_club_for_free_agent_buys(v_row.id)
      limit 1;

    exception
      when others then
        if public.market_ai_is_skippable_roster_exception_v1(
             sqlstate,
             sqlerrm
           ) then
          v_fab_skip_no_candidate := v_fab_skip_no_candidate + 1;
          continue;
        end if;

        raise;
    end;

    if v_result.action_taken = 'offered' then
      v_fab_offered := v_fab_offered + 1;
    elsif v_result.action_taken = 'skipped_cash_reserve' then
      v_fab_skip_cash := v_fab_skip_cash + 1;
    else
      v_fab_skip_no_candidate := v_fab_skip_no_candidate + 1;
    end if;
  end loop;

  return query
  select
    v_transfer.expired_listing_count,
    v_transfer.expired_offer_count,
    v_transfer.expired_negotiation_count,
    v_free_agents.expired_free_agent_count,
    v_free_agents.expired_negotiation_count,
    v_refill.created_count,
    v_refill.amateur_created,
    v_refill.continental_created,
    v_refill.proteam_created,
    v_sellers.clubs_reviewed,
    v_sellers.listings_created,
    v_sellers.skipped_count,
    v_tb_reviewed,
    v_tb_offered,
    v_tb_skip_no_candidate,
    v_tb_skip_cash,
    v_offer_review.clubs_reviewed,
    v_offer_review.offers_accepted,
    v_offer_review.offers_rejected,
    v_offer_review.skipped_count,
    v_contract_review.clubs_reviewed,
    v_contract_review.terms_submitted,
    v_contract_review.skipped_count,
    v_fab_reviewed,
    v_fab_offered,
    v_fab_skip_no_candidate,
    v_fab_skip_cash;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.scout_metric_bucket_step(p_precision_tier text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_tier text := lower(trim(coalesce(p_precision_tier, '')));
begin
  case v_tier
    when 'basic' then
      return 10; -- narrower than public 20-point range
    when 'solid' then
      return 5;
    when 'strong' then
      return 3;
    when 'elite' then
      return 1; -- exact / near-exact handling
    else
      return 20;
  end case;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.build_scout_metric_json(p_exact numeric, p_precision_tier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_step integer;
  v_exact integer;
  v_bucket_index integer;
  v_bucket_count integer;
  v_lower integer;
  v_upper integer;
  v_label text;
  v_legacy_display_value integer;
  v_tier text := lower(trim(coalesce(p_precision_tier, 'basic')));
begin
  if p_exact is null then
    return jsonb_build_object(
      'label', null,
      'exact', null,
      'exact_revealed', false,
      'precision_tier', v_tier
    );
  end if;

  v_exact := greatest(0, least(100, round(p_exact)::integer));
  v_step := public.scout_metric_bucket_step(v_tier);

  if v_step <= 1 then
    v_label := v_exact::text;
    v_legacy_display_value := v_exact;
  else
    v_bucket_count := 100 / v_step;
    v_bucket_index := least(floor(v_exact::numeric / v_step)::integer, v_bucket_count - 1);
    v_lower := v_bucket_index * v_step;
    v_upper := least(100, v_lower + v_step);
    v_label := format('%s-%s', v_lower, v_upper);
    v_legacy_display_value := round((v_lower + v_upper) / 2.0)::integer;
  end if;

  return jsonb_build_object(
    'label', v_label,
    -- Legacy UI compatibility: lower-quality reports receive only a range-derived
    -- midpoint here, never the rider's true hidden value. Elite reports may reveal exact.
    'exact', case when v_tier = 'elite' then v_exact else v_legacy_display_value end,
    'exact_revealed', (v_tier = 'elite'),
    'precision_tier', v_tier
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_scout_precision_and_duration(p_expertise integer, p_experience integer, p_potential integer, p_leadership integer, p_efficiency integer, p_loyalty integer, p_scouting_level integer DEFAULT NULL::integer)
 RETURNS TABLE(precision_score numeric, speed_score numeric, precision_tier text, duration_hours integer)
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_precision_score numeric;
  v_speed_score numeric;
  v_precision_tier text;
  v_duration_hours integer;
  v_level integer;
begin
  v_precision_score :=
      0.35 * greatest(0, least(100, coalesce(p_expertise, 0)))
    + 0.25 * greatest(0, least(100, coalesce(p_experience, 0)))
    + 0.20 * greatest(0, least(100, coalesce(p_efficiency, 0)))
    + 0.10 * greatest(0, least(100, coalesce(p_potential, 0)))
    + 0.10 * greatest(0, least(100, coalesce(p_loyalty, 0)));

  v_speed_score :=
      0.45 * greatest(0, least(100, coalesce(p_expertise, 0)))
    + 0.35 * greatest(0, least(100, coalesce(p_efficiency, 0)))
    + 0.20 * greatest(0, least(100, coalesce(p_experience, 0)));

  if v_precision_score >= 85 then
    v_precision_tier := 'elite';
  elsif v_precision_score >= 70 then
    v_precision_tier := 'strong';
  elsif v_precision_score >= 55 then
    v_precision_tier := 'solid';
  else
    v_precision_tier := 'basic';
  end if;

  -- Optional infrastructure cap by scouting office level
  v_level := coalesce(p_scouting_level, 0);

  if v_level <= 0 then
    v_precision_tier := 'basic';
  elsif v_level = 1 then
    if v_precision_tier in ('elite', 'strong', 'solid') then
      v_precision_tier := 'basic';
    end if;
  elsif v_level = 2 then
    if v_precision_tier in ('elite', 'strong') then
      v_precision_tier := 'solid';
    end if;
  elsif v_level = 3 then
    if v_precision_tier = 'elite' then
      v_precision_tier := 'strong';
    end if;
  end if;

  if v_speed_score >= 85 then
    v_duration_hours := 1;
  elsif v_speed_score >= 70 then
    v_duration_hours := 2;
  elsif v_speed_score >= 55 then
    v_duration_hours := 3;
  else
    v_duration_hours := 4;
  end if;

  return query
  select
    round(v_precision_score, 2),
    round(v_speed_score, 2),
    v_precision_tier,
    v_duration_hours;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.build_rider_scout_report_json(p_rider_id uuid, p_precision_tier text, p_precision_score numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_rider record;
begin
  select
    r.id,
    r.display_name,
    r.first_name,
    r.last_name,
    r.country_code,
    r.role,
    r.overall,
    r.potential,
    r.fatigue,
    r.availability_status,
    r.unavailable_until,
    r.unavailable_reason,
    r.sprint,
    r.climbing,
    r.time_trial,
    r.endurance,
    r.flat,
    r.recovery,
    r.resistance,
    r.race_iq,
    r.teamwork,
    r.morale
  into v_rider
  from public.riders r
  where r.id = p_rider_id
  limit 1;

  if not found then
    raise exception 'Rider not found for scouting report.';
  end if;

  return jsonb_build_object(
    'precisionTier', lower(coalesce(p_precision_tier, 'basic')),
    'precisionScore', round(coalesce(p_precision_score, 0), 2),

    'overall', public.build_scout_metric_json(v_rider.overall, p_precision_tier),
    'potential', public.build_scout_metric_json(v_rider.potential, p_precision_tier),
    'fatigue', public.build_scout_metric_json(v_rider.fatigue, p_precision_tier),

    'availability', jsonb_build_object(
      'status', v_rider.availability_status,
      'unavailable_until', v_rider.unavailable_until,
      'reason', v_rider.unavailable_reason
    ),

    'attributes', jsonb_build_object(
      'sprint',     public.build_scout_metric_json(v_rider.sprint, p_precision_tier),
      'climbing',   public.build_scout_metric_json(v_rider.climbing, p_precision_tier),
      'time_trial', public.build_scout_metric_json(v_rider.time_trial, p_precision_tier),
      'endurance',  public.build_scout_metric_json(v_rider.endurance, p_precision_tier),
      'flat',       public.build_scout_metric_json(v_rider.flat, p_precision_tier),
      'recovery',   public.build_scout_metric_json(v_rider.recovery, p_precision_tier),
      'resistance', public.build_scout_metric_json(v_rider.resistance, p_precision_tier),
      'race_iq',    public.build_scout_metric_json(v_rider.race_iq, p_precision_tier),
      'teamwork',   public.build_scout_metric_json(v_rider.teamwork, p_precision_tier),
      'morale',     public.build_scout_metric_json(v_rider.morale, p_precision_tier)
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.start_rider_scout_task_v1(p_rider_id uuid, p_scout_staff_id uuid, p_requesting_user_id uuid)
 RETURNS TABLE(task_id uuid, task_status text, club_id uuid, rider_id uuid, scout_staff_id uuid, scout_name text, precision_score numeric, precision_tier text, duration_hours integer, is_paid boolean, coin_cost integer, free_reports_used_before integer, free_reports_left_after integer, wallet_balance_after integer, started_at_game_ts timestamp without time zone, completes_at_game_ts timestamp without time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$declare
  v_club_id uuid;
  v_game_ts timestamp without time zone;
  v_game_date date;
  v_scouting_level integer;
  v_scout record;
  v_usage record;
  v_existing_task record;
  v_precision record;
  v_is_paid boolean;
  v_coin_cost integer;
  v_wallet_balance integer;
  v_task_id uuid;
  v_system_key text;
begin
  v_club_id := public.resolve_main_club_id_for_user(p_requesting_user_id);

  if v_club_id is null then
    raise exception 'Main club not found.';
  end if;

  -- do not allow scouting your own rider
  if exists (
    select 1
    from public.club_riders cr
    where cr.club_id = v_club_id
      and cr.rider_id = p_rider_id
  ) then
    raise exception 'Own riders cannot be scouted from the external scouting flow.';
  end if;

  select public.get_current_game_timestamp() at time zone 'UTC'
  into v_game_ts;

  if v_game_ts is null then
    raise exception 'Current game state could not be resolved.';
  end if;

  v_game_date := v_game_ts::date;

  -- open task already exists for this rider = blocker
  select
    rst.id,
    rst.status,
    rst.club_id,
    rst.rider_id,
    rst.scout_staff_id,
    cs.staff_name as scout_name,
    rst.precision_score,
    rst.precision_tier,
    rst.duration_hours,
    rst.is_paid,
    rst.coin_cost,
    rst.free_reports_used_before,
    rst.started_at_game_ts,
    rst.completes_at_game_ts
  into v_existing_task
  from public.rider_scout_tasks rst
  join public.club_staff cs
    on cs.id = rst.scout_staff_id
  where rst.club_id = v_club_id
    and rst.rider_id = p_rider_id
    and rst.status in ('queued', 'in_progress')
  order by rst.created_at desc
  limit 1;

  if found then
    raise exception 'An open scouting task already exists for this rider.';
  end if;

  select ci.scouting_level
  into v_scouting_level
  from public.club_infrastructure ci
  where ci.club_id = v_club_id
  limit 1;

  select
    cs.id,
    cs.staff_name,
    cs.role_type,
    cs.is_active,
    cs.expertise,
    cs.experience,
    cs.potential,
    cs.leadership,
    cs.efficiency,
    cs.loyalty,
    exists (
      select 1
      from public.staff_courses sc
      where sc.staff_id = cs.id
        and sc.status = 'active'
    ) as on_active_course
  into v_scout
  from public.club_staff cs
  where cs.id = p_scout_staff_id
    and cs.club_id = v_club_id
    and cs.role_type = 'scout_analyst'
  limit 1;

  if not found then
    raise exception 'Selected scout is not available for your club.';
  end if;

  if coalesce(v_scout.is_active, false) = false then
    raise exception 'Selected scout is not active.';
  end if;

  if v_scout.on_active_course then
    raise exception 'Selected scout is currently on an active course.';
  end if;

  -- one active scouting task per scout
  if exists (
    select 1
    from public.rider_scout_tasks rst
    where rst.scout_staff_id = p_scout_staff_id
      and rst.status in ('queued', 'in_progress')
  ) then
    raise exception 'Selected scout is already assigned to another scouting task.';
  end if;

  -- ensure daily usage row exists
  insert into public.staff_scout_daily_usage (
    club_id,
    staff_id,
    game_date,
    free_reports_used,
    paid_reports_used
  )
  values (
    v_club_id,
    p_scout_staff_id,
    v_game_date,
    0,
    0
  )
  on conflict do nothing;

  select *
  into v_usage
  from public.staff_scout_daily_usage sdu
  where sdu.club_id = v_club_id
    and sdu.staff_id = p_scout_staff_id
    and sdu.game_date = v_game_date
  for update;

  v_is_paid := coalesce(v_usage.free_reports_used, 0) >= 1;
  v_coin_cost := case when v_is_paid then 3 else 0 end;

  if v_is_paid then
    insert into public.user_wallets (user_id, balance)
    values (p_requesting_user_id, 0)
    on conflict (user_id) do nothing;

    select uw.balance
    into v_wallet_balance
    from public.user_wallets uw
    where uw.user_id = p_requesting_user_id
    for update;

    v_wallet_balance := coalesce(v_wallet_balance, 0);

    if v_wallet_balance < v_coin_cost then
      raise exception 'You are out of free scouting for today and do not have enough coins for another report.';
    end if;
  else
    select coalesce(uw.balance, 0)
    into v_wallet_balance
    from public.user_wallets uw
    where uw.user_id = p_requesting_user_id
    limit 1;

    v_wallet_balance := coalesce(v_wallet_balance, 0);
  end if;

  select *
  into v_precision
  from public.calculate_scout_precision_and_duration(
    v_scout.expertise,
    v_scout.experience,
    v_scout.potential,
    v_scout.leadership,
    least(100, v_scout.efficiency + public.team_policy_staff_quality_bonus_v1(v_club_id)), v_scout.loyalty,
    v_scouting_level
  );

  insert into public.rider_scout_tasks (
    club_id,
    rider_id,
    scout_staff_id,
    created_by_user_id,
    status,
    precision_score,
    precision_tier,
    duration_hours,
    is_paid,
    coin_cost,
    free_reports_used_before,
    started_at_game_ts,
    completes_at_game_ts,
    metadata
  )
  values (
    v_club_id,
    p_rider_id,
    p_scout_staff_id,
    p_requesting_user_id,
    'queued',
    v_precision.precision_score,
    v_precision.precision_tier,
    v_precision.duration_hours,
    v_is_paid,
    v_coin_cost,
    coalesce(v_usage.free_reports_used, 0),
    v_game_ts,
    v_game_ts + make_interval(hours => v_precision.duration_hours),
    jsonb_build_object(
      'scouting_level', coalesce(v_scouting_level, 0),
      'requested_by_user_id', p_requesting_user_id
    )
  )
  returning id
  into v_task_id;

  -- increment daily usage counters
  update public.staff_scout_daily_usage sdu
  set
    free_reports_used = sdu.free_reports_used + case when v_coin_cost = 0 then 1 else 0 end,
    paid_reports_used = sdu.paid_reports_used + case when v_coin_cost > 0 then 1 else 0 end,
    updated_at = now()
  where sdu.club_id = v_club_id
    and sdu.staff_id = p_scout_staff_id
    and sdu.game_date = v_game_date;

  if v_is_paid then
    v_system_key := format(
      'scout_paid_task_%s',
      v_task_id::text
    );

    insert into public.user_coin_ledger (
      user_id,
      delta,
      reason,
      payload_json,
      created_at
    )
    values (
      p_requesting_user_id,
      -v_coin_cost,
      'scout_report_extra',
      jsonb_build_object(
        'system_key', v_system_key,
        'task_id', v_task_id,
        'rider_id', p_rider_id,
        'scout_staff_id', p_scout_staff_id,
        'club_id', v_club_id,
        'cost', v_coin_cost
      ),
      now()
    );

    update public.user_wallets
    set balance = balance - v_coin_cost
    where user_id = p_requesting_user_id;

    v_wallet_balance := v_wallet_balance - v_coin_cost;
  end if;

  return query
  select
    v_task_id,
    'queued',
    v_club_id,
    p_rider_id,
    p_scout_staff_id,
    v_scout.staff_name,
    v_precision.precision_score,
    v_precision.precision_tier,
    v_precision.duration_hours,
    v_is_paid,
    v_coin_cost,
    coalesce(v_usage.free_reports_used, 0),
    greatest(0, 1 - (coalesce(v_usage.free_reports_used, 0) + case when v_is_paid then 0 else 1 end)),
    coalesce(v_wallet_balance, 0),
    v_game_ts,
    v_game_ts + make_interval(hours => v_precision.duration_hours);
end;$function$
;

CREATE OR REPLACE FUNCTION public.complete_due_rider_scout_tasks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_game_ts timestamp without time zone;
  v_completed_count integer := 0;
  v_task record;
  v_report_id uuid;
  v_report_json jsonb;
  v_type_id bigint;
  v_notification_id bigint;
  v_rider_name text;

  v_notes jsonb;
  v_completed_counter integer;
  v_quality_counter integer;
  v_free_counter integer;
  v_experience_gain integer;
  v_efficiency_gain integer;
  v_loyalty_gain integer;
begin
  select public.get_current_game_timestamp() at time zone 'UTC'
  into v_game_ts;

  if v_game_ts is null then
    raise exception 'Current game state could not be resolved.';
  end if;

  select nt.id
  into v_type_id
  from public.notification_types nt
  where nt.code = 'SCOUT_REPORT_COMPLETED'
  limit 1;

  for v_task in
    select
      rst.*,
      r.id as rider_row_id,
      r.first_name as rider_first_name,
      r.last_name as rider_last_name,
      r.display_name as rider_display_name,
      coalesce(
        nullif(r.display_name, ''),
        nullif(trim(concat_ws(' ', r.first_name, r.last_name)), ''),
        'Unknown rider'
      ) as rider_name
    from public.rider_scout_tasks rst
    join public.riders r on r.id = rst.rider_id
    where rst.status in ('queued', 'in_progress')
      and rst.completes_at_game_ts <= v_game_ts
    order by rst.completes_at_game_ts asc, rst.created_at asc
    for update of rst skip locked
  loop
    v_report_json :=
      public.build_rider_scout_report_json(
        v_task.rider_id,
        v_task.precision_tier,
        v_task.precision_score
      )
      ||
      jsonb_build_object(
        'rider', jsonb_build_object(
          'id', v_task.rider_row_id,
          'first_name', v_task.rider_first_name,
          'last_name', v_task.rider_last_name,
          'display_name', v_task.rider_display_name,
          'name', coalesce(
            nullif(v_task.rider_display_name, ''),
            nullif(trim(concat_ws(' ', v_task.rider_first_name, v_task.rider_last_name)), ''),
            'Unknown rider'
          )
        )
      );

    insert into public.rider_scout_reports (
      task_id,
      club_id,
      rider_id,
      scout_staff_id,
      scouted_on_game_date,
      precision_score,
      precision_tier,
      report_json,
      created_at_game_ts
    )
    values (
      v_task.id,
      v_task.club_id,
      v_task.rider_id,
      v_task.scout_staff_id,
      v_game_ts::date,
      v_task.precision_score,
      v_task.precision_tier,
      v_report_json,
      v_game_ts
    )
    on conflict (task_id) where (task_id is not null) do update
    set
      scouted_on_game_date = excluded.scouted_on_game_date,
      report_json = excluded.report_json,
      precision_score = excluded.precision_score,
      precision_tier = excluded.precision_tier,
      created_at_game_ts = excluded.created_at_game_ts
    returning id into v_report_id;

    update public.rider_scout_tasks
    set status = 'completed',
        updated_at = now()
    where id = v_task.id;

    select coalesce(notes, '{}'::jsonb)
    into v_notes
    from public.club_staff
    where id = v_task.scout_staff_id
    for update;

    v_completed_counter :=
      coalesce((v_notes #>> '{staff_xp,scout_completed_tasks}')::int, 0) + 1;

    v_quality_counter :=
      coalesce((v_notes #>> '{staff_xp,scout_quality_tasks}')::int, 0)
      + case when coalesce(v_task.precision_score, 0) >= 65 then 1 else 0 end;

    v_free_counter :=
      coalesce((v_notes #>> '{staff_xp,scout_free_tasks}')::int, 0)
      + case when coalesce(v_task.is_paid, false) = false then 1 else 0 end;

    v_experience_gain := case when v_completed_counter % 5 = 0 then 1 else 0 end;
    v_efficiency_gain := case when v_quality_counter % 8 = 0 and coalesce(v_task.precision_score, 0) >= 65 then 1 else 0 end;
    v_loyalty_gain := case when v_free_counter % 10 = 0 and coalesce(v_task.is_paid, false) = false then 1 else 0 end;

    update public.club_staff
    set
      experience = least(100, coalesce(experience, 0) + v_experience_gain),
      efficiency = least(100, coalesce(efficiency, 0) + v_efficiency_gain),
      loyalty = least(100, coalesce(loyalty, 0) + v_loyalty_gain),
      notes =
        v_notes ||
        jsonb_build_object(
          'staff_xp',
          jsonb_build_object(
            'scout_completed_tasks', v_completed_counter,
            'scout_quality_tasks', v_quality_counter,
            'scout_free_tasks', v_free_counter,
            'last_scout_task_id', v_task.id,
            'last_scout_completed_at_game_ts', v_game_ts,
            'last_gains', jsonb_build_object(
              'experience_gain', v_experience_gain,
              'efficiency_gain', v_efficiency_gain,
              'loyalty_gain', v_loyalty_gain
            )
          )
        ),
      updated_at = now()
    where id = v_task.scout_staff_id
      and role_type = 'scout_analyst'
      and is_active = true;

    if v_type_id is not null and v_task.created_by_user_id is not null then
      v_rider_name := coalesce(v_task.rider_name, 'Unknown rider');

      insert into public.notifications (
        type_id,
        title,
        message,
        source,
        created_by_user_id,
        action_url,
        payload_json,
        expires_at,
        created_at
      )
      values (
        v_type_id,
        format('Scout report ready: %s', coalesce(v_rider_name, 'Unknown rider')),
        format(
          'Your scout completed a report on %s. Open to view improved attributes and potential.',
          coalesce(v_rider_name, 'this rider')
        ),
        'game',
        null,
        format('/dashboard/external-riders/%s', v_task.rider_id),
        jsonb_build_object(
          'task_id', v_task.id,
          'report_id', v_report_id,
          'rider_id', v_task.rider_id,
          'club_id', v_task.club_id,
          'scout_staff_id', v_task.scout_staff_id,
          'precision_tier', v_task.precision_tier,
          'precision_score', v_task.precision_score,
          'staff_xp', jsonb_build_object(
            'scout_completed_tasks', v_completed_counter,
            'scout_quality_tasks', v_quality_counter,
            'scout_free_tasks', v_free_counter,
            'experience_gain', v_experience_gain,
            'efficiency_gain', v_efficiency_gain,
            'loyalty_gain', v_loyalty_gain
          ),
          'rider', jsonb_build_object(
            'id', v_task.rider_row_id,
            'first_name', v_task.rider_first_name,
            'last_name', v_task.rider_last_name,
            'display_name', v_task.rider_display_name,
            'name', v_rider_name
          )
        ),
        null,
        now()
      )
      returning id into v_notification_id;

      insert into public.user_notifications (
        user_id,
        notification_id,
        status,
        read_at,
        deleted_at,
        created_at
      )
      values (
        v_task.created_by_user_id,
        v_notification_id,
        'unread',
        null,
        null,
        now()
      );
    end if;

    v_completed_count := v_completed_count + 1;
  end loop;

  return v_completed_count;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_free_agent_resale_rules(p_rider_id uuid, p_club_id uuid)
 RETURNS TABLE(acquisition_type text, acquisition_game_date date, signed_market_value bigint, signing_bonus bigint, agent_fee bigint, days_since_signing integer, transfer_locked boolean, restricted_resale boolean, max_asking_price bigint, phase text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_contract record;
  v_today date;
  v_days_since integer := 0;
  v_cap bigint := null;
  v_phase text := 'normal';
  v_locked boolean := false;
  v_restricted boolean := false;
begin
  v_today := public.get_current_game_date_date();

  if v_today is null then
    raise exception 'Current game date not available';
  end if;

  select
    rc.acquisition_type,
    rc.acquisition_game_date,
    rc.acquisition_market_value,
    coalesce(rc.free_agent_signing_bonus, 0) as free_agent_signing_bonus,
    coalesce(rc.free_agent_agent_fee, 0) as free_agent_agent_fee
  into v_contract
  from public.rider_contracts rc
  where rc.rider_id = p_rider_id
    and rc.club_id = p_club_id
    and rc.status = 'active'
  order by rc.created_at desc
  limit 1;

  if not found then
    return query
    select
      'transfer'::text,
      null::date,
      null::bigint,
      0::bigint,
      0::bigint,
      0::integer,
      false,
      false,
      null::bigint,
      'normal'::text;
    return;
  end if;

  if coalesce(v_contract.acquisition_type, 'transfer') <> 'free_agent' then
    return query
    select
      coalesce(v_contract.acquisition_type, 'transfer')::text,
      v_contract.acquisition_game_date::date,
      v_contract.acquisition_market_value::bigint,
      v_contract.free_agent_signing_bonus::bigint,
      v_contract.free_agent_agent_fee::bigint,
      0::integer,
      false,
      false,
      null::bigint,
      'normal'::text;
    return;
  end if;

  if v_contract.acquisition_game_date is null then
    raise exception 'Free-agent acquisition metadata missing: acquisition_game_date';
  end if;

  if v_contract.acquisition_market_value is null or v_contract.acquisition_market_value <= 0 then
    raise exception 'Free-agent acquisition metadata missing: acquisition_market_value';
  end if;

  v_days_since := greatest((v_today - v_contract.acquisition_game_date), 0);

  if v_days_since < 90 then
    v_locked := true;
    v_restricted := true;
    v_phase := 'lock_0_90';
    v_cap := null;
  elsif v_days_since < 180 then
    v_locked := false;
    v_restricted := true;
    v_phase := 'cap_91_180';
    v_cap := floor(v_contract.acquisition_market_value * 0.20)::bigint;
  elsif v_days_since < 270 then
    v_locked := false;
    v_restricted := true;
    v_phase := 'cap_181_270';
    v_cap := floor(v_contract.acquisition_market_value * 0.40)::bigint;
  elsif v_days_since < 360 then
    v_locked := false;
    v_restricted := true;
    v_phase := 'cap_271_360';
    v_cap := floor(v_contract.acquisition_market_value * 0.65)::bigint;
  else
    v_locked := false;
    v_restricted := false;
    v_phase := 'normal_361_plus';
    v_cap := null;
  end if;

  return query
  select
    'free_agent'::text,
    v_contract.acquisition_game_date::date,
    v_contract.acquisition_market_value::bigint,
    v_contract.free_agent_signing_bonus::bigint,
    v_contract.free_agent_agent_fee::bigint,
    v_days_since::integer,
    v_locked,
    v_restricted,
    v_cap,
    v_phase::text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_rider_free_agent_negotiation_page_context(p_negotiation_id uuid)
 RETURNS TABLE(negotiation_id uuid, rider_id uuid, club_id uuid, club_name text, status text, current_salary_weekly integer, expected_salary_weekly integer, offer_salary_weekly integer, offer_duration_seasons smallint, min_acceptable_salary_weekly integer, preferred_duration_seasons smallint, rider_market_value bigint, offer_signing_bonus bigint, offer_agent_fee bigint, closed_reason text, opened_on_game_date date, expires_on_game_date date, locked_until timestamp with time zone, attempt_count integer, max_attempts integer, created_at timestamp with time zone, updated_at timestamp with time zone, rider_first_name text, rider_last_name text, rider_display_name text, rider_country_code text, rider_role text, rider_birth_date date, rider_image_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  return query
  select
    n.id as negotiation_id,
    n.rider_id,
    n.club_id,
    c.name as club_name,
    n.status,
    n.current_salary_weekly,
    n.expected_salary_weekly,
    n.offer_salary_weekly,
    n.offer_duration_seasons,
    n.min_acceptable_salary_weekly,
    n.preferred_duration_seasons,
    r.market_value as rider_market_value,
    coalesce(
      n.offer_signing_bonus,
      floor(coalesce(r.market_value, 0)::numeric * 0.10)::bigint
    ) as offer_signing_bonus,
    coalesce(
      n.offer_agent_fee,
      floor(coalesce(r.market_value, 0)::numeric * 0.15)::bigint
    ) as offer_agent_fee,
    n.closed_reason,
    n.opened_on_game_date,
    n.expires_on_game_date,
    n.locked_until,
    n.attempt_count,
    n.max_attempts,
    n.created_at,
    n.updated_at,
    r.first_name as rider_first_name,
    r.last_name as rider_last_name,
    r.display_name as rider_display_name,
    r.country_code as rider_country_code,
    r.role::text as rider_role,
    r.birth_date as rider_birth_date,
    r.image_url as rider_image_url
  from public.rider_free_agent_negotiations n
  join public.riders r
    on r.id = n.rider_id
  left join public.clubs c
    on c.id = n.club_id
  where n.id = p_negotiation_id
  limit 1;
end;
$function$
;

